-- ----------------------------------------------------------------------------
-- 3. Movies (Total: 1000 modern blockbusters, Top 20 NOW_SHOWING)
-- ----------------------------------------------------------------------------
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (1, 'Project Hail Mary', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', 'Christopher Miller, Phil Lord', 157, '2026-03-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/AdpvqIhgaqg5JHzH3M6532XV3PG.jpg', 'https://www.youtube.com/watch?v=5VYsnngkS_U', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (2, 'Avatar Aang: The Last Airbender', 'Avatar Aang, the world''s last Airbender, learns of an ancient power that could save his culture from extinction. With the help of his friends, he embarks on a global quest to find it before it falls into the wrong hands and threatens to upend the peace they sacrificed everything to achieve.', 'Lauren Montgomery', 99, '2026-07-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3sgnSfNT27Bx5O5ukr7B26mhEQq.jpg', 'https://www.youtube.com/watch?v=7b20GRFZBFE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (3, 'Avengers: Endgame', 'After the devastating events of Avengers: Infinity War, the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos'' actions and restore order to the universe once and for all, no matter what consequences may be in store.', 'Anthony Russo, Joe Russo', 181, '2019-04-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ulzhLuWrPK07P1YkdWQLZnQh1JL.jpg', 'https://www.youtube.com/watch?v=AMSITikqKiM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (4, 'Avengers: Infinity War', 'As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment - the fate of Earth and existence itself has never been more uncertain.', 'Anthony Russo, Joe Russo', 149, '2018-04-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', 'https://www.youtube.com/watch?v=6ZfuNTqbHE8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (5, 'The Odyssey', 'Odysseus, the legendary King of Ithaca, embarks on a long and perilous journey home following the Trojan War. Throughout his voyage, he is forced to confront the whims of gods, mythological monsters, and trials that stretch both his cunning and his humanity to the breaking point.', 'Christopher Nolan', 173, '2026-07-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg', 'https://www.youtube.com/watch?v=AyIZ9tiiN8I', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (6, 'Spider-Man: Brand New Day', 'Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.', 'Destin Daniel Cretton', 145, '2026-07-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', 'https://www.youtube.com/watch?v=62bIsvRcPv0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (7, 'Demon Slayer: Kimetsu no Yaiba Infinity Castle', 'The Demon Slayer Corps are drawn into the Infinity Castle, where Tanjiro, Nezuko, and the Hashira face terrifying Upper Rank demons in a desperate fight as the final battle against Muzan Kibutsuji begins.', 'Haruo Sotozaki', 156, '2025-07-18', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/fWVSwgjpT2D78VUh6X8UBd2rorW.jpg', 'https://www.youtube.com/watch?v=11iy5Hyl0fs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (8, 'Parasite', 'All unemployed, Ki-taek''s family takes peculiar interest in the wealthy and glamorous Parks for their livelihood until they get entangled in an unexpected incident.', 'Bong Joon Ho', 133, '2019-05-30', 'T18', 'ko', 'https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', 'https://www.youtube.com/watch?v=PhPROyE0OaM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (9, 'Obsession', 'After breaking the mysterious "One Wish Willow" to win his crush''s heart, a hopeless romantic finds himself getting exactly what he asked for but soon discovers that some desires come at a dark, sinister price.', 'Curry Barker', 109, '2026-05-13', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', 'https://www.youtube.com/watch?v=gMC8kkwbIQQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (10, 'Michael', 'The story of Michael Jackson, one of the most influential artists the world has ever known, and his life beyond the music. His journey from the discovery of his extraordinary talent as the lead of the Jackson Five, to the visionary artist whose creative ambition fueled a relentless pursuit to become the biggest entertainer in the world, highlighting both his life off-stage and some of the most iconic performances from his early solo career.', 'Antoine Fuqua', 128, '2026-04-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dueFqKLvjftnELZaGYwY7xinfaI.jpg', 'https://www.youtube.com/watch?v=k-YAcjaLuSI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (11, 'Toy Story 5', 'When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.', 'Andrew Stanton', 102, '2026-06-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sfQtVlIHljToOwYjhe21KPGzZWK.jpg', 'https://www.youtube.com/watch?v=QftAW9TTmuQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (12, 'Haunted 3D: Echoes of the Past', 'A man seeks refuge in a remote Indian mountain mansion, fleeing his past. He discovers the house harbors sinister secrets, pain, and terror ready to torment him.', 'Vikram Bhatt', 140, '2026-06-12', 'T18', 'hi', 'https://image.tmdb.org/t/p/w500/tSmAFNckiqcKg7aFgjCFnhNqNbP.jpg', 'https://www.youtube.com/watch?v=MmWxmeChy9o', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (13, 'Batman: Knightfall Part 1: Knightfall', 'Arkham Asylum has been destroyed, and all its inmates have been unleashed upon Gotham City. As Batman races to round up some of his greatest enemies, he is pushed to his physical and mental limits and into a final confrontation with a new threat: the man called Bane!', 'Jeff Wamester', 79, '2026-06-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/360qdtu2hLnqMu8SVHMywn420w1.jpg', 'https://www.youtube.com/watch?v=90HAqMk7qv0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (14, 'Spider-Man: Into the Spider-Verse', 'Struggling to find his place in the world while juggling school and family, Brooklyn teenager Miles Morales is unexpectedly bitten by a radioactive spider and develops unfathomable powers just like the one and only Spider-Man. While wrestling with the implications of his new abilities, Miles discovers a super collider created by the madman Wilson "Kingpin" Fisk, causing others from across the Spider-Verse to be inadvertently transported to his dimension.', 'Bob Persichetti, Peter Ramsey, Rodney Rothman', 117, '2018-12-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', 'https://www.youtube.com/watch?v=g4Hbz2jLxvQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (15, 'Spider-Man: Across the Spider-Verse', 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse, where he encounters the Spider Society, a team of Spider-People charged with protecting the Multiverse''s very existence. But when the heroes clash on how to handle a new threat, Miles finds himself pitted against the other Spiders and must set out on his own to save those he loves most.', 'Joaquim Dos Santos, Justin K. Thompson, Kemp Powers', 140, '2023-05-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', 'https://www.youtube.com/watch?v=BbXJ3_AQE_o', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (16, 'Joker', 'During the 1980s, a failed stand-up comedian is driven insane and turns to a life of crime and chaos in Gotham City while becoming an infamous psychopathic crime figure.', 'Todd Phillips', 122, '2019-10-01', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg', 'https://www.youtube.com/watch?v=-RFFRxcoKfA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (17, 'Swapped', 'A small woodland creature and a majestic bird, two natural sworn enemies of the Valley, magically trade places and set off on an adventure of a lifetime to switch back. Their journey soon uncovers a greater threat—one that could endanger not only their species, but the entire valley they call home.', 'Nathan Greno', 102, '2026-05-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tHhxWxge06goXU6ZQH1hj7vK8Hd.jpg', 'https://www.youtube.com/watch?v=glgmAwRDP8s', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (18, 'Your Name.', 'High schoolers Mitsuha and Taki are complete strangers living separate lives. But one night, they suddenly switch places. Mitsuha wakes up in Taki’s body, and he in hers. This bizarre occurrence continues to happen randomly, and the two must adjust their lives around each other.', 'Makoto Shinkai', 106, '2016-07-01', 'K', 'ja', 'https://image.tmdb.org/t/p/w500/vfJFJPepRKapMd5G2ro7klIRysq.jpg', 'https://www.youtube.com/watch?v=RuyHIkXdYf8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (19, 'Dune: Part Two', 'Follow the mythic journey of Paul Atreides as he unites with Chani and the Fremen while on a path of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the known universe, Paul endeavors to prevent a terrible future only he can foresee.', 'Denis Villeneuve', 167, '2024-02-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6izwz7rsy95ARzTR3poZ8H6c5pp.jpg', 'https://www.youtube.com/watch?v=U2Qp5pL3ovA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (20, 'Medal', 'Rajvir Singh, a young athlete, dreams of winning a gold medal, but tragedies always prevent him from achieving his goal. After losing his hearing due to an accident, he gets admission to an athlete academy where he betrays by angad.', 'Maneesh Chandra Bhatt', 124, '2023-06-02', 'T13', 'pa', 'https://image.tmdb.org/t/p/w500/1hNX1246a9hPxL2pO0wvlodHzUy.jpg', 'https://www.youtube.com/watch?v=0L2VcgC27WA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (21, 'The Wild Robot', 'After a shipwreck, an intelligent robot called Roz is stranded on an uninhabited island. To survive the harsh environment, Roz bonds with the island''s animals and cares for an orphaned baby goose.', 'Chris Sanders', 102, '2024-09-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wTnV3PCVW5O92JMrFvvrRcV39RU.jpg', 'https://www.youtube.com/watch?v=67vbA5ZJdKQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (22, 'Top Gun: Maverick', 'After more than thirty years of service as one of the Navy’s top aviators, and dodging the advancement in rank that would ground him, Pete “Maverick” Mitchell finds himself training a detachment of TOP GUN graduates for a specialized mission the likes of which no living pilot has ever seen.', 'Joseph Kosinski', 131, '2022-05-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/n0YuM4f5lvGAP6MAW2kBIzugXnc.jpg', 'https://www.youtube.com/watch?v=Klc__shdj88', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (23, 'Mastaney', 'Set in 1739, Nader Shah''s undefeated army is attacked by Sikh rebellions. Nadar demands their arrest to no avail. Five civilians are hired to play Sikh rebels but over time, they learn the Sikh way.', 'Sharan Art', 145, '2023-08-24', 'T13', 'pa', 'https://image.tmdb.org/t/p/w500/8vrlTSiMcNlnCQn6oNcgbbKbSn3.jpg', 'https://www.youtube.com/watch?v=YMDfraipmA8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (24, 'Coco', 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.', 'Lee Unkrich', 105, '2017-10-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', 'https://www.youtube.com/watch?v=Rvr68u6k5sI', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (25, 'Facing El Chapo', 'Two Mexican officers must survive the final hours of their shift after crossing a ruthless cartel boss.', 'Chava Cartas', 91, '2026-08-21', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/alpf5v4UqSFawPmG9RX03Or4BDk.jpg', 'https://www.youtube.com/watch?v=Rk0efhpa-5Y', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (26, 'Spider-Man: No Way Home', 'Peter Parker is unmasked and no longer able to separate his normal life from the high-stakes of being a super-hero. When he asks for help from Doctor Strange the stakes become even more dangerous, forcing him to discover what it truly means to be Spider-Man.', 'Jon Watts', 148, '2021-12-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', 'https://www.youtube.com/watch?v=1mTjfMFyPi8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (27, 'Prem Geet 3', 'The epic story of the mighty khazak kingdom from the beyul of himalayas set on an ancient periodic setup. The story revolves around two major characters PREM and GEET, where prem is supposed to be the heir to the throne as he was born on the most auspicious time according to astrology. However he had to overcome one obstacle, that is Prem (love) itself.', 'Chhetan Gurung, Santosh Sen', 130, '2022-09-23', 'T16', 'ne', 'https://image.tmdb.org/t/p/w500/l9CE2XNoJaoXt2Iv78y7eDOkJyV.jpg', 'https://www.youtube.com/watch?v=YroXZEErED8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (28, 'Oppenheimer', 'The story of J. Robert Oppenheimer''s role in the development of the atomic bomb during World War II.', 'Christopher Nolan', 181, '2023-07-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg', 'https://www.youtube.com/watch?v=bK6ldnjE3Y0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (29, 'Hacksaw Ridge', 'WWII American Army Medic Desmond T. Doss, who served during the Battle of Okinawa, refuses to kill people and becomes the first Conscientious Objector in American history to receive the Congressional Medal of Honor.', 'Mel Gibson', 139, '2016-10-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fnOMP6mjmOmZwmlC1n0K7ivrzt1.jpg', 'https://www.youtube.com/watch?v=s2-1hz1juBI', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (30, 'Koli Taal', 'Excited about their grandson''s visit, an elderly couple plan to cook chicken curry for dinner. But, things begin to fall apart when the chicken goes missing.', 'Abhilash Shetty', 92, '2021-10-30', 'T16', 'kn', 'https://image.tmdb.org/t/p/w500/cqt1btAbKvmj25rv4QEG8efVH1D.jpg', 'https://www.youtube.com/watch?v=VCLSttZ1Adc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (31, 'Bol Bol Rani', 'Aabhas a journalist arrives in village to cover a chilling story. He finds about Maya whose arrested for killing her husband but everyone fears talking about her. He first meets Ravdya a drunkard who tells that Maya was caged and tortured by her husband, then her neighbor Gandha revels Maya was fast forward girl living with a caring husband but she cheated on him for her boyfriend and was addicted to drugs. Finally a village driver tells Maya and her husband were living happily as perfect couple. But things changed when her past lover arrived back in her life. All three people have different versions of their stories with one common link that Maya possibly killed her husband', 'Sid Vinsurkar', 125, '2026-07-17', 'T16', 'mr', 'https://image.tmdb.org/t/p/w500/jblubtkbCrBRmEcqGn3psUDG3Pt.jpg', 'https://www.youtube.com/watch?v=xEdb7D9ohXw', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (32, 'The Adventures of Açela', 'Açela and her friends embark on an enchanting journey deep into a mysterious forest to discover the village''s legend of the Tale-teller.', 'Özgür Dogruöz', 70, '2020-02-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7nynvfK3keDyQsvCZjhPExd8qev.jpg', 'https://www.youtube.com/watch?v=SZ5UxlVuu1k', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (33, 'Chainsaw Man - The Movie: Reze Arc', 'In a brutal war between devils, hunters, and secret enemies, a mysterious girl named Reze has stepped into Denji''s world, and he faces his deadliest battle yet, fueled by love in a world where survival knows no rules.', 'Tatsuya Yoshihara', 100, '2025-09-19', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/pHyxb2RV5wLlboAwm9ZJ9qTVEDw.jpg', 'https://www.youtube.com/watch?v=EPaoHkV0dYw', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (34, 'Green Book', 'Tony Lip, a bouncer in 1962, is hired to drive pianist Don Shirley on a tour through the Deep South in the days when African Americans, forced to find alternate accommodations and services due to segregation laws below the Mason-Dixon Line, relied on a guide called The Negro Motorist Green Book.', 'Peter Farrelly', 130, '2018-11-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7BsvSuDQuoqhWmU2fL7W2GOcZHU.jpg', 'https://www.youtube.com/watch?v=QkZxoko_HC0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (35, 'Flight', 'The movie follows the journey of Ranveer Malhotra, who against all the odds, has to face deadly obstacles on a plane in order to survive.', 'Suraj Joshi', 110, '2021-04-02', 'T16', 'hi', 'https://image.tmdb.org/t/p/w500/cTidclJOxLIwqmV4zzMSs8goTu1.jpg', 'https://www.youtube.com/watch?v=i37xLxNM9pY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (36, 'Game On', 'A loser enters into a real time game to win which leads him to explore challenges and brings out the hidden secrets from his past.', 'Dayanandh Gaddam', 140, '2024-02-02', 'T18', 'te', 'https://image.tmdb.org/t/p/w500/bFD8MyNYCG4k4zf40nlCiDR6Wai.jpg', 'https://www.youtube.com/watch?v=RA3Z5lrPags', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (37, 'Leera The Soulmate', 'Leera the Soulmate takes place in the distant future in 6900, the humanity has lost all it''s faith and love is taken as a poison, Leera(protagonist) wakes up after 4882 years to realize that world has been, she reaches the nearby habitat, and falls in love with a boy, everyone tries to split her apart, Saiman, a voice of help is a friend or foe? The story telltales this awesome love journey.', 'Sumnash Sri Kaljai', 104, '2018-08-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fZUot0svHgXjstB8nWWbvPdsnlN.jpg', 'https://www.youtube.com/watch?v=4D_5qwvHjrQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (38, 'Puss in Boots: The Last Wish', 'Puss in Boots discovers that his passion for adventure has taken its toll: He has burned through eight of his nine lives, leaving him with only one life left. Puss sets out on an epic journey to find the mythical Last Wish and restore his nine lives.', 'Joel Crawford', 103, '2022-12-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kuf6dutpsT0vSVehic3EZIqkOBt.jpg', 'https://www.youtube.com/watch?v=RqrXhwS33yc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (39, 'Colony', 'Professor Se-jeong is thrust into a bloody nightmare when a rapidly mutating virus is released during a biotech conference causing authorities to seal the facility. Trapped inside with no escape, Se-jeong along with a small group of survivors must fight to stay alive while the infected undergo horrific transformations.', 'Yeon Sang-ho', 123, '2026-05-21', 'T18', 'ko', 'https://image.tmdb.org/t/p/w500/tN799oUR0f1gUKDYdMNrDaY7I51.jpg', 'https://www.youtube.com/watch?v=LW6dpj1uCK8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (40, 'Mudras Calling', 'When US-raised Jaden returns to his birthplace Myanmar, to search for his roots, he discovers a shocking truth, a new love and ultimately a possible future in his homeland.', 'Christina Kyi', 95, '2018-03-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jZE5aOFwXxjEAQjrjbXDL3XWO6l.jpg', 'https://www.youtube.com/watch?v=abplnDyLohY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (41, 'Songs of Solomon', 'Inspired by true events, this is a film about a childhood friendship, torn apart by the horrific Hamidian massacres infiltrated by the Ottoman Empire under the rule of Sultan Abdul Hamid II (1894-1896).', 'Arman Nshanian', 103, '2020-11-26', 'P', 'hy', 'https://image.tmdb.org/t/p/w500/xkqXf7Od8e0SIZ366UidcjACnL8.jpg', 'https://www.youtube.com/watch?v=QwVYHsSHytU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (42, 'Runner', 'A former soldier is thrown into a brutal race against time when a critical medical delivery makes him and his unlikely partner the targets of a ruthless cartel. As the mission spirals into a deadly manhunt, every detour, delay, and bullet pushes them closer to failure. With betrayal closing in from every side, they must survive the chase and deliver their cargo to save the life of a little girl.', 'Scott Waugh', 97, '2026-09-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yBKMAIj7clP42UkFejhGDBBoTpb.jpg', 'https://www.youtube.com/watch?v=B6Z9MM1LhEA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (43, 'The Super Mario Galaxy Movie', 'Having thwarted Bowser''s previous plot to marry Princess Peach, Mario and Luigi now face a fresh threat in Bowser Jr., who is determined to liberate his father from captivity and restore the family legacy. Alongside companions new and old, the brothers travel across the stars to stop the young heir''s crusade.', 'Aaron Horvath, Michael Jelenic', 98, '2026-04-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eJGWx219ZcEMVQJhAgMiqo8tYY.jpg', 'https://www.youtube.com/watch?v=En5QZmL5R1s', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (44, 'Sarangi : A Journey of Purna Bahadur', 'A struggling single father battles poverty, using his musical talents to support and inspire his son. Together, they persevere through hardship, fueled by the father''s dream of a better life.', 'Saroj Poudel', 145, '2024-10-31', 'K', 'ne', 'https://image.tmdb.org/t/p/w500/jf4I51HXyk9SFkKYf8JYmZjLk3A.jpg', 'https://www.youtube.com/watch?v=5zbtEmxEyGk', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (45, 'Dune', 'Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence - a commodity capable of unlocking humanity''s greatest potential - only those who can conquer their fear will survive.', 'Denis Villeneuve', 155, '2021-09-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/v1tRXZ4JtD2Iv6fjkPvT4GiwslV.jpg', 'https://www.youtube.com/watch?v=8g18jFHCLXk', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (46, 'Zack Snyder''s Justice League', 'Determined to ensure Superman''s ultimate sacrifice was not in vain, Bruce Wayne aligns forces with Diana Prince with plans to recruit a team of metahumans to protect the world from an approaching threat of catastrophic proportions.', 'Zack Snyder', 242, '2021-03-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/tnAuB8q5vv7Ax9UAEje5Xi4BXik.jpg', 'https://www.youtube.com/watch?v=ZrdQSAX2kyw', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (47, 'Hoppers', 'Scientists have discovered how to ''hop'' human consciousness into lifelike robotic animals, allowing people to communicate with animals as animals. Animal lover Mabel seizes an opportunity to use the technology, uncovering mysteries within the animal world beyond anything she could have imagined.', 'Daniel Chong', 104, '2026-03-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xjtWQ2CL1mpmMNwuU5HeS4Iuwuu.jpg', 'https://www.youtube.com/watch?v=PypDSyIRRSs', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (48, 'Guardians of the Galaxy Vol. 3', 'Peter Quill, still reeling from the loss of Gamora, must rally his team around him to defend the universe along with protecting one of their own. A mission that, if not completed successfully, could quite possibly lead to the end of the Guardians as we know them.', 'James Gunn', 150, '2023-05-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/r2J02Z2OpNTctfOSN1Ydgii51I3.jpg', 'https://www.youtube.com/watch?v=AAE5VZktooM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (49, 'A Silent Voice: The Movie', 'Shouya Ishida starts bullying the new girl in class, Shouko Nishimiya, because she is deaf. But as the teasing continues, the rest of the class starts to turn on Shouya for his lack of compassion. When they leave elementary school, Shouko and Shouya do not speak to each other again... until an older, wiser Shouya, tormented by his past behaviour, decides he must see Shouko once more. He wants to atone for his sins, but is it already too late...?', 'Naoko Yamada', 129, '2016-09-17', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/tuFaWiqX0TXoWu7DGNcmX3UW7sT.jpg', 'https://www.youtube.com/watch?v=E7utbHbxDAM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (50, 'Blade Runner 2049', 'Thirty years after the events of the first film, a new blade runner, LAPD Officer K, unearths a long-buried secret that has the potential to plunge what''s left of society into chaos. K''s discovery leads him on a quest to find Rick Deckard, a former LAPD blade runner who has been missing for 30 years.', 'Denis Villeneuve', 164, '2017-10-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', 'https://www.youtube.com/watch?v=dZOaI_Fn5o4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (51, 'The Shadow''s Edge', 'Macau Police brings the tracking expert police officer out of retirement to help catch a dangerous group of professional thieves.', 'Larry Yang', 142, '2025-08-16', 'T16', 'zh', 'https://image.tmdb.org/t/p/w500/cHKo3m8N1fwvEy2ZEr0xGmmMODV.jpg', 'https://www.youtube.com/watch?v=dDuzTlur3NU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (52, 'Soul', 'Joe Gardner is a middle school teacher with a love for jazz music. After a successful audition at the Half Note Club, he suddenly gets into an accident that separates his soul from his body and is transported to the You Seminar, a center in which souls develop and gain passions before being transported to a newborn child. Joe must enlist help from the other souls-in-training, like 22, a soul who has spent eons in the You Seminar, in order to get back to Earth.', 'Pete Docter', 101, '2020-12-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hm58Jw4Lw8OIeECIq5qyPYhAeRJ.jpg', 'https://www.youtube.com/watch?v=4TojlZYqPUo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (53, 'The Handmaiden', '1930s Korea, in the period of Japanese occupation, a new girl, Sook-hee, is hired as a handmaiden to a Japanese heiress, Hideko, who lives a secluded life on a large countryside estate with her domineering Uncle Kouzuki. But the maid has a secret. She is a pickpocket recruited by a swindler posing as a Japanese Count to help him seduce the Lady to steal her fortune.', 'Park Chan-wook', 145, '2016-06-01', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/dLlH4aNHdnmf62umnInL8xPlPzw.jpg', 'https://www.youtube.com/watch?v=6sVYumzrKvs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (54, 'Attack on Titan: THE LAST ATTACK', 'A colossal-sized omnibus film bringing together the last two episodes of Attack on Titan in the franchise''s first-ever theatrical experience. After venturing beyond the walls and separated from his comrades, Eren finds himself inspired by this new truth and plots the "Rumbling," a terrifying plan to eradicate every living thing in the world. With the fate of the world hanging in the balance, a motley crew of Eren''s former comrades and enemies scramble to halt his deadly mission. The only question is, can they stop him?', 'Yuichiro Hayashi', 145, '2024-03-20', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/wgwldDDlTDDMrluOMkpSA8lyKjv.jpg', 'https://www.youtube.com/watch?v=3xNH23QkNpk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (55, 'La La Land', 'Mia, an aspiring actress, serves lattes to movie stars in between auditions and Sebastian, a jazz musician, scrapes by playing cocktail party gigs in dingy bars, but as success mounts they are faced with decisions that begin to fray the fragile fabric of their love affair, and the dreams they worked so hard to maintain in each other threaten to rip them apart.', 'Damien Chazelle', 129, '2016-12-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uDO8zWDhfWwoFdKS4fzkUJt0Rf0.jpg', 'https://www.youtube.com/watch?v=0pdqf4P9MB8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (56, 'Call Me by Your Name', 'In the summer of 1983, a 17-year-old Elio spends his days in his family''s villa in Italy. One day Oliver, a graduate student, arrives to assist Elio''s father, a professor of Greco-Roman culture. Soon, Elio and Oliver discover a summer that will alter their lives forever.', 'Luca Guadagnino', 132, '2017-10-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gXiE0WveDnT0n5J4sW9TMxXF4oT.jpg', 'https://www.youtube.com/watch?v=Z9AYPxH5NTM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (57, 'Ford v Ferrari', 'American car designer Carroll Shelby and the British-born driver Ken Miles work together to battle corporate interference, the laws of physics, and their own personal demons to build a revolutionary race car for Ford Motor Company and take on the dominating race cars of Enzo Ferrari at the 24 Hours of Le Mans in France in 1966.', 'James Mangold', 153, '2019-11-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dR1Ju50iudrOh3YgfwkAU1g2HZe.jpg', 'https://www.youtube.com/watch?v=I3h9Z89U9ZA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (58, 'The Furious', 'After a criminal network kidnaps Wang Wei''s daughter and the corrupt police refuse to assist him, Wei sets out on his own to locate her. Navin, a tenacious journalist whose wife has mysteriously vanished, is his only ally. In this explosive martial arts showdown, the unlikely duo fights the kidnappers ruthlessly driven by a furious vengeance.', 'Kenji Tanigaki', 113, '2026-06-10', 'T16', 'zh', 'https://image.tmdb.org/t/p/w500/ivQ1Z3lI1xWvAeGDHBw3CCYZDGJ.jpg', 'https://www.youtube.com/watch?v=Avky8dVaqAI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (59, 'Knives Out', 'When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan''s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan''s untimely death.', 'Rian Johnson', 131, '2019-11-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pThyQovXQrw2m0s9x82twj48Jq4.jpg', 'https://www.youtube.com/watch?v=qGqiHJTsRkQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (60, 'Hidden Figures', 'The untold story of Katherine G. Johnson, Dorothy Vaughan and Mary Jackson – brilliant African-American women working at NASA and serving as the brains behind one of the greatest operations in history – the launch of astronaut John Glenn into orbit. The visionary trio crossed all gender and race lines to inspire generations to dream big.', 'Theodore Melfi', 127, '2016-12-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9lfz2W2uGjyow3am00rsPJ8iOyq.jpg', 'https://www.youtube.com/watch?v=5wfrDhgUMGI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (61, '1917', 'At the height of the First World War, two young British soldiers must cross enemy territory and deliver a message that will stop a deadly attack on hundreds of soldiers.', 'Sam Mendes', 119, '2019-12-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iZf0KyrE25z1sage4SYFLCCrMi9.jpg', 'https://www.youtube.com/watch?v=UcmZN0Mbl04', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (62, 'The Batman', 'In his second year of fighting crime, Batman uncovers corruption in Gotham City that connects to his own family while facing a serial killer known as the Riddler.', 'Matt Reeves', 177, '2022-03-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/74xTEgt7R36Fpooo50r9T25onhq.jpg', 'https://www.youtube.com/watch?v=mqqft2x_Aa4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (63, 'F1', 'Racing legend Sonny Hayes is coaxed out of retirement to lead a struggling Formula 1 team—and mentor a young hotshot driver—while chasing one more chance at glory.', 'Joseph Kosinski', 156, '2025-06-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9PXZIUsSDh4alB80jheWX4fhZmy.jpg', 'https://www.youtube.com/watch?v=8yh9BPUBbbQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (64, 'KPop Demon Hunters', 'When K-pop superstars Rumi, Mira and Zoey aren''t selling out stadiums, they''re using their secret powers to protect their fans from supernatural threats.', 'Chris Appelhans, Maggie Kang', 96, '2025-06-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zT7Lhw3BhJbMkRqm9Zlx2YGMsY0.jpg', 'https://www.youtube.com/watch?v=AzCAwdp1uIQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (65, 'Logan', 'In the near future, a weary Logan cares for an ailing Professor X in a hideout on the Mexican border. But Logan''s attempts to hide from the world and his legacy are upended when a young mutant arrives, pursued by dark forces.', 'James Mangold', 137, '2017-02-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fnbjcRDYn6YviCcePDnGdyAkYsB.jpg', 'https://www.youtube.com/watch?v=Div0iP65aZo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (66, 'Bohemian Rhapsody', 'Singer Freddie Mercury, guitarist Brian May, drummer Roger Taylor and bass guitarist John Deacon take the music world by storm when they form the rock ''n'' roll band Queen in 1970. Hit songs become instant classics. When Mercury''s increasingly wild lifestyle starts to spiral out of control, Queen soon faces its greatest challenge yet – finding a way to keep the band together amid the success and excess.', 'Bryan Singer', 135, '2018-10-24', 'K', 'en', 'https://image.tmdb.org/t/p/w500/lHu1wtNaczFPGFDTrjCSzeLPTKN.jpg', 'https://www.youtube.com/watch?v=27zlBpzdOZg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (67, 'The Legend of Hei 2', 'When an attack shatters the fragile peace between the spirit world and humanity, Hei teams up with Luye, the last disciple of his Shifu Wuxian, to expose a conspiracy that threatens both realms - and the bond they''ve sworn to protect.', 'Gu Jie, MTJJ', 119, '2025-07-18', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/dRCUBiTKtsmju3fmSS4MK0ywcqR.jpg', 'https://www.youtube.com/watch?v=6t-uv2Vv_vA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (68, 'Three Billboards Outside Ebbing, Missouri', 'After seven months have passed without a culprit in her daughter''s murder case, Mildred Hayes makes a bold move, painting three signs leading into her town with a controversial message directed at Bill Willoughby, the town''s revered chief of police. When his second-in-command Officer Jason Dixon, an immature mother''s boy with a penchant for violence, gets involved, the battle between Mildred and Ebbing''s law enforcement is only exacerbated.', 'Martin McDonagh', 115, '2017-12-01', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/bRYLt8fV82tdVoDppSFTZIcJiLN.jpg', 'https://www.youtube.com/watch?v=Jit3YhGx5pU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (69, 'Coyote vs. Acme', 'After Acme products fail him one too many times in his dogged pursuit of the Roadrunner, Wile E. Coyote decides to hire a billboard lawyer to sue the Acme Corporation.', 'Dave Green', 103, '2026-08-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg', 'https://www.youtube.com/watch?v=H-43VeYGiPM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (70, 'Remarkably Bright Creatures', 'Through unlikely bonds formed during night shifts at a local aquarium, Tova, an elderly widow, learns of a life-changing discovery that may bring her joy and wonder once again.', 'Olivia Newman', 114, '2026-05-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9HcEqn3D4J6b2Z0jK54id9nA0fr.jpg', 'https://www.youtube.com/watch?v=b14IFe4an5k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (71, 'Deadpool & Wolverine', 'A listless Wade Wilson toils away in civilian life with his days as the morally flexible mercenary, Deadpool, behind him. But when his homeworld faces an existential threat, Wade must reluctantly suit-up again with an even more reluctant Wolverine.', 'Shawn Levy', 128, '2024-07-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8cdWjvZQUExUUTzyp4t6EDMubfO.jpg', 'https://www.youtube.com/watch?v=73_1biulkYk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (72, 'Everything Everywhere All at Once', 'An aging Chinese immigrant is swept up in an insane adventure, where she alone can save what''s important to her by connecting with the lives she could have led in other universes.', 'Daniel Kwan, Daniel Scheinert', 140, '2022-03-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/u68AjlvlutfEIcpmbYpKcdi09ut.jpg', 'https://www.youtube.com/watch?v=wxN1T1uxQ2g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (73, 'Voicemails for Isabelle', 'A young woman''s hilariously confessional voicemails to her late sister are unknowingly redirected to a stranger, who begins to fall in love from afar.', 'Leah McKendrick', 119, '2026-06-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/canZTWSxACSnAluir3dCtMxKpA1.jpg', 'https://www.youtube.com/watch?v=9mi3YVYm3ZU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (74, 'Mission C1000', 'Hindu Atankwad and the Honey Trap is a film about a character named Ram who tries to stop terrorists from stealing a scientific formula. The movie explores themes of patriotism, cultural identity, and the fight against terrorism', 'Tejeshwar', 128, '2026-01-23', 'T13', 'te', 'https://image.tmdb.org/t/p/w500/jrwKIZR9P7IWkP5oPe5Xlw1j3vH.jpg', 'https://www.youtube.com/watch?v=86qI0Sefg3c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (75, 'Zootopia', 'Determined to prove herself, Officer Judy Hopps, the first bunny on Zootopia''s police force, jumps at the chance to crack her first case - even if it means partnering with scam-artist fox Nick Wilde to solve the mystery.', 'Byron Howard, Rich Moore', 109, '2016-02-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hlK0e0wAQ3VLuJcsfIYPvb4JVud.jpg', 'https://www.youtube.com/watch?v=bY73vFGhSVk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (76, 'Battleground Melbourne', 'The story of the Fall of the World''s Most Liveable City, through the eyes of those who risked everything to save it.', 'Topher Field', 102, '2022-01-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vsFyNmsqBIQbEdP6XZfHH27DMTM.jpg', 'https://www.youtube.com/watch?v=i-p_nE9spqA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (77, 'Mayday', 'When a U.S. Navy pilot on a top-secret mission during the Cold War gets trapped behind enemy lines, his only chance at survival is to form an alliance with an eccentric ex-KGB agent.', 'John Francis Daley, Jonathan Goldstein', 111, '2026-09-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hVXjX1jLZ1ljFSNGXpjJfbTUOa7.jpg', 'https://www.youtube.com/watch?v=om5Un9X720M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (78, 'Avatar: Fire and Ash', 'In the wake of the devastating war against the RDA and the loss of their eldest son, Jake Sully and Neytiri face a new threat on Pandora: the Ash People, a violent and power-hungry Na''vi tribe led by the ruthless Varang. Jake''s family must fight for their survival and the future of Pandora in a conflict that pushes them to their emotional and physical limits.', 'James Cameron', 198, '2025-12-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg', 'https://www.youtube.com/watch?v=Ma1x7ikpid8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (79, 'Klaus', 'A selfish postman and a reclusive toymaker form an unlikely friendship, delivering joy to a cold, dark town that desperately needs it.', 'Sergio Pablos', 97, '2019-11-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/q125RHUDgR4gjwh1QkfYuJLYkL.jpg', 'https://www.youtube.com/watch?v=taE3PwurhYM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (80, 'Me Before You', 'Lou Clark, a directionless 26-year-old from the English countryside, takes a job at the local castle as a caregiver and companion to a wealthy young banker, Will Traynor. Wheelchair-bound from an accident two years prior, the once adventurous Will has all but given up — that is until Lou determines to show him that life is worth living.', 'Thea Sharrock', 110, '2016-06-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/Ia3dzj5LnCj1ZBdlVeJrbKJQxG.jpg', 'https://www.youtube.com/watch?v=T0MmkG_nG1U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (81, 'Demon Slayer -Kimetsu no Yaiba- The Movie: Mugen Train', 'Tanjiro Kamado, joined with Inosuke Hashibira, a boy raised by boars who wears a boar''s head, and Zenitsu Agatsuma, a scared boy who reveals his true power when he sleeps, boards the Infinity Train on a new mission with the Fire Hashira, Kyojuro Rengoku, to defeat a demon who has been tormenting the people and killing the demon slayers who oppose it!', 'Haruo Sotozaki', 117, '2020-10-16', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/h8Rb9gBr48ODIwYUttZNYeMWeUU.jpg', 'https://www.youtube.com/watch?v=23riEOmDOgM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (82, 'I Swear', 'Diagnosed with Tourette Syndrome at 15, John Davidson navigates his way against the odds through troubled teenage years and into adulthood, finding inspiration in the kindness of others to discover his true purpose in life.', 'Kirk Jones', 121, '2025-09-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vUwyhNWBKkSwK8ELvEeBRwV724h.jpg', 'https://www.youtube.com/watch?v=10ynpduiRpM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (83, 'Deadpool', 'The origin story of former Special Forces operative turned mercenary Wade Wilson, who, after being subjected to a rogue experiment that leaves him with accelerated healing powers, adopts the alter ego Deadpool. Armed with his new abilities and a dark, twisted sense of humor, Deadpool hunts down the man who nearly destroyed his life.', 'Tim Miller', 108, '2016-02-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3E53WEZJqP6aM84D8CckXx4pIHw.jpg', 'https://www.youtube.com/watch?v=9vN6DHB6bJc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (84, 'Jojo Rabbit', 'Jojo, a lonely German boy during World War II has his world shaken when he learns that his single mother is hiding a Jewish girl in their home. Influenced by a buffoonish imaginary version of Adolf Hitler, he begins to question his beliefs and confront the conflict between propaganda and his own humanity.', 'Taika Waititi', 108, '2019-10-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1mqL7VG4Ix8wmxwypmCA1HTHBky.jpg', 'https://www.youtube.com/watch?v=tL4McUzXfFI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (85, 'Wonder', 'The story of August Pullman – a boy with facial differences – who enters fifth grade, attending a mainstream elementary school for the first time.', 'Stephen Chbosky', 113, '2017-11-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sONh3LYGFcVDTy8pm1tbSOB13Li.jpg', 'https://www.youtube.com/watch?v=ASAGdtAJPnU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (86, 'Zootopia 2', 'After cracking the biggest case in Zootopia''s history, rookie cops Judy Hopps and Nick Wilde find themselves on the twisting trail of a great mystery when Gary De''Snake arrives and turns the animal metropolis upside down. To crack the case, Judy and Nick must go undercover to unexpected new parts of town, where their growing partnership is tested like never before.', 'Byron Howard, Jared Bush', 108, '2025-11-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oJ7g2CifqpStmoYQyaLQgEU32qO.jpg', 'https://www.youtube.com/watch?v=5AwtptT8X8k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (87, 'Cruella', 'In 1970s London amidst the punk rock revolution, a young grifter named Estella is determined to make a name for herself with her designs. She befriends a pair of young thieves who appreciate her appetite for mischief, and together they are able to build a life for themselves on the London streets. One day, Estella’s flair for fashion catches the eye of the Baroness von Hellman, a fashion legend who is devastatingly chic and terrifyingly haute. But their relationship sets in motion a course of events and revelations that will cause Estella to embrace her wicked side and become the raucous, fashionable and revenge-bent Cruella.', 'Craig Gillespie', 134, '2021-05-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hjS9mH8KvRiGHgjk6VUZH7OT0Ng.jpg', 'https://www.youtube.com/watch?v=gmRKv7n2If8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (88, 'How to Train Your Dragon', 'On the rugged isle of Berk, where Vikings and dragons have been bitter enemies for generations, Hiccup stands apart, defying centuries of tradition when he befriends Toothless, a feared Night Fury dragon. Their unlikely bond reveals the true nature of dragons, challenging the very foundations of Viking society.', 'Dean DeBlois', 125, '2025-06-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/53dsJ3oEnBhTBVMigWJ9tkA5bzJ.jpg', 'https://www.youtube.com/watch?v=22w7z_lT6YM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (89, 'August', 'The documentary marks the directorial debut of Chinese actor Zhang Zhehan, it documents his deeply personal journey of self-healing in the aftermath of a devastating cyber media storm in August 2021 that abruptly halted his acting career.', 'Zhang Zhehan', 53, '2024-04-14', 'P', 'zh', 'https://image.tmdb.org/t/p/w500/2YjOwZmn1ZrGDt7JzWhZFFkbHvS.jpg', 'https://www.youtube.com/watch?v=tAOl77RPzQI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (90, 'Once Upon a Time in the Middle East', 'Seeking a fresh start, chef Xu Fu travels to the Middle East to support his family and repay his debts. Alongside restaurant manager Ma Junsheng, he transforms the struggling Dragon Restaurant into a thriving business. But when war engulfs the city, their hard-won success is shattered and the restaurant becomes a refuge for those caught in the conflict. As danger closes in, Xu Fu must risk everything to protect his newfound community and preserve a small beacon of hope amid the devastation.', 'Wen Muye', 141, '2026-08-08', 'T16', 'zh', 'https://image.tmdb.org/t/p/w500/wAuGgXjA7GV8NrKfmUKl2AP8vqG.jpg', 'https://www.youtube.com/watch?v=IEgL2ycJcao', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (91, 'BTS: Permission to Dance on Stage - Seoul', 'Join us as BTS and ARMY become one once again with music and dance in this unmissable live concert experience broadcast from Seoul to cinemas around the world! "BTS: Permission to Dance on Stage" is the latest world tour series headlined by pop icons BTS, featuring powerful performances and the greatest hit songs from throughout their incredible career.', 'Ha Jung-jae', 195, '2022-03-12', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/d5Qg9sbntjqmuswpIuF7BltuUZq.jpg', 'https://www.youtube.com/watch?v=z-2XxjBh-Ds', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (92, 'Young Hearts', '14-year-old Elias increasingly feels like an outsider in his village. When he meets his new neighbour of the same age, Alexander, Elias is confronted with his burgeoning sexuality.', 'Anthony Schatteman', 99, '2024-10-26', 'T13', 'nl', 'https://image.tmdb.org/t/p/w500/iGCtYxfuvXfy0BD5m6p7vKuPOxS.jpg', 'https://www.youtube.com/watch?v=1aCTG9HplF8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (93, 'The Father', 'A man refuses all assistance from his daughter as he ages and, as he tries to make sense of his changing circumstances, he begins to doubt his loved ones, his own mind and even the fabric of his reality.', 'Florian Zeller', 97, '2020-12-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/pr3bEQ517uMb5loLvjFQi8uLAsp.jpg', 'https://www.youtube.com/watch?v=4TZb7YfK-JI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (94, 'The Sheep Detectives', 'George Hardy is a shepherd who reads detective novels to his beloved sheep every night, assuming they can''t possibly understand. But when a mysterious incident disrupts life on the farm, the sheep realize they must become the detectives. As they follow the clues and investigate human suspects, they prove that even sheep can be brilliant crime-solvers.', 'Kyle Balda', 109, '2026-04-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iKy5460GdsoknM8ppmGlJbKxAKa.jpg', 'https://www.youtube.com/watch?v=826SRt1CFbg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (95, 'Avatar: The Way of Water', 'Set more than a decade after the events of the first film, learn the story of the Sully family (Jake, Neytiri, and their kids), the trouble that follows them, the lengths they go to keep each other safe, the battles they fight to stay alive, and the tragedies they endure.', 'James Cameron', 192, '2022-12-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/t6HIqrRAclMCA60NsSmeqe9RmNV.jpg', 'https://www.youtube.com/watch?v=a8Gx8wiNbs8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (96, 'Predator: Badlands', 'Cast out from his clan, a young Predator finds an unlikely ally in a damaged android and embarks on a treacherous journey in search of the ultimate adversary.', 'Dan Trachtenberg', 107, '2025-11-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pHpq9yNUIo6aDoCXEBzjSolywgz.jpg', 'https://www.youtube.com/watch?v=43R9l7EkJwE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (97, 'Vidrohi', 'A strict Intelligent and brave police officer Karthik knows about clue less series of rapes going on girls in their own houses without their notice by unknown person. He sneaks in to investigate and kick starts a dangerous series of event.', 'Venkata Subramanyam Vijjana', 134, '2025-10-24', 'T16', 'te', 'https://image.tmdb.org/t/p/w500/oyBgDfjR65odyWZAyh8AjG2mt66.jpg', 'https://www.youtube.com/watch?v=CZ4yJchWPRI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (98, 'John Wick: Chapter 4', 'With the price on his head ever increasing, John Wick uncovers a path to defeating The High Table. But before he can earn his freedom, Wick must face off against a new enemy with powerful alliances across the globe and forces that turn old friends into foes.', 'Chad Stahelski', 170, '2023-03-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vZloFAK7NmvMGKE7VkF5UHaz0I.jpg', 'https://www.youtube.com/watch?v=qEVUtrk8_B4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (99, 'Ne Zha 2', 'After a catastrophic event leaves their bodies destroyed, Ne Zha and Ao Bing are granted a fragile second chance at life. As tensions rise between the dragon clans and celestial forces, the two must undergo a series of perilous trials that will test their bond, challenge their identities, and decide the fate of both mortals and immortals.', 'Jiao Zi', 144, '2025-01-29', 'T16', 'zh', 'https://image.tmdb.org/t/p/w500/293Mo4GWf7Tl0TfAr5NFghqeMy7.jpg', 'https://www.youtube.com/watch?v=ETlOSBR92Fs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (100, 'Nobody', 'Hutch Mansell, a suburban dad, overlooked husband, nothing neighbor — a "nobody." When two thieves break into his home one night, Hutch''s unknown long-simmering rage is ignited and propels him on a brutal path that will uncover dark secrets he fought to leave behind.', 'Ilya Naishuller', 91, '2021-03-18', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/oBgWY00bEFeZ9N25wWVyuQddbAo.jpg', 'https://www.youtube.com/watch?v=wZti8QKBWPo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (101, 'Thor: Ragnarok', 'Thor is imprisoned on the other side of the universe and finds himself in a race against time to get back to Asgard to stop Ragnarok, the destruction of his home-world and the end of Asgardian civilization, at the hands of a powerful new threat, the ruthless Hela.', 'Taika Waititi', 131, '2017-10-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rzRwTcFvttcN1ZpX2xv4j3tSdJu.jpg', 'https://www.youtube.com/watch?v=ue80QwXMRHg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (102, 'Arrival', 'Taking place after alien crafts land around the world, an expert linguist is recruited by the military to determine whether they come in peace or are a threat.', 'Denis Villeneuve', 116, '2016-11-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pEzNVQfdzYDzVK0XqxERIw2x2se.jpg', 'https://www.youtube.com/watch?v=7W1m5ER3I1Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (103, 'Flow', 'A solitary cat, displaced by a great flood, finds refuge on a boat with various species and must navigate the challenges of adapting to a transformed world together.', 'Gints Zilbalodis', 85, '2024-08-29', 'P', 'lv', 'https://image.tmdb.org/t/p/w500/z2sG41PxfL1hnL1mHbxzSREUtOf.jpg', 'https://www.youtube.com/watch?v=82WW9dVbglI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (104, 'The Invisible Guest', 'Barcelona, Spain. Adrián Doria, a young and successful businessman accused of murder, meets one night with Virginia Goodman, an expert interrogation lawyer, in order to devise a defense strategy.', 'Oriol Paulo', 107, '2017-01-06', 'T18', 'es', 'https://image.tmdb.org/t/p/w500/fptnZJbLzKUHeNlYrAynbyoL5YJ.jpg', 'https://www.youtube.com/watch?v=epCg2RbyF80', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (105, 'Dear You', 'Xiaowei travels to Thailand to find his "billionaire grandfather" who is out of contact due to debt problems, but unexpectedly find the one who has been corresponding with his grandmother for years is not her husband.', 'Lan Hongchun', 118, '2026-04-30', 'P', 'zh', 'https://image.tmdb.org/t/p/w500/rjmhzdVS3Ia535pFawju857e2Na.jpg', 'https://www.youtube.com/watch?v=abeSQSbNXSk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (106, 'Portrait of a Lady on Fire', 'On an isolated island in Brittany at the end of the eighteenth century, a female painter is obliged to paint a wedding portrait of a young woman.', 'Céline Sciamma', 121, '2019-09-06', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/2LquGwEhbg3soxSCs9VNyh5VJd9.jpg', 'https://www.youtube.com/watch?v=Bn_-YoG69Sw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (107, 'Guardians of the Galaxy Vol. 2', 'The Guardians must fight to keep their newfound family together as they unravel the mysteries of Peter Quill''s true parentage.', 'James Gunn', 137, '2017-04-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/y4MBh0EjBlMuOzv9axM4qJlmhzz.jpg', 'https://www.youtube.com/watch?v=dW1BIid8Osg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (108, 'The Greatest Showman', 'The story of American showman P.T. Barnum, founder of the circus that became the famous traveling Ringling Bros. and Barnum & Bailey Circus.', 'Michael Gracey', 105, '2017-12-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/b9CeobiihCx1uG1tpw8hXmpi7nm.jpg', 'https://www.youtube.com/watch?v=EodWwczRIe4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (109, 'The Amazing Digital Circus: The Last Act', 'With Caine gone and the circus dark, the cast are left with only the mistakes and traumas of their pasts to keep them company. As the prospect of eternity closes in around them, they discover the truth about the Digital Circus and its history. Will they come to terms with what they uncover, or will they make... the other choice? Also, presumably at some point someone says something funny, because this ending can’t be THAT depressing, can it? A theatrical screening of episode 8 and the all new, hour-long episode 9.', 'Gooseworx', 93, '2026-06-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uoZeXWuUS2z2F7VaC1iS5RS5cnk.jpg', 'https://www.youtube.com/watch?v=qQilWg28HMM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (110, 'GOAT', 'A small goat with big dreams gets a once-in-a-lifetime shot to join the pros and play roarball, a high-intensity, co-ed, full-contact sport dominated by the fastest, fiercest animals in the world.', 'Tyree Dillihay', 100, '2026-02-11', 'K', 'en', 'https://image.tmdb.org/t/p/w500/wfuqMlaExcoYiUEvKfVpUTt1v4u.jpg', 'https://www.youtube.com/watch?v=5r-7eWDBc40', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (111, 'Look Back', 'Popular, outgoing Fujino is celebrated by her classmates for her funny comics in the class newspaper. One day, her teacher asks her to share the space with Kyomoto, a truant recluse whose beautiful artwork sparks a competitive fervor in Fujino. What starts as jealousy transforms when Fujino realizes their shared passion for drawing.', 'Kiyotaka Oshiyama', 58, '2024-06-28', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/4f2EcNkp1Mvp9wE5w7HKxcmACWg.jpg', 'https://www.youtube.com/watch?v=H6HOnlTnVwc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (112, 'Kaalamega Karigindhi..?', 'A Light, Heartwarming, and conflict-less film on School Nostalgia with a poetic touch in its narration.', 'Singara Mohan, Singara Mohan', 110, '2025-03-21', 'T13', 'te', 'https://image.tmdb.org/t/p/w500/87EOhP9TnaTlw1YyYjSYTiqpJsG.jpg', 'https://www.youtube.com/watch?v=F8nYD0C3hqE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (113, 'Little Women', 'Four sisters come of age in America in the aftermath of the Civil War.', 'Greta Gerwig', 135, '2019-12-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yn5ihODtZ7ofn8pDYfxCmxh8AXI.jpg', 'https://www.youtube.com/watch?v=AST2-4db4ic', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (114, 'Get Out', 'Chris and his girlfriend Rose go upstate to visit her parents for the weekend. At first, Chris reads the family''s overly accommodating behavior as nervous attempts to deal with their daughter''s interracial relationship, but as the weekend progresses, a series of increasingly disturbing discoveries lead him to a truth that he never could have imagined.', 'Jordan Peele', 104, '2017-02-24', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/tFXcEccSQMf3lfhfXKSU9iRBpa3.jpg', 'https://www.youtube.com/watch?v=Lc9pZmkNf34', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (115, 'Captain America: Civil War', 'Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.', 'Anthony Russo, Joe Russo', 147, '2016-04-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rAGiXaUfPzY7CDEyNKUofk3Kw2e.jpg', 'https://www.youtube.com/watch?v=43NWzay3W4s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (116, 'Shooter', 'A ruthless Punjabi gangster and his friends clash with a rival gang protecting a corrupt politician.', 'Dilsher Singh', 143, '2022-01-14', 'T18', 'pa', 'https://image.tmdb.org/t/p/w500/aDbEoU2J0NSBePJsY7HQtKxt2Pl.jpg', 'https://www.youtube.com/watch?v=HbJFQ8ViRzw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (117, 'Train to Busan', 'When a zombie virus pushes Korea into a state of emergency, those trapped on an express train to Busan must fight for their own survival.', 'Yeon Sang-ho', 118, '2016-07-20', 'T18', 'ko', 'https://image.tmdb.org/t/p/w500/vNVFt6dtcqnI7hqa6LFBUibuFiw.jpg', 'https://www.youtube.com/watch?v=0_sV9luPnMk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (118, 'Perfect Days', 'Hirayama is content with his life as a toilet cleaner in Tokyo. Outside of his structured routine, he cherishes music on cassette tapes, books, and taking photos of trees. Through unexpected encounters, he reflects on finding beauty in the world.', 'Wim Wenders', 124, '2023-11-10', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/tvUHVSTJV9ITON3oyHaWp7oaAc8.jpg', 'https://www.youtube.com/watch?v=HTgWYojq-z8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (119, 'Lee Cronin''s The Mummy', 'The young daughter of a journalist disappears into the desert without a trace—eight years later, the broken family is shocked when she is returned to them, as what should be a joyful reunion turns into a living nightmare.', 'Lee Cronin', 133, '2026-04-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1q308iixueCU4pFtSYugNOevtNx.jpg', 'https://www.youtube.com/watch?v=6wbMsDmJLCs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (120, 'Five Feet Apart', 'Seventeen-year-old Stella spends most of her time in the hospital as a cystic fibrosis patient. Her life is full of routines, boundaries and self-control — all of which get put to the test when she meets Will, an impossibly charming teen who has the same illness. There''s an instant flirtation, though restrictions dictate that they must maintain a safe distance between them. As their connection intensifies, so does the temptation to throw the rules out the window and embrace that attraction.', 'Justin Baldoni', 116, '2019-03-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kreTuJBkUjVWePRfhHZuYfhNE1T.jpg', 'https://www.youtube.com/watch?v=24YrEAGF32M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (121, 'PAW Patrol: The Dino Movie', 'The Paw Patrol lands on a mysterious dinosaur island after a storm, where they meet Rex, a stranded pup. When Humdinger''s reckless mining triggers a volcano, the team faces their biggest rescue mission yet to save the island.', 'Cal Brunker', 88, '2026-07-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qnin56Syy5rbG7KCaxWY7SPuy6p.jpg', 'https://www.youtube.com/watch?v=xgI5iYmOf5Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (122, 'The Gentlemen', 'American expat Mickey Pearson has built a highly profitable marijuana empire in London. When word gets out that he’s looking to cash out of the business forever it triggers plots, schemes, bribery and blackmail in an attempt to steal his domain out from under him.', 'Guy Ritchie', 113, '2020-01-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/jtrhTYB7xSrJxR1vusu99nvnZ1g.jpg', 'https://www.youtube.com/watch?v=2B0RpUGss2c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (123, 'Disclosure Day', 'A cybersecurity expert becomes a whistleblower after uncovering secrets about aliens, putting him on the run from a corporation. Meanwhile, a meteorologist experiencing strange phenomena joins forces with him to prove there''s life beyond our understanding.', 'Steven Spielberg', 146, '2026-06-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/AnJ8IQJI23hNpYXVNaythu061Ru.jpg', 'https://www.youtube.com/watch?v=SCYT8vb2siQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (124, 'Sufna', 'Sufna, Dream, there is saying that, “dream is not, which you have while sleeping, dream is the one, which doesn’t let you sleep. This is story about that kind of dream. How a young man from very humble background achieve, what he aims for, and in this journey how a young girl from humble background only, become his back bone, become his strength and motivational source.', 'Jagdeep Sidhu', 144, '2020-02-14', 'T13', 'pa', 'https://image.tmdb.org/t/p/w500/ozso0mV2H6Yke5L6mgZnripGwez.jpg', 'https://www.youtube.com/watch?v=5Z0XEsuJPX8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (125, 'Mortal Kombat II', 'The fan favorite champions—now joined by Johnny Cage himself—are pitted against one another in the ultimate, no-holds barred, gory battle to defeat the dark rule of Shao Kahn that threatens the very existence of the Earthrealm and its defenders.', 'Simon McQuoid', 116, '2026-05-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hwRdDFIhaEmpRgoki805YvyyjZf.jpg', 'https://www.youtube.com/watch?v=ZdC5mFHPldg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (126, 'Lion', 'A five-year-old Indian boy gets lost on the streets of Calcutta, thousands of kilometers from home. He survives many challenges before being adopted by a couple in Australia; 25 years later, he sets out to find his lost family.', 'Garth Davis', 118, '2016-11-24', 'K', 'en', 'https://image.tmdb.org/t/p/w500/kCELJH1tCmaRLqvwIgKDb09aEaw.jpg', 'https://www.youtube.com/watch?v=GKkk-hDigTk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (127, 'Transformers One', 'The untold origin story of Optimus Prime and Megatron, better known as sworn enemies, but once were friends bonded like brothers who changed the fate of Cybertron forever.', 'Josh Cooley', 104, '2024-09-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iRCgqpdVE4wyLQvGYU3ZP7pAtUc.jpg', 'https://www.youtube.com/watch?v=5a09yJU-mCI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (128, 'Once Upon a Time... in Hollywood', 'Los Angeles, 1969. TV star Rick Dalton, a struggling actor specializing in westerns, and stuntman Cliff Booth, his best friend, try to survive in a constantly changing movie industry. Dalton is the neighbor of the young and promising actress and model Sharon Tate, who has just married the prestigious Polish director Roman Polanski…', 'Quentin Tarantino', 162, '2019-07-24', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg', 'https://www.youtube.com/watch?v=ELeMaP8EPAA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (129, 'Sinners', 'Trying to leave their troubled lives behind, twin brothers return to their hometown to start again, only to discover that an even greater evil is waiting to welcome them back.', 'Ryan Coogler', 138, '2025-04-16', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/fWPgbnt2LSqkQ6cdQc0SZN9CpLm.jpg', 'https://www.youtube.com/watch?v=7joulECTx_U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (130, 'The Uprising', 'As war and plague devastate 14th-century England, a humble peasant ignites a rebellion, uniting an army of commoners to defy the King’s might in a desperate fight for justice and survival.', 'Paul Greengrass', 128, '2026-09-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7TUl15TOsIvndKlgMWTtLgtEzZP.jpg', 'https://www.youtube.com/watch?v=ZVkrhHebz1Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (131, 'David Attenborough: A Life on Our Planet', 'The story of life on our planet by the man who has seen more of the natural world than any other. In more than 90 years, Attenborough has visited every continent on the globe, exploring the wild places of our planet and documenting the living world in all its variety and wonder. Addressing the biggest challenges facing life on our planet, the film offers a powerful message of hope for future generations.', 'Alastair Fothergill, Jonathan Hughes, Keith Scholey', 83, '2020-09-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zSKwyUDKDHiFU5syTTvQRDcGBPS.jpg', 'https://www.youtube.com/watch?v=64R2MYUt394', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (132, 'Society of the Snow', 'On October 13, 1972, Uruguayan Air Force Flight 571, chartered to take a rugby team to Chile, crashes into a glacier in the heart of the Andes.', 'J. A. Bayona', 143, '2023-12-15', 'T13', 'es', 'https://image.tmdb.org/t/p/w500/2e853FDVSIso600RqAMunPxiZjq.jpg', 'https://www.youtube.com/watch?v=pDak4qLyF4Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (133, 'CODA', 'As a CODA (Child of Deaf Adults), Ruby is the only hearing person in her deaf family. When the family''s fishing business is threatened, Ruby finds herself torn between pursuing her love of music and her fear of abandoning her parents.', 'Sian Heder', 112, '2021-08-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/BzVjmm8l23rPsijLiNLUzuQtyd.jpg', 'https://www.youtube.com/watch?v=0pmfrE1YL4I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (134, 'Stray Kids: The dominATE Experience', 'Featuring the global K-Pop sensation Stray Kids and a live performance from their record-breaking world tour, alongside exclusive behind-the-scenes footage and intimate interviews with the band, Stray Kids: The dominATE Experience is an epic concert film that gives fans both a spectacular front-row seat and unique access to their favourite band.', 'Farah Khalid, Paul Dugdale', 146, '2026-02-04', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/8pi8IZ2lqJB0k0XKgh2b89OYqYd.jpg', 'https://www.youtube.com/watch?v=2R8MBgJWn4w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (135, 'Deadpool 2', 'Wisecracking mercenary Deadpool battles the evil and powerful Cable and other bad guys to save a boy''s life.', 'David Leitch', 120, '2018-05-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/to0spRl1CMDvyUbOnbb4fTk3VAd.jpg', 'https://www.youtube.com/watch?v=20bpjtCbCz0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (136, 'Gifted', 'Frank, a single man raising his child prodigy niece Mary, is drawn into a custody battle with his mother.', 'Marc Webb', 101, '2017-04-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7YB2YrMwIm1g8FyZtlvmVDfRnAT.jpg', 'https://www.youtube.com/watch?v=x7CAjpdRaXU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (137, 'The Gorge', 'Two highly trained operatives grow close from a distance after being sent to guard opposite sides of a mysterious gorge. When an evil below emerges, they must work together to survive what lies within.', 'Scott Derrickson', 128, '2025-02-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7iMBZzVZtG0oBug4TfqDb9ZxAOa.jpg', 'https://www.youtube.com/watch?v=rUSdnuOLebE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (138, 'The Super Mario Bros. Movie', 'While working underground to fix a water main, Brooklyn plumbers—and brothers—Mario and Luigi are transported down a mysterious pipe and wander into a magical new world. But when the brothers are separated, Mario embarks on an epic quest to find Luigi.', 'Aaron Horvath, Michael Jelenic', 93, '2023-04-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qNBAXBIQlnOThrVvA6mA2B5ggV6.jpg', 'https://www.youtube.com/watch?v=KydqdKKyGEk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (139, 'Minions & Monsters', 'This is the rambunctious, ridiculous and totally true story of how the Minions conquered Hollywood, became movie stars, lost everything, unleashed monsters onto the world and then banded together to try and save the planet from the mayhem they had just created.', 'Pierre Coffin', 90, '2026-06-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4LwvU9SZc8QQzW1X1FAPhNbXnEU.jpg', 'https://www.youtube.com/watch?v=V-O-uBaHk3c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (140, 'Karmakhya', 'A mysterious visit to a grieving family pulls a young woman into a terrifying world of secrets, black magic, and haunting illusions. As disturbing events begin to blur the line between reality and nightmare, Kaamakhya finds herself trapped in a chilling chain of events rooted in a dark past that refuses to stay buried.', 'Abhinaya Krishna', 126, '2026-07-31', 'T16', 'te', 'https://image.tmdb.org/t/p/w500/sGVN0bh4xQtJIHiXFy2JyWVOiMd.jpg', 'https://www.youtube.com/watch?v=800-mrhBRyc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (141, 'Guillermo del Toro''s Pinocchio', 'During the rise of fascism in Mussolini''s Italy, a wooden boy brought magically to life struggles to live up to his father''s expectations.', 'Guillermo del Toro, Mark Gustafson', 117, '2022-11-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vx1u0uwxdlhV2MUzj4VlcMB0N6m.jpg', 'https://www.youtube.com/watch?v=Od2NW1sfRdA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (142, 'Miracle in Cell No. 7', 'Separated from his daughter, a father with an intellectual disability must prove his innocence when he is jailed for the death of a commander''s child.', 'Mehmet Ada Öztekin', 132, '2019-10-10', 'P', 'tr', 'https://image.tmdb.org/t/p/w500/bOth4QmNyEkalwahfPCfiXjNh1r.jpg', 'https://www.youtube.com/watch?v=bDAkHkR6fwA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (143, 'Captain Fantastic', 'Deep in the forests of the Pacific Northwest, a father devoted to raising his six kids with a rigorous physical and intellectual education is forced to leave his paradise and enter the world, beginning a journey that challenges his idea of what it means to be a parent.', 'Matt Ross', 119, '2016-07-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/2sFME73GaD8UsUxPUKe60cPdLif.jpg', 'https://www.youtube.com/watch?v=w5jeBvjcJe4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (144, 'Big World', 'Liu Chunhe, suffering from cerebral palsy, bravely breaks through the shackles of body and mind to realize the dream stage for his grandmother, while trying to find the coordinates of his own life. After experiencing a summer transformation, he finally embarked on a new journey.', 'Yang Lina', 131, '2024-12-27', 'K', 'zh', 'https://image.tmdb.org/t/p/w500/rLj287mA1tp4hZmd69umb1rOZu8.jpg', 'https://www.youtube.com/watch?v=DPCZaofIKuc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (145, 'Inside Out 2', 'Teenager Riley''s mind headquarters is undergoing a sudden demolition to make room for something entirely unexpected: new Emotions! Joy, Sadness, Anger, Fear and Disgust, who’ve long been running a successful operation by all accounts, aren’t sure how to feel when Anxiety shows up. And it looks like she’s not alone.', 'Kelsey Mann', 97, '2024-06-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vpnVM9B6NMmQpWeZvzLvDESb2QY.jpg', 'https://www.youtube.com/watch?v=L4DrolmDxmw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (146, 'All Quiet on the Western Front', 'Paul Baumer and his friends Albert and Muller, egged on by romantic dreams of heroism, voluntarily enlist in the German army. Full of excitement and patriotic fervour, the boys enthusiastically march into a war they believe in. But once on the Western Front, they discover the soul-destroying horror of World War I.', 'Edward Berger', 147, '2022-10-07', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/2IRjbi9cADuDMKmHdLK7LaqQDKA.jpg', 'https://www.youtube.com/watch?v=hf8EYbVxtCY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (147, 'Jujutsu Kaisen 0', 'Yuta Okkotsu is a nervous high school student who is suffering from a serious problem—his childhood friend Rika has turned into a curse and won''t leave him alone. Since Rika is no ordinary curse, his plight is noticed by Satoru Gojo, a teacher at Jujutsu High, a school where fledgling exorcists learn how to combat curses. Gojo convinces Yuta to enroll, but can he learn enough in time to confront the curse that haunts him?', 'Sunghoo Park', 105, '2021-12-24', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/23oJaeBh0FDk2mQ2P240PU9Xxfh.jpg', 'https://www.youtube.com/watch?v=2docezZl574', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (148, 'The Mandalorian and Grogu', 'The evil Empire has fallen, and Imperial warlords remain scattered throughout the galaxy. As the fledgling New Republic works to protect everything the Rebellion fought for, they have enlisted the help of legendary Mandalorian bounty hunter Din Djarin and his young apprentice Grogu.', 'Jon Favreau', 132, '2026-05-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uwMKWjcNID0D9jjplsjkQS2OrB4.jpg', 'https://www.youtube.com/watch?v=IHWlvwu8t1w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (149, 'Sound of Freedom', 'The story of Tim Ballard, a former US government agent, who quits his job in order to devote his life to rescuing children from global sex traffickers.', 'Alejandro Monteverde', 131, '2023-07-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qA5kPYZA7FkVvqcEfJRoOy4kpHg.jpg', 'https://www.youtube.com/watch?v=UwSBQWI-bek', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (150, 'Love, Simon', 'Everyone deserves a great love story, but for 17-year-old Simon Spier, it''s a little more complicated. He hasn''t told his family or friends that he''s gay, and he doesn''t know the identity of the anonymous classmate that he''s fallen for online.', 'Greg Berlanti', 110, '2018-02-16', 'K', 'en', 'https://image.tmdb.org/t/p/w500/snIsqVPmlu4LPjvToHpDotxa7Eh.jpg', 'https://www.youtube.com/watch?v=E0cbWdlQg_8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (151, 'The Whale', 'A reclusive English teacher suffering from severe obesity attempts to reconnect with his estranged teenage daughter for one last chance at redemption.', 'Darren Aronofsky', 117, '2022-12-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jQ0gylJMxWSL490sy0RrPj1Lj7e.jpg', 'https://www.youtube.com/watch?v=D30r0CwtIKc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (152, 'Selena Gomez: My Mind & Me', 'After years in the limelight, Selena Gomez achieves unimaginable stardom. But just as she reaches a new peak, an unexpected turn pulls her into darkness. This uniquely raw and intimate documentary spans her six-year journey into a new light.', 'Alek Keshishian', 95, '2022-11-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oMpsswJv8x4vnOnIKqs4xJs2Kn3.jpg', 'https://www.youtube.com/watch?v=of32sI9jw5Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (153, 'Wrath of Man', 'A cold and mysterious new security guard for a Los Angeles cash truck company surprises his co-workers when he unleashes precision skills during a heist. The crew is left wondering who he is and where he came from. Soon, the marksman''s ultimate motive becomes clear as he takes dramatic and irrevocable steps to settle a score.', 'Guy Ritchie', 119, '2021-04-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/M7SUK85sKjaStg4TKhlAVyGlz3.jpg', 'https://www.youtube.com/watch?v=EFYEni2gsK0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (154, 'Ready Player One', 'When the creator of a popular video game system dies, a virtual contest is created to compete for his fortune.', 'Steven Spielberg', 140, '2018-03-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pU1ULUq8D3iRxl1fdX2lZIzdHuI.jpg', 'https://www.youtube.com/watch?v=1hrwbc5qCZ4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (155, 'Poor Things', 'Brought back to life by an unorthodox scientist, a young woman runs off with a lawyer on a whirlwind adventure across the continents. Free from the prejudices of her times, she grows steadfast in her purpose to stand for equality and liberation.', 'Yorgos Lanthimos', 141, '2023-12-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kCGlIMHnOm8JPXq3rXM6c5wMxcT.jpg', 'https://www.youtube.com/watch?v=-EfYJWRw2FM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (156, 'Shatak', 'The narrative covers a century of institutional history, revealing how a small group expanded its mission and membership to achieve widespread influence.', 'Aashish Mall', 112, '2026-02-20', 'T13', 'hi', 'https://image.tmdb.org/t/p/w500/el9P81GOvCmD7RFf2TcLJEtUJ1n.jpg', 'https://www.youtube.com/watch?v=XyY8KGMF5y0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (157, 'Doctor Strange', 'After his career is destroyed, a brilliant but arrogant surgeon gets a new lease on life when a sorcerer takes him under her wing and trains him to defend the world against evil.', 'Scott Derrickson', 115, '2016-10-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uGBVj3bEbCoZbDjjl9wTxcygko1.jpg', 'https://www.youtube.com/watch?v=HSzx-zryEgM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (158, 'Isle of Dogs', 'In the future, an outbreak of canine flu leads the mayor of a Japanese city to banish all dogs to an island used as a garbage dump. The outcasts must soon embark on an epic journey when a 12-year-old boy arrives on the island to find his beloved pet.', 'Wes Anderson', 101, '2018-03-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4C7ZHv5LUPq7XzxC3nq8mBr77sP.jpg', 'https://www.youtube.com/watch?v=dt__kig8PVU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (159, 'A Poet', 'An aging poet finds purpose mentoring Yurlady, a talented teen, though exposing her to the poetry scene might be unwise. His own poetic pursuits led nowhere, leaving him a stereotypical obscure writer.', 'Simón Mesa Soto', 123, '2025-08-28', 'P', 'es', 'https://image.tmdb.org/t/p/w500/o0MRVa3XMUUIxiSCZYaJ1jGXdk.jpg', 'https://www.youtube.com/watch?v=Ia4PVP0qtO4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (160, 'The Mitchells vs. the Machines', 'A quirky, dysfunctional family''s road trip is upended when they find themselves in the middle of the robot apocalypse and suddenly become humanity''s unlikeliest last hope.', 'Mike Rianda', 110, '2021-04-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mI2Di7HmskQQ34kz0iau6J1vr70.jpg', 'https://www.youtube.com/watch?v=9c52Z5sMuTQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (161, 'Sing 2', 'Buster and his new cast now have their sights set on debuting a new show at the Crystal Tower Theater in glamorous Redshore City. But with no connections, he and his singers must sneak into the Crystal Entertainment offices, run by the ruthless wolf mogul Jimmy Crystal, where the gang pitches the ridiculous idea of casting the lion rock legend Clay Calloway in their show. Buster must embark on a quest to find the now-isolated Clay and persuade him to return to the stage.', 'Garth Jennings', 110, '2021-12-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/aWeKITRFbbwY8txG5uCj4rMCfSP.jpg', 'https://www.youtube.com/watch?v=EPZu5MA2uqI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (162, 'Break the Silence: The Movie', 'K-pop sensation BTS embark on their 2019 ''Love Yourself: Speak Yourself'' Tour, as the seven members begin to candidly tell personal stories they have never voiced before.', 'Park Jun-soo', 90, '2020-09-10', 'K', 'ko', 'https://image.tmdb.org/t/p/w500/k1VK2L971GmEevIjFbjcimxSeMx.jpg', 'https://www.youtube.com/watch?v=hz9_jkrrptU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (163, 'Wolfwalkers', 'In a time of superstition and magic, when wolves are seen as demonic and nature an evil to be tamed, a young apprentice hunter comes to Ireland with her father to wipe out the last pack. But when she saves a wild native girl, their friendship leads her to discover the world of the Wolfwalkers and transform her into the very thing her father is tasked to destroy.', 'Ross Stewart, Tomm Moore', 102, '2020-10-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vqGiNbdc2sDwsnivMMYzwAoSSu6.jpg', 'https://www.youtube.com/watch?v=BL_RH3P6Cz0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (164, 'Hadestown: The Musical', 'The tragic love of Orpheus and Eurydice is intertwined with the complex relationship of Hades and Persephone. Eurydice, struggling with poverty, is lured to the industrial underworld of Hadestown by Hades, while Orpheus, a struggling musician, ventures down below to bring her back. (Filmed live at the Lyric Theatre, London, featuring the core five original Broadway cast members.)', 'Brett Sullivan', 141, '2026-07-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iJNVygzkuOSCOdCPNI1nLSeF7sz.jpg', 'https://www.youtube.com/watch?v=76Q5TWHslOE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (165, 'Evil Dead Burn', 'After her husband''s abrupt death, Alice seeks solace with his remaining family — descendants of a leading researcher on demonic possession. As her in-laws transform one by one into creatures that feed on fear, she comes to discover that the vows she took in life survive even in death.', 'Sébastien Vaniček', 110, '2026-07-07', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/uRxrNXQWkHoENm3nwVOZDYSCx2F.jpg', 'https://www.youtube.com/watch?v=RddZObTlmA8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (166, 'Shelter', 'A man living in self-imposed exile on a remote island rescues a young girl from a violent storm, setting off a chain of events that forces him out of seclusion to protect her from enemies tied to his past.', 'Ric Roman Waugh', 107, '2026-01-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cv7DeQQ7TOozPoTCBdNJIvWKhU1.jpg', 'https://www.youtube.com/watch?v=PPMawzJxKF4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (167, 'Spider-Man: Far From Home', 'Peter Parker and his friends go on a summer trip to Europe. However, they will hardly be able to rest - Peter will have to agree to help Nick Fury uncover the mystery of creatures that cause natural disasters and destruction throughout the continent.', 'Jon Watts', 129, '2019-06-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg', 'https://www.youtube.com/watch?v=DYYtuKyMtY8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (168, 'Frankenstein', 'Dr. Victor Frankenstein, a brilliant but egotistical scientist, brings a creature to life in a monstrous experiment that ultimately leads to the undoing of both the creator and his tragic creation.', 'Guillermo del Toro', 150, '2025-10-17', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/g4JtvGlQO7DByTI6frUobqvSL3R.jpg', 'https://www.youtube.com/watch?v=8aulMPhE12g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (169, 'Raya and the Last Dragon', 'Long ago, in the fantasy world of Kumandra, humans and dragons lived together in harmony. But when an evil force threatened the land, the dragons sacrificed themselves to save humanity. Now, 500 years later, that same evil has returned and it’s up to a lone warrior, Raya, to track down the legendary last dragon to restore the fractured land and its divided people.', 'Carlos López Estrada, Don Hall', 107, '2021-03-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5nVhgCzxKbK47OLIKxCR1syulOn.jpg', 'https://www.youtube.com/watch?v=1VIZ89FEjYI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (170, 'Black Panther', 'King T''Challa returns home to the reclusive, technologically advanced African nation of Wakanda to serve as his country''s new leader. However, T''Challa soon finds that he is challenged for the throne by factions within his own country as well as without. Using powers reserved to Wakandan kings, T''Challa assumes the Black Panther mantle to join with ex-girlfriend Nakia, the queen-mother, his princess-kid sister, members of the Dora Milaje (the Wakandan ''special forces'') and an American secret agent, to prevent Wakanda from being dragged into a world war.', 'Ryan Coogler', 135, '2018-02-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uxzzxijgPIY7slzFvMotPv8wjKA.jpg', 'https://www.youtube.com/watch?v=dxWvtMOGAhw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (171, 'How to Train Your Dragon: The Hidden World', 'As Hiccup fulfills his dream of creating a peaceful dragon utopia, Toothless’ discovery of an untamed, elusive mate draws the Night Fury away. When danger mounts at home and Hiccup’s reign as village chief is tested, both dragon and rider must make impossible decisions to save their kind.', 'Dean DeBlois', 104, '2019-01-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xvx4Yhf0DVH8G4LzNISpMfFBDy2.jpg', 'https://www.youtube.com/watch?v=5DEdq57E5ls', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (172, 'Chardikala', 'The film follows story of Bibi Bimal Kaur a mother and a wife who is falsely implicated in a major incident, leading to her being abandoned by society. She finds refuge in Punjab, where she moves from being a victim to a leader.', 'Amarjit Singh Saron', 140, '2026-05-29', 'T13', 'pa', 'https://image.tmdb.org/t/p/w500/haTgVHRQ1pfCwIiU8MDI2qt30HV.jpg', 'https://www.youtube.com/watch?v=DJBAS4Md7Hk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (173, 'Luca', 'Luca and his best friend Alberto experience an unforgettable summer on the Italian Riviera. But all the fun is threatened by a deeply-held secret: they are sea monsters from another world just below the water’s surface.', 'Enrico Casarosa', 95, '2021-06-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9x4i9uKGXt8IiiIF5Ey0DIoY738.jpg', 'https://www.youtube.com/watch?v=YdAIBlPVe9s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (174, 'The End of Oak Street', 'After a mysterious cosmic event rips Oak Street from suburbia and transports their neighborhood to someplace unknown, the Platt family soon discovers that their very survival depends on them sticking together as they navigate their now unrecognizable surroundings.', 'David Robert Mitchell', 100, '2026-08-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fYXqpgPmHMphSF2W30GbTeJVIa5.jpg', 'https://www.youtube.com/watch?v=3oB9AxspVow', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (175, 'A Man Called Otto', 'When a lively young family moves in next door, grumpy widower Otto Anderson meets his match in a quick-witted, pregnant woman named Marisol, leading to an unlikely friendship that turns his world upside down.', 'Marc Forster', 126, '2022-12-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/130H1gap9lFfiTF9iDrqNIkFvC9.jpg', 'https://www.youtube.com/watch?v=XvbGalkHKPY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (176, 'Red, White & Royal Blue', 'After an altercation between Alex, the president''s son, and Britain''s Prince Henry at a royal event becomes tabloid fodder, their long-running feud now threatens to drive a wedge in U.S./British relations. When the rivals are forced into a staged truce, their icy relationship begins to thaw and the friction between them sparks something deeper than they ever expected.', 'Matthew López', 118, '2023-07-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/dD3vhyDRCCT90hf4rldHU6Wu3Va.jpg', 'https://www.youtube.com/watch?v=pt56IC8gDZ4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (177, 'Guy Ritchie''s The Covenant', 'After an ambush, Afghan interpreter Ahmed goes to Herculean lengths to save US Army Sergeant John Kinley''s life. When Kinley learns that Ahmed and his family were not given safe passage to America as promised, he must return to the war zone and repay his debt.', 'Guy Ritchie', 123, '2023-04-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kVG8zFFYrpyYLoHChuEeOGAd6Ru.jpg', 'https://www.youtube.com/watch?v=02PPMPArNEQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (178, 'Shang-Chi and the Legend of the Ten Rings', 'Shang-Chi must confront the past he thought he left behind when he is drawn into the web of the mysterious Ten Rings organization.', 'Destin Daniel Cretton', 132, '2021-09-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9f2Q0U3IOsLgrI2HkvldwSABZy5.jpg', 'https://www.youtube.com/watch?v=8YjFbMbfXaQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (179, 'The Suicide Squad', 'Supervillains Harley Quinn, Bloodsport, Peacemaker and a collection of nutty cons at Belle Reve prison join the super-secret, super-shady Task Force X as they are dropped off at the remote, enemy-infused island of Corto Maltese.', 'James Gunn', 132, '2021-07-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/q61qEyssk2ku3okWICKArlAdhBn.jpg', 'https://www.youtube.com/watch?v=PDARAdc04oM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (180, 'Toxic: A Fairy Tale for Grown-ups', 'A powerful drug cartel pulls the strings behind a facade of sun-soaked beaches as a gritty, violent underworld power struggle emerges during the crumbling of Portuguese colonial rule.', 'Geetu Mohandas', 192, '2026-08-26', 'T18', 'kn', 'https://image.tmdb.org/t/p/w500/tZ8eSBXbza96vzCYeVTG9RBJ78E.jpg', 'https://www.youtube.com/watch?v=EfluEyQ5QIA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (181, 'My Fault', 'Noah must leave her city, boyfriend, and friends to move into William Leister''s mansion, the flashy and wealthy husband of her mother Rafaela. As a proud and independent 17 year old, Noah resists living in a mansion surrounded by luxury. However, it is there where she meets Nick, her new stepbrother, and the clash of their strong personalities becomes evident from the very beginning.', 'Domingo González', 116, '2023-06-08', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/w46Vw536HwNnEzOa7J24YH9DPRS.jpg', 'https://www.youtube.com/watch?v=xY-qRGC6Yu0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (182, 'BTS: Permission to Dance on Stage - LA', 'Purple colors the city of Los Angeles, as BTS brings their "Permission to Dance" concert to SoFi Stadium for the first time in two years. In a stadium radiating anticipation and cheer, splendid performances from "On" to "Permission to Dance" glorify the stage that now comes to life on screen. Be united once again by the power of music.', 'Park Jun-soo, Sam Wrench', 130, '2022-09-08', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/9pNGRpOOQpZtqMLncEcQDv86OkW.jpg', 'https://www.youtube.com/watch?v=E0JxDffw9J8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (183, 'Prey', 'When danger threatens her camp, the fierce and highly skilled Comanche warrior Naru sets out to protect her people. But the prey she stalks turns out to be a highly evolved alien predator with a technically advanced arsenal.', 'Dan Trachtenberg', 100, '2022-08-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2FKjLRt7oK1bRRIrxgWmthbBdFh.jpg', 'https://www.youtube.com/watch?v=wZ7LytagKlc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (184, 'Toy Story 4', 'Woody has always been confident about his place in the world, devoted to taking care of his kid—whether that''s Andy or Bonnie. But after Bonnie creates a reluctant new toy called "Forky", a road trip adventure alongside old and new friends challenges everything Woody believes about loyalty, purpose, and what it truly means to be a toy.', 'Josh Cooley', 100, '2019-06-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg', 'https://www.youtube.com/watch?v=LDXYRzerjzU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (185, 'Capernaum', 'After running away from his negligent parents, committing a violent crime and being sentenced to five years in jail, a hardened, streetwise 12-year-old Lebanese boy sues his parents in protest of the life they have given him.', 'Nadine Labaki', 126, '2018-09-20', 'P', 'ar', 'https://image.tmdb.org/t/p/w500/mFnfTVADj8yOxwzprYOmTPselk8.jpg', 'https://www.youtube.com/watch?v=ULUo0048xZE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (186, 'The Irishman', 'Pennsylvania, 1956. Frank Sheeran, a war veteran of Irish origin who works as a truck driver, accidentally meets mobster Russell Bufalino. Once Frank becomes his trusted man, Bufalino sends him to Chicago with the task of helping Jimmy Hoffa, a powerful union leader related to organized crime, with whom Frank will maintain a close friendship for nearly twenty years.', 'Martin Scorsese', 209, '2019-11-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mbm8k3GFhXS0ROd9AD1gqYbIFbM.jpg', 'https://www.youtube.com/watch?v=RS3aHkkfuEI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (187, 'A Quiet Place', 'A family is forced to live in silence while hiding from creatures that hunt by sound.', 'John Krasinski', 91, '2018-04-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/nAU74GmpUk7t5iklEp3bufwDq4n.jpg', 'https://www.youtube.com/watch?v=WR7cc5t7tv8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (188, 'Bullet Train', 'Unlucky assassin Ladybug is determined to do his job peacefully after one too many gigs gone off the rails. Fate, however, may have other plans, as Ladybug''s latest mission puts him on a collision course with lethal adversaries from around the globe—all with connected, yet conflicting, objectives—on the world''s fastest train.', 'David Leitch', 126, '2022-07-20', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/j8szC8OgrejDQjjMKSVXyaAjw3V.jpg', 'https://www.youtube.com/watch?v=0IOsk2Vlc4o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (189, 'Marriage Story', 'A stage director and an actress struggle through a grueling, coast-to-coast divorce that pushes them to their personal extremes.', 'Noah Baumbach', 137, '2019-09-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/2JRyCKaRKyJAVpsIHeLvPw5nHmw.jpg', 'https://www.youtube.com/watch?v=BHi-a1n8t7M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (190, 'I Want to Eat Your Pancreas', 'After his classmate and crush is diagnosed with a pancreatic disease, an average high schooler sets out to make the most of her final days.', 'Shinichiro Ushijima', 108, '2018-09-01', 'K', 'ja', 'https://image.tmdb.org/t/p/w500/qpV8kvRfAntV7D4aOOsLIz7OdPc.jpg', 'https://www.youtube.com/watch?v=MONVPR1dnRQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (191, 'Superman', 'Superman, a journalist in Metropolis, embarks on a journey to reconcile his Kryptonian heritage with his human upbringing as Clark Kent.', 'James Gunn', 130, '2025-07-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ldyfo0BKmz5rWtJJKCvwaNS4cJT.jpg', 'https://www.youtube.com/watch?v=MikgqM0LXr4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (192, 'Violet Evergarden: The Movie', 'As the world moves on from the war and technological advances bring changes to her life, Violet still hopes to see her lost commanding officer again.', 'Taichi Ishidate', 140, '2020-09-18', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/bajajkoErDst0JxdFyBkABiF9rW.jpg', 'https://www.youtube.com/watch?v=BUfSen2rYQs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (193, 'Weathering with You', 'The summer of his high school freshman year, Hodaka runs away from his remote island home to Tokyo, and quickly finds himself pushed to his financial and personal limits. The weather is unusually gloomy and rainy every day, as if taking its cue from his life. After many days of solitude, he finally finds work as a freelance writer for a mysterious occult magazine. Then, one day, Hodaka meets Hina on a busy street corner. This bright and strong-willed girl possesses a strange and wonderful ability: the power to stop the rain and clear the sky.', 'Makoto Shinkai', 112, '2019-07-19', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/qgrk7r1fV4IjuoeiGS5HOhXNdLJ.jpg', 'https://www.youtube.com/watch?v=Q6iK6DjV_iE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (194, 'Purple Hearts', 'An aspiring musician agrees to a marriage of convenience with a soon-to-deploy Marine, but a tragedy soon turns their fake relationship all too real.', 'Elizabeth Allen Rosenbaum', 122, '2022-07-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4JyNWkryifWbWXJyxcWh3pVya6N.jpg', 'https://www.youtube.com/watch?v=WTLgg8oRSBE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (195, 'Dunkirk', 'The story of the miraculous evacuation of Allied soldiers from Belgium, Britain, Canada and France, who were cut off and surrounded by the German army from the beaches and harbour of Dunkirk between May 26th and June 4th 1940 during World War II.', 'Christopher Nolan', 107, '2017-07-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/b4Oe15CGLL61Ped0RAS9JpqdmCt.jpg', 'https://www.youtube.com/watch?v=F-eMt3SrfFU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (196, 'Past Lives', 'After decades apart, childhood friends Nora and Hae Sung are reunited in New York for one fateful weekend as they confront notions of destiny, love, and the choices that make a life.', 'Celine Song', 106, '2023-06-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/k3waqVXSnvCZWfJYNtdamTgTtTA.jpg', 'https://www.youtube.com/watch?v=kA244xewjcI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (197, 'Mission: Impossible - Dead Reckoning Part One', 'Ethan Hunt and his IMF team embark on their most dangerous mission yet: To track down a terrifying new weapon that threatens all of humanity before it falls into the wrong hands. With control of the future and the world''s fate at stake and dark forces from Ethan''s past closing in, a deadly race around the globe begins. Confronted by a mysterious, all-powerful enemy, Ethan must consider that nothing can matter more than his mission—not even the lives of those he cares about most.', 'Christopher McQuarrie', 164, '2023-07-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/NNxYkU70HPurnNCSiCjYAmacwm.jpg', 'https://www.youtube.com/watch?v=2m1drlOZSDw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (198, 'The Art of Racing in the Rain', 'A family dog – with a near-human soul and a philosopher''s mind – evaluates his life through the lessons learned by his human owner, a race-car driver.', 'Simon Curtis', 109, '2019-08-08', 'K', 'en', 'https://image.tmdb.org/t/p/w500/mi5VN4ww0JZgRFJIaPxxTGKjUg7.jpg', 'https://www.youtube.com/watch?v=Dp2ufFO4QGg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (199, 'Murphy', 'MURPHY, starring Prabhu Mundkur, Roshini Prakash and Ila Veermalla,It is an ode to the beauty and the struggle of bringing in the essence of familial bonds, friendship and above all love in the era of dispassion.', 'B.S.P. Varma', 136, '2024-10-18', 'T13', 'kn', 'https://image.tmdb.org/t/p/w500/7r8uyBhraQS1ArTV0DmmPqxSjbR.jpg', 'https://www.youtube.com/watch?v=LRUodmjNBig', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (200, 'Encanto', 'The tale of an extraordinary family, the Madrigals, who live hidden in the mountains of Colombia, in a magical house, in a vibrant town, in a wondrous, charmed place called an Encanto. The magic of the Encanto has blessed every child in the family—every child except one, Mirabel. But when she discovers that the magic surrounding the Encanto is in danger, Mirabel decides that she, the only ordinary Madrigal, might just be her exceptional family''s last hope.', 'Byron Howard, Jared Bush', 102, '2021-10-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4j0PNHkMr5ax3IA8tjtxcmPU3QT.jpg', 'https://www.youtube.com/watch?v=CaimKeDcudo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (201, 'Protector', 'Nikki''s life is shattered when her daughter is kidnapped. Thrust into the criminal underworld while hunted by cops and military, she must fight to rescue her child.', 'Adrian Grünberg', 90, '2026-02-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/icOZpnGuH9YrEaW3wrw5GJaXGih.jpg', 'https://www.youtube.com/watch?v=IRKGIuL3728', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (202, 'John Wick: Chapter 3 - Parabellum', 'Super-assassin John Wick returns with a $14 million price tag on his head and an army of bounty-hunting killers on his trail. After killing a member of the shadowy international assassin’s guild, the High Table, John Wick is excommunicado, but the world’s most ruthless hit men and women await his every turn.', 'Chad Stahelski', 131, '2019-05-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ziEuG1essDuWuC5lpWUaw1uXY2O.jpg', 'https://www.youtube.com/watch?v=M7XM597XO94', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (203, 'Krishnavataram Part 1: The Heart (Hridayam)', 'An epic devotional narrative that reimagines the journey of Lord Krishna, tracing his path from Dwarka to Kurukshetra after parting ways with Radha. As his journey unfolds, it explores his connection with people, his layered personality, and the lessons he imparts about love and life.', 'Hardik Gajjar', 149, '2026-05-07', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/7AxJYvPWLlNiGH52A9eenDxQzu8.jpg', 'https://www.youtube.com/watch?v=KIwC1m7etLE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (204, 'Moana', 'Teenage Moana answers the Ocean''s call and, for the first time, voyages beyond the reef of her island of Motunui with infamous demigod Maui on an unforgettable journey to restore prosperity to her people.', 'Thomas Kail', 115, '2026-07-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gaet1xQ2nxrG0V1Ep9T20ZMNEIC.jpg', 'https://www.youtube.com/watch?v=EEz5xbzYPKI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (205, 'Sonic the Hedgehog 3', 'Sonic, Knuckles, and Tails reunite against a powerful new adversary, Shadow, a mysterious villain with powers unlike anything they have faced before. With their abilities outmatched in every way, Team Sonic must seek out an unlikely alliance in hopes of stopping Shadow and protecting the planet.', 'Jeff Fowler', 110, '2024-12-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/d8Ryb8AunYAuycVKDp5HpdWPKgC.jpg', 'https://www.youtube.com/watch?v=LH1J1EbqCaI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (206, 'Hanuman Ansh', 'A grieving boy seeks God to meet his departed mother, and in finding the divine, learns to serve humanity with miracles of love, food and silent blessings, becoming Hanuman Ansh, Neem Karoli Baba.', 'Vishal Chaturvedi', 150, '2026-08-07', 'K', 'hi', 'https://image.tmdb.org/t/p/w500/as2Y3zGUa2IUS3uAx2sh6Ano3es.jpg', 'https://www.youtube.com/watch?v=YpGhCA2X3gU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (207, 'I''m Still Here', 'A woman married to a former politician during the 1971 military dictatorship in Brazil is forced to reinvent herself and chart a new course for her family after a violent and arbitrary act.', 'Walter Salles', 138, '2024-09-19', 'P', 'pt', 'https://image.tmdb.org/t/p/w500/gZnsMbhCvhzAQlKaVpeFRHYjGyb.jpg', 'https://www.youtube.com/watch?v=Eo49pAwMxKQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (208, 'A Star Is Born', 'Seasoned musician Jackson Maine discovers — and falls in love with — struggling artist Ally. She has just about given up on her dream to make it big as a singer — until Jack coaxes her into the spotlight. But even as Ally''s career takes off, the personal side of their relationship is breaking down, as Jack fights an ongoing battle with his own internal demons.', 'Bradley Cooper', 136, '2018-10-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wrFpXMNBRj2PBiN4Z5kix51XaIZ.jpg', 'https://www.youtube.com/watch?v=-KT3J1VsMec', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (209, 'War Machine', 'On one last grueling mission during Army Ranger training, a combat engineer must lead his unit in a fight against a giant otherworldly killing machine.', 'Patrick Hughes', 110, '2026-02-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ril8yx5SOmj0KjNlftsdfIp00fr.jpg', 'https://www.youtube.com/watch?v=AFuE1LRxm80', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (210, 'Rogue One: A Star Wars Story', 'A rogue band of resistance fighters unite for a mission to steal the Death Star plans and bring a new hope to the galaxy.', 'Gareth Edwards', 133, '2016-12-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/i0yw1mFbB7sNGHCs7EXZPzFkdA1.jpg', 'https://www.youtube.com/watch?v=Wji-BZ0oCwg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (211, 'Bless Me Father', 'A man confesses his sins and unveils the ugly truth of his life; he is killing for the same mobster that killed his father. Will Vinny Dapello follow his father''s footsteps in the organized crime family? Or sacrifice his soul to save his life?', 'Gianni McLaughlin', 91, '2023-05-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2lik9yR6zIqcEKtSlYnK1rNjEgl.jpg', 'https://www.youtube.com/watch?v=3lqQ7inRER8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (212, 'Incredibles 2', 'Elastigirl springs into action to save the day, while Mr. Incredible faces his greatest challenge yet – taking care of the problems of his three children.', 'Brad Bird', 118, '2018-06-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9lFKBtaVIhP7E2Pk0IY1CwTKTMZ.jpg', 'https://www.youtube.com/watch?v=YBpdL9hSac4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (213, 'Palmer', 'After 12 years in prison, former high school football star Eddie Palmer returns home to put his life back together—and forms an unlikely bond with Sam, an outcast boy from a troubled home. But Eddie''s past threatens to ruin his new life and family.', 'Fisher Stevens', 110, '2021-01-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xSDdRAjxKAGi8fUBLOqSrBhJmF0.jpg', 'https://www.youtube.com/watch?v=8jVuOheTNGQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (214, 'The Holdovers', 'A curmudgeonly instructor at a New England prep school is forced to remain on campus during Christmas break to babysit the handful of students with nowhere to go. Eventually, he forms an unlikely bond with one of them — a damaged, brainy troublemaker — and with the school’s head cook, who has just lost a son in Vietnam.', 'Alexander Payne', 133, '2023-10-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/VHSzNBTwxV8vh7wylo7O9CLdac.jpg', 'https://www.youtube.com/watch?v=AhKLpJmHhIg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (215, 'Free Guy', 'A bank teller discovers he is actually a background player in an open-world video game, and decides to become the hero of his own story. Now, in a world where there are no limits, he is determined to be the guy who saves his world his way before it''s too late.', 'Shawn Levy', 115, '2021-08-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dxraF0qPr1OEgJk17ltQTO84kQF.jpg', 'https://www.youtube.com/watch?v=JORN2hkXLyM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (216, 'Evangelion: 3.0+1.0 Thrice Upon a Time', 'In the aftermath of the Fourth Impact, stranded without their Evangelions, Shinji, Asuka and Rei find refuge in one of the rare pockets of humanity that still exist on the ruined planet Earth. There, each lives a life far different from their days as an Evangelion pilot. However, the danger to the world is far from over. A new impact is looming on the horizon—one that will prove to be the true end of Evangelion.', 'Hideaki Anno, Katsuichi Nakayama, Kazuya Tsurumaki, Mahiro Maeda', 155, '2021-03-08', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/md5wZRRj8biHrGtyitgBZo7674t.jpg', 'https://www.youtube.com/watch?v=GZfuWMDEJpw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (217, 'Killers of the Flower Moon', 'When oil is discovered in 1920s Oklahoma under Osage Nation land, the Osage people are murdered one by one—until the FBI steps in to unravel the mystery.', 'Martin Scorsese', 206, '2023-10-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dB6Krk806zeqd0YNp2ngQ9zXteH.jpg', 'https://www.youtube.com/watch?v=1oZUCkJEuvo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (218, 'Godzilla Minus One', 'In postwar Japan, Godzilla brings new devastation to an already scorched landscape. With no military intervention or government help in sight, the survivors must join together in the face of despair and fight back against an unrelenting horror.', 'Takashi Yamazaki', 125, '2023-11-03', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/2E2WTX0TJEflAged6kzErwqX1kt.jpg', 'https://www.youtube.com/watch?v=MSp68m8OJus', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (219, 'Utshob', 'On the eve of Eid, a grumpy, miserly loner Jahangir is visited by three mysterious guests, claiming to be ghosts. As they make him revisit his past, Jahangir is forced to confront the life he has built in bitterness and solitude. A heartwarming tale of regrets, memories and rediscovering love and laughter.', 'Tanim Noor', 112, '2025-06-07', 'P', 'bn', 'https://image.tmdb.org/t/p/w500/oA3mmn4fqiNVbspRsON1gVEHOzG.jpg', 'https://www.youtube.com/watch?v=jHPf1iKw4T8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (220, 'The Hate U Give', 'Raised in a poverty-stricken slum, a 16-year-old girl named Starr now attends a suburban prep school. After she witnesses a police officer shoot her unarmed best friend, she''s torn between her two very different worlds as she tries to speak her truth.', 'George Tillman Jr.', 133, '2018-10-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/2icwBom0t5nmOuZI9FVXF3gkMK0.jpg', 'https://www.youtube.com/watch?v=3MM8OkVT0hw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (221, 'Suzume', 'Suzume, 17, lost her mother as a little girl. On her way to school, she meets a mysterious young man. But her curiosity unleashes a calamity that endangers the entire population of Japan, and so Suzume embarks on a journey to set things right.', 'Makoto Shinkai', 122, '2022-11-11', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/yStW1TXF5s7Tbtu9KjIZEaWl6HL.jpg', 'https://www.youtube.com/watch?v=9UuwS0mTBNM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (222, 'Baby Driver', 'After being coerced into working for a crime boss, a young getaway driver finds himself taking part in a heist doomed to fail.', 'Edgar Wright', 113, '2017-06-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tYzFuYXmT8LOYASlFCkaPiAFAl0.jpg', 'https://www.youtube.com/watch?v=YR8cerFfWZo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (223, 'The Gangster, the Cop, the Devil', 'After barely surviving a brutal attack by a sadistic serial killer, crime boss Jang Dong-su is left humiliated. Determined to catch the killer known as K, he forms an uneasy alliance with Jung Tae-seok, a relentless and incorruptible detective who often disrupts his illegal business. However, while Jang Dong-su wants K dead, Jung Tae-suk is determined to bring him to justice. With a deal in place—whoever finds K first will decide his fate—the hunt begins, blurring the lines between crime and law.', 'Lee Won-tae', 110, '2019-05-15', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/oHlM4abRm6BzrRcz9Nup1uidw9H.jpg', 'https://www.youtube.com/watch?v=D1XANQUYSvk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (224, 'John Wick: Chapter 2', 'John Wick is forced out of retirement by a former associate looking to seize control of a shadowy international assassins’ guild. Bound by a blood oath to aid him, Wick travels to Rome and does battle against some of the world’s most dangerous killers.', 'Chad Stahelski', 122, '2017-02-08', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/hXWBc0ioZP3cN4zCu6SN3YHXZVO.jpg', 'https://www.youtube.com/watch?v=ChpLV9AMqm4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (225, 'No Time to Die', 'Bond has left active service and is enjoying a tranquil life in Jamaica. His peace is short-lived when his old friend Felix Leiter from the CIA turns up asking for help. The mission to rescue a kidnapped scientist turns out to be far more treacherous than expected, leading Bond onto the trail of a mysterious villain armed with dangerous new technology.', 'Cary Joji Fukunaga', 163, '2021-09-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iUgygt3fscRoKWCV1d0C7FbM9TP.jpg', 'https://www.youtube.com/watch?v=BIhNsAtPbPI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (226, 'Rite Here Rite Now', 'Whether you’re a devoted disciple looking to relive treasured memories of the GHOST live spectacle or among the curious uninitiated, RITE HERE RITE NOW will put you right there: putting your phones down and living in the moment—as a shadow of uncertainty looms—completely spellbound and in the thrall of this bombastic yet intimate cinematic portrait of GHOST.', 'Alex Ross Perry, Tobias Forge', 144, '2024-06-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/w3xJNhW5ZYuK3BySbsJiGDmKEiV.jpg', 'https://www.youtube.com/watch?v=GJVgZX-vQUc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (227, 'Togo', 'The untold true story set in the winter of 1925 that takes you across the treacherous terrain of the Alaskan tundra for an exhilarating and uplifting adventure that will test the strength, courage and determination of one man, Leonhard Seppala, and his lead sled dog, Togo.', 'Ericson Core', 113, '2019-12-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/921q4gPNN4J6UxvKaw6SCNBe3F8.jpg', 'https://www.youtube.com/watch?v=HMfyueM-ZBQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (228, '20th Century Girl', 'In 1999, a teen girl keeps close tabs on a boy in school on behalf of her deeply smitten best friend – then she gets swept up in a love story of her own.', 'Bang Woo-ri', 119, '2022-10-06', 'T13', 'ko', 'https://image.tmdb.org/t/p/w500/od22ftNnyag0TTxcnJhlsu3aLoU.jpg', 'https://www.youtube.com/watch?v=KFS4_qevE7M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (229, 'Gran Turismo', 'The ultimate wish-fulfillment tale of a teenage Gran Turismo player whose gaming skills won him a series of Nissan competitions to become an actual professional racecar driver.', 'Neill Blomkamp', 135, '2023-08-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/51tqzRtKMMZEYUpSYkrUE7v9ehm.jpg', 'https://www.youtube.com/watch?v=GVPzGBvPrzw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (230, 'Furiosa: A Mad Max Saga', 'As the world falls, young Furiosa is snatched from the Green Place of Many Mothers into the hands of a great biker horde led by the warlord Dementus. Sweeping through the wasteland, they encounter the citadel presided over by Immortan Joe. The two tyrants wage war for dominance, and Furiosa must survive many trials as she puts together the means to find her way home.', 'George Miller', 149, '2024-05-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iADOJ8Zymht2JPMoy3R7xceZprc.jpg', 'https://www.youtube.com/watch?v=FVswuip0-co', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (231, 'Hamnet', 'The powerful story of love and loss that inspired the creation of Shakespeare''s timeless masterpiece, Hamlet.', 'Chloé Zhao', 125, '2025-11-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vbeyOZm2bvBXcbgPD3v6o94epPX.jpg', 'https://www.youtube.com/watch?v=E2xtmPkuksA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (232, 'One Battle After Another', 'Washed-up revolutionary Bob exists in a state of stoned paranoia, surviving off-grid with his spirited, self-reliant daughter, Willa. When his evil nemesis resurfaces after 16 years and she goes missing, the former radical scrambles to find her, father and daughter both battling the consequences of his past.', 'Paul Thomas Anderson', 162, '2025-09-23', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/lbBWwxBht4JFP5PsuJ5onpMqugW.jpg', 'https://www.youtube.com/watch?v=EDeHW1cvIkQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (233, 'The Count of Monte Cristo', 'Edmond Dantès becomes the target of a sinister plot and is arrested on his wedding day for a crime he did not commit. After 14 years in the island prison of Château d’If, he manages a daring escape. Now rich beyond his dreams, he assumes the identity of the Count of Monte-Cristo and exacts his revenge on the three men who betrayed him.', 'Alexandre de La Patellière, Matthieu Delaporte', 178, '2024-06-28', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/sAT1P3FGhtJ68anUyJScnMu8t1l.jpg', 'https://www.youtube.com/watch?v=8Q6y1waxlTY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (234, 'Even If This Love Disappears Tonight', 'A high school girl wakes up each day with no memory of yesterday. When she agrees to date a shy classmate, can their love grow with every new beginning?', 'Kim Hye-young', 106, '2025-12-24', 'K', 'ko', 'https://image.tmdb.org/t/p/w500/5eNN8KLDPUXDqIkTdCbmn1gx5P7.jpg', 'https://www.youtube.com/watch?v=rjAs9Ks-3V0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (235, 'Hamilton', 'Presenting the tale of American founding father Alexander Hamilton, this filmed version of the original Broadway smash hit is the story of America then, told by America now.', 'Thomas Kail', 160, '2025-09-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/h1B7tW0t399VDjAcWJh8m87469b.jpg', 'https://www.youtube.com/watch?v=0pvj1p1aaH8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (236, 'The Legend of Hei', 'When cat spirit Luo Xiaohei''s home is deforested by humans, he must find a new one. He runs into a group of other spirit creatures who take him under their wing with dreams of reconquering the land they say is rightfully theirs. However, they run into a human known as Wuxian who separates Luo Xiaohei from the other spirits and the two go on a journey, with the cat spirit learning to control his abilities as well as forming his own thoughts on whether or not he should ally with the spirits or the humans.', 'MTJJ', 102, '2019-08-27', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/nWdES36hGwADWWBGzvgT1Z3Xn86.jpg', 'https://www.youtube.com/watch?v=NC9M8QYRZpE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (237, 'RRR', 'A fictional history of two legendary revolutionaries'' journey away from home before they began fighting for their country in the 1920s.', 'S. S. Rajamouli', 187, '2022-03-24', 'T16', 'te', 'https://image.tmdb.org/t/p/w500/u0XUBNQWlOvrh0Gd97ARGpIkL0.jpg', 'https://www.youtube.com/watch?v=AVVO3Yat_Bw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (238, 'O.J.: Made in America', 'A chronicle of the rise and fall of O.J. Simpson, whose high-profile murder trial exposed the extent of American racial tensions, revealing a fractured and divided nation.', 'Ezra Edelman', 467, '2016-05-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/nFmg2G4IJ0x9mALXkYFN8Gw0Dw5.jpg', 'https://www.youtube.com/watch?v=HrB3rOcrJxg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (239, 'Aftersun', 'Sophie reflects on the shared joy and private melancholy of a holiday she took with her father twenty years earlier. Memories fill the gaps between camcorder footages as she tries to reconcile the father she knew with the troubled man she didn''t.', 'Charlotte Wells', 101, '2022-10-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/evKz85EKouVbIr51zy5fOtpNRPg.jpg', 'https://www.youtube.com/watch?v=4A34B1DIGl8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (240, 'Weapons', 'When all but one child from the same class mysteriously vanish on the same night at exactly the same time, a community is left questioning who or what is behind their disappearance.', 'Zach Cregger', 129, '2025-08-04', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/cpf7vsRZ0MYRQcnLWteD5jK9ymT.jpg', 'https://www.youtube.com/watch?v=OpThntO9ixc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (241, 'Mutiny', 'After witnessing his billionaire boss'' murder and being framed for the crime, Cole Reed boards a cargo ship on a one-man crusade to avenge his boss'' death only to discover an international conspiracy.', 'Jean-François Richet', 96, '2026-08-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pu2VxGlpGwffOx292w18b1tv96j.jpg', 'https://www.youtube.com/watch?v=2Iqvbe98Gb4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (242, 'JUJUTSU KAISEN: Hidden Inventory / Premature Death - The Movie', 'Pursued by a religious cult and other curse users, former friends Satoru Gojo and Suguru Geto are the only sorcerers capable of carrying the difficult task of protecting Riko Amanai, a student who has been designated to be sacrificed as the Star Plasma Vessel, until she can fulfill her duty.', 'Shota Goshozono', 110, '2025-05-30', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/kZkyr1sRzarENrxjtltPvmHRrTk.jpg', 'https://www.youtube.com/watch?v=A0p4XMdWvm8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (243, 'Dangal', 'Dangal is an extraordinary true story based on the life of Mahavir Singh and his two daughters, Geeta and Babita Phogat. The film traces the inspirational journey of a father who trains his daughters to become world class wrestlers.', 'Nitesh Tiwari', 161, '2016-12-21', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/cJRPOLEexI7qp2DKtFfCh7YaaUG.jpg', 'https://www.youtube.com/watch?v=x_7YlGv9u1g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (244, 'Mission: Impossible - Fallout', 'When an IMF mission ends badly, the world is faced with dire consequences. As Ethan Hunt takes it upon himself to fulfill his original briefing, the CIA begin to question his loyalty and his motives. The IMF team find themselves in a race against time, hunted by assassins while trying to prevent a global catastrophe.', 'Christopher McQuarrie', 147, '2018-07-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/AkJQpZp9WoNdj7pLYSj1L0RcMMN.jpg', 'https://www.youtube.com/watch?v=MEOOas3JZt0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (245, 'Jatt Nuu Chudail Takri', 'Jallaludin thinks all women are evil and refers to them as `chudail`. On a trip out with his married friend, he convinces them to divorce their wives but to his surprise he falls in love with Rani. He gets married to her within a week, only to realise that she is actually a ghost (chudail). What will Jallaludin`s next plan of action be? Will he be able to fight against Rani or will he succumb to the fear?', 'Vikas Vashisht', 154, '2024-03-15', 'P', 'pa', 'https://image.tmdb.org/t/p/w500/3LC5hxRbscA5Yi5E6eNJLKrFW84.jpg', 'https://www.youtube.com/watch?v=D4LyZPfnznE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (246, 'Manchester by the Sea', 'After his older brother passes away, Lee Chandler is forced to return home to care for his 16-year-old nephew. There he is compelled to deal with a tragic past that separated him from his family and the community where he was born and raised.', 'Kenneth Lonergan', 138, '2016-11-17', 'K', 'en', 'https://image.tmdb.org/t/p/w500/o9VXYOuaJxCEKOxbA86xqtwmqYn.jpg', 'https://www.youtube.com/watch?v=NxQmuJnrjxg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (247, 'Elemental', 'In a city where fire, water, land and air residents live together, a fiery young woman and a go-with-the-flow guy will discover something elemental: how much they have in common.', 'Peter Sohn', 102, '2023-06-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4Y1WNkd88JXmGfhtWR7dmDAo1T2.jpg', 'https://www.youtube.com/watch?v=-cT495xKvvs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (248, 'Thunderbolts*', 'After finding themselves ensnared in a death trap, seven disillusioned castoffs must embark on a dangerous mission that will force them to confront the darkest corners of their pasts.', 'Jake Schreier', 127, '2025-04-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hqcexYHbiTBfDIdDWxrxPtVndBX.jpg', 'https://www.youtube.com/watch?v=-sAOWhvheK8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (249, 'Black Clover: Sword of the Wizard King', 'As a lionhearted boy who can''t wield magic strives for the title of Wizard King, four banished Wizard Kings of yore return to crush the Clover Kingdom.', 'Ayataka Tanemura', 113, '2023-06-16', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/9YEGawvjaRgnyW6QVcUhFJPFDco.jpg', 'https://www.youtube.com/watch?v=M-JD8QqStBg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (250, 'Blades of the Guardians', 'Dao Ma, the "second most wanted fugitive," is entrusted by his benefactor, the chief of Mo family clan, to take on a mysterious escort mission-escorting the "most wanted fugitive" to Chang''an.', 'Yuen Woo-ping', 126, '2026-02-17', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/R84km7PJ0frFSNPmvIjG6LV1kg.jpg', 'https://www.youtube.com/watch?v=7jkL4-uYriY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (251, 'Ne Zha', 'A young boy is born as the reincarnation of a demonic power, into a society that hates and fears him. Destined by prophecy to bring destruction to the world, Nezha must choose between good and evil to see if he can change his fate.', 'Jiao Zi', 110, '2019-07-26', 'P', 'zh', 'https://image.tmdb.org/t/p/w500/phM9bb6s9c60LA8qwsdk7U1N2cS.jpg', 'https://www.youtube.com/watch?v=0S7_LgTiHnA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (252, 'Godzilla vs. Kong', 'In a time when monsters walk the Earth, humanity’s fight for its future sets Godzilla and Kong on a collision course that will see the two most powerful forces of nature on the planet collide in a spectacular battle for the ages.', 'Adam Wingard', 114, '2021-03-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pgqgaUx1cJb5oZQQ5v0tNARCeBp.jpg', 'https://www.youtube.com/watch?v=odM92ap8_c0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (253, 'The King of Kings', 'Charles Dickens tells his young son Walter the greatest story ever told, and what begins as a bedtime tale becomes a life-changing journey. Through vivid imagination, the boy walks alongside Jesus, witnessing His miracles, facing His trials, and understanding His ultimate sacrifice.', 'Jang Seong-ho', 102, '2025-04-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ccw7CCIAvcZV431CP7NhHAHuiHR.jpg', 'https://www.youtube.com/watch?v=HDhet3EVRac', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (254, 'National Theatre Live: Prima Facie', 'Tessa is a young, brilliant barrister. From working class origins, she has reached the top of her game. An unexpected event forces her to confront the lines where the patriarchal power of the law, burden of proof and morals diverge.', 'Justin Martin, Matthew Amos', 114, '2022-07-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mA154UHwvm9bFEt6kEfVdyWyuAk.jpg', 'https://www.youtube.com/watch?v=tOQ7YsxkVUQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (255, 'Bonolota Express', 'On a foggy winter journey, the Bonolota Express carries strangers burdened by secrets whose lives begin to collide within the train’s confined corridors. As the night unfolds, personal and political crises erupt, exposing hidden grief, moral decay, and moments of unexpected compassion amid chaos and revolt. By dawn, the train moves on, leaving its passengers irrevocably changed by a single journey where illusions collapse and human truths emerge.', 'Tanim Noor', 153, '2026-03-21', 'P', 'bn', 'https://image.tmdb.org/t/p/w500/h6nITbbSobZ0EwU6Dcw6LGZOZYA.jpg', 'https://www.youtube.com/watch?v=ZTZUaHsfR8o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (256, 'Doctor Strange in the Multiverse of Madness', 'Doctor Strange, with the help of mystical allies both old and new, traverses the mind-bending and dangerous alternate realities of the Multiverse to confront a mysterious new adversary.', 'Sam Raimi', 126, '2022-05-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ddJcSKbcp4rKZTmuyWaMhuwcfMz.jpg', 'https://www.youtube.com/watch?v=Rf8LAYJSOL8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (257, 'Just Mercy', 'The powerful true story of Harvard-educated lawyer Bryan Stevenson, who goes to Alabama to defend the disenfranchised and wrongly condemned — including Walter McMillian, a man sentenced to death despite evidence proving his innocence. Bryan fights tirelessly for Walter with the system stacked against them.', 'Destin Daniel Cretton', 137, '2019-12-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2bDZl3PzFLFWe4gaFUQnnaslqT3.jpg', 'https://www.youtube.com/watch?v=GVQbeG5yW78', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (258, 'A Dog''s Journey', 'A dog finds the meaning of his own existence through the lives of the humans he meets.', 'Gail Mancuso', 109, '2019-05-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wquJChp0NpoqthYdE3YjXNNxvVC.jpg', 'https://www.youtube.com/watch?v=A2FrrSyyKfA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (259, 'Memoir of a Snail', 'Forcibly separated from her twin brother when they are orphaned, a melancholic misfit learns how to find confidence within herself amid the clutter of misfortunes and everyday life.', 'Adam Elliot', 94, '2024-10-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/woaN8CbloH0akyX0E72ayxlJAB4.jpg', 'https://www.youtube.com/watch?v=Ehc8cc7g31I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (260, 'Kadaisi Vivasayi', 'Maayandi, the only farmer in a village that has abandoned farming, is charged with a petty case that leads to his imprisonment.', 'M. Manikandan', 145, '2022-02-11', 'T13', 'ta', 'https://image.tmdb.org/t/p/w500/8TNnEojAEc8Kt6HMWgQNRPcL9J3.jpg', 'https://www.youtube.com/watch?v=cGorkMwcjd4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (261, 'Fantastic Beasts and Where to Find Them', 'In 1926, Newt Scamander arrives at the Magical Congress of the United States of America with a magically expanded briefcase, which houses a number of dangerous creatures and their habitats. When the creatures escape from the briefcase, it sends the American wizarding authorities after Newt, and threatens to strain even further the state of magical and non-magical relations.', 'David Yates', 133, '2016-11-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/h6NYfVUyM6CDURtZSnBpz647Ldd.jpg', 'https://www.youtube.com/watch?v=ViuDsy7yb8M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (262, 'The Tomorrow War', 'The world is stunned when a group of time travelers arrive from the year 2051 to deliver an urgent message: Thirty years in the future, mankind is losing a global war against a deadly alien species. The only hope for survival is for soldiers and civilians from the present to be transported to the future and join the fight. Among those recruited is high school teacher and family man Dan Forester. Determined to save the world for his young daughter, Dan teams up with a brilliant scientist and his estranged father in a desperate quest to rewrite the fate of the planet.', 'Chris McKay', 138, '2021-09-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/34nDCQZwaEvsy4CFO5hkGRFDCVU.jpg', 'https://www.youtube.com/watch?v=QPistcpGB8o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (263, 'In the Grey', 'A covert team of elite operatives are living in the shadows. When a ruthless despot steals a billion-dollar fortune, they''re sent to take it back—an impossible heist that erupts into a deadly game of strategy, deception and survival.', 'Guy Ritchie', 97, '2026-05-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dQgIcW6Th08kMRf2HBoYWoFE6OD.jpg', 'https://www.youtube.com/watch?v=nufP15iN4GE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (264, 'Louis Tomlinson: All of Those Voices', 'Ditching the typical glossy sheen of celebrity documentaries, this film gives audiences an intimate and unvarnished view of Louis Tomlinson''s life and career. Through never-before-seen home movie footage and behind the scenes access to Louis’ sell-out 2022 World Tour, the documentary offers a unique perspective on what it''s like to be a musician in today''s fast-paced world.', 'Charlie Lightening', 108, '2023-03-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ctYglXhhUh0Nhd99GRbeKZlakGJ.jpg', 'https://www.youtube.com/watch?v=K0UZuiqToow', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (265, 'The Black Phone', 'Finney Blake, a shy but clever 13-year-old boy, is abducted by a sadistic killer and trapped in a soundproof basement where screaming is of little use. When a disconnected phone on the wall begins to ring, Finney discovers that he can hear the voices of the killer’s previous victims. And they are dead set on making sure that what happened to them doesn’t happen to Finney.', 'Scott Derrickson', 103, '2022-06-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/p9ZUzCyy9wRTDuuQexkQ78R2BgF.jpg', 'https://www.youtube.com/watch?v=3eGP6im8AZA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (266, 'The Conjuring 2', 'Lorraine and Ed Warren travel to north London to help a single mother raising four children alone in a house plagued by malicious spirits.', 'James Wan', 134, '2016-06-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zEqyD0SBt6HL7W9JQoWwtd5Do1T.jpg', 'https://www.youtube.com/watch?v=VFsmuRPClr4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (267, 'Backrooms', 'A strange doorway appears in the basement of a furniture showroom.', 'Kane Parsons', 111, '2026-05-27', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', 'https://www.youtube.com/watch?v=0HjdiohVOik', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (268, 'Rule of Thirds', 'A successful high-end fashion photographer scouts a new model, who watches as their instant connection leads to dangerous consequences.', 'Patrick Flaherty', 108, '2024-06-28', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/wq6BPgEoobU5bvobSMgShynuUu3.jpg', 'https://www.youtube.com/watch?v=h3hvuY7JssM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (269, 'Ron''s Gone Wrong', 'In a world where walking, talking, digitally connected bots have become children''s best friends, an 11-year-old finds that his robot buddy doesn''t quite work the same as the others do.', 'Jean-Philippe Vine, Sarah Smith', 107, '2021-10-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/plzgQAXIEHm4Y92ktxU6fedUc0x.jpg', 'https://www.youtube.com/watch?v=8I8nMtzN05s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (270, 'Anatomy of a Fall', 'A woman is suspected of her husband''s murder, and their blind son faces a moral dilemma as the sole witness.', 'Justine Triet', 151, '2023-08-23', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/kQs6keheMwCxJxrzV83VUwFtHkB.jpg', 'https://www.youtube.com/watch?v=FUXawkH-ONM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (271, 'Shoplifters', 'In the outskirts of Tokyo, a poor but close-knit group living on the fringes of society survives through shoplifting and odd jobs. When Osamu and his son take in a neglected young girl, their already fragile existence begins to unravel. As the family grows attached to her, buried secrets surface, forcing them to confront the true meaning of love, belonging, and what makes a family.', 'Hirokazu Kore-eda', 120, '2018-06-02', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/4nfRUOv3LX5zLn98WS1WqVBk9E9.jpg', 'https://www.youtube.com/watch?v=9382rwoMiRc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (272, 'Sing Street', 'A boy growing up in Dublin during the 1980s escapes his strained family life by starting a band to impress the mysterious girl he likes.', 'John Carney', 105, '2016-03-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/sUWpVlrvzU2SJbnVZqIeKulPKwk.jpg', 'https://www.youtube.com/watch?v=TxT30uAoSHA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (273, 'TAYLOR SWIFT | THE ERAS TOUR', 'A concert film documenting Taylor Swift''s record-breaking Eras Tour (2023-2024). Filmed during the Los Angeles shows, the film captures the tour''s ten acts, each representing a different musical era from Swift''s career. The film showcases over 40 songs, elaborate stage productions, and Swift''s performance.', 'Sam Wrench', 169, '2023-10-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jf3YO8hOqGHCupsREf5qymYq1n.jpg', 'https://www.youtube.com/watch?v=5UBl0rLEl0w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (274, 'Yesterday''s Past', 'After returning to his drowned village in search of his family, Gunu finds himself haunted by the past as another cyclone approaches, pulling him into a journey through grief, memory, and the eye of the storm.', 'Nila Madhab Panda', 83, '2020-11-06', 'P', 'or', 'https://image.tmdb.org/t/p/w500/eVNraGPgkJULAgX1863uhiFYho6.jpg', 'https://www.youtube.com/watch?v=gTijL47CNfk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (275, 'The Housemaid', 'Trying to escape her past, Millie Calloway accepts a job as a live-in housemaid for the wealthy Nina and Andrew Winchester. But what begins as a dream job quickly unravels into something far more dangerous—a sexy, seductive game of secrets, scandal, and power.', 'Paul Feig', 131, '2025-12-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cWsBscZzwu5brg9YjNkGewRUvJX.jpg', 'https://www.youtube.com/watch?v=48CtX6OgU3s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (276, 'Onward', 'In a suburban fantasy world, two teenage elf brothers embark on an extraordinary quest to discover if there is still a little magic left out there.', 'Dan Scanlon', 102, '2020-02-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/f4aul3FyD3jv3v4bul1IrkWZvzq.jpg', 'https://www.youtube.com/watch?v=A5Z7QsRGxGo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (277, 'Monster', 'After an outburst at school involving her son, a concerned single mother demands answers, triggering a sequence of deepening suspicion and turmoil.', 'Hirokazu Kore-eda', 125, '2023-06-02', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/kvUJUyUGOhEoiWWNH04IXoExPE2.jpg', 'https://www.youtube.com/watch?v=Y8_KfdcIMBY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (278, 'Loving Vincent', 'A young man arrives at the last hometown of painter Vincent van Gogh to deliver the troubled artist''s final letter and ends up investigating his final days there.', 'DK Welchman, Hugh Welchman', 95, '2017-06-22', 'K', 'en', 'https://image.tmdb.org/t/p/w500/56sq57kDm7XgyXBYrgJLumo0Jac.jpg', 'https://www.youtube.com/watch?v=2ZX7OANSoAg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (279, 'Atithi Bhooto Bhava', 'Srikant''s life turns upside down when he bumps into a middle-aged ghost who claims to be his grandson from his previous birth. Things take an even more comical turn when the ghost seeks Srikant''s help to meet his long-lost love.', 'Hardik Gajjar', 113, '2022-09-23', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/7hdFezTGLhBCmhuM34lbXRwegy4.jpg', 'https://www.youtube.com/watch?v=LzIKi4d7QSg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (280, 'Drawing Closer', 'With only a year left to live, 17-year-old Akito finds new meaning in life by bringing joy to a terminally ill girl who has just six months remaining.', 'Takahiro Miki', 119, '2024-06-26', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/173FD4a0rpSF30z4CoWx6qdx8Ry.jpg', 'https://www.youtube.com/watch?v=WMpngmDc7Sg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (281, 'Babylon', 'A tale of outsized ambition and outrageous excess, tracing the rise and fall of multiple characters in an era of unbridled decadence and depravity during Hollywood''s transition from silent films to sound films in the late 1920s.', 'Damien Chazelle', 189, '2022-12-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wjOHjWCUE0YzDiEzKv8AfqHj3ir.jpg', 'https://www.youtube.com/watch?v=5muQK7CuFtY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (282, 'Falling in Love Like in Movies', 'Bagus, a screenwriter, reunites with his high school friend and crush, Hana, who is still grieving from the loss of her husband. He wants to convince her to fall in love once again, just like in the movies.', 'Yandy Laurens', 118, '2023-11-30', 'K', 'id', 'https://image.tmdb.org/t/p/w500/nWslpGqZnSvpX2UxOkg7pespZOA.jpg', 'https://www.youtube.com/watch?v=FmsljtjpvpU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (283, '12th Fail', 'Based on the true story of IPS officer Manoj Kumar Sharma, 12th Fail sheds limelight on fearlessly embracing the idea of restarting the academic journey despite the setbacks and challenges and reclaiming one''s destiny at a place where millions of students attempt the world''s toughest competitive exam: UPSC.', 'Vidhu Vinod Chopra', 146, '2023-08-11', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/eebUPRI4Z5e1Z7Hev4JZAwMIFkX.jpg', 'https://www.youtube.com/watch?v=KjbtuqENvVE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (284, 'Ready or Not: Here I Come', 'Moments after surviving an all-out attack from the Le Domas family, Grace discovers she’s reached the next level of the nightmarish game — and this time with her estranged sister Faith at her side. Grace has one chance to survive, keep her sister alive, and claim the High Seat of the Council that controls the world. Four rival families are hunting her for the throne, and whoever wins rules it all.', 'Matt Bettinelli-Olpin, Tyler Gillett', 108, '2026-03-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/13ZcJzSGEqVgDSqsS9U5EkQwPkV.jpg', 'https://www.youtube.com/watch?v=7K3sNRm8J0w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (285, 'A Quiet Place Part II', 'Following the events at home, the Abbott family now face the terrors of the outside world. Forced to venture into the unknown, they realize that the creatures that hunt by sound are not the only threats that lurk beyond the sand path.', 'John Krasinski', 97, '2021-05-21', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4q2hz2m8hubgvijz8Ez0T2Os2Yv.jpg', 'https://www.youtube.com/watch?v=BpdDN9d9Jio', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (286, 'Counterattack', 'When a hostage rescue mission creates a new enemy, Capt. Guerrero and his elite soldiers must face an ambush by a criminal group.', 'Chava Cartas', 85, '2025-02-27', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/kxnFdLJhi37ZVFDCL1ka0yeQVU5.jpg', 'https://www.youtube.com/watch?v=pEO34SeTsY0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (287, 'The Lighthouse', 'Two lighthouse keepers try to maintain their sanity while living on a remote and mysterious New England island in the 1890s.', 'Robert Eggers', 109, '2019-10-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yAKNmpcUweGH6WMCEWenwU9PsbE.jpg', 'https://www.youtube.com/watch?v=42_UHhpq530', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (288, 'Split', 'Though Kevin has evidenced 23 personalities to his trusted psychiatrist, Dr. Fletcher, there remains one still submerged who is set to materialize and dominate all the others. Compelled to abduct three teenage girls led by the willful, observant Casey, Kevin reaches a war for survival among all of those contained within him — as well as everyone around him — as the walls between his compartments shatter apart.', 'M. Night Shyamalan', 117, '2017-01-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/ow2BSQGKJtZpH2zZY1rmX8eXKAi.jpg', 'https://www.youtube.com/watch?v=6bfooooTKyM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (289, 'My Hero Academia: Heroes Rising', 'Class 1-A visits Nabu Island where they finally get to do some real hero work. The place is so peaceful that it''s more like a vacation... until they''re attacked by a villain with an unfathomable Quirk! His power is eerily familiar, and it looks like Shigaraki had a hand in the plan. But with All Might retired and citizens'' lives on the line, there''s no time for questions. Deku and his friends are the next generation of heroes, and they''re the island''s only hope.', 'Kenji Nagasaki', 104, '2019-12-20', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/kpWsIkfXrnQ1pmR79qAHHq7DPxc.jpg', 'https://www.youtube.com/watch?v=W6LxpZeIxNQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (290, 'Wind River', 'An FBI agent teams with the town''s veteran game tracker to investigate a murder that occurred on a Native American reservation.', 'Taylor Sheridan', 107, '2017-08-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pySivdR845Hom4u4T2WNkJxe6Ad.jpg', 'https://www.youtube.com/watch?v=E0qRHABxvfc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (291, 'Pappa Tamne Nahi Samjaay', 'The generation gap between a 56-year-old father and an 18-year-old son results in misunderstanding, distance, and tension between them. A family entertainer, Pappa Tamne Nahi Samjaay has the right balance of comedy and drama, featuring the emotional bond the two protagonists share.', 'Dharmesh Metha', 134, '2017-08-25', 'P', 'gu', 'https://image.tmdb.org/t/p/w500/sYI1nHDnAU971aKI1n67ndnLaPn.jpg', 'https://www.youtube.com/watch?v=RncSm40YlIU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (292, 'Life in a Year', 'A 17 year old finds out that his girlfriend is dying, so he sets out to give her an entire life, in the last year she has left.', 'Mitja Okorn', 107, '2020-11-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/bP7u19opmHXYeTCUwGjlLldmUMc.jpg', 'https://www.youtube.com/watch?v=BgmJ14p4Uuk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (293, 'Ennio', 'A portrait of Ennio Morricone, the most popular and prolific film composer of the 20th century, the one most loved by the international public, a two-time Oscar winner and the author of over five hundred unforgettable scores.', 'Giuseppe Tornatore', 156, '2022-02-17', 'P', 'it', 'https://image.tmdb.org/t/p/w500/lEuLAubp74HYztEyNYpEx3AoqOu.jpg', 'https://www.youtube.com/watch?v=q5WBbULw_0U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (294, 'How to Make Millions Before Grandma Dies', 'M, a university dropout low on money and luck, volunteers to take care of his terminally ill grandmother, in the hope of pocketing an inheritance.', 'Pat Boonnitipat', 126, '2024-04-04', 'K', 'th', 'https://image.tmdb.org/t/p/w500/9Xa0Grd2jq2lM2gqcoTB4F9TjMd.jpg', 'https://www.youtube.com/watch?v=HrVX_nHNIUA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (295, '20 Days in Mariupol', 'As the Russian invasion begins, a team of Ukrainian journalists trapped in the besieged city of Mariupol struggle to continue their work documenting the war''s atrocities.', 'Mstyslav Chernov', 94, '2023-07-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zIRp1IeuPh4GgqFCH3y0DQuY9xP.jpg', 'https://www.youtube.com/watch?v=9H_Fg_5x4ME', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (296, 'Roma', 'In 1970s Mexico City, two domestic workers help a mother of four while her husband is away for an extended period of time.', 'Alfonso Cuarón', 135, '2018-11-21', 'T13', 'es', 'https://image.tmdb.org/t/p/w500/dtIIyQyALk57ko5bjac7hi01YQ.jpg', 'https://www.youtube.com/watch?v=6BS27ngZtxg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (297, 'Mortal Kombat Legends: Scorpion''s Revenge', 'After the vicious slaughter of his family by stone-cold mercenary Sub-Zero, Hanzo Hasashi is exiled to the torturous Netherrealm. There, in exchange for his servitude to the sinister Quan Chi, he’s given a chance to avenge his family – and is resurrected as Scorpion, a lost soul bent on revenge. Back on Earthrealm, Lord Raiden gathers a team of elite warriors – Shaolin monk Liu Kang, Special Forces officer Sonya Blade, and action star Johnny Cage – an unlikely band of heroes with one chance to save humanity. To do this, they must defeat Shang Tsung''s horde of Outworld gladiators and reign over the Mortal Kombat tournament.', 'Ethan Spaulding', 80, '2020-04-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iBvo3qOPcmhlqAaJcXcQHtx2qLk.jpg', 'https://www.youtube.com/watch?v=P87QXvvav7Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (298, 'The Substance', 'A fading celebrity decides to use a black market drug, a cell-replicating substance that temporarily creates a younger, better version of herself.', 'Coralie Fargeat', 141, '2024-09-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lqoMzCcZYEFK729d6qzt349fB4o.jpg', 'https://www.youtube.com/watch?v=LNlrGhBpYjc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (299, 'Predator: Killer of Killers', 'While three of the fiercest warriors in human history—a Viking raider, a ninja in feudal Japan, and a WWII pilot—are killers in their own right, they are merely prey for their new opponent: the ultimate killer of killers.', 'Dan Trachtenberg', 85, '2025-06-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2XDQa6EmFHSA37j1t0w88vpWqj9.jpg', 'https://www.youtube.com/watch?v=eWzPKrNoSyM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (300, 'Robot Dreams', 'A lonely dog''s friendship with his robot companion takes a sad turn when an unexpected malfunction forces him to abandon Robot at the beach. Will Dog ever meet Robot again?', 'Pablo Berger', 102, '2023-12-06', 'T13', 'es', 'https://image.tmdb.org/t/p/w500/ds402Qq09ybgBcXKiQNTZfzsP5o.jpg', 'https://www.youtube.com/watch?v=0CHV_ZDlhrA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (301, 'The Bad Guys', 'When the Bad Guys, a crew of criminal animals, are finally caught after years of heists and being the world’s most-wanted villains, Mr. Wolf brokers a deal to save them all from prison.', 'Pierre Perifel', 100, '2022-03-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7qop80YfuO0BwJa1uXk1DXUUEwv.jpg', 'https://www.youtube.com/watch?v=m8Xt0yXaDPU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (302, 'You Are the Apple of My Eye', 'A group of close friends who attend a private school all have a debilitating crush on the sunny star pupil, Sun-ah. The only member of the group who claims not to is Jin-woo, but he ends up loving her as well.', 'Cho Young-myoung', 102, '2025-02-21', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/bBnyDM1gWBLd91K245iVKH19t42.jpg', 'https://www.youtube.com/watch?v=uWm6p2j_ixk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (303, 'It', 'In a small town in Maine, seven children known as The Losers Club come face to face with life problems, bullies and a monster that takes the shape of a clown called Pennywise.', 'Andy Muschietti', 135, '2017-09-06', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/9E2y5Q7WlCVNEhP5GiVTjhEhx1o.jpg', 'https://www.youtube.com/watch?v=FnCdOQsX5kc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (304, 'Luck', 'Suddenly finding herself in the never-before-seen Land of Luck, the unluckiest person in the world must unite with the magical creatures there to turn her luck around.', 'Peggy Holmes', 105, '2022-08-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1HOYvwGFioUFL58UVvDRG6beEDm.jpg', 'https://www.youtube.com/watch?v=xSG5UX0EQVg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (305, 'The Favourite', 'England, early 18th century. The close relationship between Queen Anne and Sarah Churchill is threatened by the arrival of Sarah''s cousin, Abigail Hill, resulting in a bitter rivalry between the two cousins to be the Queen''s favourite.', 'Yorgos Lanthimos', 120, '2018-11-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cwBq0onfmeilU5xgqNNjJAMPfpw.jpg', 'https://www.youtube.com/watch?v=SYb-wkehT1g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (306, 'Hereditary', 'Following the death of the Leigh family matriarch, Annie and her children uncover disturbing secrets about their heritage. Their daily lives are not only impacted, but they also become entangled in a chilling fate from which they cannot escape, driving them to the brink of madness.', 'Ari Aster', 128, '2018-06-07', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4GFPuL14eXi66V96xBWY73Y9PfR.jpg', 'https://www.youtube.com/watch?v=MJNR58zaStE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (307, 'Marty Supreme', 'Marty Mauser, a young man with a dream no one respects, goes to hell and back in pursuit of greatness.', 'Josh Safdie', 150, '2025-12-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lYWEXbQgRTR4ZQleSXAgRbxAjvq.jpg', 'https://www.youtube.com/watch?v=s9gSuKaKcqM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (308, 'The Trial of the Chicago 7', 'What was supposed to be a peaceful protest turned into a violent clash with the police. What followed was one of the most notorious trials in history.', 'Aaron Sorkin', 130, '2020-09-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ahf5cVdooMAlDRiJOZQNuLqa1Is.jpg', 'https://www.youtube.com/watch?v=FVb6EdKDBfU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (309, 'Wonder Woman', 'An Amazon princess comes to the world of Man in the grips of the First World War to confront the forces of evil and bring an end to human conflict.', 'Patty Jenkins', 141, '2017-05-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/v4ncgZjG2Zu8ZW5al1vIZTsSjqX.jpg', 'https://www.youtube.com/watch?v=1Q8fG0TtVAY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (310, 'Thirteen Lives', 'Based on the true nail-biting mission that captivated the world. Twelve boys and the coach of a Thai soccer team explore the Tham Luang cave when an unexpected rainstorm traps them in a chamber inside the mountain. Entombed behind a maze of flooded cave tunnels, they face impossible odds. A team of world-class divers navigate through miles of dangerous cave networks to discover that finding the boys is only the beginning.', 'Ron Howard', 147, '2022-07-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yi5KcJqFxy0D6yP8nCfcF8gJGg5.jpg', 'https://www.youtube.com/watch?v=R068Si4eb3Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (311, 'Super Heroes The Movie', 'After a bad breakup, Wonderful Woman and Superbman, must work together with the super crew to prevent world domination by an invincible super villain from the 5th dimension named Bob. Shot in 1998, this superhero parody stars Lisa Guerrero as Wonderful Woman, Ric Borelli as Superbman and Kevin Glikmann as Bob. Siskel and Ebert would have said, it''s so campy the marshmallows cook themselves.', 'Wesley Wittkamper', 80, '2021-02-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/homwymbPU1R4lde7iX8TtjiAIS4.jpg', 'https://www.youtube.com/watch?v=U5L7cBHcp8I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (312, 'Along with the Gods: The Two Worlds', 'Having died unexpectedly, firefighter Ja-hong is taken to the afterlife by 3 afterlife guardians. Only when he passes 7 trials over 49 days and proves he was innocent in human life, he’s able to reincarnate, and his 3 afterlife guardians are by his side to defend him in trial.', 'Kim Yong-hwa', 139, '2017-12-20', 'T18', 'ko', 'https://image.tmdb.org/t/p/w500/gJSvIsI6oQfFim0PGyuuiCYfqKs.jpg', 'https://www.youtube.com/watch?v=dyh_OY1DgqU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (313, 'Moana', 'In Ancient Polynesia, when a terrible curse incurred by Maui reaches an impetuous Chieftain''s daughter''s island, she answers the Ocean''s call to seek out the demigod to set things right.', 'John Musker, Ron Clements', 107, '2016-10-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4JeejGugONWpJkbnvL12hVoYEDa.jpg', 'https://www.youtube.com/watch?v=C6PbWhWGUrY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (314, 'The Fall of Minneapolis', 'Based on Liz Collin’s Amazon bestseller, “They’re Lying: The Media, The Left, and The Death of George Floyd,” which exposes the holes in the prevailing narrative surrounding George Floyd’s death, the trial of Derek Chauvin, and the fallout the city of Minneapolis has suffered ever since.', 'JC Chaix', 102, '2023-11-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/MWPp4Uz9ZUQZewQVJ4ScXN3nSu.jpg', 'https://www.youtube.com/watch?v=Cxc7wCEVSa0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (315, 'Dungeons & Dragons: Honor Among Thieves', 'A charming thief and a band of unlikely adventurers undertake an epic heist to retrieve a lost relic, but things go dangerously awry when they run afoul of the wrong people.', 'John Francis Daley, Jonathan Goldstein', 134, '2023-03-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/v7UF7ypAqjsFZFdjksjQ7IUpXdn.jpg', 'https://www.youtube.com/watch?v=9LLOLEBlVIA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (316, 'The Voice of Hind Rajab', 'January 29, 2024. Red Crescent volunteers receive an emergency call. A five-year old girl is trapped in a car under fire in Gaza, pleading for rescue. While trying to keep her on the line, they do everything they can to get an ambulance to her. Her name was Hind Rajab.', 'Kaouther Ben Hania', 89, '2025-09-10', 'T13', 'ar', 'https://image.tmdb.org/t/p/w500/q7M8kQB46T11vmDMD6E239jsqTz.jpg', 'https://www.youtube.com/watch?v=JkeKrG0YONQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (317, 'Radical', 'In a Mexican border town plagued by neglect, corruption, and violence, a frustrated teacher tries an unorthodox new method to break through his students’ apathy and unlock their curiosity, their potential... and perhaps even their genius.', 'Christopher Zalla', 125, '2023-10-19', 'P', 'es', 'https://image.tmdb.org/t/p/w500/lOAJYpX608aT0ApIv63ZTnol27Y.jpg', 'https://www.youtube.com/watch?v=BXcGgvAKC1Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (318, 'Steven Universe: The Movie', 'Two years after bringing peace to the galaxy, Steven Universe sees his past come back to haunt him in the form of a deranged Gem who wants to destroy the Earth.', 'Rebecca Sugar', 83, '2019-10-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8mRgpubxHqnqvENK4Bei30xMDvy.jpg', 'https://www.youtube.com/watch?v=9FGyVAIRI-4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (319, 'Sound of Metal', 'Metal drummer Ruben begins to lose his hearing. When a doctor tells him his condition will worsen, he thinks his career and life is over. His girlfriend Lou checks the former addict into a rehab for the deaf hoping it will prevent a relapse and help him adapt to his new life. After being welcomed and accepted just as he is, Ruben must choose between his new normal and the life he once knew.', 'Darius Marder', 121, '2020-11-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3178oOJKKPDeQ2legWQvMPpllv.jpg', 'https://www.youtube.com/watch?v=VFOrGkAvjAE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (320, 'Another Round', 'Four stagnant high school teachers decide to test out a theory that maintaining a constant level of intoxication will improve their overall lives.', 'Thomas Vinterberg', 117, '2020-09-24', 'T13', 'da', 'https://image.tmdb.org/t/p/w500/aDcIt4NHURLKnAEu7gow51Yd00Q.jpg', 'https://www.youtube.com/watch?v=xlwAgvn1e5E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (321, 'The Beekeeper', 'One man''s campaign for vengeance takes on national stakes after he is revealed to be a former operative of a powerful and clandestine organization known as Beekeepers.', 'David Ayer', 106, '2024-01-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/A7EByudX0eOzlkQ2FIbogzyazm2.jpg', 'https://www.youtube.com/watch?v=CHKn-yDCE2w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (322, 'Tenet', 'Armed with only one word - Tenet - and fighting for the survival of the entire world, the Protagonist journeys through a twilight world of international espionage on a mission that will unfold in something beyond real time.', 'Christopher Nolan', 150, '2020-08-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/aCIFMriQh8rvhxpN1IWGgvH0Tlg.jpg', 'https://www.youtube.com/watch?v=AZGcmvrTX9M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (323, 'Nuremberg', 'In postwar Germany, an American psychiatrist must determine whether Nazi prisoners are fit to go on trial for war crimes, and finds himself in a complex battle of intellect and ethics with Hermann Göring, Hitler''s right-hand man.', 'James Vanderbilt', 149, '2025-11-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xthXNYltOOm80vW5Kxjzxx5gvQ6.jpg', 'https://www.youtube.com/watch?v=WvAy9C-bipY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (324, 'Behind Closed Doors', 'Politically Exposed Persons (PEPs) are people who hold a public function and as a result, present higher risks of being involved in bribery or corruption. Offshore leaks have revealed repeatedly that PEPs use British finance and British offshore jurisdictions to launder their wealth, hide their wealth and re-invest it into the global financial system. London is the place where they buy property, where they take legal action against their critics and where they live when they fall from grace. But what happens when a developing country fights back and attempts to get Britain to return the money that it claims has been stolen? Watch Behind Closed Doors and find out.', 'Michael Oswald', 64, '2023-05-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uXTZR5N4NWZJNsTfqoS7zyHpuFC.jpg', 'https://www.youtube.com/watch?v=JUpgQZvrZKc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (325, 'Josee, the Tiger and the Fish', 'With dreams of diving abroad, Tsuneo gets a job assisting Josee, an artist whose imagination takes her far beyond her wheelchair. But when the tide turns against them, they push each other to places they never thought possible, and inspire a love fit for a storybook.', 'Kotaro Tamura', 98, '2020-12-25', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/z1D8xi9x4uEhyFruo7uEHXUMD4K.jpg', 'https://www.youtube.com/watch?v=QvgpMxoyDds', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (326, 'Pressure', 'In the tense 72 hours before D-Day, and the fate of the free world hanging in the balance, General Dwight D. Eisenhower and Captain James Stagg face an impossible choice—launch the largest and most dangerous seaborne invasion in history or risk losing the war altogether.', 'Anthony Maras', 101, '2026-05-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gFjEggtrejCN79r6SXRjM269OtG.jpg', 'https://www.youtube.com/watch?v=EBh1LGRwiis', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (327, 'Finch', 'On a post-apocalyptic Earth, a robot, built to protect the life of his dying creator''s beloved dog, learns about life, love, friendship, and what it means to be human.', 'Miguel Sapochnik', 116, '2021-11-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eEJtzD1F05xDipFEDY98CTH5yZn.jpg', 'https://www.youtube.com/watch?v=-0bYWnP3jH4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (328, 'A Taxi Driver', 'May, 1980. Man-seob is a taxi driver in Seoul who lives from hand to mouth, raising his young daughter alone. One day, he hears that there is a foreigner who will pay big money for a drive down to Gwangju city. Not knowing that he’s a German journalist with a hidden agenda, Man-seob takes the job.', 'Jang Hoon', 138, '2017-08-02', 'T13', 'ko', 'https://image.tmdb.org/t/p/w500/iXVaWbxmyPk4KZGZk5GGDGFieMX.jpg', 'https://www.youtube.com/watch?v=bB7z4Xn5oNA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (329, 'Free Solo', 'Follow Alex Honnold as he attempts to become the first person to ever free solo climb Yosemite''s 3,000 foot high El Capitan wall. With no ropes or safety gear, this would arguably be the greatest feat in rock climbing history.', 'Elizabeth Chai Vasarhelyi, Jimmy Chin', 100, '2018-09-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/v4QfYZMACODlWul9doN9RxE99ag.jpg', 'https://www.youtube.com/watch?v=urRVZ4SW7WU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (330, 'Hunt for the Wilderpeople', 'Ricky is a defiant young city kid who finds himself on the run with his cantankerous foster uncle in the wild New Zealand bush. A national manhunt ensues, and the two are forced to put aside their differences and work together to survive.', 'Taika Waititi', 101, '2016-01-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hkmz9rxgcweizXNElozGeKwmAJE.jpg', 'https://www.youtube.com/watch?v=XTk3DpccpUY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (331, 'Mission: Impossible - The Final Reckoning', 'Ethan Hunt and team continue their search for the terrifying AI known as the Entity — which has infiltrated intelligence networks all over the globe — with the world''s governments and a mysterious ghost from Hunt''s past on their trail. Joined by new allies and armed with the means to shut the Entity down for good, Hunt is in a race against time to prevent the world as we know it from changing forever.', 'Christopher McQuarrie', 170, '2025-05-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iKPsC9EFUafRP9SrUznI61getVP.jpg', 'https://www.youtube.com/watch?v=G1VBfMCZVkw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (332, 'Black Widow', 'Natasha Romanoff, also known as Black Widow, confronts the darker parts of her ledger when a dangerous conspiracy with ties to her past arises. Pursued by a force that will stop at nothing to bring her down, Natasha must deal with her history as a spy and the broken relationships left in her wake long before she became an Avenger.', 'Cate Shortland', 134, '2021-07-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qAZ0pzat24kLdO3o8ejmbLxyOac.jpg', 'https://www.youtube.com/watch?v=Fp9pNPdNwjI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (333, 'Kubo and the Two Strings', 'Kubo mesmerizes the people in his village with his magical gift for spinning wild tales with origami. When he accidentally summons an evil spirit seeking vengeance, Kubo is forced to go on a quest to solve the mystery of his fallen samurai father and his mystical weaponry, as well as discover his own magical powers.', 'Travis Knight', 102, '2016-08-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/la6QA9tk4Foq8OBH2Dyh5dTcw6H.jpg', 'https://www.youtube.com/watch?v=Pz49Ml_rB34', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (334, 'The Bad Guys 2', 'The now-reformed Bad Guys are trying (very, very hard) to be good, but instead find themselves hijacked into a high-stakes, globe-trotting heist, masterminded by a new team of criminals they never saw coming: The Bad Girls.', 'Pierre Perifel', 104, '2025-07-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/26oSPnq0ct59l07QOXZKyzsiRtN.jpg', 'https://www.youtube.com/watch?v=HvLHYox_Vq8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (335, 'Wish Dragon', 'Determined teen Din is longing to reconnect with his childhood best friend when he meets a wish-granting dragon who shows him the magic of possibilities.', 'Chris Appelhans', 99, '2021-01-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lnPf6hzANL6pVQTxUlsNYSuhT5l.jpg', 'https://www.youtube.com/watch?v=uWIRyU5fuzU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (336, 'King Richard', 'The story of how Richard Williams served as a coach to his daughters Venus and Serena, who will soon become two of the most legendary tennis players in history.', 'Reinaldo Marcus Green', 144, '2021-11-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vjpMd1dsEsVBoUhq6iVHXwwFj9n.jpg', 'https://www.youtube.com/watch?v=BKP_0z52ZAw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (337, 'To All the Boys I''ve Loved Before', 'Lara Jean''s love life goes from imaginary to out of control when her secret letters to every boy she''s ever fallen for are mysteriously mailed out.', 'Susan Johnson', 100, '2018-08-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hKHZhUbIyUAjcSrqJThFGYIR6kI.jpg', 'https://www.youtube.com/watch?v=555oiY9RWM4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (338, 'The Banshees of Inisherin', 'Two lifelong friends find themselves at an impasse when one abruptly ends their relationship, with alarming consequences for both of them.', 'Martin McDonagh', 114, '2022-10-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4yFG6cSPaCaPhyJ1vtGOtMD1lgh.jpg', 'https://www.youtube.com/watch?v=9-R9u2UD3FU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (339, 'Flamin'' Hot', 'The inspiring true story of Richard Montañez, the Frito Lay janitor who channeled his Mexican American heritage and upbringing to turn the iconic Flamin'' Hot Cheetos into a snack that disrupted the food industry and became a global pop culture phenomenon.', 'Eva Longoria', 99, '2023-03-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/a7KyFMPXj0iY4EoLq1PIGU1WJPw.jpg', 'https://www.youtube.com/watch?v=it7sNRloq-A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (340, 'Iron Maiden: Burning Ambition', 'With unprecedented access to the official archives and intimate recollections from the band, both current and past, Iron Maiden: Burning Ambition invites fans to experience one of the most iconic journeys in music history. Spanning five decades, this electrifying documentary charts the band’s rise from the pubs of East London to the world’s biggest stadiums. Featuring exclusive interviews with band members and contributors such as Javier Bardem, Lars Ulrich and Chuck D, as well as all-new animated sequences of the band''s legendary mascot, Eddie, the film offers a rare and intimate look at Iron Maiden’s uncompromising vision and unwavering connection with their truly global army of fans.', 'Malcolm Venville', 105, '2026-05-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/yZqhFJDenLfgF1VygOOCNmAdS1P.jpg', 'https://www.youtube.com/watch?v=pD_H2u79tp0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (341, 'Upgrade', 'A brutal mugging leaves Grey Trace paralyzed in the hospital and his beloved wife dead. A billionaire inventor soon offers Trace a cure — an artificial intelligence implant called STEM that will enhance his body. Now able to walk, Grey finds that he also has superhuman strength and agility — skills he uses to seek revenge against the thugs who destroyed his life.', 'Leigh Whannell', 100, '2018-05-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/woLGROUdPWdBnLVFKYdGD3kFkPY.jpg', 'https://www.youtube.com/watch?v=1hTLGlgZ4Z8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (342, 'Thriller 40', 'Forty years after the release of Michael Jackson’s ‘Thriller,’ the best-selling album of all-time, director Nelson George takes fans back in time to the making of a pop masterpiece, featuring never-before-seen footage and candid interviews.', 'Nelson George', 89, '2023-12-02', 'K', 'en', 'https://image.tmdb.org/t/p/w500/5LOKk1Ca1YaCb3EjTEMDJdPbQxN.jpg', 'https://www.youtube.com/watch?v=xyJJnzHr96c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (343, 'Tetris', 'In 1988, American video game salesman Henk Rogers discovers the video game Tetris. When he sets out to bring the game to the world, he enters a dangerous web of lies and corruption behind the Iron Curtain.', 'Jon S. Baird', 118, '2023-03-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4F2QwCOYHJJjecSvdOjStuVLkpu.jpg', 'https://www.youtube.com/watch?v=-BLM1naCfME', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (344, 'Turning Red', 'Thirteen-year-old Mei is experiencing the awkwardness of being a teenager with a twist – when she gets too excited, she transforms into a giant red panda.', 'Domee Shi', 100, '2022-03-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qsdjk9oAKSQMWs0Vt5Pyfh6O4GZ.jpg', 'https://www.youtube.com/watch?v=XdKzUbAiswE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (345, 'A Dog''s Purpose', 'A dog goes on quest to discover his purpose in life over the course of several lifetimes with multiple owners.', 'Lasse Hallström', 100, '2017-01-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3jcNvhtVQe5Neoffdic39fRactM.jpg', 'https://www.youtube.com/watch?v=1jLOOCADTGs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (346, 'Hans Zimmer: Live in Prague', 'Hans Zimmer is one of the most successful film music composers working today. His multi-award winning career reaches back to the mid-eighties and he has developed close working relationships with renowned directors such as Ridley Scott, Tony Scott, Michael Bay, Ron Howard, Gore Verbinski and Christopher Nolan. His credits include some of the biggest blockbuster movies of all time along with acclaimed TV series such as The Crown and Planet Earth II. This concert was filmed on 7th May 2016 in Prague during Hans Zimmer’s hugely successful European concert tour. Hans was accompanied by a band, orchestra and choir, 72 musicians in total, including guitarist Johnny Marr. The staging was spectacular with a ground breaking light show, stunning visuals and a state of the art sound system. Hans Zimmer performs on multiple instruments and gives introductory insights to many of the pieces during the concert. This show is a treat for lovers of both great music and great movies.', 'Tim Van Someren', 139, '2017-10-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hHs54DFWuXJqh1XmYZVDsiiVHS8.jpg', 'https://www.youtube.com/watch?v=7reir6nGoD4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (347, 'Better Days', 'A bullied teenage girl forms an unlikely friendship with a mysterious young man who protects her from her assailants, while she copes with the pressures of her final examinations.', 'Derek Tsang Kwok-Cheung', 135, '2019-10-25', 'T16', 'zh', 'https://image.tmdb.org/t/p/w500/csVZ2ZQCj98XdZoCuW1aixMYJ0W.jpg', 'https://www.youtube.com/watch?v=mXYifqtNj38', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (348, 'Attack on Titan: The Roar of Awakening', 'Eren Yeager and others of the 104th Training Corps have just begun to become full members of the Survey Corps. As they ready themselves to face the Titans once again, their preparations are interrupted by the invasion of Wall Rose—but all is not as it seems as more mysteries are unraveled. As the Survey Corps races to save the wall, they uncover more about the invading Titans and the dark secrets of their own members.', 'Masashi Koizuka, Tetsuro Araki', 120, '2018-01-13', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/tLkdCvfmTOvxirrpSaaOBJD7qsU.jpg', 'https://www.youtube.com/watch?v=NO079o58Vgg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (349, 'Forgotten', 'Jin-seok, 21-year-old, moves into a new house with his family. He suffers from a slight schizophrenia but he carries an ordinary life under the warm care of the family. His older brother Yu-seok is a decent college student, a mentor, and role model for Jin-seok. One night, his beloved brother is kidnapped by unidentified assailants before Jin-seok''s eye. Jin-seok can’t recognize their faces, but can remember only the VIN that matches with no car. After long silence of 19 days, suddenly Yu-seok returns home, but remembers nothing which had happened in the meantime. And soon Jin-seok feels Yu-seok is a total stranger.', 'Chang Hang-jun', 108, '2017-11-29', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/cBgj41y1RvmW1zJCEX0uNWL0UjW.jpg', 'https://www.youtube.com/watch?v=i5fAD6PqBMQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (350, 'The Quintessential Quintuplets Movie', 'When five lovely young girls who hate studying hire part-time tutor Futaro, he guides not only their education but also their hearts. Time spent has brought them all closer, with feelings growing within the girls and Futaro. As they finish their third year of high school and their last school festival approaches, they set their sights on what’s next. Is there a future with one of them and Futaro?', 'Masato Jimbo', 136, '2022-05-20', 'K', 'ja', 'https://image.tmdb.org/t/p/w500/sg7klpt1xwK1IJirBI9EHaqQwJ5.jpg', 'https://www.youtube.com/watch?v=maS5nHFa1o8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (351, 'The Eighth Sense', 'A shy art student joins a surfing club—and falls for the senior who teaches him more than just how to ride the waves.', 'Inu Baek, Werner du Plessis', 118, '2023-03-29', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/dVntReaq2jaKalinalwoCkIReC6.jpg', 'https://www.youtube.com/watch?v=s4p1S6-iyGs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (352, 'Billie Eilish: The World''s a Little Blurry', 'This documentary offers a deeply intimate look at extraordinary teenager Billie Eilish. Award-winning filmmaker R.J. Cutler follows her journey on the road, onstage, and at home with her family as the writing and recording of her debut album changes her life.', 'R.J. Cutler', 140, '2021-02-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/bDQ95W5LPHW9FHlPj3QX3jvM9Z7.jpg', 'https://www.youtube.com/watch?v=7JUQvUv7QxY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (353, 'No Other Land', 'This film made by a Palestinian-Israeli collective shows the destruction of the occupied West Bank''s Masafer Yatta by Israeli soldiers and the alliance which develops between the Palestinian activist Basel and Israeli journalist Yuval.', 'Basel Adra, Hamdan Ballal, Rachel Szor, Yuval Abraham', 92, '2024-11-01', 'P', 'ar', 'https://image.tmdb.org/t/p/w500/bVlXZnI24U4QPlGvggUbeShMhz8.jpg', 'https://www.youtube.com/watch?v=-pI2IXKtlew', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (354, 'Frozen II', 'Elsa, Anna, Kristoff and Olaf head far into the forest to learn the truth about an ancient mystery of their kingdom.', 'Chris Buck, Jennifer Lee', 103, '2019-11-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mINJaa34MtknCYl5AjtNJzWj8cD.jpg', 'https://www.youtube.com/watch?v=-o8JGxdEKIU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (355, 'Hustle', 'After discovering a once-in-a-lifetime player with a rocky past abroad, a down on his luck basketball scout takes it upon himself to bring the phenom to the States without his team''s approval. Against the odds, they have one final shot to prove they have what it takes to make it in the NBA.', 'Jeremiah Zagar', 117, '2022-06-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xWic7kPq13oRxYjbGLApXCnc7pz.jpg', 'https://www.youtube.com/watch?v=nM4iy0reaCA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (356, 'Moonlight', 'The tender, heartbreaking story of a young man’s struggle to find himself, told across three defining chapters in his life as he experiences the ecstasy, pain, and beauty of falling in love, while grappling with his own sexuality.', 'Barry Jenkins', 112, '2016-10-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qLnfEmPrDjJfPyyddLJPkXmshkp.jpg', 'https://www.youtube.com/watch?v=9NJj12tJzqc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (357, 'Your Eyes Tell', 'A tragic accident lead to Akari''s blindness, but she clings to life and the smaller pleasures it can still afford her. She meets Rui and begins to talk to him. Rui was once a promising kickboxer, but something happened in his past. Akari''s smile brings out a change in Rui. However, the two are connected in more than one way. Rui attempts to do what is right.', 'Takahiro Miki', 123, '2020-10-23', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/cVn8E3Fxbi8HzYYtaSfsblYC4gl.jpg', 'https://www.youtube.com/watch?v=k_Wv1Oxhkw0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (358, 'The Boy Who Harnessed the Wind', 'Against all the odds, a thirteen year old boy in Malawi invents an unconventional way to save his family and village from famine.', 'Chiwetel Ejiofor', 113, '2019-02-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yOr7RxHw15MMXNxGMXSmngDqHyI.jpg', 'https://www.youtube.com/watch?v=nPkr9HmglG0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (359, 'Rental Family', 'An American actor in Tokyo struggles to find purpose until he lands an unusual gig: working for a Japanese ''rental family'' agency, playing stand-in roles for strangers. As he immerses himself in his clients'' worlds, he begins to form genuine bonds that blur the lines between performance and reality.', 'Hikari', 110, '2025-11-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/A5lswNlytTUrnMWsuD0NFfhZlf3.jpg', 'https://www.youtube.com/watch?v=RP9QKdU0vvA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (360, 'Folklore: The Long Pond Studio Sessions', 'An intimate concert film, in which Taylor Swift performs each song from her album ''folklore'' in order, as she reveals the meaning and the stories behind all 17 tracks for the very first time.', 'Taylor Swift', 106, '2020-11-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4iroJUn8YuQBekDwGy7r61YHXiu.jpg', 'https://www.youtube.com/watch?v=jgdFUoZzCI0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (361, 'David', 'From the songs of his mother’s heart to the whispers of a faithful God, David’s story begins in quiet devotion. When the giant Goliath rises to terrorize a nation, a young shepherd armed with only a sling, a few stones, and unshakable faith steps forward. Pursued by power and driven by purpose, his journey tests the limits of loyalty, love, and courage—culminating in a battle not just for a crown, but for the soul of a kingdom.', 'Brent Dawes, Phil Cunningham', 109, '2025-12-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/bESlrLOrsQ9gKzaGQGHXKOyIUtX.jpg', 'https://www.youtube.com/watch?v=gWgyI6_lR0A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (362, 'The Forge', '19 year old Isaiah Wright lives for basketball and video games. A year out of high school, he has no job, no plans, and no idea how to be a man. At odds with his single mother Cynthia, Isaiah is given an ultimatum – to step up or move out. Feeling the pull from his friends and the push from his mom, Isaiah is hired by Moore Fitness, unaware of how the owner will personally impact his life. With the prayers of his mother and unexpected guidance from his new mentor, Isaiah is forced to deal with his past, sacrifice his selfishness and discover how God might have a greater purpose for his life.', 'Alex Kendrick', 123, '2024-08-22', 'K', 'en', 'https://image.tmdb.org/t/p/w500/oranxontIQRmhuyQlkoAwxpeBYz.jpg', 'https://www.youtube.com/watch?v=iAt_j6zEeF0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (363, 'Extraction 2', 'Back from the brink of death, highly skilled commando Tyler Rake takes on another dangerous mission: saving the imprisoned family of a ruthless gangster.', 'Sam Hargrave', 122, '2023-06-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7gKI9hpEMcZUQpNgKrkDzJpbnNS.jpg', 'https://www.youtube.com/watch?v=Y274jZs5s7s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (364, 'The Fabelmans', 'Growing up in post-World War II era Arizona, young Sammy Fabelman aspires to become a filmmaker as he reaches adolescence, but soon discovers a shattering family secret and explores how the power of films can help him see the truth.', 'Steven Spielberg', 151, '2022-11-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/h7llKkqkkJtJrTOaDLuVeUYDQ7I.jpg', 'https://www.youtube.com/watch?v=9wAKUa487aw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (365, 'The Iron Claw', 'The true story of the inseparable Von Erich brothers, who made history in the intensely competitive world of professional wrestling in the early 1980s. Through tragedy and triumph, under the shadow of their domineering father and coach, the brothers seek larger-than-life immortality on the biggest stage in sports.', 'Sean Durkin', 133, '2023-12-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/s2VLjcykJfwplJNGT5iEeCA0mRx.jpg', 'https://www.youtube.com/watch?v=8KVsaoveTbw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (366, 'Ballerina', 'Taking place during the events of John Wick: Chapter 3 – Parabellum, Eve Macarro begins her training in the assassin traditions of the Ruska Roma.', 'Len Wiseman', 125, '2025-06-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2VUmvqsHb6cEtdfscEA6fqqVzLg.jpg', 'https://www.youtube.com/watch?v=0FSwsrFpkbw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (367, 'The Shape of Water', 'An other-worldly story, set against the backdrop of Cold War era America circa 1962, where a mute janitor working at a lab falls in love with an amphibious man being held captive there and devises a plan to help him escape.', 'Guillermo del Toro', 123, '2017-12-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9zfwPffUXpBrEP26yp0q1ckXDcj.jpg', 'https://www.youtube.com/watch?v=368_ovPsJk8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (368, 'I, Tonya', 'Competitive ice skater Tonya Harding rises amongst the ranks at the U.S. Figure Skating Championships, but her future in the sport is thrown into doubt when her ex-husband intervenes.', 'Craig Gillespie', 120, '2017-12-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6gNXwSHxaksR1PjVZRqNapmkgj3.jpg', 'https://www.youtube.com/watch?v=d2iy5y0YjGM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (369, 'Nimona', 'A knight framed for a tragic crime teams with a scrappy, shape-shifting teen to prove his innocence.', 'Nick Bruno, Troy Quane', 99, '2023-06-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2NQljeavtfl22207D1kxLpa4LS3.jpg', 'https://www.youtube.com/watch?v=f_fuHRyQbOc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (370, 'Billie Eilish - Hit Me Hard and Soft: The Tour (Live in 3D)', 'Captured during Billie Eilish''s sold-out world tour, a concert experience from one of the most celebrated and successful artists of her generation, presented in immersive 3D.', 'Billie Eilish, James Cameron', 114, '2026-05-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zfFvltKHntGBupFuubx3r61v48e.jpg', 'https://www.youtube.com/watch?v=9ElURjcuWLQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (371, 'Ghich Pich', 'A coming-of-age story about middle-class Indian fathers and their relationships with their sons - entangled in rebellion, insecurities and bound by tradition. Set in ''90s Chandigarh.', 'Ankur Singla', 94, '2025-08-08', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/zQiAoLfGxD3XYlQ4xULS7RN70RA.jpg', 'https://www.youtube.com/watch?v=53AK4RIEkg0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (372, 'Sonic the Hedgehog', 'Powered with incredible speed, Sonic The Hedgehog embraces his new home on Earth. That is, until Sonic sparks the attention of super-uncool evil genius Dr. Robotnik. Now it’s super-villain vs. super-sonic in an all-out race across the globe to stop Robotnik from using Sonic’s unique power for world domination.', 'Jeff Fowler', 99, '2020-02-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/aQvJ5WPzZgYVDrxLX4R6cLJCEaQ.jpg', 'https://www.youtube.com/watch?v=szby7ZHLnkA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (373, 'Alita: Battle Angel', 'When Alita awakens with no memory of who she is in a future world she does not recognize, she is taken in by Ido, a compassionate doctor who realizes that somewhere in this abandoned cyborg shell is the heart and soul of a young woman with an extraordinary past.', 'Robert Rodriguez', 122, '2019-01-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xRWht48C2V8XNfzvPehyClOvDni.jpg', 'https://www.youtube.com/watch?v=U3D2vmWD88w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (374, 'Nocturnal Animals', 'Susan Morrow receives a book manuscript from her ex-husband – a man she left 20 years earlier – asking for her opinion of his writing. As she reads, she is drawn into the fictional life of Tony Hastings, a mathematics professor whose family vacation turns violent.', 'Tom Ford', 116, '2016-11-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mdLDgQBD0va09npSQX5Zgo2evXM.jpg', 'https://www.youtube.com/watch?v=JOsEU5oYpTA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (375, 'The Equalizer 3', 'Robert McCall finds himself at home in Southern Italy but he discovers his friends are under the control of local crime bosses. As events turn deadly, McCall knows what he has to do: become his friends'' protector by taking on the mafia.', 'Antoine Fuqua', 109, '2023-08-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/b0Ej6fnXAP8fK75hlyi2jKqdhHz.jpg', 'https://www.youtube.com/watch?v=19ikl8vy4zs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (376, 'Dark Waters', 'A tenacious attorney uncovers a dark secret that connects a growing number of unexplained deaths to one of the world''s largest corporations. In the process, he risks everything — his future, his family, and his own life — to expose the truth.', 'Todd Haynes', 127, '2019-11-22', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/bzvzaHqKBSuGIIWhinTQPHvT0zf.jpg', 'https://www.youtube.com/watch?v=RvAOuhyunhY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (377, 'The Conjuring: The Devil Made Me Do It', 'Paranormal investigators Ed and Lorraine Warren encounter what would become one of the most sensational cases from their files. The fight for the soul of a young boy takes them beyond anything they''d ever seen before, to mark the first time in U.S. history that a murder suspect would claim demonic possession as a defense.', 'Michael Chaves', 111, '2021-05-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/xbSuFiJbbBWCkyCCKIMfuDCA4yV.jpg', 'https://www.youtube.com/watch?v=5FEdg3FhiGc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (378, 'Elvis', 'The life story of Elvis Presley as seen through the complicated relationship with his enigmatic manager, Colonel Tom Parker.', 'Baz Luhrmann', 159, '2022-06-22', 'K', 'en', 'https://image.tmdb.org/t/p/w500/qBOKWqAFbveZ4ryjJJwbie6tXkQ.jpg', 'https://www.youtube.com/watch?v=Gp2BNHwbwvI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (379, 'Lucy Shimmers and the Prince of Peace', 'Second chances start when a hardened criminal crosses paths with a precocious little girl who is helped by an angel to change hearts during the holiday season.', 'Rob Diamond', 87, '2020-10-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yfnJ5qIYx7q33fY4jqv9Pu95RSg.jpg', 'https://www.youtube.com/watch?v=bu2yPlLTfZ8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (380, 'Tuner', 'A gifted piano tuner''s meticulous skills for tuning pianos lead him to discover an unexpected aptitude for cracking safes, turning his life upside down.', 'Daniel Roher', 108, '2026-05-21', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/5OvA3i9wZs5jHu0DCrfmXlzAM67.jpg', 'https://www.youtube.com/watch?v=XiehvETTjTQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (381, 'BlacKkKlansman', 'Colorado Springs, late 1970s. Ron Stallworth, an African American police officer, and Flip Zimmerman, his Jewish colleague, run an undercover operation to infiltrate the Ku Klux Klan.', 'Spike Lee', 136, '2018-08-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8jxqAvSDoneSKRczaK8v9X5gqBp.jpg', 'https://www.youtube.com/watch?v=7tgMuagdEhc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (382, 'Succubus', 'A new father going through a marital separation joins a dating app and matches with a beautiful but mysterious young woman... whose powers of seduction and manipulation entangle him in a mystery more horrifying than he could have ever imagined.', 'R.J. Daniel Hanna', 103, '2024-10-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7AfBMebJS8mEtSV5ymdxEPpgvXb.jpg', 'https://www.youtube.com/watch?v=kzZP33WEPZw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (383, 'Cosmic Princess Kaguya!', 'Iroha''s life gets knocked off its orbit when Kaguya, a carefree runaway from the Moon, moves in and convinces her to perform in a virtual world together.', 'Shingo Yamashita', 141, '2026-01-22', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/9I9cM38gecZcwJ0C6r0cwfvtPJP.jpg', 'https://www.youtube.com/watch?v=5I8vubBZOb4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (384, 'Instant Family', 'When Pete and Ellie decide to start a family, they stumble into the world of foster care adoption. They hope to take in one small child but when they meet three siblings, including a rebellious 15 year old girl, they find themselves speeding from zero to three kids overnight.', 'Sean Anders', 118, '2018-11-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xYV1mODz99w7AjKDSQ7h2mzZhVe.jpg', 'https://www.youtube.com/watch?v=IUfZq3DUd3Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (385, 'Searching', 'After David Kim''s 16-year-old daughter goes missing, a local investigation is opened and a detective is assigned to the case. But 37 hours later and without a single lead, David decides to search the one place no one has looked yet, where all secrets are kept today: his daughter''s laptop.', 'Aneesh Chaganty', 102, '2018-08-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yuAPCsCGJGSxA7YOW4elF5JNrzK.jpg', 'https://www.youtube.com/watch?v=1f-nx8OAMVk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (386, 'Love Untangled', 'A lovestruck teen plans to win the school heartthrob by going from curly to straight hair — until a new transfer student changes everything.', 'Namkoong Sun', 121, '2025-08-28', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/e7jStO2xfBUAUK37LbINHd1qtgy.jpg', 'https://www.youtube.com/watch?v=0HwDE0HXbqc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (387, '3E', 'Following the closing arguments in a murder trial, case is about to be closed as a guilty verdict with a unanimous decision. But a Jr. Lawyer casts considerable doubt on elements of the case which shall derail the total conflict threatening to question the delicate law system which will decide one girl''s fate.', 'Vishwanath Batchu', 110, '2022-02-04', 'T16', 'te', 'https://image.tmdb.org/t/p/w500/9gKe0w4zl2VfuGzXrsfg3tn0pN9.jpg', 'https://www.youtube.com/watch?v=qRqy4VeASKs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (388, 'Perfect Strangers', 'During a dinner, a group of friends decide to share whatever message or phone call they will receive during the evening, with unforeseen consequences.', 'Paolo Genovese', 97, '2016-02-11', 'T13', 'it', 'https://image.tmdb.org/t/p/w500/3wknM629Vryofb1HNo2YnLQnQyn.jpg', 'https://www.youtube.com/watch?v=-lOUnBsjGuY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (389, 'Where the Crawdads Sing', 'Abandoned by her family, Kya raises herself all alone in the marshes outside of her small town. When her former boyfriend is found dead, Kya is instantly branded by the local townspeople and law enforcement as the prime suspect for his murder.', 'Olivia Newman', 126, '2022-07-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/n1el846gLDXfhOvrRCsyvaAOQWv.jpg', 'https://www.youtube.com/watch?v=PY3808Iq0Tg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (390, 'EPiC: Elvis Presley in Concert', 'Long-lost footage from Elvis Presley''s legendary Las Vegas residency in the 1970s woven together with rare 16mm footage from Elvis on Tour, and 8mm from the Graceland archive, plus recordings of Elvis telling "his side of the story" rediscovered during Baz Luhrmann''s research for his 2022 film, Elvis.', 'Baz Luhrmann', 98, '2026-02-18', 'K', 'en', 'https://image.tmdb.org/t/p/w500/2K2NH5dforjT9kLcUC0eeBpdZkC.jpg', 'https://www.youtube.com/watch?v=2s_dCvUgOBI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (391, 'Ghostbusters: Afterlife', 'When single mom Callie and her two kids Trevor and Phoebe arrive in a small Oklahoma town, they begin to discover their connection to the original Ghostbusters and the secret legacy their grandfather left behind.', 'Jason Reitman', 124, '2021-11-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sg4xJaufDiQl7caFEskBtQXfD4x.jpg', 'https://www.youtube.com/watch?v=G_ua10EMbSg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (392, 'Redeeming Love', 'A young couple''s relationship clashes with the harsh realities of the California Gold Rush of 1850. Angel, experiencing love for the first time and facing demons unsurmountable, runs from the new life she doesn''t believe she deserves. When Michael sets out to find her, Angel discovers that she indeed has the power to choose the life she wants.', 'D.J. Caruso', 134, '2022-01-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/2iu0lBF7sfAioLfSnSJtdKxlms6.jpg', 'https://www.youtube.com/watch?v=6Z-0C02cqFo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (393, 'Dou kyu sei – Classmates', 'Rihito Sajo, an honor student with a perfect score on the entrance exam and Hikaru Kusakabe, in a band and popular among girls, would have never crossed paths. Until one day they started talking at the practice for their school’s upcoming chorus festival. After school, the two meet regularly, as Hikaru helps Rihito to improve his singing skills. While they listen to each other’s voice and harmonize, their hearts start to beat together.', 'Shoko Nakamura', 61, '2016-02-20', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/cIfRCA5wEvj9tApca4UDUagQEiM.jpg', 'https://www.youtube.com/watch?v=R8KZ9WOTU78', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (394, 'The Remarkable Life of Ibelin', 'The secret life of a young World of Warcraft gamer is vividly reimagined when his online friends contact his family after his death.', 'Benjamin Ree', 103, '2024-03-08', 'K', 'no', 'https://image.tmdb.org/t/p/w500/73vRLcc0syVTMXmXyztUWaPJiK3.jpg', 'https://www.youtube.com/watch?v=lM_hkJ0Rl-c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (395, 'War for the Planet of the Apes', 'Caesar and his apes are forced into a deadly conflict with an army of humans led by a ruthless Colonel. After the apes suffer unimaginable losses, Caesar wrestles with his darker instincts and begins his own mythic quest to avenge his kind. As the journey finally brings them face to face, Caesar and the Colonel are pitted against each other in an epic battle that will determine the fate of both their species and the future of the planet.', 'Matt Reeves', 140, '2017-07-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3vYhLLxrTtZLysXtIWktmd57Snv.jpg', 'https://www.youtube.com/watch?v=1TxqmlIv1Iw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (396, 'Sonic the Hedgehog 2', 'After settling in Green Hills, Sonic is eager to prove he has what it takes to be a true hero. His test comes when Dr. Robotnik returns, this time with a new partner, Knuckles, in search for an emerald that has the power to destroy civilizations. Sonic teams up with his own sidekick, Tails, and together they embark on a globe-trotting journey to find the emerald before it falls into the wrong hands.', 'Jeff Fowler', 123, '2022-03-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6DrHO1jr3qVrViUO6s6kFiAGM7.jpg', 'https://www.youtube.com/watch?v=47r8FXYZWNU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (397, 'Young Woman and the Sea', 'This is the extraordinary true story of Trudy Ederle, the first woman to successfully swim the English Channel. Through the steadfast support of her older sister and supportive trainers, she overcame adversity and the animosity of a patriarchal society to rise through the ranks of the Olympic swimming team and complete the 21-mile trek from France to England.', 'Joachim Rønning', 129, '2024-05-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/bZlecCuBVvKuarNGvchBwaOsQ3c.jpg', 'https://www.youtube.com/watch?v=7tNvrYzPUrk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (398, 'Drinker Sai', 'Heartbroken and spiraling into alcoholism, a jilted lover desperately pursues his former muse, unwilling to accept their relationship''s end.', 'Kiran Tirumalasetti', 148, '2024-12-27', 'P', 'te', 'https://image.tmdb.org/t/p/w500/t7hKwM0txUagQvtU0ZcJg7lRokX.jpg', 'https://www.youtube.com/watch?v=cWQflkvQ3fE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (399, 'Everybody’s Everything', 'The story of artist Lil Peep from his birth in Long Island and meteoric rise as a genre blending pop star & style icon, to his death due to an accidental opioid overdose in Arizona at just 21 years of age.', 'Ramez Silyan, Sebastian Jones', 116, '2019-11-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wbMkjkNX8VylPVLmQ2Dp6i5iayY.jpg', 'https://www.youtube.com/watch?v=nV7qfPcyaXQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (400, 'Masters of the Universe', 'After being separated for 15 years, the Sword of Power leads Prince Adam back to Eternia, where he discovers his home shattered under the fiendish rule of Skeletor. To save his family and his world, Adam must join forces with his closest allies, Teela and Duncan/Man-At-Arms, and embrace his true destiny as He-Man — the most powerful man in the universe.', 'Travis Knight', 141, '2026-06-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oRuyGUHdoaQxWP3SDfafGkStxTC.jpg', 'https://www.youtube.com/watch?v=RZ4dblwZ2TY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (401, 'Midsommar', 'Several friends travel to Sweden to study as anthropologists a summer festival that is held every ninety years in the remote hometown of one of them. What begins as a dream vacation in a place where the sun never sets, gradually turns into a dark nightmare as the mysterious inhabitants invite them to participate in their disturbing festive activities.', 'Ari Aster', 147, '2019-07-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', 'https://www.youtube.com/watch?v=1Vnghdsjmd0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (402, 'Gandhi Tatha Chettu', 'A young girl''s non-violent campaign to protect her grandfather''s beloved tree from demolition, is inspired by Gandhi''s philosophy of peaceful resistance.', 'Padmavathi Malladi', 114, '2025-01-24', 'K', 'te', 'https://image.tmdb.org/t/p/w500/wMpvUhkzodjLwvZJmqs9N0QLb0c.jpg', 'https://www.youtube.com/watch?v=A1Xozp18TMM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (403, 'Alien: Romulus', 'While scavenging the deep ends of a derelict space station, a group of young space colonizers come face to face with the most terrifying life form in the universe.', 'Fede Álvarez', 119, '2024-08-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2uSWRTtCG336nuBiG8jOTEUKSy8.jpg', 'https://www.youtube.com/watch?v=OzY2r2JXsDM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (404, 'Maquia: When the Promised Flower Blooms', 'Fleeing the war, the immortal Maquia, graced with eternal youth, finds a baby abandoned in the forest and decides to raise it as her own child, sparking a moving story between a mortal and a being who does not age.', 'Mari Okada', 115, '2018-02-24', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/hL3NqRE2ccR4Y2sYSJTrmalRjrz.jpg', 'https://www.youtube.com/watch?v=AEWvRqZQ0RU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (405, 'Rascal Does Not Dream of a Dreaming Girl', 'In Fujisawa, Sakuta Azusagawa is in his second year of high school. Blissful days with his girlfriend and upperclassman, Mai Sakurajima, are interrupted by the appearance of his first crush, Shoko Makinohara.', 'Soichi Masui', 90, '2019-06-15', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/AtFnN4OztDJy8IFwYd5JfU0jlEM.jpg', 'https://www.youtube.com/watch?v=JqHS7nylmVQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (406, 'For Sama', 'A love letter from a young mother to her daughter, the film tells the story of Waad al-Kateab’s life through five years of the uprising in Aleppo, Syria as she falls in love, gets married and gives birth to Sama, all while cataclysmic conflict rises around her. Her camera captures incredible stories of loss, laughter and survival as Waad wrestles with an impossible choice– whether or not to flee the city to protect her daughter’s life, when leaving means abandoning the struggle for freedom for which she has already sacrificed so much.', 'Edward Watts, Waad al-Kateab', 100, '2019-07-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mDna51F8QfrJFZOgPGQUz3VKqsB.jpg', 'https://www.youtube.com/watch?v=bT_Agp-ZXAk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (407, 'Clouds', 'Young musician Zach Sobiech discovers his cancer has spread, leaving him just a few months to live. With limited time, he follows his dream and makes an album, unaware that it will soon be a viral music phenomenon.', 'Justin Baldoni', 121, '2020-10-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/2YvT3pdGngzpbAuxamTz4ZlabnT.jpg', 'https://www.youtube.com/watch?v=OWEgUhWU4g4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (408, 'Metallica and San Francisco Symphony: S&M2', 'S&M2, the live concert film from Metallica and the San Francisco Symphony is the concert event of the year! S&M2 features 20 songs from the two-night event that opened San Francisco’s new Chase Center, with many Metallica fan favourites and two unique classical songs chosen by San Francisco Symphony Musical Director, Michael Tilson Thomas. S&M2 is newly re-edited by the band, with re-mixed and remastered audio, for a whole new look and sound from the original theatrical run in October 2019.', 'Wayne Isham', 150, '2019-10-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/yf9RJWfeWVwVbqlDPdUdbn0al0N.jpg', 'https://www.youtube.com/watch?v=Gd6SycTT-NI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (409, 'There''s Still Tomorrow', 'In postwar Rome, a working-class woman dreams of a better future for herself and her daughter while facing abuse at the hands of her domineering husband. When a mysterious letter arrives, she discovers the courage to change the circumstances of her life.', 'Paola Cortellesi', 118, '2023-10-26', 'P', 'it', 'https://image.tmdb.org/t/p/w500/4Hi7yjiQjokEDStT1MOj5rPgRfW.jpg', 'https://www.youtube.com/watch?v=Z5hAvdF6xQA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (410, 'Close', 'Two 13-year-old boys spend an idyllic summer together, but their connection is put to the test when they become the subject of speculation at school.', 'Lukas Dhont', 104, '2022-11-01', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/dlMNnWs7Mz8Nk5AC447Ew1tD5pn.jpg', 'https://www.youtube.com/watch?v=6EJGnU2AmV4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (411, 'Bugonia', 'Two conspiracy obsessed young men kidnap the high-powered CEO of a major company, convinced that she is an alien intent on destroying planet Earth.', 'Yorgos Lanthimos', 119, '2025-10-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rSdOua3wKMEaFWDcKAYWRjXQWOt.jpg', 'https://www.youtube.com/watch?v=7VBigr-JHB0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (412, 'The Last Duel', 'King Charles VI declares that Knight Jean de Carrouges settle his dispute with his squire, Jacques Le Gris, by challenging him to a duel.', 'Ridley Scott', 153, '2021-10-13', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/zjrJE0fpzPvX8saJXj8VNfcjBoU.jpg', 'https://www.youtube.com/watch?v=mgygUwPJvYk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (413, 'The Rescue', 'The enthralling, against-all-odds story that transfixed the world in 2018: the daring rescue of twelve boys and their coach from deep inside a flooded cave in Northern Thailand.', 'Elizabeth Chai Vasarhelyi, Jimmy Chin', 107, '2021-10-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kC7fVtCkJACwPBaRr2hlj2whfKX.jpg', 'https://www.youtube.com/watch?v=_-Kw5kAPSbk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (414, 'The Woman King', 'The story of the Agojie, the all-female unit of warriors who protected the African Kingdom of Dahomey in the 1800s with skills and a fierceness unlike anything the world has ever seen, and General Nanisca as she trains the next generation of recruits and readies them for battle against an enemy determined to destroy their way of life.', 'Gina Prince-Bythewood', 135, '2022-09-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/438QXt1E3WJWb3PqNniK0tAE5c1.jpg', 'https://www.youtube.com/watch?v=3RDaPV_rJ1Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (415, 'The Menu', 'A young couple travels to a remote island to eat at an exclusive restaurant where the chef has prepared a lavish menu, with some shocking surprises.', 'Mark Mylod', 107, '2022-11-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fPtUgMcLIboqlTlPrq0bQpKK8eq.jpg', 'https://www.youtube.com/watch?v=CAWZMssP3gM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (416, 'Satluj', 'Triggered by the search for his missing aunt, human rights activist Jaswant Singh Khalra takes on a broken system in a courageous fight to uncover the conspiracy behind thousands of disappearances and extrajudicial killings during the nadir of Punjab’s period of insurgency.', 'Honey Trehan', 164, '2026-07-03', 'T18', 'hi', 'https://image.tmdb.org/t/p/w500/hm4ou83RwLVwNj3HsmQuqC1qkWy.jpg', 'https://www.youtube.com/watch?v=WtL3YbjUJN8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (417, 'The Boy and the Heron', 'While the Second World War rages, the teenage Mahito, haunted by his mother''s tragic death, is relocated from Tokyo to the serene rural home of his new stepmother Natsuko, a woman who bears a striking resemblance to the boy''s mother. As he tries to adjust, this strange new world grows even stranger following the appearance of a persistent gray heron, who perplexes and bedevils Mahito, dubbing him the "long-awaited one."', 'Hayao Miyazaki', 124, '2023-07-14', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/f4oZTcfGrVTXKTWg157AwikXqmP.jpg', 'https://www.youtube.com/watch?v=A002-b7IH2M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (418, 'Ayla: The Daughter of War', 'In 1950, amidst the ravages of the Korean War, Sergeant Süleyman stumbles upon a a half-frozen little girl, with no parents and no help in sight and he risks his own life to save her, smuggling her into his army base and out of harm’s way.', 'Can Ulkay', 124, '2017-10-27', 'T13', 'tr', 'https://image.tmdb.org/t/p/w500/8RELLU0RK9hRIteLzHFZ0dK8YSi.jpg', 'https://www.youtube.com/watch?v=0j0I5drZkJM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (419, 'Praveen IPS', 'After overcoming difficulties, a determined man joins the IPS, evolving into a tenacious force for good.', NULL, 135, '2024-02-16', 'P', 'te', 'https://image.tmdb.org/t/p/w500/hgrvwVNttHK6VAwFhATf4Qv9ztl.jpg', 'https://www.youtube.com/watch?v=zSuIVD85GoA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (420, 'The Invite', 'Joe and Angela''s marriage is on thin ice. When they invite their enigmatic upstairs neighbors for a dinner party, the night spirals into unexpected places. Have they reignited the spark or lit the match that burns it all down?', 'Olivia Wilde', 107, '2026-06-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/b7Dr8Chzse8VagexAporUu2RtLx.jpg', 'https://www.youtube.com/watch?v=OJ19I9q_hOQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (421, 'Soulm8te', 'After a ruthless tech giant acquires a small robotics company, a grieving engineer is tasked with testing their new AI companion. But when he attempts to reprogram her to be a truly sentient soulmate, she develops needs of her own—unleashing a relentless spree of precision-engineered mayhem.', 'Kate Dolan', 99, '2026-07-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bNErActDctl6cdUGw9pnjSCmyhQ.jpg', 'https://www.youtube.com/watch?v=DF9I1wLlXbk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (422, 'Only the Brave', 'Members of the Granite Mountain Hotshots battle deadly wildfires to save an Arizona town.', 'Joseph Kosinski', 133, '2017-09-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/db5IkOJu9UHktrKroNktw1Z8ARY.jpg', 'https://www.youtube.com/watch?v=DSHk_BHQxp0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (423, 'Beautiful Boy', 'After he and his first wife separate, journalist David Sheff struggles to help their teenage son, who goes from experimenting with drugs to becoming devastatingly addicted to methamphetamine.', 'Felix van Groeningen', 121, '2018-10-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/u2Gfv0mz3xePsgyCPHovrnFL1sB.jpg', 'https://www.youtube.com/watch?v=8NR8w8s9zWA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (424, 'The Witch: Part 1. The Subversion', 'Ja-yoon is a high school student who struggles with memory loss after she endured some unknown trauma during her childhood. While trying to uncover the truth, she is unwittingly dragged into a world of crime and finds herself on a journey that will awaken many secrets hidden deep within.', 'Park Hoon-jung', 126, '2018-06-27', 'T13', 'ko', 'https://image.tmdb.org/t/p/w500/4i2wo2ja5g2PmUxWa1a2eYIboZf.jpg', 'https://www.youtube.com/watch?v=BmD6BAQjDzY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (425, 'Spies in Disguise', 'Super spy Lance Sterling and scientist Walter Beckett are almost exact opposites. Lance is smooth, suave and debonair. Walter is… not. But what Walter lacks in social skills he makes up for in smarts and invention, creating the awesome gadgets Lance uses on his epic missions. But when events take an unexpected turn, Walter and Lance suddenly have to rely on each other in a whole new way.', 'Nick Bruno, Troy Quane', 102, '2019-12-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/z52xI0MnoX1rqySFJYnmBqHbXRn.jpg', 'https://www.youtube.com/watch?v=6FK19sxxnBU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (426, 'Reminders of Him', 'When Diem''s custodial grandparents adamantly refuse Kenna''s attempts to see her daughter, Kenna discovers unexpected compassion, and then something truer and deeper, with former NFL player and local bar owner Ledger. As their secret romance develops, so do the dangers for both of them, leading Kenna toward heartbreak and, ultimately, the hope for a second chance.', 'Vanessa Caswill', 114, '2026-03-11', 'K', 'en', 'https://image.tmdb.org/t/p/w500/7L6rceYgzQ0NeHD7PRDNrRoQ291.jpg', 'https://www.youtube.com/watch?v=i36Zw32GfRQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (427, 'Five Nights at Freddy''s', 'Recently fired and desperate for work, a troubled young man named Mike agrees to take a position as a night security guard at an abandoned theme restaurant: Freddy Fazbear''s Pizzeria. But he soon discovers that nothing at Freddy''s is what it seems.', 'Emma Tammi', 110, '2023-10-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7BpNtNfxuocYEVREzVMO75hso1l.jpg', 'https://www.youtube.com/watch?v=9fJtM5z0g7M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (428, 'One Life', 'British stockbroker Nicholas Winton visits Czechoslovakia in the 1930s and forms plans to assist in the rescue of Jewish children before the onset of World War II, in an operation that came to be known as the Kindertransport.', 'James Hawes', 109, '2023-12-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/yvnIWt2j8VnDgwKJE2VMiFMa2Qo.jpg', 'https://www.youtube.com/watch?v=6ethollg-PI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (429, 'Gabriel''s Inferno', 'An intriguing and sinful exploration of seduction, forbidden love, and redemption, Gabriel''s Inferno is a captivating and wildly passionate tale of one man''s escape from his own personal hell as he tries to earn the impossible--forgiveness and love.', 'Tosca Musk', 122, '2020-05-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/oyG9TL7FcRP4EZ9Vid6uKzwdndz.jpg', 'https://www.youtube.com/watch?v=kgWFjmiqHmQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (430, 'Bring Her Back', 'Following the death of their father, a brother and sister are sent to live with a foster mother, only to learn that she is hiding a terrifying secret.', 'Danny Philippou, Michael Philippou', 104, '2025-05-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1Q3GlCXGYWELifxANYZ5OVMRVZl.jpg', 'https://www.youtube.com/watch?v=1I15ttCedfY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (431, 'Barbie', 'Barbie and Ken are having the time of their lives in the colorful and seemingly perfect world of Barbie Land. However, when they get a chance to go to the real world, they soon discover the joys and perils of living among humans.', 'Greta Gerwig', 114, '2023-07-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iuFNMS8U5cb6xfzi51Dbkovj7vM.jpg', 'https://www.youtube.com/watch?v=8zIf0XvoL9Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (432, 'Mufasa: The Lion King', 'Mufasa, a cub lost and alone, meets a sympathetic lion named Taka, the heir to a royal bloodline. The chance meeting sets in motion an expansive journey of a group of misfits searching for their destiny.', 'Barry Jenkins', 118, '2024-12-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jbOSUAWMGzGL1L4EaUF8K6zYFo7.jpg', 'https://www.youtube.com/watch?v=MjQG-a7d41Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (433, 'Along with the Gods: The Last 49 Days', 'As the deceased soul Ja-hong and his three afterlife guardians prepare for their remaining trials for reincarnation, the guardians soon come face to face with the truth of their tragic time on Earth 1,000 years earlier.', 'Kim Yong-hwa', 141, '2018-08-01', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/9BnqBHFGDv3WlCPB2qQwzAWdy7y.jpg', 'https://www.youtube.com/watch?v=7LEDE-YPR0g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (434, 'A Place Called Silence', 'Chen Yutong, a girl''s middle school student, was bullied at school, but her mother Li Han was unable to save her daughter from the "hell." Everyone around her turned a blind eye, and a collective silence brewed greater violence.', 'Sam Quah', 119, '2024-07-03', 'T16', 'zh', 'https://image.tmdb.org/t/p/w500/uKThqY2oRYSHOPxYryTp2550fuZ.jpg', 'https://www.youtube.com/watch?v=AhDiIVEa4UU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (435, 'Darkest Hour', 'In May 1940, the fate of World War II hangs on Winston Churchill, who must decide whether to negotiate with Adolf Hitler or fight on knowing that it could mean the end of the British Empire.', 'Joe Wright', 125, '2017-11-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xa6G3aKlysQeVg9wOb0dRcIGlWu.jpg', 'https://www.youtube.com/watch?v=JQAYFbcgf60', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (436, 'Promising Young Woman', 'A young woman, traumatized by a tragic event in her past, seeks out vengeance against those who crossed her path.', 'Emerald Fennell', 114, '2020-12-13', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/2h4EkRxy36zSsBDkijXSUMJFDaz.jpg', 'https://www.youtube.com/watch?v=7i5kiFDunk8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (437, 'The Accountant', 'As a math savant uncooks the books for a new client, the Treasury Department closes in on his activities and the body count starts to rise.', 'Gavin O''Connor', 128, '2016-10-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fceheXB5fC4WrLVuWJ6OZv9FXYr.jpg', 'https://www.youtube.com/watch?v=0KHOVlEpMyY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (438, 'Young Washington', 'Before he led a nation, George Washington was a young soldier thrown into a global conflict. With alliances crumbling and war closing in, he must choose who to trust and confront the leader he''s becoming.', 'Jon Erwin', 121, '2026-07-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6CdoTKnRQHJkjRGxTefFGkPQplB.jpg', 'https://www.youtube.com/watch?v=LJek-kc384w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (439, 'No Other Choice', 'After being laid off and humiliated by a ruthless job market, a veteran paper mill manager descends into violence in a desperate bid to reclaim his dignity.', 'Park Chan-wook', 139, '2025-09-24', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/vc2S0dvgpsM0XfSiXZDMVkRCSSU.jpg', 'https://www.youtube.com/watch?v=SK_DEabMNVg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (440, 'Paddington 2', 'Paddington, now happily settled with the Browns, picks up a series of odd jobs to buy the perfect present for his Aunt Lucy, but it is stolen.', 'Paul King', 104, '2017-11-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1OJ9vkD5xPt3skC6KguyXAgagRZ.jpg', 'https://www.youtube.com/watch?v=07Um1PY_P4o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (441, 'Midnight Sun', 'Katie, a 17-year-old, has been sheltered since childhood and confined to her house during the day by a rare disease that makes even the smallest amount of sunlight deadly. Fate intervenes when she meets Charlie and they embark on a summer romance.', 'Scott Speer', 92, '2018-03-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vPG2zEKPXhovPW9S91SRnwr5JM1.jpg', 'https://www.youtube.com/watch?v=U8N1fKXunCg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (442, 'Avicii - I''m Tim', 'Before Avicii, there was Tim. Through his own words, witness how a prodigious musical talent became one of the defining artists of his generation.', 'Henrik Burman', 97, '2024-06-09', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/bHrkrKQxYKem0ljWHPinIQK2gxy.jpg', 'https://www.youtube.com/watch?v=X8LHNaCHYsg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (443, 'Bad Boys: Ride or Die', 'After their late former Captain is framed, Lowrey and Burnett try to clear his name, only to end up on the run themselves.', 'Adil El Arbi, Bilall Fallah', 116, '2024-06-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oGythE98MYleE6mZlGs5oBGkux1.jpg', 'https://www.youtube.com/watch?v=ZTQyMmz-cQE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (444, 'Don''t Look Up', 'Two astronomers go on a media tour to warn humankind of a planet-killing comet hurtling toward Earth. The response from a distracted world: Meh.', 'Adam McKay', 138, '2021-12-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/th4E1yqsE8DGpAseLiUrI60Hf8V.jpg', 'https://www.youtube.com/watch?v=RbIxYm3mKzI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (445, 'My Octopus Teacher', 'After years of swimming every day in the freezing ocean at the tip of Africa, Craig Foster meets an unlikely teacher: a young octopus who displays remarkable curiosity. Visiting her den and tracking her movements for months on end he eventually wins the animal’s trust and they develop a never-before-seen bond between human and wild animal.', 'James Reed, Pippa Ehrlich', 85, '2020-09-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hvTVZb7hBC8tZAGoEhH5eiMJu2B.jpg', 'https://www.youtube.com/watch?v=3s0LTDhqe5A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (446, 'Gintama: The Very Final', 'The countdown to destruction has begun! Gintoki and the others set out to fulfill the wishes of their teacher Shoyo and thwart Utsuro''s plans. Shinpachi, Kagura, the Shinsengumi, members of the Kabuki District, and even former enemies will join their fight. As Utsuro''s power grows, Takasugi fights for his very life. Will Gintoki be able to put an end to all this?!', 'Chizuru Miyawaki', 104, '2021-01-08', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/kxBHS1PGebEN0lrFdk0o9FZY6Rn.jpg', 'https://www.youtube.com/watch?v=_ZR8Lc-TnD8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (447, 'The Banker', 'In the 1960s, two entrepreneurs hatch an ingenious business plan to fight for housing integration—and equal access to the American Dream.', 'George Nolfi', 120, '2020-03-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/biXzsw22U6vSd0XktmZwAOc4uik.jpg', 'https://www.youtube.com/watch?v=J_-nk9-sMus', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (448, 'Lady Bird', 'Lady Bird McPherson, a strong willed, deeply opinionated, artistic 17 year old comes of age in Sacramento. Her relationship with her mother and her upbringing are questioned and tested as she plans to head off to college.', 'Greta Gerwig', 94, '2017-09-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gl66K7zRdtNYGrxyS2YDUP5ASZd.jpg', 'https://www.youtube.com/watch?v=cNi_HC839Wo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (449, 'Dragon Ball Super: Super Hero', 'The Red Ribbon Army, an evil organization that was once destroyed by Goku in the past, has been reformed by a group of people who have created new and mightier Androids, Gamma 1 and Gamma 2, and seek vengeance against Goku and his family.', 'Tetsuro Kodama', 100, '2022-06-11', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/pi0iZOEHeA3ih4p1IwAG4x2DZNH.jpg', 'https://www.youtube.com/watch?v=6_fXQSobiHs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (450, 'Wake Up Dead Man: A Knives Out Mystery', 'When young priest Jud Duplenticy is sent to assist charismatic firebrand Monsignor Jefferson Wicks, it’s clear that all is not well in the pews. After a sudden and seemingly impossible murder rocks the town, the lack of an obvious suspect prompts local police chief Geraldine Scott to join forces with renowned detective Benoit Blanc to unravel a mystery that defies all logic.', 'Rian Johnson', 145, '2025-11-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iV9LM8aUb83BjCCx2RUnKE5sSQg.jpg', 'https://www.youtube.com/watch?v=0hc8yz5-d5Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
