  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (451, 'A Street Cat Named Bob', 'James Bowen, a homeless busker and recovering drug addict, has his life transformed when he meets a stray ginger cat.', 'Roger Spottiswoode', 103, '2016-11-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nBYG0D2FcbL1m926sIj7RN4m0sb.jpg', 'https://www.youtube.com/watch?v=ai3hleBXRpo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (452, 'How to Train Your Dragon: Homecoming', 'It''s been ten years since the dragons moved to the Hidden World, and even though Toothless doesn''t live in New Berk anymore, Hiccup continues the holiday traditions he once shared with his best friend. But the Vikings of New Berk were beginning to forget about their friendship with dragons. Hiccup, Astrid, and Gobber know just what to do to keep the dragons in the villagers'' hearts. And across the sea, the dragons have a plan of their own...', 'Tim Johnson', 22, '2019-12-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kXj2Qrfm994yLeuADqbOieU1mUH.jpg', 'https://www.youtube.com/watch?v=CehPixdKUuE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (453, 'STRAW', 'What will be her last straw? A devastatingly bad day pushes a hardworking single mother to the breaking point — and into a shocking act of desperation.', 'Tyler Perry', 105, '2025-06-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/t3cmnXYtxJb9vVL1ThvT2CWSe1n.jpg', 'https://www.youtube.com/watch?v=k1vWhii4tkE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (454, 'Fall', 'For best friends Becky and Hunter, life is all about conquering fears and pushing limits. But after they climb 2,000 feet to the top of a remote, abandoned radio tower, they find themselves stranded with no way down. Now Becky and Hunter''s expert climbing skills will be put to the ultimate test as they desperately fight to survive the elements, a lack of supplies, and vertigo-inducing heights.', 'Scott Mann', 107, '2022-08-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/spCAxD99U1A6jsiePFoqdEcY0dG.jpg', 'https://www.youtube.com/watch?v=FNk7Cu4sJOs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (455, 'Won''t You Be My Neighbor?', 'For more than thirty years, and through his television program, Fred Rogers (1928-2003), host, producer, writer and pianist, accompanied by his puppets and his many friends, spoke directly to young children about some of life''s most important issues.', 'Morgan Neville', 95, '2018-06-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8qE8NZjiP2M884baH0VoLF828Vp.jpg', 'https://www.youtube.com/watch?v=EAwR54HrVW8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (456, 'Hell or High Water', 'A divorced dad and his ex-con brother resort to a desperate scheme in order to save their family''s farm in West Texas.', 'David Mackenzie', 102, '2016-08-11', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/ljRRxqy2aXIkIBXLmOVifcOR021.jpg', 'https://www.youtube.com/watch?v=JQoqsKoJVDw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (457, 'The Nice Guys', 'A private eye investigates the apparent suicide of a fading porn star in 1970s Los Angeles and uncovers a conspiracy.', 'Shane Black', 116, '2016-05-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/clq4So9spa9cXk3MZy2iMdqkxP2.jpg', 'https://www.youtube.com/watch?v=GQR5zsLHbYw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (458, 'Lilo & Stitch', 'The wildly funny and touching story of a lonely Hawaiian girl and the fugitive alien who helps to mend her broken family.', 'Dean Fleischer Camp', 108, '2025-05-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ckQzKpQJO4ZQDCN5evdpKcfm7Ys.jpg', 'https://www.youtube.com/watch?v=VWqJifMMgZE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (459, 'Color of Victory', 'The days when Istanbul was occupied as a result of the Armistice of Mudros after the First World War and the Fenerbahce football team won the "Harington Cup".', 'Abdullah Oğuz', 157, '2024-02-16', 'P', 'tr', 'https://image.tmdb.org/t/p/w500/nBkUpDWUBwcA3KPPr1cSzTKtzU8.jpg', 'https://www.youtube.com/watch?v=xLHgS10xd_4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (460, 'Utsavam', 'The course of true love is strewn with misunderstandings and unwanted drama for a young couple from theatre families.', 'Arjun Sai', 138, '2024-10-11', 'T13', 'te', 'https://image.tmdb.org/t/p/w500/qcw0LshYV3qdfOlo9yP3gKhz4ks.jpg', 'https://www.youtube.com/watch?v=WcSXBDs5xWA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (461, 'Dominion', 'Exposing the dark underbelly of modern animal agriculture through drones, hidden & handheld cameras, the feature-length film explores the morality and validity of our dominion over the animal kingdom.', 'Chris Delforce', 120, '2018-03-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/mzqwEuYSPQ7Kj6ovg016KclS0Sw.jpg', 'https://www.youtube.com/watch?v=LpDJlEQsDoA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (462, 'Primal: Tales of Savagery', 'Genndy Tartakovsky''s Primal: Tales of Savagery features a caveman and a dinosaur on the brink of extinction. Bonded by tragedy, this unlikely friendship becomes the only hope of survival.', 'Genndy Tartakovsky', 85, '2019-11-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9NBBkdxH0TjQEBSN2AzeE1sgsF9.jpg', 'https://www.youtube.com/watch?v=vaOn8koDa9E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (463, 'The Croods: A New Age', 'Searching for a safer habitat, the prehistoric Crood family discovers an idyllic, walled-in paradise that meets all of its needs. Unfortunately, they must also learn to live with the Bettermans -- a family that''s a couple of steps above the Croods on the evolutionary ladder. As tensions between the new neighbors start to rise, a new threat soon propels both clans on an epic adventure that forces them to embrace their differences, draw strength from one another, and survive together.', 'Joel Crawford', 95, '2020-11-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tbVZ3Sq88dZaCANlUcewQuHQOaE.jpg', 'https://www.youtube.com/watch?v=GkXeVIfbJOw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (464, 'Blast', 'A seemingly ordinary family must unleash their hidden martial arts skills when they clash with a ruthless criminal gang tied to corruption and violence.', 'Subash K Raj', 143, '2026-05-28', 'T18', 'ta', 'https://image.tmdb.org/t/p/w500/lpsUpXieodUhN6DlK9ZDnjkysLk.jpg', 'https://www.youtube.com/watch?v=aM5OLvxFBO4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (465, 'Greyhound', 'A first-time captain leads a convoy of allied ships carrying thousands of soldiers across the treacherous waters of the "Black Pit" to the front lines of WWII. With no air cover protection for 5 days, the captain and his convoy must battle the surrounding enemy Nazi U-boats in order to give the allies a chance to win the war.', 'Aaron Schneider', 92, '2020-07-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kjMbDciooTbJPofVXgAoFjfX8Of.jpg', 'https://www.youtube.com/watch?v=5Byeq_hyh2U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (466, 'Aryabhatt Ka Zero', 'A directionless young man from a middle-class family struggles to find his place in a world that has already written him off. As life tests his resilience, he embarks on a heartfelt journey of self-discovery, hope, and finding the courage to believe in himself.', 'Kamal Chandra', 116, '2026-08-07', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/hI5MZ78pj2aFuyEz1oOFMVsr8dM.jpg', 'https://www.youtube.com/watch?v=_pu7Y9AbMsQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (467, 'Anora', 'A young sex worker from Brooklyn gets her chance at a Cinderella story when she meets and impulsively marries the son of an oligarch. Once the news reaches Russia, her fairytale is threatened as his parents set out to get the marriage annulled.', 'Sean Baker', 139, '2024-10-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cgXk2tNYhJZLXdBDO5DidAVzQ82.jpg', 'https://www.youtube.com/watch?v=8m6UrWMl18M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (468, '13 Hours: The Secret Soldiers of Benghazi', 'An American Ambassador is killed during an attack at a U.S. compound in Libya as a security team struggles to make sense out of the chaos.', 'Michael Bay', 144, '2016-01-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fZlAxZMo6BId1SiqyjLmkd7oUB7.jpg', 'https://www.youtube.com/watch?v=4CJBuUwd0Os', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (469, 'Jungle Cruise', 'Dr. Lily Houghton enlists the aid of wisecracking skipper Frank Wolff to take her down the Amazon in his dilapidated boat. Together, they search for an ancient tree that holds the power to heal – a discovery that will change the future of medicine.', 'Jaume Collet-Serra', 127, '2021-07-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yKy9ELL8CON5sqDg4yIvBb5LTZL.jpg', 'https://www.youtube.com/watch?v=f_HvoipFcA8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (470, 'Ocean with David Attenborough', 'David Attenborough takes viewers on a breathtaking journey showing there is nowhere more vital for our survival, more full of life, wonder, or surprise, than the ocean. Through spectacular sequences featuring coral reefs, kelp forests and the open ocean, Attenborough shares why a healthy ocean keeps the entire planet stable and flourishing.', 'Colin Butfield, Keith Scholey, Toby Nowlan', 85, '2025-05-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/oAKzcqUCP3EK7rgAx9Jj8Futv8O.jpg', 'https://www.youtube.com/watch?v=cIZAdCtKT_g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (471, 'Yeh Saali Aashiqui', 'When Sahil met Mittee in a hotel management school, it was love at first sight for both of them. Their love was everything - picture perfect and flawless. But an unlikely event at school turns their dream-come-true romance into a nightmare and makes them realize how important it is to know your partner thoroughly before getting into any kind of romantic relationship.', 'Cheraagg Ruparel', 127, '2019-11-29', 'T16', 'hi', 'https://image.tmdb.org/t/p/w500/z83KrUMwgXPZM442lhl0Mth0pPk.jpg', 'https://www.youtube.com/watch?v=BP0k4SdquG0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (472, 'Louis Theroux: The Settlers', 'Fourteen years after his first visit, Louis Theroux meets some of the growing community of religious-nationalist Israelis who have settled in the occupied West Bank.', 'Joshua Baker', 62, '2025-04-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iT1J9zYzEY069wF546RJmuYO5m4.jpg', 'https://www.youtube.com/watch?v=zesI26Xi0Fk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (473, 'Black Panther: Wakanda Forever', 'Queen Ramonda, Shuri, M’Baku, Okoye and the Dora Milaje fight to protect their nation from intervening world powers in the wake of King T’Challa’s death. As the Wakandans strive to embrace their next chapter, the heroes must band together with the help of War Dog Nakia and Everett Ross and forge a new path for the kingdom of Wakanda.', 'Ryan Coogler', 162, '2022-11-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/sv1xJUazXeYqALzczSZ3O6nkH75.jpg', 'https://www.youtube.com/watch?v=_Z3QKkl1WyM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (474, 'Migration', 'After a migrating duck family alights on their pond with thrilling tales of far-flung places, the Mallard family embarks on a family road trip, from New England, to New York City, to tropical Jamaica.', 'Benjamin Renner', 83, '2023-12-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ldfCF9RhR40mppkzmftxapaHeTo.jpg', 'https://www.youtube.com/watch?v=UkHxhPGpRuA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (475, 'Checkered Ninja 3', 'In this 3rd installment Alex’s interest for Ninja missions is starting to vanish. He’ll rather spend his time with his friends and Checkered Ninja feels he is overlooked and is eager to engage in a new mission. The result of this is that Alex, by accident, ends up having a conflict with Marco, the bad boy boyfriend of Jessica, entangling him in a conflict he hasn’t asked for and he is pressured by Checkered Ninja to defend himself.', 'Anders Matthesen, Thorbjørn Christoffersen', 84, '2026-01-01', 'T13', 'da', 'https://image.tmdb.org/t/p/w500/sGUesG39H2LWZ6lUTwZXOqUHsxI.jpg', 'https://www.youtube.com/watch?v=coRdidSZRTE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (476, 'Exhuma', 'After tracing the origin of a disturbing supernatural affliction to a wealthy family''s ancestral gravesite, a team of paranormal experts relocates the remains—and soon discovers what happens to those who dare to mess with the wrong grave.', 'Jang Jae-hyun', 134, '2024-02-22', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/6dasJ58GGFcC62H9KuukAryltUp.jpg', 'https://www.youtube.com/watch?v=BLPprtcADkk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (477, 'The Fantastic 4: First Steps', 'Against the vibrant backdrop of a 1960s-inspired, retro-futuristic world, Marvel''s First Family is forced to balance their roles as heroes with the strength of their family bond, while defending Earth from a ravenous space god called Galactus and his enigmatic Herald, Silver Surfer.', 'Matt Shakman', 115, '2025-07-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/nf5qaSEvyYSNeFH0YhSs5EsBLX9.jpg', 'https://www.youtube.com/watch?v=0uDUlDmGhUo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (478, 'tick, tick... BOOM!', 'On the brink of turning 30, a promising theater composer navigates love, friendship and the pressure to create something great before time runs out.', 'Lin-Manuel Miranda', 120, '2021-11-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/DPmfcuR8fh8ROYXgdjrAjSGA0o.jpg', 'https://www.youtube.com/watch?v=YJserno8tyU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (479, 'A Whisker Away', 'A peculiar girl transforms into a cat to catch her crush''s attention. But before she realizes it, the line between human and animal starts to blur.', 'Junichi Sato, Tomotaka Shibayama', 104, '2020-06-18', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/6inkRM1XGBG5vRhclCPWfMenp7N.jpg', 'https://www.youtube.com/watch?v=aXc9DVfLTGo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (480, 'Dogman', 'A boy, bruised by life, finds his salvation through the love of his dogs.', 'Luc Besson', 115, '2023-09-27', 'T18', 'fr', 'https://image.tmdb.org/t/p/w500/5RuUD7J4vO0El7TRL9guZIik0I0.jpg', 'https://www.youtube.com/watch?v=8-IceYBT584', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (481, 'Drishyam 2', '7 years after the case related to Vijay Salgaonkar and his family was closed, a series of unexpected events bring truth to light that threatens to change everything for the Salgaonkars. Can Vijay save his family this time?', 'Abhishek Pathak', 140, '2022-11-18', 'T16', 'hi', 'https://image.tmdb.org/t/p/w500/wk8Vu0DI0MiNLaXXiVqAwjLRKL5.jpg', 'https://www.youtube.com/watch?v=cxA2y9Tgl7o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (482, 'Conclave', 'After the unexpected death of the Pope, Cardinal Lawrence is tasked with managing the covert and ancient ritual of electing a new one. Sequestered in the Vatican with the Catholic Church’s most powerful leaders until the process is complete, Lawrence finds himself at the center of a conspiracy that could lead to its downfall.', 'Edward Berger', 120, '2024-10-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/m5x8D0bZ3eKqIVWZ5y7TnZ2oTVg.jpg', 'https://www.youtube.com/watch?v=JX9jasdi3ic', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (483, 'A Father''s Diary', 'Hassan and Mario are neighbors. They have raised their daughters, Dina and Isabella together, supporting each other through tough times. When Hassan, faces the challenges of modern life, both inside and outside the home, his reactions propel a series of events that threatens everything he holds dear. When his daughter Dina becomes more than good friends, a life partner, with her best friend Isabella, hard decisions have to be made.', 'Golam Mustofa', 113, '2021-01-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/m4q1KyoKeaBa2X0TyAq5yO2cqH0.jpg', 'https://www.youtube.com/watch?v=7TrRU-NhhTg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (484, 'The Devil Wears Prada 2', 'Andy Sachs returns to Runway as Miranda Priestly navigates a new media landscape and Runway''s position within. The duo reconnect with former assistant Emily Charlton, now the head of a luxury brand that possesses funding which could ensure Runway''s survival.', 'David Frankel', 119, '2026-04-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xTI42pmsP5EDnvsNJPEDubwWBQO.jpg', 'https://www.youtube.com/watch?v=PMd1at7OwiE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (485, 'Extraction', 'A hardened gun-for-hire''s latest mission becomes a soul-searching race to survive when he''s sent into Bangladesh to rescue a drug lord''s kidnapped son.', 'Sam Hargrave', 116, '2020-04-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/nygOUcBKPHFTbxsYRFZVePqgPK6.jpg', 'https://www.youtube.com/watch?v=L6P3nI6VnlY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (486, 'De Gaulle: Résistance', 'June, 1940. France collapses and signs the armistice. In the midst of the chaos, one man refuses to give up. Alone against the odds, this unknown general flees to London to save what remains of freedom.', 'Antonin Baudry', 160, '2026-06-03', 'K', 'fr', 'https://image.tmdb.org/t/p/w500/4ri8KO5i7ldQiS3807KXn6awQEs.jpg', 'https://www.youtube.com/watch?v=dKUArYoZ_0U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (487, 'Dragon Ball Super: Broly', 'Earth is peaceful following the Tournament of Power. Realizing that the universes still hold many more strong people yet to see, Goku spends all his days training to reach even greater heights. Then one day, Goku and Vegeta are faced by a Saiyan called ''Broly'' who they''ve never seen before. The Saiyans were supposed to have been almost completely wiped out in the destruction of Planet Vegeta, so what''s this one doing on Earth? This encounter between the three Saiyans who have followed completely different destinies turns into a stupendous battle, with even Frieza (back from Hell) getting caught up in the mix.', 'Tatsuya Nagamine', 101, '2018-12-14', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/uMEgkyiPznZP5AiMSWAk2jsj5gC.jpg', 'https://www.youtube.com/watch?v=1GtIJsvIFAQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (488, 'Violet Evergarden: Eternity and the Auto Memory Doll', 'Violet Evergarden, a former soldier returned from war, comes to teach at a women''s academy and changes a young girl''s life.', 'Haruka Fujita', 90, '2019-09-06', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/3BV1M10SuSi5jOJbSDQQtjX96ov.jpg', 'https://www.youtube.com/watch?v=CcJvT_aiKMA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (489, 'Square One', 'An investigation into the original 1993 Michael Jackson allegations brought by the Chandler family.', 'Danny Wu', 83, '2019-10-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/sVsAd5QoMbzEBt2U3WnzwAGD0dU.jpg', 'https://www.youtube.com/watch?v=MUYq7dhJkow', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (490, 'The Promised Land', 'Denmark, 1755. Captain Ludvig Kahlen sets out to conquer a Danish heath reputed to be uncultivable, with an impossible goal: to establish a colony in the name of the king, in exchange for a royal title. A single-minded ambition that the ruthless lord of the region will relentlessly seek to put down. Kahlen''s fate hangs in the balance: will his endevours bring him wealth and honour, or cost him his life...?', 'Nikolaj Arcel', 127, '2023-10-05', 'T13', 'da', 'https://image.tmdb.org/t/p/w500/okVwls2laPGOsLKKhXQCEiTBwpw.jpg', 'https://www.youtube.com/watch?v=c9U1E9cC5is', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (491, 'Ready or Not', 'A young bride''s wedding night turns into her worst nightmare when her ridiculously rich in-laws force her to play a gruesome game of hide-and-seek.', 'Matt Bettinelli-Olpin, Tyler Gillett', 96, '2019-08-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oJD9KQFoObZmxAS1je56SIFVNJt.jpg', 'https://www.youtube.com/watch?v=LBwfO9Hj6oQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (492, 'The Unforgivable', 'A woman is released from prison after serving a sentence for a violent crime and re-enters a society that refuses to forgive her past.', 'Nora Fingscheidt', 112, '2021-11-24', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/1b3dNFDuE7i05TJlXrIC571yR01.jpg', 'https://www.youtube.com/watch?v=JNUjx7LZoiU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (493, 'Glass Onion: A Knives Out Mystery', 'World-famous detective Benoit Blanc heads to Greece to peel back the layers of a mystery surrounding a tech billionaire and his eclectic crew of friends.', 'Rian Johnson', 140, '2022-11-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vDGr1YdrlfbU9wxTOdpf3zChmv9.jpg', 'https://www.youtube.com/watch?v=-xR_lBtEvSc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (494, 'The Lego Batman Movie', 'A cooler-than-ever Batman must face the usual villains as the Joker plots a takeover of Gotham City. But when Bruce Wayne accidentally adopts a teenage orphan who wishes to become his sidekick, he’s forced to give up his lone-vigilante ways and learn to work with others.', 'Chris McKay', 104, '2017-02-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/e1TliRWOdXQ73pRunbpFiGst6Kd.jpg', 'https://www.youtube.com/watch?v=LHgQSwgKygk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (495, 'Palm Springs', 'When carefree Nyles and reluctant maid of honor Sarah have a chance encounter at a Palm Springs wedding, things get complicated when they find themselves unable to escape the venue, themselves, or each other.', 'Max Barbakow', 90, '2020-07-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gnAfqiV7yO3Jq9IntTmwkcaICqc.jpg', 'https://www.youtube.com/watch?v=CpBLtXduh_k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (496, 'Better Man', 'Follow Robbie Williams'' journey from childhood, to being the youngest member of chart-topping boyband Take That, through to his unparalleled achievements as a record-breaking solo artist – all the while confronting the challenges that stratospheric fame and success can bring.', 'Michael Gracey', 135, '2024-12-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fbGCmMp0HlYnAPv28GOENPShezM.jpg', 'https://www.youtube.com/watch?v=KVeH5T4wxkE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (497, 'Lekh', 'During their teen years, Rajvir and Ronak are attracted to one another but never act on their feelings. As years go on and they drift apart, they are reunited by fate and rediscover their attraction.', 'Manvir Brar', 130, '2022-04-01', 'P', 'pa', 'https://image.tmdb.org/t/p/w500/xUQK8J7RrDRxdd00oGOM55KjJzg.jpg', 'https://www.youtube.com/watch?v=tOlsYCsXJdY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (498, 'The Lion King', 'Simba idolizes his father, King Mufasa, and takes to heart his own royal destiny. But not everyone in the kingdom celebrates the new cub''s arrival. Scar, Mufasa''s brother—and former heir to the throne—has plans of his own. The battle for Pride Rock is ravaged with betrayal, tragedy and drama, ultimately resulting in Simba''s exile. With help from a curious pair of newfound friends, Simba will have to figure out how to grow up and take back what is rightfully his.', 'Jon Favreau', 118, '2019-07-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/dzBtMocZuJbjLOXvrl4zGYigDzh.jpg', 'https://www.youtube.com/watch?v=7TavVZMewpY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (499, 'Transformers: Rise of the Beasts', 'When a new threat capable of destroying the entire planet emerges, Optimus Prime and the Autobots must team up with a powerful faction known as the Maximals. With the fate of humanity hanging in the balance, humans Noah and Elena will do whatever it takes to help the Transformers as they engage in the ultimate battle to save Earth.', 'Steven Caple Jr.', 127, '2023-06-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gPbM0MK8CP8A174rmUwGsADNYKD.jpg', 'https://www.youtube.com/watch?v=WWWDskI46Js', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (500, 'Uncut Gems', 'A charismatic New York City jeweler always on the lookout for the next big score makes a series of high-stakes bets that could lead to the windfall of a lifetime. Howard must perform a precarious high-wire act, balancing business, family, and encroaching adversaries on all sides in his relentless pursuit of the ultimate win.', 'Benny Safdie, Josh Safdie', 136, '2019-12-13', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/6XN1vxHc7kUSqNWtaQKN45J5x2v.jpg', 'https://www.youtube.com/watch?v=akKdBkmugEI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (501, 'Sentimental Value', 'Sisters Nora and Agnes reunite with their estranged father, the charismatic Gustav, a once-renowned director who offers stage actress Nora a role in what he hopes will be his comeback film. When Nora turns it down, she soon discovers he has given her part to an eager young Hollywood star.', 'Joachim Trier', 133, '2025-08-20', 'P', 'no', 'https://image.tmdb.org/t/p/w500/pz9NCWxxOk3o0W3v1Zkhawrwb4i.jpg', 'https://www.youtube.com/watch?v=CbHbW7De3W4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (502, 'The Florida Project', 'The story of a precocious six year-old and her ragtag group of friends whose summer break is filled with childhood wonder, possibility and a sense of adventure while the adults around them struggle with hard times.', 'Sean Baker', 112, '2017-10-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5QnDxdJg1fi6uMSkSi4x8tHsltm.jpg', 'https://www.youtube.com/watch?v=WwQ-NH1rRT4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (503, 'My Hero Academia: Two Heroes', 'All Might and Deku accept an invitation to go abroad to a floating and mobile manmade city, called ''I-Island'', where they research quirks as well as hero supplemental items at the special ''I-Expo'' convention that is currently being held on the island. During that time, suddenly, despite an iron wall of security surrounding the island, the system is breached by a villain, and the only ones able to stop him are the students of Class 1-A.', 'Kenji Nagasaki', 96, '2018-08-03', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/hC4nTxdhXqFWzgqynGvvXVMiMNp.jpg', 'https://www.youtube.com/watch?v=HcwVhcgjKHU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (504, 'Super/Man: The Christopher Reeve Story', 'Christopher Reeve portrayed the Man of Steel in four Superman films and played dozens of other roles that displayed his talent and range as an actor, before being injured in a near-fatal horse-riding accident in 1995 that left him paralyzed from the neck down. After becoming a quadriplegic, he became a charismatic leader and activist in the quest to find a cure for spinal cord injuries, as well as a passionate advocate for disability rights and care.', 'Ian Bonhôte, Peter Ettedgui', 104, '2024-09-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/73WchlI0Hj4HQd0T2KOztKquOek.jpg', 'https://www.youtube.com/watch?v=gX-B3HMlMfY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (505, 'Deep Water', 'A group of international passengers on a flight from Los Angeles to Shanghai is forced to make an emergency landing in shark-infested waters. The terrified group is forced to work together and overcome their differences if they hope to escape their sinking plane and the frenzy of sharks drawn to the wreckage.', 'Renny Harlin', 107, '2026-04-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ZWHxL2ETItcZzeVsVfs6gv3SZ7.jpg', 'https://www.youtube.com/watch?v=f0ptq0Lzdh8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (506, 'Hobal', 'The Saudi family is following strict instructions from their grandfather to remain confined in the desert during the early 1990s. A series of events shakes the family''s foundation and they find them in a struggle between life and death.', 'Abdulaziz Alshlahei', 116, '2025-01-02', 'T13', 'ar', 'https://image.tmdb.org/t/p/w500/z0YPcVdWvxG5dmBL0QRQeB2B6Th.jpg', 'https://www.youtube.com/watch?v=8DbWL7YCF5s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (507, 'Burn the Stage: The Movie', 'Burn the Stage: the Movie is the first movie from BTS, going behind-the-scenes of the BTS WINGS TOUR to reveal the full story of the band’s meteoric rise to fame. This unmissable film provides an intimate look at what happens when the most successful global boy band of all time breaks down barriers and invades the mainstream music scene. Exclusive tour footage and brand-new one-on-one interviews with BTS members give fans an unprecedented glimpse into their lives and an opportunity for everyone to celebrate together worldwide.', 'Park Jun-soo', 85, '2018-11-15', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/pJKy1yvnKh8UjcuYeG3Rt35xHFA.jpg', 'https://www.youtube.com/watch?v=g_6FoBgps9Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (508, 'The Call of the Wild', 'Buck is a big-hearted dog whose blissful domestic life is turned upside down when he is suddenly uprooted from his California home and transplanted to the exotic wilds of the Yukon during the Gold Rush of the 1890s. As the newest rookie on a mail delivery dog sled team—and later its leader—Buck experiences the adventure of a lifetime, ultimately finding his true place in the world and becoming his own master.', 'Chris Sanders', 100, '2020-02-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/33VdppGbeNxICrFUtW2WpGHvfYc.jpg', 'https://www.youtube.com/watch?v=5P8R2zAhEwg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (509, 'The Breadwinner', 'A headstrong young girl in Afghanistan, ruled by the Taliban, disguises herself as a boy in order to provide for her family.', 'Nora Twomey', 94, '2017-11-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/2d6qmkJz9AWqmk9wBWtd2uFX89t.jpg', 'https://www.youtube.com/watch?v=p64O8KAHHaQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (510, 'Girl in the Basement', 'Sara is a teen girl who is looking forward to her 18th birthday to move away from her controlling father Don. But before she could even blow out the candles, Don imprisons her in the basement of their home.', 'Elisabeth Röhm', 88, '2021-02-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tPP9n6r5QrIKPnshnJqE7klptj2.jpg', 'https://www.youtube.com/watch?v=a7VGn_0Vsx8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (511, 'Maharaja', 'A barber seeks vengeance after his home is burglarized, cryptically telling police his "Lakshmi" has been taken, leaving them uncertain if it''s a person or object, jeer at his request until they learn what they''re really looking for.', 'Nithilan Saminathan', 141, '2024-06-14', 'T16', 'ta', 'https://image.tmdb.org/t/p/w500/s0m4TM1XRAftQStgKpw024RvkJo.jpg', 'https://www.youtube.com/watch?v=Otcr-vRuaQs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (512, 'Emancipation', 'Inspired by the gripping true story of a man who would do anything for his family—and for freedom. When Peter, an enslaved man, risks his life to escape and return to his family, he embarks on a perilous journey of love and endurance.', 'Antoine Fuqua', 132, '2022-12-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/AkdNXEquLf4GIkwh1dcSB7j0FTY.jpg', 'https://www.youtube.com/watch?v=C3yHUpR7yv8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (513, 'Sully', 'On 15 January 2009, the world witnessed the ''Miracle on the Hudson'' when Captain ''Sully'' Sullenberger glided his disabled plane onto the Hudson River, saving the lives of all 155 souls aboard. However, even as Sully was being heralded by the public and the media for his unprecedented feat of aviation skill, an investigation was unfolding that threatened to destroy his reputation and career.', 'Clint Eastwood', 96, '2016-09-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4vs83YcJ8TsabADDtaeCJ6ZTjYY.jpg', 'https://www.youtube.com/watch?v=6Tbkbx4Hz8Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (514, 'Last Night in Soho', 'A young girl, passionate about fashion design, is mysteriously able to enter the 1960s where she encounters her idol, a dazzling wannabe singer. But 1960s London is not what it seems, and time seems to be falling apart with shady consequences.', 'Edgar Wright', 117, '2021-10-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/n1ZRmjlk1BJTY7aASqACfPAaLn2.jpg', 'https://www.youtube.com/watch?v=AcVnFrxjPjI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (515, 'Minions: The Rise of Gru', 'A fanboy of a supervillain supergroup known as the Vicious 6, Gru hatches a plan to become evil enough to join them, with the backup of his followers, the Minions.', 'Kyle Balda', 87, '2022-06-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wKiOkZTN9lUUUNZLmtnwubZYONg.jpg', 'https://www.youtube.com/watch?v=6DxjJzmYsXo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (516, 'Kingdom of the Planet of the Apes', 'Several generations following Caesar''s reign, apes – now the dominant species – live harmoniously while humans have been reduced to living in the shadows. As a new tyrannical ape leader builds his empire, one young ape undertakes a harrowing journey that will cause him to question all he''s known about the past and to make choices that will define a future for apes and humans alike.', 'Wes Ball', 145, '2024-05-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gKkl37BQuKTanygYQG1pyYgLVgf.jpg', 'https://www.youtube.com/watch?v=Kdr5oedn7q8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (517, 'I Can Only Imagine 2', 'Following the breakout success of the song ''I Can Only Imagine'', MercyMe''s Bart Millard is living the dream—sold-out arenas, a devoted fanbase, and a thriving career. But behind the spotlight, Bart''s past threatens the family he''s built, especially the fragile bond with his son Sam. When hopeful newcomer Tim Timmons joins the band for their biggest tour yet, he unknowingly brings a renewed gratitude to Bart''s life through their unlikely friendship. Bart soon discovers that Tim carries hardships—and secrets—of his own, forcing him to face his past and repair his relationships with Sam and his wife Shannon before fame costs him what matters most.', 'Andrew Erwin, Brent McCorkle', 110, '2026-02-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7McqI2S0tmfCPAP15Ivve9sa6cZ.jpg', 'https://www.youtube.com/watch?v=8MLqWdUOZYQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (518, 'The Greatest Night in Pop', 'On a January night in 1985, music''s biggest stars gathered to record "We Are the World." This documentary goes behind the scenes of the historic event.', 'Bao Nguyen', 96, '2024-01-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jDz4wFujk94tQP9Sx6EMKDULvkn.jpg', 'https://www.youtube.com/watch?v=MD3oU1gowu4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (519, 'Maleficent: Mistress of Evil', 'Maleficent and her goddaughter Aurora begin to question the complex family ties that bind them as they are pulled in different directions by impending nuptials, unexpected allies, and dark new forces at play.', 'Joachim Rønning', 119, '2019-10-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vloNTScJ3w7jwNwtNGoG8DbTThv.jpg', 'https://www.youtube.com/watch?v=1qIziwbp_7A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (520, 'Be With You', 'Along with his young son, Ji-ho, Woo-jin misses his wife Soo-a, who died after promising to return a year later with the rainy season. Miraculously, they reunite with Soo-a when the rainy season comes around, but she has no memory of her husband and son whom she dearly loved.', 'Lee Jang-hoon', 132, '2018-03-14', 'T13', 'ko', 'https://image.tmdb.org/t/p/w500/mvstNgM68EyCRWwpArakLhWvvtk.jpg', 'https://www.youtube.com/watch?v=s_GBy9vx2PQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (521, 'My First Client', 'A success-hungry lawyer finds himself unable to turn his back on a suspicious case involving a child who claims she murdered her brother.', 'Jang Kyu-sung', 114, '2019-05-22', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/fLss1W1DuAI9kL0Kc8iI9bnJt0.jpg', 'https://www.youtube.com/watch?v=ZKfDdo0Anlg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (522, 'Ultraman: Rising', 'A star athlete reluctantly returns home to take over his father''s duties as Ultraman, shielding Tokyo from giant monsters as he becomes a legendary hero.', 'Shannon Tindle', 117, '2024-06-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/j886YEkIUsiImY53px5VHKD4lRa.jpg', 'https://www.youtube.com/watch?v=TwXgOMDONK8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (523, 'Fast X', 'Over many missions and against impossible odds, Dom Toretto and his family have outsmarted, out-nerved and outdriven every foe in their path. Now, they confront the most lethal opponent they''ve ever faced: A terrifying threat emerging from the shadows of the past who''s fueled by blood revenge, and who is determined to shatter this family and destroy everything—and everyone—that Dom loves, forever.', 'Louis Leterrier', 142, '2023-05-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fiVW06jE7z9YnO4trhaMEdclSiC.jpg', 'https://www.youtube.com/watch?v=32RAq6JzY-w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (524, 'STILL: A Michael J. Fox Movie', 'A short kid from a Canadian army base becomes the international pop culture darling of the 1980s—only to find the course of his life altered by a stunning diagnosis. What happens when an incurable optimist confronts an incurable disease?', 'Davis Guggenheim', 95, '2023-01-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fDO4gYZxvdsIrHKzsSAbc3N7Wfg.jpg', 'https://www.youtube.com/watch?v=yHgMSR4F1Ak', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (525, 'Richard Jewell', 'Richard Jewell thinks quick, works fast, and saves hundreds, perhaps thousands, of lives after a domestic terrorist plants several pipe bombs and they explode during a concert, only to be falsely suspected of the crime by sloppy FBI work and sensational media coverage.', 'Clint Eastwood', 131, '2019-12-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5Lgkm8jt4roAFPZQ52fKMhVmDaZ.jpg', 'https://www.youtube.com/watch?v=gSMxBLlA8qY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (526, 'Bring the Soul: The Movie', 'A glimpse into K-pop group BTS’ world away from the stage, featuring intimate group discussions alongside spectacular concert performances from their world tour.', 'Park Jun-soo', 105, '2019-08-07', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/7x5CguA0MxHqbSjhi14UEuK7c95.jpg', 'https://www.youtube.com/watch?v=AwrClxIhsYc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (527, 'Enola Holmes', 'While searching for her missing mother, intrepid teen Enola Holmes uses her sleuthing skills to outsmart big brother Sherlock and help a runaway lord.', 'Harry Bradbeer', 124, '2020-09-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/riYInlsq2kf1AWoGm80JQW5dLKp.jpg', 'https://www.youtube.com/watch?v=1d0Zf9sXlHk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (528, 'Enola Holmes 2', 'Enola takes on her first official case as a detective, but to solve the mystery of a missing girl, she''ll need help from friends — and brother Sherlock.', 'Harry Bradbeer', 131, '2022-11-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/tegBpjM5ODoYoM1NjaiHVLEA0QM.jpg', 'https://www.youtube.com/watch?v=0DIftINqIjo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (529, 'Sisu', 'When an ex-soldier who discovers gold in the Lapland wilderness tries to take the loot into the city, German soldiers led by a brutal SS officer battle him.', 'Jalmari Helander', 91, '2022-09-09', 'T16', 'fi', 'https://image.tmdb.org/t/p/w500/xgb30M1wL4nibyFvlHh3w4XlDYq.jpg', 'https://www.youtube.com/watch?v=d2k4QAItiSA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (530, 'Gabriel''s Inferno: Part III', 'The final part of the film adaption of the erotic romance novel Gabriel''s Inferno written by an anonymous Canadian author under the pen name Sylvain Reynard.', 'Tosca Musk', 102, '2020-11-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fYtHxTxlhzD4QWfEbrC1rypysSD.jpg', 'https://www.youtube.com/watch?v=mjPUGem9SaY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (531, 'Never Look Away', 'German artist Kurt Barnert has escaped East Germany and now lives in West Germany, but is tormented by his childhood under the Nazis and the GDR regime.', 'Florian Henckel von Donnersmarck', 188, '2018-10-03', 'P', 'de', 'https://image.tmdb.org/t/p/w500/fn0Tp9SG0IQ3Nx8iHPYPiseLMWd.jpg', 'https://www.youtube.com/watch?v=gCEYXnDNcrg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (532, 'Moana 2', 'After receiving an unexpected call from her wayfinding ancestors, Moana journeys alongside Maui and a new crew to the far seas of Oceania and into dangerous, long-lost waters for an adventure unlike anything she''s ever faced.', 'Dana Ledoux Miller, David G. Derrick Jr., Jason Hand', 100, '2024-11-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aLVkiINlIeCkcZIzb7XHzPYgO6L.jpg', 'https://www.youtube.com/watch?v=JdSl4RMNtGE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (533, 'Raado', 'Some powerful people, with strong political influence, leaders of the crowd and determined law enforcement collide with one another and the society implodes.', 'Krishnadev Yagnik', 142, '2022-07-22', 'T16', 'gu', 'https://image.tmdb.org/t/p/w500/gAILFHdcSbgCE9mQX2j6Jn9pzgP.jpg', 'https://www.youtube.com/watch?v=ee77lfNAAhc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (534, 'Pashupati Prasad', 'Pashupati visits Kathmandu to meet his Mitbaa and pay his father''s loans but his stay is made difficult by Bhasme and his gang.', 'Dipendra K. Khanal', 138, '2016-01-29', 'K', 'ne', 'https://image.tmdb.org/t/p/w500/cFN1xnKcrr8bDiuEf47MrSyHSQg.jpg', 'https://www.youtube.com/watch?v=O3GRxW9IkTg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (535, 'Phantom Thread', 'In 1950s London, a renowned dressmaker''s meticulous lifestyle begins drastically changing as his relationship with his young muse intensifies.', 'Paul Thomas Anderson', 130, '2017-12-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hgoWjp9Sh0MI97eAMZCnIoVfgvq.jpg', 'https://www.youtube.com/watch?v=xNsiQMeSvMk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (536, 'Mr Dread', 'Dehşet Engiz, a top hitman from a forbidden organization called Fedailer Ocağı, falls in love with Dr. Abide. This unprecedented feeling leads him to question the group''s rules against love, potentially forcing him to choose between his duty and his newfound love for Abide, which could have heavy consequences for everyone.', 'Mehmet Ada Öztekin', 139, '2025-10-30', 'T18', 'tr', 'https://image.tmdb.org/t/p/w500/9Mg9q8hsv7aaUspAW2taRHXNkmC.jpg', 'https://www.youtube.com/watch?v=itcj_pBvNSA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (537, 'The Wailing', 'A stranger arrives in a little village and soon after a mysterious sickness starts spreading. A policeman is drawn into the incident and is forced to solve the mystery in order to save his daughter.', 'Na Hong-jin', 156, '2016-05-12', 'T18', 'ko', 'https://image.tmdb.org/t/p/w500/lWE9ih9qgjx8HatYboP7fG0nri.jpg', 'https://www.youtube.com/watch?v=43uAputjI4k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (538, 'The Founder', 'The true story of how Ray Kroc, a salesman from Illinois, met Mac and Dick McDonald, who were running a burger operation in 1950s Southern California. Kroc was impressed by the brothers’ speedy system of making the food and saw franchise potential. He maneuvered himself into a position to be able to pull the company from the brothers and create a billion-dollar empire.', 'John Lee Hancock', 115, '2016-11-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8gLIksu5ggdfBL1UbeTeonHquxl.jpg', 'https://www.youtube.com/watch?v=oprJX5BomEc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (539, 'Beauty and the Beast', 'A live-action adaptation of Disney''s version of the classic tale of a cursed prince and a beautiful young woman who helps him break the spell.', 'Bill Condon', 129, '2017-03-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hKegSKIDep2ewJWPUQD7u0KqFIp.jpg', 'https://www.youtube.com/watch?v=Fp0DE1hyO6o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (540, 'Aladdin', 'A kindhearted street urchin named Aladdin embarks on a magical adventure after finding a lamp that releases a wisecracking genie while a power-hungry Grand Vizier vies for the same lamp that has the power to make their deepest wishes come true.', 'Guy Ritchie', 127, '2019-05-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ykUEbfpkf8d0w49pHh0AD2KrT52.jpg', 'https://www.youtube.com/watch?v=foyufD52aog', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (541, 'The Yellow Tie', 'The extraordinary life of Sergiu Celibidache, from his childhood in Romania to his exile in pursuit of a career in music, his struggle for survival in wartime Germany and his rise, fall and rise again, in an unimaginable life journey.', 'Serge Ioan Celebidachi', 145, '2025-11-14', 'P', 'ro', 'https://image.tmdb.org/t/p/w500/tkCQjcvLKG5HhvVyqkNriifLgLW.jpg', 'https://www.youtube.com/watch?v=2BhecPoz6bU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (542, 'Argentina 1985', 'In the 1980s, a team of lawyers takes on the heads of Argentina''s bloody military dictatorship in a battle against odds and a race against time.', 'Santiago Mitre', 141, '2022-09-29', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/nmh7vD2eDVRqFJoCpEzVcfGcPPf.jpg', 'https://www.youtube.com/watch?v=a4iiyPOM6rA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (543, 'Ralph Breaks the Internet', 'Video game bad guy Ralph and fellow misfit Vanellope von Schweetz must risk it all by traveling to the World Wide Web in search of a replacement part to save Vanellope''s video game, Sugar Rush. In way over their heads, Ralph and Vanellope rely on the citizens of the internet — the netizens — to help navigate their way, including an entrepreneur named Yesss, who is the head algorithm and the heart and soul of trend-making site BuzzzTube.', 'Phil Johnston, Rich Moore', 112, '2018-11-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iVCrhBcpDaHGvv7CLYbK6PuXZo1.jpg', 'https://www.youtube.com/watch?v=DIBw9dSVKdU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (544, 'The Dawn Wall', 'In an unbelievable story of perseverance, free climber Tommy Caldwell and climbing partner Kevin Jorgeson attempt to scale the impossible 3000ft Dawn Wall of El Capitan.', 'Josh Lowell, Peter Mortimer', 101, '2017-11-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/bZQCNGb1II5eWASBhEgJBGxOPUM.jpg', 'https://www.youtube.com/watch?v=5Hc8tB9uhho', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (545, 'I, Daniel Blake', 'A 59-year-old carpenter recovering from a heart attack befriends a single mother and her two kids as they navigate the impersonal, Kafkaesque benefits system. With equal amounts of humour, warmth and despair, the journey is heartfelt and emotional until the end.', 'Ken Loach', 100, '2016-10-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nu3WVABXz2W85N6JXTZOT1aWS3b.jpg', 'https://www.youtube.com/watch?v=ahWgxw9E_h4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (546, 'Pawn', 'A debt collector who looks intimidating, but actually has a warm heart, ends up becoming the guardian of a child, who has been left behind as collateral by her illegal immigrant mother.', 'Kang Dae-gyu', 113, '2020-09-29', 'K', 'ko', 'https://image.tmdb.org/t/p/w500/nNgeb1Jy18azKKDcUUdh1Hhkjbr.jpg', 'https://www.youtube.com/watch?v=ylq5mKnv07Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (547, '6 Days', 'Yusef and Alia, former high school sweethearts separated by fate, are brought together years later, forced to confront their past and whether their rekindled love can withstand their changed lives. They must determine if they can navigate the complexities of their new realities to find a second chance at romance.', 'Karim Shaaban', 105, '2025-01-15', 'P', 'ar', 'https://image.tmdb.org/t/p/w500/eZ4vyiAfZXSyuKygWjmCCcDFd5P.jpg', 'https://www.youtube.com/watch?v=hSZvUFoCgH8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (548, 'Arthur the King', 'Over the course of ten days and 435 miles, an unbreakable bond is forged between pro adventure racer Michael Light and a scrappy street dog companion dubbed Arthur. As the team is pushed to their outer limits of endurance in the race, Arthur redefines what victory, loyalty and friendship truly mean.', 'Simon Cellan Jones', 107, '2024-02-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zkKB3kOun5DKAkm61pHvLbrjxfa.jpg', 'https://www.youtube.com/watch?v=wjDJNEPghNY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (549, 'Pratikshya', 'An unemployed graduate faces the dilemma of securing a government job and saving his father after the family meets a medical crisis.', 'Anupam Patnaik', 137, '2022-12-02', 'P', 'or', 'https://image.tmdb.org/t/p/w500/n5T8NqVwzp68kIgI9DHcMNkeKPJ.jpg', 'https://www.youtube.com/watch?v=E_p4kHzZBTM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (550, 'Bad Boys for Life', 'Marcus and Mike are forced to confront new threats, career changes, and midlife crises as they join the newly created elite team AMMO of the Miami police department to take down the ruthless Armando Armas, the vicious leader of a Miami drug cartel.', 'Adil El Arbi, Bilall Fallah', 124, '2020-01-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/y95lQLnuNKdPAzw9F9Ab8kJ80c3.jpg', 'https://www.youtube.com/watch?v=R228yPrwqTo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
