  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (551, 'The Two Popes', 'Frustrated with the direction of the church, Cardinal Bergoglio requests permission to retire in 2012 from Pope Benedict. Instead, facing scandal and self-doubt, the introspective Pope Benedict summons his harshest critic and future successor to Rome to reveal a secret that would shake the foundations of the Catholic Church.', 'Fernando Meirelles', 125, '2019-11-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4d4mTSfDIFIbUbMLUfaKodvxYXA.jpg', 'https://www.youtube.com/watch?v=T5OhkFY1PQE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (552, 'Natsamrat', 'A veteran Shakespearean actor steps off the stage and into the painful tragedy of old age, facing ungrateful family and his fleeting legacy. Based on a play of the same name written by playwright Kusumagraj (V. V. Shirwadkar).', 'Mahesh Manjrekar', 166, '2016-01-01', 'T13', 'mr', 'https://image.tmdb.org/t/p/w500/x4KvM8NBi8m44aqwEMgsJPzA5Ne.jpg', 'https://www.youtube.com/watch?v=DCXDyIsPEN8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (553, 'The Rip', 'Trust frays when a team of Miami cops discovers millions in cash inside a run-down stash house, calling everyone — and everything — into question.', 'Joe Carnahan', 113, '2026-01-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4wsYWH73Hb1B6noGIFaRQSAkuXj.jpg', 'https://www.youtube.com/watch?v=yeR5bcbRPak', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (554, 'Nirvanna the Band the Show the Movie', 'When their plan to book a show at the Rivoli goes horribly wrong, Matt and Jay accidentally travel back to the year 2008.', 'Matt Johnson', 100, '2026-02-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/sm5TGX8WbnCd9Uo26cLyTxVwA1n.jpg', 'https://www.youtube.com/watch?v=y2K9ccMREOI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (555, 'Gaga Chromatica Ball', 'In front of a sold-out crowd of 52,000 people, Lady Gaga delivers a career-defining performance at Los Angeles''s Dodger Stadium during her 2022 Chromatica Ball Tour.', 'Lady Gaga, Nick Knight', 113, '2024-07-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kxrJArfrDlxukCXiiMDhsEvMXfS.jpg', 'https://www.youtube.com/watch?v=IW6LngKk9f4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (556, 'Air', 'Discover the game-changing partnership between a then undiscovered Michael Jordan and Nike''s fledgling basketball division which revolutionized the world of sports and culture with the Air Jordan brand.', 'Ben Affleck', 112, '2023-04-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/76AKQPdH3M8cvsFR9K8JsOzVlY5.jpg', 'https://www.youtube.com/watch?v=Euy4Yu6B3nU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (557, 'Train Dreams', 'A logger leads a life of quiet grace as he experiences love and loss during an era of monumental change in early 20th-century America.', 'Clint Bentley', 102, '2025-11-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jnaOmD9PmAkNjgVtCn17o7clOYe.jpg', 'https://www.youtube.com/watch?v=6voWeM-xQ4Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (558, 'Krantijyoti Vidyalay Marathi Madhyam', 'Students and teachers from a Marathi school come together to save their school from demolition, as an international school is set to be built in its place. Personal challenges merge with institutional struggles as they seek preservation of Marathi-medium schools and their local culture, while also acknowledging the need for change.', 'Hemant Dhome', 149, '2026-01-01', 'K', 'mr', 'https://image.tmdb.org/t/p/w500/xoswfeiBUEnWzBfixEvRbCUIwpV.jpg', 'https://www.youtube.com/watch?v=bPvWVuqfz1Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (559, 'The Worst Person in the World', 'The chronicles of four years in the life of Julie, a young woman who navigates the troubled waters of her love life and struggles to find her career path, leading her to take a realistic look at who she really is.', 'Joachim Trier', 128, '2021-10-13', 'P', 'no', 'https://image.tmdb.org/t/p/w500/1NxGNQchGBTHXJ6RShLY1IlZqWn.jpg', 'https://www.youtube.com/watch?v=42ouy74zntk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (560, 'Mirage', 'During a mysterious thunderstorm, Vera, a young mother, manages to save a life in danger, but her good deed causes a disturbing chain of unexpected consequences.', 'Oriol Paulo', 129, '2018-11-30', 'T18', 'es', 'https://image.tmdb.org/t/p/w500/hmhYM1CNBhpWTYjUEZ4leQDmIYw.jpg', 'https://www.youtube.com/watch?v=3NCOwTBWYdE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (561, 'Apollo 11', 'A look at the Apollo 11 mission to land on the moon led by commander Neil Armstrong and pilot Buzz Aldrin.', 'Todd Douglas Miller', 93, '2019-03-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/woLMRroHyoTGoXyxdEeBJEYBFtu.jpg', 'https://www.youtube.com/watch?v=3Co8Z8BQgWc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (562, 'God''s Own Country', 'A young farmer in rural Yorkshire numbs his daily frustrations with binge drinking and casual sex, until the arrival of a Romanian migrant worker.', 'Francis Lee', 104, '2017-08-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hKJz8Moim43P1f1kGrM9Gh0c0rf.jpg', 'https://www.youtube.com/watch?v=2sPE9sbXQoQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (563, 'Black Beauty', 'Born free in the American West, Black Beauty is a horse rounded up and brought to Birtwick Stables, where she meets spirited teenager Jo Green. The two forge a bond that carries Beauty through the different chapters, challenges and adventures.', 'Ashley Avis', 110, '2020-11-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5ZjMNJJabwBEnGVQoR2yoMEL9um.jpg', 'https://www.youtube.com/watch?v=DpZ3yZhsWZE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (564, 'Talk to Me', 'When a group of friends discover how to conjure spirits using an embalmed hand, they become hooked on the new thrill, until one of them goes too far and unleashes terrifying supernatural forces.', 'Danny Philippou, Michael Philippou', 95, '2023-07-26', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/kdPMUMJzyYAc4roD52qavX0nLIC.jpg', 'https://www.youtube.com/watch?v=PGo4wfCejsk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (565, 'John Candy: I Like Me', 'Those who knew iconic funnyman John Candy best share his story, in their own words, through never-before-seen archival footage, imagery, and interviews.', 'Colin Hanks', 113, '2025-09-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/mNEJdx9WSXeyMmkuQfTeY4zouNx.jpg', 'https://www.youtube.com/watch?v=PrcQRsrBcCk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (566, '13th', 'An in-depth look at the prison system in the United States and how it reveals the nation''s history of racial inequality.', 'Ava DuVernay', 100, '2016-10-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tcKNWD6IFPPsvkpvyZ548naz0is.jpg', 'https://www.youtube.com/watch?v=K6IXQbXPO3I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (567, 'Truth & Treason', 'When loyalty to country becomes loyalty to a lie, one teen risks everything to expose the truth. With the Gestapo closing in, he must decide what it really means to be a good German.', 'Matt Whitaker', 121, '2025-10-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ArDLn658OjT3dMThIi4GDQJRuY3.jpg', 'https://www.youtube.com/watch?v=MoUnZcAd5uE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (568, 'Strung', 'A talented violinist''s prestigious new role as a music tutor for an enigmatic, elite family spirals into a psychological battle for her safety and sanity.', 'Malcolm D. Lee', 119, '2026-06-18', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/exO0gvoZUXERxUaejyDchobOvjD.jpg', 'https://www.youtube.com/watch?v=DT_i0aq-vPs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (569, 'Hi Nanna', 'Six-year-old Mahi, a spirited child with cystic fibrosis, shares a deep yet complex bond with her father, Viraj, a dedicated single parent and successful fashion photographer. Her curiosity about her absent mother leads to a journey of discovery when she runs away with her loyal dog, Pluto. A chance encounter with a kind woman named Yashna sparks unexpected revelations, intertwining their lives in ways they never anticipated. Set against a backdrop of love, sacrifice, and redemption, Mahi’s story is a heartfelt exploration of family, resilience, and the enduring power of connection.', 'Shouryuv', 155, '2023-12-07', 'P', 'te', 'https://image.tmdb.org/t/p/w500/hhMLtq9m1aK0dpY9Wcq26XeDH2z.jpg', 'https://www.youtube.com/watch?v=3Ld05Om2UWs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (570, 'Marty, Life Is Short', 'Martin Short looks back on a life fueled by joy in this documentary with classic clips, fresh interviews and star-studded, never-before-seen home movies.', 'Lawrence Kasdan', 102, '2026-05-11', 'K', 'en', 'https://image.tmdb.org/t/p/w500/5u8r3iMUVeVejv8G2PrRvlTbogC.jpg', 'https://www.youtube.com/watch?v=QBvYXE6oZ64', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (571, 'Descendants 3', 'The teenagers of Disney''s most infamous villains return to the Isle of the Lost to recruit a new batch of villainous offspring to join them at Auradon Prep.', 'Kenny Ortega', 106, '2019-08-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7IRy0iHdaS0JI3ng4ZYlk5gLSFn.jpg', 'https://www.youtube.com/watch?v=8jpvcD_LkK4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (572, 'Vickida No Varghodo', 'Vikas Majethia aka your Vicky is getting married soon. Amidst the festivities, things take an exciting twist, when not one, but two of his exes return to his life. The big question on everyone''s mind, including Vicky''s, is who will he get married to?', NULL, 148, '2022-07-08', 'K', 'gu', 'https://image.tmdb.org/t/p/w500/wH6V9Mep6r7RBtfKUnyXVlG5dUX.jpg', 'https://www.youtube.com/watch?v=-y8f_RbYpMY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (573, 'Io Capitano', 'Longing for a brighter future, two Senegalese teenagers embark on a journey from West Africa to Italy. However, between their dreams and reality lies a labyrinth of checkpoints, the Sahara Desert, and the vast waters of the Mediterranean.', 'Matteo Garrone', 121, '2023-09-07', 'P', 'it', 'https://image.tmdb.org/t/p/w500/kGlZFwUQI5gAUdySNFfqGIkAF9n.jpg', 'https://www.youtube.com/watch?v=5Mg_AiPGw-0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (574, 'Godzilla x Kong: The New Empire', 'Following their explosive showdown, Godzilla and Kong must reunite against a colossal undiscovered threat hidden within our world, challenging their very existence – and our own.', 'Adam Wingard', 115, '2024-03-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/z1p34vh7dEOnLDmyCrlUVLuoDzd.jpg', 'https://www.youtube.com/watch?v=XeDbyVODQ5M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (575, 'Ant-Man and the Wasp', 'Just when his time under house arrest is about to end, Scott Lang once again puts his freedom at risk to help Hope van Dyne and Dr. Hank Pym dive into the quantum realm and try to accomplish, against time and any chance of success, a very dangerous rescue mission.', 'Peyton Reed', 119, '2018-07-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/cFQEO687n1K6umXbInzocxcnAQz.jpg', 'https://www.youtube.com/watch?v=8_rTIAOohas', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (576, 'Send Help', 'Two colleagues become stranded on a deserted island, the only survivors of a plane crash. On the island, they must overcome past grievances and work together to survive, but ultimately, it''s a battle of wills and wits to make it out alive.', 'Sam Raimi', 113, '2026-01-22', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/zbJWVHOtj3ljBzWgL1P8pxP03Up.jpg', 'https://www.youtube.com/watch?v=R4wiXj9NmEE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (577, 'My Life as a Zucchini', 'After his mother’s death, Zucchini is befriended by a kind police officer, Raymond, who accompanies him to his new foster home filled with other orphans his age. There, with the help of his newfound friends, Zucchini eventually learns to trust and love as he searches for a new family of his own.', 'Claude Barras', 66, '2016-09-22', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/2uu8fIzl76C9MFiUQhjKYSLKVq.jpg', 'https://www.youtube.com/watch?v=8Dtqw1dTMHc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (578, 'The Northman', 'Prince Amleth is on the verge of becoming a man when his father is brutally murdered by his uncle, who kidnaps the boy''s mother. Two decades later, Amleth is now a Viking who''s on a mission to save his mother, kill his uncle and avenge his father.', 'Robert Eggers', 137, '2022-04-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aSSJMnHknzKjlZ6zybwD7eyJ4Po.jpg', 'https://www.youtube.com/watch?v=6WrpvCmv0hk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (579, 'Sing', 'A koala named Buster recruits his best friend to help him drum up business for his theater by hosting a singing competition.', 'Garth Jennings', 108, '2016-11-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/rwopfpHqPCYBSgBuZwkaXXqHp14.jpg', 'https://www.youtube.com/watch?v=GIgXWuLQPFY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (580, 'All of Us Strangers', 'One night in his near-empty tower block in contemporary London, Adam has a chance encounter with a mysterious neighbor, which punctures the rhythm of his everyday life.', 'Andrew Haigh', 105, '2023-12-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aviJMFZSnnCAsCVyJGaPNx4Ef3i.jpg', 'https://www.youtube.com/watch?v=1SMz_C9lI1o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (581, 'Bāhubali 2: The Conclusion', 'When Mahendra, the son of Bāhubali, learns about his heritage, he begins to look for answers. His story is juxtaposed with past events that unfolded in the Mahishmati Kingdom.', 'S. S. Rajamouli', 167, '2017-04-27', 'T13', 'te', 'https://image.tmdb.org/t/p/w500/21sC2assImQIYCEDA84Qh9d1RsK.jpg', 'https://www.youtube.com/watch?v=qD-6d8Wo3do', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (582, 'See You Up There', 'In November 1918, a few days before the Armistice, when Lieutenant Pradelle orders a senseless attack, he causes a useless disaster; but his outrageous act also binds the lives of two soldiers who have nothing more in common than the battlefield: Édouard saves Albert, although at a high cost. They become companions in misfortune who will attempt to survive in a changing world. Pradelle, in his own way, does the same.', 'Albert Dupontel', 113, '2017-10-25', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/pkO5YoznMR9neuHVzhxHK9JJpAj.jpg', 'https://www.youtube.com/watch?v=bIqPXc5QU3U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (583, 'Pariyerum Perumal', 'A law student from a lower caste begins a friendship with his classmate, a girl who belongs to a higher caste, and the men in her family start giving him trouble over this.', 'Mari Selvaraj', 155, '2018-09-28', 'P', 'ta', 'https://image.tmdb.org/t/p/w500/78YoIO3gzkZPC1jotfDmolNDmgT.jpg', 'https://www.youtube.com/watch?v=GMNsUxJe4R4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (584, 'Doctor Sleep', 'Still scarred by the trauma he endured as a child at the Overlook Hotel, Dan Torrance faces the ghosts of the past when he meets Abra, a courageous teen who desperately needs his help -- and who possesses a powerful extrasensory ability called the "shine".', 'Mike Flanagan', 152, '2019-10-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/p69QzIBbN06aTYqRRiCOY1emNBh.jpg', 'https://www.youtube.com/watch?v=2msJTFvhkU4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (585, 'Red One', 'After Santa Claus (codename: Red One) is kidnapped, the North Pole''s Head of Security must team up with the world''s most infamous tracker in a globe-trotting, action-packed mission to save Christmas.', 'Jake Kasdan', 124, '2024-10-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cdqLnri3NEGcmfnqwk2TSIYtddg.jpg', 'https://www.youtube.com/watch?v=7l3hfD74X-4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (586, 'The Witch', 'In 1630, a farmer relocates his family to a remote plot of land on the edge of a forest where strange, unsettling things happen. With suspicion and paranoia mounting, each family member''s faith, loyalty and love are tested in shocking ways.', 'Robert Eggers', 92, '2016-02-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zap5hpFCWSvdWSuPGAQyjUv2wAC.jpg', 'https://www.youtube.com/watch?v=97OQ7MQC5Ck', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (587, 'The Kissing Booth 2', 'With college decisions looming, Elle juggles her long-distance romance with Noah, changing relationship with bestie Lee and feelings for a new classmate.', 'Vince Marcello', 132, '2020-07-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/mb7wQv0adK3kjOUr9n93mANHhPJ.jpg', 'https://www.youtube.com/watch?v=fjVonI2oVeM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (588, 'Bad Genius', 'Lynn, a brilliant student, after helping her friends to get the grades they need, develops the idea of starting a much bigger exam-cheating business.', 'Nattawut Poonpiriya', 130, '2017-05-03', 'T18', 'th', 'https://image.tmdb.org/t/p/w500/g1gW6DQ7QFocDn24QBOZqoYpd3O.jpg', 'https://www.youtube.com/watch?v=CLdhN4oMxCQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (589, 'The Idea of You', '40-year-old single mom Solène begins an unexpected romance with 24-year-old Hayes Campbell, the lead singer of August Moon, the hottest boy band on the planet. As they begin a whirlwind romance, it isn''t long before Hayes'' superstar status poses unavoidable challenges to their relationship, and Solène soon discovers that life in the glare of his spotlight might be more than she bargained for.', 'Michael Showalter', 116, '2024-05-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/Y5P4Q3q8nrruZ9aD3wXeJS2Plg.jpg', 'https://www.youtube.com/watch?v=pz6qx4n2Ewc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (590, 'j-hope IN THE BOX', 'For 200 days, the daily life of artist j-hope is captured. From his production of solo album "Jack in the Box" and listening party, this documentary follows him all the way to his debut on the stage of "Lollapalooza."', 'Park Jun-soo', 85, '2023-06-16', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/6EzOqBScbCqoTKCM77LEPxgSNTi.jpg', 'https://www.youtube.com/watch?v=rGESlN9wias', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (591, 'Dhurandhar', 'In the early 2000s, an undercover operative infiltrates Karachi''s underworld, breaking into its inner circle to dismantle a violent nexus from within.', 'Aditya Dhar', 214, '2025-12-05', 'T16', 'hi', 'https://image.tmdb.org/t/p/w500/8FHOtUpNIk5ZPEay2N2EY5lrxkv.jpg', 'https://www.youtube.com/watch?v=o--C7AH5SuI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (592, 'Finding Dory', 'Dory is reunited with her friends Nemo and Marlin in the search for answers about her past. What can she remember? Who are her parents? And where did she learn to speak Whale?', 'Andrew Stanton', 97, '2016-06-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3UVe8NL1E2ZdUZ9EDlKGJY5UzE.jpg', 'https://www.youtube.com/watch?v=JhvrQeY3doI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (593, '28 Years Later: The Bone Temple', 'Dr. Kelson finds himself in a shocking new relationship - with consequences that could change the world as they know it - and Spike''s encounter with Jimmy Crystal becomes a nightmare he can''t escape.', 'Nia DaCosta', 109, '2026-01-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kK1BGkG3KAvWB0WMV1DfOx9yTMZ.jpg', 'https://www.youtube.com/watch?v=EOwTdTZA8D8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (594, 'The Creator', 'Amid a future war between the human race and the forces of artificial intelligence, a hardened ex-special forces agent grieving the disappearance of his wife, is recruited to hunt down and kill the Creator, the elusive architect of advanced AI who has developed a mysterious weapon with the power to end the war—and mankind itself.', 'Gareth Edwards', 134, '2023-09-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3dSivDtOuyxLDxPH4v2tcNG1fP7.jpg', 'https://www.youtube.com/watch?v=573GCxqkYEg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (595, 'Green Snake', 'While trying to free her sister from Fahai''s clutches, Xiao Qing winds up in a dystopian city and meets a mysterious man who can''t recall his past life.', 'Amp Wong', 132, '2021-07-23', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/g9SQCIGHDqol11QcymtDqMI7SCp.jpg', 'https://www.youtube.com/watch?v=atyZQvSJLYo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (596, 'The First Slam Dunk', 'Shohoku''s “speedster” and point guard, Ryota Miyagi, always plays with brains and lightning speed, running circles around his opponents while feigning composure. In his second year of high school, Ryota plays with the Shohoku High School basketball team along with Sakuragi, Rukawa, Akagi, and Mitsui as they take the stage at the Inter-High School National Championship. And now, they are on the brink of challenging the reigning champions, Sannoh Kogyo High School.', 'Takehiko Inoue', 125, '2022-12-03', 'K', 'ja', 'https://image.tmdb.org/t/p/w500/yq4tSiYvfGw150Ntq8NbsFZ12En.jpg', 'https://www.youtube.com/watch?v=E-gGTCru5ZM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (597, 'Ohh My Dog', 'In Assam, 14-year-old Apu embarks on a desperate quest to rescue his beloved dog, Momo, after he is kidnapped. Elsewhere, in Bihar, a devoted dog named Oscar sets out on a perilous journey to find his kidnapped owner, a 15-year-old child labourer. As their journeys unfold, it becomes clear that the two kidnappings may be connected to a larger, sinister plan.', 'Amit Rai', 150, '2026-08-06', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/zzHV3rmS07lrFkcHXFx2J9JhZwJ.jpg', 'https://www.youtube.com/watch?v=Hkv1-F5-EaI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (598, 'Kingsman: The Golden Circle', 'When an attack on the Kingsman headquarters takes place and a new villain rises, Eggsy and Merlin are forced to work together with the American agency known as the Statesman to save the world.', 'Matthew Vaughn', 141, '2017-09-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/34xBL6BXNYFqtHO9zhcgoakS4aP.jpg', 'https://www.youtube.com/watch?v=0fvqnGmr9S8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (599, 'The Social Dilemma', 'This documentary-drama hybrid explores the dangerous human impact of social networking, with tech experts sounding the alarm on their own creations.', 'Jeff Orlowski', 94, '2020-01-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jcaM6V2tCtu6iMHDsGLBUbaYgYp.jpg', 'https://www.youtube.com/watch?v=uaaC57tcci0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (600, 'Shazam!', 'A boy is given the ability to become an adult superhero in times of need with a single magic word.', 'David F. Sandberg', 132, '2019-03-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/xnopI5Xtky18MPhK40cZAGAOVeV.jpg', 'https://www.youtube.com/watch?v=go6GEIrcvFY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (601, 'Aaja Mexico Challiye', 'Pamma is an ambitious youngster from Punjab who wants to go abroad. But this one dream turns his life around as he becomes caught in dangerous situations. Will Pamma be able to make it out of the jungles of Mexico?', 'Rakesh Dhawan', 125, '2022-02-25', 'T16', 'pa', 'https://image.tmdb.org/t/p/w500/khH1DWBlGZydimNyaz2ENj57PLl.jpg', 'https://www.youtube.com/watch?v=kyadkLznN-U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (602, 'Digimon Adventure: Last Evolution Kizuna', 'Tai is now a university student, living alone, working hard at school, and working every day, but with his future still undecided. Meanwhile, Matt and others continue to work on Digimon incidents and activities that help people with their partner Digimon. When an unprecedented phenomenon occurs, the DigiDestined discover that when they grow up, their relationship with their partner Digimon will come closer to an end.', 'Tomohisa Taguchi', 95, '2020-02-21', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/22oG48YszCraRJigJw5F6qFs4sR.jpg', 'https://www.youtube.com/watch?v=GwWY2a2fA0Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (603, 'KONOSUBA – God''s blessing on this wonderful world! Legend of Crimson', 'After receiving a warning that Yunyun''s hometown is in danger, Kazuma''s party is relieved to discover it''s only a joke...until it isn''t. The Demon King''s general has just arrived to obtain The Mage Killer, a weapon with world-ending power.', 'Takaomi Kanasaki', 90, '2019-08-30', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/6hdIiFKf504I2uAMk7sXh6mATPy.jpg', 'https://www.youtube.com/watch?v=5h4rQY9bpgE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (604, 'Pearl', 'Trapped on her family’s isolated farm, Pearl must tend to her ailing father under the bitter and overbearing watch of her devout mother. Lusting for a glamorous life like she’s seen in the movies, Pearl’s ambitions, temptations, and repressions collide.', 'Ti West', 102, '2022-09-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ulBLIBqvdnf4H6JBt0OpMCU1ECn.jpg', 'https://www.youtube.com/watch?v=L5PW5r3pEOg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (605, 'Final Destination Bloodlines', 'Plagued by a violent recurring nightmare, college student Stefanie heads home to track down the one person who might be able to break the cycle and save her family from the grisly demise that inevitably awaits them all.', 'Adam Stein, Zach Lipovsky', 110, '2025-05-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6WxhEvFsauuACfv8HyoVX6mZKFj.jpg', 'https://www.youtube.com/watch?v=KnWzz0n60pE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (606, 'The Brutalist', 'When an innovative modern architect flees post-war Europe, he is given the opportunity to rebuild his legacy. Set during the dawn of the modern United States (in Pennsylvania), his wife joins him, and their lives are forever changed by a demanding, wealthy patron.', 'Brady Corbet', 215, '2024-12-20', 'K', 'en', 'https://image.tmdb.org/t/p/w500/vP7Yd6couiAaw9jgMd5cjMRj3hQ.jpg', 'https://www.youtube.com/watch?v=6d7yU379Ur0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (607, 'Bleach: Thousand-Year Blood War - The Calamity', 'The Soul Reapers and Quincies clash in a final battle as Yhwach breaches the Royal Palace. When the Soul King falls, reality begins collapsing. Former enemies unite to storm the transformed palace and face a threat to all existence. A theatrical screening of the first three episodes of the anime featuring an exclusive behind‑the‑scenes conversation with creator Tite Kubo, chief series director Tomohisa Taguchi, and series director Hikaru Murata about the production.', 'Chen Dali, Hikaru Murata', 80, '2026-06-25', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/tEaeXZZO7SEcDr6yRP31UrrxcX0.jpg', 'https://www.youtube.com/watch?v=DKKZ10FsSBM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (608, 'Mandaadi', 'A fishing captain applies his maritime knowledge in a traditional boat race along Tamil Nadu''s coast during a festival, leading a six-person team against other crews.', 'Mathimaran Pugazhendhi', 153, '2026-09-10', 'T13', 'ta', 'https://image.tmdb.org/t/p/w500/cDFW9BI1PSqrBWu8W0ZoeUQivEM.jpg', 'https://www.youtube.com/watch?v=VOHaf-0DV-U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (609, 'Star Wars: The Last Jedi', 'Rey develops her newly discovered abilities with the guidance of Luke Skywalker, who is unsettled by the strength of her powers. Meanwhile, the Resistance prepares to do battle with the First Order.', 'Rian Johnson', 152, '2017-12-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kOVEVeg59E0wsnXmF9nrh6OmWII.jpg', 'https://www.youtube.com/watch?v=Q0CbN8sfihY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (610, 'The Fall Guy', 'Fresh off an almost career-ending accident, stuntman Colt Seavers has to track down a missing movie star, solve a conspiracy and try to win back the love of his life while still doing his day job.', 'David Leitch', 127, '2024-04-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/e7olqFmzcIX5c23kX4zSmLPJi8c.jpg', 'https://www.youtube.com/watch?v=EySdVK0NK1Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (611, 'Miraculous: Ladybug & Cat Noir, The Movie', 'After a guardian of magical jewels turns an awkward girl and a popular boy into superheroes, they can never reveal their identities — even to each other.', 'Jeremy Zag', 105, '2023-07-05', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/dQNJ8SdCMn3zWwHzzQD2xrphR1X.jpg', 'https://www.youtube.com/watch?v=3fzFvZToh8o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (612, 'They Shall Not Grow Old', 'A documentary about World War I with never-before-seen footage to commemorate the centennial of Armistice Day, and the end of the war.', 'Peter Jackson', 99, '2018-11-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yMGfJeTXUdIjOqjS0jJfjgYEuYC.jpg', 'https://www.youtube.com/watch?v=D6Do1p1CWyc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (613, 'Captain Marvel', 'The story follows Carol Danvers as she becomes one of the universe’s most powerful heroes when Earth is caught in the middle of a galactic war between two alien races. Set in the 1990s, Captain Marvel is an all-new adventure from a previously unseen period in the history of the Marvel Cinematic Universe.', 'Anna Boden, Ryan Fleck', 124, '2019-03-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/AtsgWhDnHTq68L0lLsUrCnM7TjG.jpg', 'https://www.youtube.com/watch?v=0LHxvxdRnYc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (614, 'HAIKYU!! The Dumpster Battle', 'Shoyo Hinata joins Karasuno High''s volleyball club to be like his idol, a former Karasuno player known as the ''Little Giant''. But Hinata soon learns that he must team up with his middle school nemesis, Tobio Kageyama. Their clashing styles form a surprising weapon, but can their newfound teamwork defeat their rival Nekoma High in the highly anticipated ''Dumpster Battle'', the long awaited ultimate showdown between two opposing underdog teams?', 'Susumu Mitsunaka', 84, '2024-02-16', 'K', 'ja', 'https://image.tmdb.org/t/p/w500/ntRU0OA4etGGiMMmH1Yw0bnaMdW.jpg', 'https://www.youtube.com/watch?v=6X8kZCzF3zI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (615, 'BLACKPINK: Light Up the Sky', 'Record-shattering Korean girl band BLACKPINK tell their story — and detail the hard fought journey of the dreams and trials behind their meteoric rise.', 'Caroline Suh', 79, '2020-10-14', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/wwrvjmcgkDyB2RbCbIVLXZf82pl.jpg', 'https://www.youtube.com/watch?v=7jx_vdvxWu0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (616, 'Paper Lives', 'In the streets of Istanbul, ailing waste warehouse worker Mehmet takes a small boy under his wing and must soon confront his own traumatic childhood.', 'Can Ulkay', 96, '2021-03-12', 'T13', 'tr', 'https://image.tmdb.org/t/p/w500/cmru6N6Hnw2pJwuo1ctH1CxKqKZ.jpg', 'https://www.youtube.com/watch?v=lXdSaVK-vzs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (617, 'Greenland', 'John Garrity, his estranged wife and their young son embark on a perilous journey to find sanctuary as a planet-killing comet hurtles toward Earth. Amid terrifying accounts of cities getting levelled, the Garritys experience the best and worst in humanity. As the countdown to the global apocalypse approaches zero, their incredible trek culminates in a desperate and last-minute flight to a possible safe haven.', 'Ric Roman Waugh', 120, '2020-07-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bNo2mcvSwIvnx8K6y1euAc1TLVq.jpg', 'https://www.youtube.com/watch?v=d4s9XNChIRk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (618, 'The Invisible Man', 'When Cecilia''s abusive ex takes his own life and leaves her his fortune, she suspects his death was a hoax. As a series of coincidences turn lethal, Cecilia works to prove that she is being hunted by someone nobody can see.', 'Leigh Whannell', 124, '2020-02-26', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/5EufsDwXdY2CVttYOk2WtYhgKpa.jpg', 'https://www.youtube.com/watch?v=WO_FJdiY9dA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (619, 'S4: The Bob Lazar Story', 'Over 35 years after Bob Lazar''s revelations, this documentary exposes secrets of a facility the government still denies. Featuring Lazar''s testimony, recreations, and new evidence, it reopens a case that continues to spark global curiosity', 'Luigi Vendittelli', 114, '2026-04-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sQB50PgwLfftaRdNB36eJxtH3AZ.jpg', 'https://www.youtube.com/watch?v=nqA_8tq3hlE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (620, 'The Astronaut Lovers', 'Pedro arrives at the coast and reunites with Maxi, whom he hasn''t seen since childhood. Hoping to make his ex-girlfriend jealous, Maxi asks Pedro to pretend to be his boyfriend. Pedro agrees, amused, but fails to realize that this game could turn into reality.', 'Marco Berger', 116, '2024-06-20', 'T13', 'es', 'https://image.tmdb.org/t/p/w500/i3HQEc5gwP0mxTAuCI1tKwoHhxS.jpg', 'https://www.youtube.com/watch?v=IepMsdf5hYM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (621, 'The Wrecking Crew', 'Estranged half-brothers Jonny and James reunite after their father''s mysterious death. As they search for the truth, buried secrets reveal a conspiracy threatening to tear their family apart.', 'Ángel Manuel Soto', 125, '2026-01-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gbVwHl4YPSq6BcC92TQpe7qUTh6.jpg', 'https://www.youtube.com/watch?v=v8R0xDczERo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (622, 'Marcel the Shell with Shoes On', 'Marcel is an adorable one-inch-tall shell who ekes out a colorful existence with his grandmother Connie and their pet lint, Alan. Once part of a sprawling community of shells, they now live alone as the sole survivors of a mysterious tragedy. When a documentarian discovers them amongst the clutter of his Airbnb, his resulting short film brings Marcel millions of passionate fans, as well as unprecedented dangers and a new hope at finding his long-lost family.', 'Dean Fleischer Camp', 90, '2022-06-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jaYmP4Ct8YLnxWAW2oYkUjeXtzm.jpg', 'https://www.youtube.com/watch?v=k98Afd7Nf3Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (623, 'Hotel Mumbai', 'Mumbai, India, November 26, 2008. While several terrorists spread hatred and death through the city, others attack the Taj Mahal Palace Hotel. Both hotel staff and guests risk their lives, making unthinkable sacrifices to protect themselves and keep everyone safe while help arrives.', 'Anthony Maras', 123, '2019-03-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/v32SC4HFZtlDRWXMaR2V2dWqAXJ.jpg', 'https://www.youtube.com/watch?v=A8IxhVslvro', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (624, 'Companion', 'During a weekend getaway at a secluded lakeside estate, a group of friends finds themselves entangled in a web of secrets, deception, and advanced technology. As tensions rise and loyalties are tested, they uncover unsettling truths about themselves and the world around them.', 'Drew Hancock', 97, '2025-01-22', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/oCoTgC3UyWGfyQ9thE10ulWR7bn.jpg', 'https://www.youtube.com/watch?v=PhcLjiVtgco', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (625, 'Ordinary Angels', 'Inspired by the incredible true story of a hairdresser who single-handedly rallies an entire community to help a widowed father save the life of his critically ill young daughter.', 'Jon Gunn', 118, '2024-02-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wdi9kEU4W2UeBTtdqOPZISGMtDR.jpg', 'https://www.youtube.com/watch?v=Nh9vNnimfTo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (626, 'Crime 101', 'When an elusive thief whose high-stakes heists unfold along the iconic 101 freeway in Los Angeles eyes the score of a lifetime, with hopes of this being his final job, his path collides with a disillusioned insurance broker who is facing her own crossroads. Determined to crack the case, a relentless detective closes in on the operation, raising the stakes even higher.', 'Bart Layton', 141, '2026-02-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tVvpFIoteRHNnoZMhdnwIVwJpCA.jpg', 'https://www.youtube.com/watch?v=KeEHsuZ4Ja4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (627, 'The Debt Collector', 'Tormented by past mistakes and a terminal diagnosis, an ex-debt collector returns to the underworld to protect the victims of a violent organization.', 'Surapong Ploensang', 134, '2026-07-20', 'T16', 'th', 'https://image.tmdb.org/t/p/w500/qADBUb5ybrkRVGZEFF8Z4RuOwys.jpg', 'https://www.youtube.com/watch?v=U9vJ2Z4SFQI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (628, 'Rocketman', 'The story of Elton John''s life, from his years as a prodigy at the Royal Academy of Music through his influential and enduring musical partnership with Bernie Taupin.', 'Dexter Fletcher', 121, '2019-05-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/f4FF18ia7yTvHf2izNrHqBmgH8U.jpg', 'https://www.youtube.com/watch?v=S3vO8E2e6G0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (629, 'A Brother and 7 Siblings', 'After the untimely death of his older sister and her husband, a struggling young architect suddenly becomes a "single parent" for his nieces and nephews. When the opportunity for a better life arises, he must choose between his love life, career, or his family.', 'Yandy Laurens', 131, '2025-01-23', 'P', 'id', 'https://image.tmdb.org/t/p/w500/d8iIVE9KmkSITslMYD6WvHvbRFk.jpg', 'https://www.youtube.com/watch?v=jaiqll7Ofqc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (630, 'Music by John Williams', 'His unforgettable scores are an essential part of some of the most beloved movies of our time, over a career that spans decades. See and hear maestro John Williams'' own story, with insights from filmmakers, musicians, and others he has inspired, complete with rare behind-the-scenes looks at the making of movie history.', 'Laurent Bouzereau', 106, '2024-11-01', 'K', 'en', 'https://image.tmdb.org/t/p/w500/dIZ3SzuT3YuAWX1fjdxDevbwQBX.jpg', 'https://www.youtube.com/watch?v=YrTTTxiuER8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (631, 'Peaky Blinders: The Immortal Man', 'After his estranged son gets embroiled in a Nazi plot, self-exiled gangster Tommy Shelby must return to Birmingham to save his family — and his nation.', 'Tom Harper', 112, '2026-03-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gRMalasZEzsZi4w2VFuYusfSfqf.jpg', 'https://www.youtube.com/watch?v=lcvUGs3xaDM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (632, 'Rescue at Dongji', 'Inspired by the real life rescue of over 300 British soldiers in 1942, Dongji Rescue is a rousing, action-packed story of heroism on the high seas. When the Japanese warship Lisbon Maru is torpedoed off the coast of Dongji Island, the lives of over 300 British POWs on board are at risk of being claimed by the sea. Their only hope is a small group of defiant Chinese fisherman who will do anything to rescue and protect them from their captors.', 'Fei Zhenxiang, Guan Hu', 134, '2025-08-08', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/nPo4VVucCQ8OLTzi4uehKB5kCTf.jpg', 'https://www.youtube.com/watch?v=GeZ01JLg2F0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (633, 'Passengers', 'A spacecraft traveling to a distant colony planet and transporting thousands of people has a malfunction in its sleep chambers. As a result, two passengers are awakened 90 years early.', 'Morten Tyldum', 116, '2016-12-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jK9S6HANSf2no64v1x1HxfcpmcA.jpg', 'https://www.youtube.com/watch?v=7BWWWQzTpNU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (634, 'In This Corner of the World', 'Japan, 1943, during World War II. Young Suzu leaves her village near Hiroshima to marry and live with her in-laws in Kure, a military harbor. Her creativity to overcome deprivation quickly makes her indispensable at home. Inhabited by an ancestral wisdom, Suzu impregnates the simple gestures of everyday life with poetry and beauty. The many hardships, the loss of loved ones, the frequent air raids of the enemy, nothing alters her enthusiasm…', 'Sunao Katabuchi', 130, '2016-11-12', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/9Z4H4M2F8OQTB04YC1Opds8MFBb.jpg', 'https://www.youtube.com/watch?v=-jBe-uHhlNs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (635, 'Words on Bathroom Walls', 'Diagnosed with a mental illness halfway through his senior year of high school, a witty, introspective teen struggles to keep it a secret while falling in love with a brilliant classmate who inspires him to open his heart and not be defined by his condition.', 'Thor Freudenthal', 111, '2020-08-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/AedH7kQttLVgqd260IXevTK0Mek.jpg', 'https://www.youtube.com/watch?v=4E1-RnpOe8Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (636, 'The Ministry of Ungentlemanly Warfare', 'During World War II, the British Army assigns a group of competent soldiers to carry out a mission against the Nazi forces behind enemy lines... A true story about a secret British WWII organization — the Special Operations Executive. Founded by Winston Churchill, their irregular warfare against the Germans helped to change the course of the war, and gave birth to modern black operations.', 'Guy Ritchie', 120, '2024-04-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8aF0iAKH9MJMYAZdi0Slg77RYa2.jpg', 'https://www.youtube.com/watch?v=zvwDen1Wrx8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (637, 'The Accountant²', 'When an old acquaintance is murdered, Wolff is compelled to solve the case. Realizing more extreme measures are necessary, Wolff recruits his estranged and highly lethal brother, Brax, to help. In partnership with Marybeth Medina, they uncover a deadly conspiracy, becoming targets of a ruthless network of killers who will stop at nothing to keep their secrets buried.', 'Gavin O''Connor', 133, '2025-04-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lUvfTcOZiK0sdcX0WNLPbMyKjGm.jpg', 'https://www.youtube.com/watch?v=3wRCOqyDI6E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (638, 'Abominable', 'A group of misfits encounter a young Yeti named Everest, and they set off to reunite the magical creature with his family on the mountain of his namesake.', 'Jill Culton', 97, '2019-09-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/20djTLqppfBx5WYA67Y300S6aPD.jpg', 'https://www.youtube.com/watch?v=Ap0NRJD-2ts', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (639, 'Miss Sloane', 'An ambitious lobbyist faces off against the powerful gun lobby in an attempt to pass gun control legislation.', 'John Madden', 133, '2016-11-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ptfvQlqe2xJiMSewSj52qAVq5z0.jpg', 'https://www.youtube.com/watch?v=5k8KaMdPYTY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (640, 'Burning', 'Deliveryman Jong-su is out on a job when he runs into Hae-mi, a girl who once lived in his neighborhood. She asks if he''d mind looking after her cat while she''s away on a trip to Africa. On her return, she introduces to Jong-su an enigmatic young man named Ben, who she met during her trip. One day Ben tells Jong-su about his most unusual hobby.', 'Lee Chang-dong', 148, '2018-05-17', 'T18', 'ko', 'https://image.tmdb.org/t/p/w500/kXiF80o74fE9gf3Utf9moAI7ar0.jpg', 'https://www.youtube.com/watch?v=irBLY-Ev9vo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (641, 'Honeyland', 'When nomadic beekeepers break Honeyland’s basic rule (take half of the honey, but leave half to the bees), the last female beehunter in Europe must save the bees and restore natural balance.', 'Ljubomir Stefanov, Tamara Kotevska', 89, '2019-07-26', 'P', 'tr', 'https://image.tmdb.org/t/p/w500/3IxGhQEzLWOxkZlcNMAIiYlOT8D.jpg', 'https://www.youtube.com/watch?v=B27ORUHlp6E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (642, 'A Monster Calls', '12-year-old Conor encounters an ancient tree monster who proceeds to help him cope with his mother''s terminal illness and being bullied in school.', 'J. A. Bayona', 108, '2016-10-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vNzWJwVqjszWwXrA7ZfsrJmhgV9.jpg', 'https://www.youtube.com/watch?v=8q-7trUd8Vw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (643, 'All the Bright Places', 'Two teens facing personal struggles form a powerful bond as they embark on a cathartic journey chronicling the wonders of Indiana.', 'Brett Haley', 108, '2020-02-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4SafxuMKQiw4reBiWKVZJpJn80I.jpg', 'https://www.youtube.com/watch?v=zfQXKVCudec', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (644, 'Given', 'Haruki secretly had feelings for Akihiko for years, but Akihiko was still in a relationship with his roommate, the violinist Ugetsu Murata. Haruki, Akihiko, and Ugetsu''s love clashes and starts to move forward.', 'Hikaru Yamaguchi', 60, '2020-08-22', 'K', 'ja', 'https://image.tmdb.org/t/p/w500/pegCub2zdYD5As43AOmGsIctuKc.jpg', 'https://www.youtube.com/watch?v=XGKGjMGZwtk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (645, 'COLORFUL STAGE! The Movie: A Miku Who Can''t Sing', 'Ichika is a high school musician who can enter a mysterious place called “SEKAI,” where she and her friends express their innermost emotions through music alongside Hatsune Miku. One day after giving a live performance, Ichika meets a new Miku that she has never seen before. No matter how hard this new Miku tries to sing, she struggles connecting with the hearts of her listeners. Miku must rely on the help of others to find a way to sing again.', 'Hiroyuki Hata', 105, '2025-01-17', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/uiQ6wj8TPYHueuIJRsNlPruzogT.jpg', 'https://www.youtube.com/watch?v=3bD1dfiRMu4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (646, 'Andhadhun', 'A series of mysterious events changes the life of a blind pianist who now must report a crime that was actually never witnessed by him.', 'Sriram Raghavan', 139, '2018-10-05', 'T16', 'hi', 'https://image.tmdb.org/t/p/w500/dy3K6hNvwE05siGgiLJcEiwgpdO.jpg', 'https://www.youtube.com/watch?v=2iVYI99VGaw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (647, 'Tony', 'A 19-year-old Anthony Bourdain travels to Provincetown and stumbles into the chaotic world of a restaurant kitchen, setting off a summer that will shape the course of his life.', 'Matt Johnson', 107, '2026-08-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uwZF5guNR5EnXkjIVTk4UPTVGiS.jpg', 'https://www.youtube.com/watch?v=k1MVnzd2aVc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (648, 'Speak No Evil', 'When an American family is invited to spend the weekend at the idyllic country estate of a charming British family they befriended on vacation, what begins as a dream holiday soon warps into a snarled psychological nightmare.', 'James Watkins', 110, '2024-09-11', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/dA4N6uWOnEMgbxXwFX7qX7adzs8.jpg', 'https://www.youtube.com/watch?v=FjzxI6uf8H8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (649, 'Miraculous World: New York, United HeroeZ', 'Marinette''s class is headed to New York, the city of superheroes, for French-American Friendship Week. But the arrival of Hawk Moth will complicate everything.', 'Thomas Astruc', 61, '2020-09-25', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/9YbyvcrHmY2SVbdfXpb8mC4Fy0g.jpg', 'https://www.youtube.com/watch?v=952fktHweJs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (650, 'The Sea Beast', 'When a young girl stows away on the ship of a legendary sea monster hunter, they launch an epic journey into uncharted waters — and make history to boot.', 'Chris Williams', 115, '2022-06-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9Zfv4Ap1e8eKOYnZPtYaWhLkk0d.jpg', 'https://www.youtube.com/watch?v=P-E-IGQCsPo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (651, 'Sarah''s Oil', 'Sarah Rector, a Black girl born in early 20th-century Oklahoma Indian Territory, believes there is oil beneath the barren land she’s allotted, and her faith proves right. As greedy oil sharks close in, Sarah turns to family, friends, and some Texas wildcatters to maintain control of her oil-rich land, eventually becoming among the nation''s first Black female millionaires—at eleven years old.', 'Cyrus Nowrasteh', 103, '2025-11-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/Av1CK61z33v2OBFLD1yF5rdRxQ1.jpg', 'https://www.youtube.com/watch?v=lcEOKJm_aLY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (652, 'Don''t Breathe', 'A group of teens break into a blind man''s home thinking they''ll get away with the perfect crime. They''re wrong.', 'Fede Álvarez', 89, '2016-06-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dSxHyPZ2nipSfvdft4IhQKjk5eZ.jpg', 'https://www.youtube.com/watch?v=76yBTNDB6vU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (653, 'The Shadow in My Eye', 'On March 21st, 1945, the British Royal Air Force set out on a mission to bomb Gestapo''s headquarters in Copenhagen. The raid had fatal consequences as some of the bombers accidentally targeted a school and more than 120 people were killed, 86 of whom were children.', 'Ole Bornedal', 107, '2021-10-28', 'T13', 'da', 'https://image.tmdb.org/t/p/w500/jCKvbH3a4V5IPoRAG85eDaniNqO.jpg', 'https://www.youtube.com/watch?v=_yBnTjcAJDY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (654, 'Gabriel''s Inferno: Part II', 'Professor Gabriel Emerson finally learns the truth about Julia Mitchell''s identity, but his realization comes a moment too late. Julia is done waiting for the well-respected Dante specialist to remember her and wants nothing more to do with him. Can Gabriel win back her heart before she finds love in another''s arms?', 'Tosca Musk', 106, '2020-07-31', 'K', 'en', 'https://image.tmdb.org/t/p/w500/x5o8cLZfEXMoZczTYWLrUo1P7UJ.jpg', 'https://www.youtube.com/watch?v=5g02v1oz5Y0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (655, 'Manjummel Boys', 'A carefree vacation turns into a desperate race against time when a group of lifelong friends must unite to save one of their own from a notoriously perilous, uncharted abyss deep within the Guna Caves.', 'Chidambaram', 135, '2024-02-22', 'T16', 'ml', 'https://image.tmdb.org/t/p/w500/bswrtewwthpsh6nABiqKevU4UBI.jpg', 'https://www.youtube.com/watch?v=9uzfrur9SDU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (656, 'The Mauritanian', 'The true story of the Mauritanian Mohamedou Ould Slahi, who was held at the U.S military''s Guantanamo Bay detention center without charges for over a decade and sought help from a defense attorney for his release.', 'Kevin Macdonald', 129, '2021-02-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/lIADEa6oH74uUapjsPbNRzxus8M.jpg', 'https://www.youtube.com/watch?v=7tmxxzZXLEM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (657, 'Ozzy: No Escape from Now', 'Ozzy Osbourne faces his identity and mortality after his world stops. Dealing with health issues and Parkinson''s, he questions if he can perform again while music remains his life''s cornerstone.', 'Tania Alexander', 120, '2025-10-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7xlmn0xpEYiqGN7bINAbEUjNqbr.jpg', 'https://www.youtube.com/watch?v=RxBYxFZccks', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (658, 'Molly''s Game', 'Molly Bloom, a young skier and former Olympic hopeful becomes a successful entrepreneur (and a target of an FBI investigation) when she establishes a high-stakes, international poker game.', 'Aaron Sorkin', 141, '2017-12-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zrGQwKNmAz5awZI2V1k5M4eTTTN.jpg', 'https://www.youtube.com/watch?v=9v-pw0ZQRLY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (659, 'Violent Night', 'When a team of mercenaries breaks into a wealthy family compound on Christmas Eve, taking everyone inside hostage, the team isn’t prepared for a surprise combatant: Santa Claus is on the grounds, and he’s about to show why this Nick is no saint.', 'Tommy Wirkola', 112, '2022-11-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/e8CpMgdyihz9Td7amQDqubPuzfN.jpg', 'https://www.youtube.com/watch?v=a53e4HHnx_s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (660, 'Kumbalangi Nights', 'Four brothers living in the fishing hamlet of Kumbalangi share a love-hate relationship with each other. Their relationship progresses when Saji, Boney and Franky decide to help Bobby stand by his love.', 'Madhu C. Narayanan', 135, '2019-02-07', 'T13', 'ml', 'https://image.tmdb.org/t/p/w500/lJ3RvIirE2C7gdBKvPRaoQ3iCo2.jpg', 'https://www.youtube.com/watch?v=3P4BFBSafF0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (661, 'Made in Abyss: Dawn of the Deep Soul', 'A continuation of the epic adventure of plucky Riko and Reg who are joined by their new friend Nanachi. Together they descend into the Abyss'' treacherous fifth layer, the Sea of Corpses, and encounter the mysterious Bondrewd, a legendary White Whistle whose shadow looms over Nanachi''s troubled past. Bondrewd is ingratiatingly hospitable, but the brave adventurers know things are not always as they seem in the enigmatic Abyss.', 'Masayuki Kojima', 105, '2020-01-17', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/k4riqNEEd5rnkbNytf02wkF4W8i.jpg', 'https://www.youtube.com/watch?v=5KLzsB5HJ6A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (662, 'Evil Dead Rise', 'A reunion between two estranged sisters gets cut short by the rise of flesh-possessing demons, thrusting them into a primal battle for survival as they face the most nightmarish version of family imaginable.', 'Lee Cronin', 96, '2023-04-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5ik4ATKmNtmJU6AYD0bLm56BCVM.jpg', 'https://www.youtube.com/watch?v=BqQNO7BzN08', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (663, 'The Ugly Stepsister', 'In a fairy-tale kingdom where beauty is a brutal business, Elvira battles to compete with her incredibly beautiful stepsister, Agnes, and she will go to any length to catch the Prince’s eye.', 'Emilie Blichfeldt', 109, '2025-03-07', 'T18', 'no', 'https://image.tmdb.org/t/p/w500/rayAREIKtSinuov10GvrZHyXfXH.jpg', 'https://www.youtube.com/watch?v=5vZ1_Yxjwzs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (664, 'The Six Triple Eight', 'During World War II, the US Army''s only all-Black, all-women battalion takes on an impossible mission: sorting through a three-year backlog of 17 million pieces of mail that hadn''t been delivered to American soldiers and finish within six months.', 'Tyler Perry', 130, '2024-12-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7tvAnzZj9e9AjdoHaN9jshm2Cjw.jpg', 'https://www.youtube.com/watch?v=7Thq-SBtukg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (665, 'Road House', 'Ex-UFC fighter Dalton takes a job as a bouncer at a Florida Keys roadhouse, only to discover that this paradise is not all it seems.', 'Doug Liman', 121, '2024-03-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fDEdtS4P0gJsxHDIt8dG8TR5dx1.jpg', 'https://www.youtube.com/watch?v=Y0ZsLudtfjI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (666, 'mid90s', 'In 1990s Los Angeles, a 13-year-old spends his summer navigating between a troubled home life and a crew of new friends he meets at a skate shop.', 'Jonah Hill', 86, '2018-10-19', 'K', 'en', 'https://image.tmdb.org/t/p/w500/9Tw0Y3DK5kGIU9X1yw3Q9gCkOlb.jpg', 'https://www.youtube.com/watch?v=DU5gJGSuelM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (667, 'The Peanut Butter Falcon', 'A down-on-his-luck crab fisherman embarks on a journey to get a young man with Down syndrome to a professional wrestling school in rural North Carolina and away from the retirement home where he’s lived for the past two and a half years.', 'Michael Schwartz, Tyler Nilson', 97, '2019-08-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qyQcRGvdW3VtxHR4fSDgPOePEip.jpg', 'https://www.youtube.com/watch?v=UNl9RqjLCwc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (668, 'I Am Frankelda', 'A gifted young writer in 19th-century Mexico journeys into her subconscious and comes face to face with characters from her own spooky stories.', 'Arturo Ambriz, Roy Ambriz', 104, '2025-10-23', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/hDzllxB1TQ7uUxVvjnGHirJJovt.jpg', 'https://www.youtube.com/watch?v=diRwnGRr-Ko', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (669, 'The Fallout', 'In the wake of a school tragedy, Vada, Mia and Quinton form a unique and dynamic bond as they navigate the never linear, often confusing journey to heal in a world that feels forever changed.', 'Megan Park', 96, '2021-03-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4ByHl9XRKR2iXbvF0ZilMRD1RcL.jpg', 'https://www.youtube.com/watch?v=Gtl-6RCOl84', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (670, 'Two Is a Family', 'A man without attachments or responsibilities suddenly finds himself with an abandoned baby and leaves for London to try and find the mother. Eight years later after he and his daughter become inseparable Gloria''s mother reappears.', 'Hugo Gélin', 118, '2016-12-07', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/aFgtdhuzgI2eqnIVWtRB03x3pnt.jpg', 'https://www.youtube.com/watch?v=QrB7tmqWrAY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (671, 'Wallace & Gromit: Vengeance Most Fowl', 'Gromit’s concern that Wallace is becoming too dependent on his inventions proves justified, when Wallace invents a “smart” gnome that seems to develop a mind of its own. When it emerges that a vengeful figure from the past might be masterminding things, it falls to Gromit to battle sinister forces and save his master… or Wallace may never be able to invent again!', 'Merlin Crossingham, Nick Park', 79, '2024-12-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jUWFSBxTOiCinPdTOh3IDUXVemZ.jpg', 'https://www.youtube.com/watch?v=HUcZBhhzoMw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (672, 'My Mom Jayne', 'Through deeply personal interviews with her siblings and an examination of the photographs, letters, and belongings left behind, Mariska assembles a new portrait of her mother Jayne Mansfield, an extraordinary and complex woman.', 'Mariska Hargitay', 106, '2025-06-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6KpfMouMavYr1UwTz6612YhYjbs.jpg', 'https://www.youtube.com/watch?v=fZM6m_GJhr8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (673, 'HOMECOMING: A film by Beyoncé', 'This intimate, in-depth look at Beyoncé''s celebrated 2018 Coachella performance reveals the emotional road from creative concept to cultural movement.', 'Beyoncé', 137, '2019-04-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nKdP4K3Bj3qnjtDCq9lTg7UOHVy.jpg', 'https://www.youtube.com/watch?v=fB8qvx0HOlI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (674, 'White Bird', 'After being expelled from Beecher Prep for his treatment of a classmate with a facial deformity, Julian has struggled to fit in at his new school. To transform his life, Julian''s grandmother finally reveals her own story of courage of her youth in Nazi-occupied France, where a classmate shelters her from mortal danger.', 'Marc Forster', 121, '2023-10-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/s2igE99PVBEMsry3qEGEH3rM83K.jpg', 'https://www.youtube.com/watch?v=MOi0b6pk3c8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (675, 'The Outlaws', 'In Chinatown, law and order is turned upside down when a trio of feral Chinese gangsters arrive, start terrorizing civilians, and usurping territory. The beleaguered local gangsters team up with the police, lead by the badass loose cannon Ma Seok-do, to bring them down. Based on a true story.', 'Kang Yun-sung', 121, '2017-10-03', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/9yi66KlKsDrsu2KuSgtBUmk6Seo.jpg', 'https://www.youtube.com/watch?v=UbLzMUbiMmY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (676, 'The Life of Chuck', 'In this extraordinary story of an ordinary man, Charles ''Chuck'' Krantz experiences the wonder of love, the heartbreak of loss, and the multitudes contained in all of us.', 'Mike Flanagan', 111, '2025-06-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oumprkO9bThExP8NwxBIBnvBu2v.jpg', 'https://www.youtube.com/watch?v=dOyXdwXt8d4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (677, 'Lost Ladies', 'In 2001, somewhere in rural India, two young brides get accidentally swapped on a train. In the ensuing chaos, they both encounter a host of colourful characters, resulting in hilarious and unexpected consequences.', 'Kiran Rao', 123, '2024-03-01', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/yXt07MYeiyQRzS69PMHy0BPjCGP.jpg', 'https://www.youtube.com/watch?v=hGM87LCJxRc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (678, 'New Gods: Nezha Reborn', 'While living as an ordinary deliveryman and motor racing fan, Nezha encounters old nemeses and must rediscover his powers to protect his loved ones.', 'Zhao Ji', 117, '2021-02-06', 'T16', 'zh', 'https://image.tmdb.org/t/p/w500/np4ScPY04HESKBbpexwstKsipKe.jpg', 'https://www.youtube.com/watch?v=G0qiLpWdm5Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (679, 'Rurouni Kenshin: The Beginning', 'Before he was a protector, Kenshin was a fearsome assassin known as Battosai. But when he meets gentle Tomoe Yukishiro, a beautiful young woman who carries a huge burden in her heart, his life will change forever.', 'Keishi Otomo', 138, '2021-06-04', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/rODS466qSdrwMlGdbUwPENhDN2c.jpg', 'https://www.youtube.com/watch?v=s0vN_2MRR50', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (680, 'Maze Runner: The Death Cure', 'Thomas leads his group of escaped Gladers on their final and most dangerous mission yet. To save their friends, they must break into the legendary Last City, a WCKD-controlled labyrinth that may turn out to be the deadliest maze of all. Anyone who makes it out alive will get answers to the questions the Gladers have been asking since they first arrived in the maze.', 'Wes Ball', 143, '2018-01-10', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/s8K0US4tUEoOrQ1LDh0eppuwGDx.jpg', 'https://www.youtube.com/watch?v=4-BTxXm8KSg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (681, 'Venom', 'Investigative journalist Eddie Brock attempts a comeback following a scandal, but accidentally becomes the host of Venom, a violent, super powerful alien symbiote. Soon, he must rely on his newfound powers to protect the world from a shadowy organization looking for a symbiote of their own.', 'Ruben Fleischer', 112, '2018-09-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', 'https://www.youtube.com/watch?v=27ykcO79F-Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (682, 'Dama Dum Mast Kalandar', 'Follows two friends navigating the pressures and comic complications of building stability abroad while struggling with the emotional pull of home and belonging.', 'Sukhbir Singh', 149, '2026-05-22', 'T13', 'pa', 'https://image.tmdb.org/t/p/w500/f3QLgWdla4VV4Me1bwhYTgvEHTO.jpg', 'https://www.youtube.com/watch?v=R4FU8eiMjLg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (683, 'Little Amélie or the Character of Rain', 'The world is a perplexing, peaceful mystery to Amélie until a miraculous encounter with chocolate ignites her wild sense of curiosity. As she develops a deep attachment to her family''s housekeeper, Nishio-san, Amélie discovers the wonders of nature as well as the emotional truths hidden beneath the surface of her family''s idyllic life as foreigners in post-war Japan.', 'Liane-cho Han, Maïlys Vallade', 77, '2025-06-25', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/qoqDvTUVPoZJWw24AjGDt3J4tZN.jpg', 'https://www.youtube.com/watch?v=-k0jMFivyT8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (684, 'Aquaman', 'Half-human, half-Atlantean Arthur Curry is taken on the journey of his lifetime to discover if he is worth of being a king.', 'James Wan', 143, '2018-12-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ufl63EFcc5XpByEV2Ecdw6WJZAI.jpg', 'https://www.youtube.com/watch?v=2wcj6SrX4zw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (685, 'The Shack', 'A grieving man receives a mysterious, personal invitation to meet with God at a place called ''The Shack''.', 'Stuart Hazeldine', 132, '2017-03-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/doAzav9kfdtsoSdw1MDFvjKq3J4.jpg', 'https://www.youtube.com/watch?v=CL0yUbSS5Eg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (686, 'Wicked', 'In the land of Oz, ostracized and misunderstood green-skinned Elphaba is forced to share a room with the popular aristocrat Glinda at Shiz University, and the two''s unlikely friendship is tested as they begin to fulfill their respective destinies as Glinda the Good and the Wicked Witch of the West.', 'Jon M. Chu', 162, '2024-10-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xDGbZ0JJ3mYaGKy4Nzd9Kph6M9L.jpg', 'https://www.youtube.com/watch?v=6COmYeLsz4c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (687, 'The Hunger Games: The Ballad of Songbirds & Snakes', '64 years before he becomes the tyrannical president of Panem, Coriolanus Snow sees a chance for a change in fortunes when he mentors Lucy Gray Baird, the female tribute from District 12.', 'Francis Lawrence', 157, '2023-11-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mBaXZ95R2OxueZhvQbcEWy2DqyO.jpg', 'https://www.youtube.com/watch?v=NxW_X4kzeus', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (688, 'Land of Bad', 'When a Delta Force special ops mission goes terribly wrong, Air Force drone pilot Reaper has 48 hours to remedy what has devolved into a wild rescue operation. With no weapons and no communication other than the drone above, the ground mission suddenly becomes a full-scale battle when the team is discovered by the enemy.', 'William Eubank', 113, '2024-02-09', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/h3jYanWMEJq6JJsCopy1h7cT2Hs.jpg', 'https://www.youtube.com/watch?v=dKcHOR-V1G4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (689, 'Visaranai', 'Pandi and his friends, immigrant workers in Andhra Pradesh, are picked up by cops for a crime they never committed. And thus begins their nightmare, where they become pawns in a vicious game where the voiceless are strangled by those with power.', 'Vetrimaaran', 118, '2016-02-04', 'T16', 'ta', 'https://image.tmdb.org/t/p/w500/c1C0x8HDShlhaprftf8vDFqYkNo.jpg', 'https://www.youtube.com/watch?v=4mnzK2KIz9U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (690, 'Love and Monsters', 'Seven years since the Monsterpocalypse began, Joel Dawson has been living underground in order to survive. But after reconnecting over radio with his high school girlfriend Aimee, Joel decides to venture out to reunite with her, despite all the dangerous monsters that stand in his way.', 'Michael Matthews', 109, '2020-10-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/718NnyxyQuBQcGWt9sdelA1Zc3h.jpg', 'https://www.youtube.com/watch?v=-19tBHrZwOM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (691, 'Miss Americana', 'A raw and emotionally revealing look at one of the most iconic artists of our time during a transformational period in her life as she learns to embrace her role not only as a songwriter and performer, but as a woman harnessing the full power of her voice.', 'Lana Wilson', 85, '2020-01-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/z1HiEB1UEfdA5fPkngekjQ2vlCC.jpg', 'https://www.youtube.com/watch?v=40RsbcFRwNA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (692, 'Heretic', 'Two young missionaries are forced to prove their faith when they knock on the wrong door and are greeted by a diabolical Mr. Reed, becoming ensnared in his deadly game of cat-and-mouse.', 'Bryan Woods, Scott Beck', 111, '2024-10-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fr96XzlzsONrQrGfdLMiwtQjott.jpg', 'https://www.youtube.com/watch?v=O9i2vmFhSSY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (693, 'Rurouni Kenshin: The Final', 'In 1879, Kenshin and his allies face their strongest enemy yet: his former brother-in-law Enishi Yukishiro and his minions, who''ve vowed their revenge.', 'Keishi Otomo', 138, '2021-04-23', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/7bbEASVf9XWtfxWiuWUMY3uyhTb.jpg', 'https://www.youtube.com/watch?v=n1iL-DveFUA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (694, 'Uncharted', 'A young street-smart, Nathan Drake and his wisecracking partner Victor “Sully” Sullivan embark on a dangerous pursuit of “the greatest treasure never found” while also tracking clues that may lead to Nathan’s long-lost brother.', 'Ruben Fleischer', 116, '2022-02-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rJHC1RUORuUhtfNb4Npclx0xnOf.jpg', 'https://www.youtube.com/watch?v=4wCH1K-ckZw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (695, 'Shakhahaari', 'When the lives of some innocent people start getting intertwined in unforeseen situations they find themselves trapped in a murder mystery. This mysterious butchery infolds in a vegetarian restaurant run by a virtuous Chef Subbanna.', 'Sandeep Sunkad', 146, '2024-02-16', 'T16', 'kn', 'https://image.tmdb.org/t/p/w500/4KtG1STjqeefi7rvsxUN7M28H2h.jpg', 'https://www.youtube.com/watch?v=HnzVItXIMro', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (696, 'The Big Sick', 'Pakistan-born comedian Kumail Nanjiani and grad student Emily Gardner fall in love but struggle as their cultures clash. When Emily contracts a mysterious illness, Kumail finds himself forced to face her feisty parents, his family''s expectations, and his true feelings.', 'Michael Showalter', 120, '2017-03-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9fJTT8pBxxQsFILJHTtHhdYFr77.jpg', 'https://www.youtube.com/watch?v=GX3Regj6nAg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (697, 'Israelism', 'When two young American Jews raised to unconditionally love Israel witness the mistreatment of Palestinians, they battle the old guard to create a new movement opposing Israel’s occupation, and recentering Judaism itself.', 'Erin Axelman, Sam Eilertsen', 84, '2023-02-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3P6vW1IjKukrNKCh1DEjm4r2BFc.jpg', 'https://www.youtube.com/watch?v=bondvm3hvGM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (698, 'Mortal Kombat', 'Washed-up MMA fighter Cole Young, unaware of his heritage, and hunted by Emperor Shang Tsung''s best warrior, Sub-Zero, seeks out and trains with Earth''s greatest champions as he prepares to stand against the enemies of Outworld in a high stakes battle for the universe.', 'Simon McQuoid', 110, '2021-04-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/nkayOAUBUu4mMvyNf9iHSUiPjF1.jpg', 'https://www.youtube.com/watch?v=jBa_aHwCbC4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (699, 'The Year Earth Changed', 'Never-before-seen footage shows how our living in lockdown opened the door for nature to bounce back and thrive. Across the seas, skies, and lands, Earth found its rhythm when we came to a stop.', 'Tom Beard', 48, '2021-04-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cLwQRXfzPjmpU6I78TCkoHazO0A.jpg', 'https://www.youtube.com/watch?v=XswV_yqPq28', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (700, 'My Fault: London', '18-year-old Noah moves from America to London, with her mother who''s recently fallen in love with William, a wealthy British businessman. Noah meets William’s son, bad-boy Nick, and soon discovers there is an attraction between them neither can avoid. As Noah spends the summer adjusting to her new life, her devastating past will catch up with her while falling in love for the first time.', 'Charlotte Fassler, Dani Girdwood', 119, '2025-02-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ttN5D6GKOwKWHmCzDGctAvaNMAi.jpg', 'https://www.youtube.com/watch?v=14z9L_MwH5s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (701, 'Black Adam', 'Nearly 5,000 years after he was bestowed with the almighty powers of the Egyptian gods—and imprisoned just as quickly—Black Adam is freed from his earthly tomb, ready to unleash his unique form of justice on the modern world.', 'Jaume Collet-Serra', 125, '2022-10-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rCtreCr4xiYEWDQTebybolIh6Xe.jpg', 'https://www.youtube.com/watch?v=DvCFc5JtkkA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (702, 'Doraemon the Movie: Nobita''s Art World Tales', 'Nobita and Doraemon enter the world in a European Renaissance painting, but run into trouble as they hop from piece to piece in search of a malevolent time traveler who wishes to recreate the extinct pigment of "Artoria Blue".', 'Yukiyo Teramoto', 105, '2025-03-07', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/scVA8g9J0xIhRmywxScDjKZpp7v.jpg', 'https://www.youtube.com/watch?v=JMQvS-jRdrs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (703, 'Sanam Teri Kasam', 'Tough ex-convict Inder and traditional mousy Saraswati fall in love and get married, but a tragedy changes their lives forever. The film is a modern rendition of the legends of Shiva-Sati and the novel "Love Story" by Eric Segal.', 'Radhika Rao, Vinay Sapru', 154, '2016-02-05', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/xb9T5kMSq4pp9CDUgO5oQAy6p4q.jpg', 'https://www.youtube.com/watch?v=1IpBoMWRjm8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (704, 'Bungo Stray Dogs: Dead Apple', 'A large scale catastrophe is occurring across the planet. Ability users are discovered after the appearance of a mysterious fog, apparently having committed suicide, so the Armed Detective Agency sets out to investigate these mysterious deaths. The case seems to involve an unknown ability user referred to as "Collector," a man who could be the mastermind behind the incident. Trust and courage are put to the test in order to save the city of Yokohama and ability users across the world from the grip of Collector where the Armed Detective Agency forms an unlikely partnership with the dangerous Port Mafia.', 'Takuya Igarashi', 90, '2018-03-03', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/gCfN6xWPyxphtgtLuDxT5s0eSoq.jpg', 'https://www.youtube.com/watch?v=6ySfGSAbNc0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (705, 'Wonka', 'Willy Wonka – chock-full of ideas and determined to change the world one delectable bite at a time – is proof that the best things in life begin with a dream, and if you’re lucky enough to meet Willy Wonka, anything is possible.', 'Paul King', 117, '2023-12-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qhb1qOilapbapxWQn9jtRCMwXJF.jpg', 'https://www.youtube.com/watch?v=otNh9bTjXWg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (706, 'Your Name Engraved Herein', 'In 1987, as martial law ends in Taiwan, Jia-han and Birdy fall in love amid family pressure, homophobia and social stigma.', 'Liu Kuang-Hui', 115, '2020-09-30', 'P', 'zh', 'https://image.tmdb.org/t/p/w500/ynNO5FhArEz68wRKOn4NgqVntmS.jpg', 'https://www.youtube.com/watch?v=mzfVBg54BGw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (707, '1987: When the Day Comes', 'In 1987 Korea under an oppressive military regime, the unlawful interrogation and death of a college student ignite ordinary citizens to fight for the truth and bring about justice.', 'Jang Joon-hwan', 129, '2017-12-27', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/vSiS2tysGNoL4QHYwWBPN0BIkbs.jpg', 'https://www.youtube.com/watch?v=eTzBIH51Irc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (708, 'Dracula', 'In late 15th-century Eastern Europe, Prince Vlad II’s bride is brutally murdered. As a result, he renounces God and damns Heaven itself. Cursed with eternal life, Vlad is reborn as Dracula, an immortal warlord who defies fate in a blood-soaked crusade to wrench his lost love back from death.', 'Luc Besson', 130, '2025-07-30', 'T18', 'fr', 'https://image.tmdb.org/t/p/w500/ykyRfv7JDofLxXLAwtLXaSuaFfM.jpg', 'https://www.youtube.com/watch?v=3OBLPpuOM10', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (709, '2000 Meters to Andriivka', 'Amid the failing counteroffensive, a journalist follows a Ukrainian platoon on their mission to traverse one mile of heavily fortified forest and liberate a strategic village from Russian occupation. But the farther they advance through their destroyed homeland, the more they realize that this war may never end.', 'Mstyslav Chernov', 108, '2025-07-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/s1TC3QebWWWJ6CceqbBgAvJde8t.jpg', 'https://www.youtube.com/watch?v=CirdrDSrjSQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (710, 'The Family Plan', 'Dan Morgan is many things: a devoted husband, a loving father, a celebrated car salesman. He''s also a former assassin. And when his past catches up to his present, he''s forced to take his unsuspecting family on a road trip unlike any other.', 'Simon Cellan Jones', 118, '2023-12-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jLLtx3nTRSLGPAKl4RoIv1FbEBr.jpg', 'https://www.youtube.com/watch?v=ns8weNznn1Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (711, 'The Alpinist', 'The life of Canadian mountain climber Marc-André Leclerc as he pushes the boundaries of climbing while on an expedition to Patagonia.', 'Nick Rosen, Peter Mortimer', 93, '2021-02-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tYbSGAVbyACEExptLu63CxCGm4O.jpg', 'https://www.youtube.com/watch?v=BRn9H_I8LXs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (712, 'Despicable Me 4', 'Gru and Lucy and their girls—Margo, Edith and Agnes—welcome a new member to the Gru family, Gru Jr., who is intent on tormenting his dad. Gru also faces a new nemesis in Maxime Le Mal and his femme fatale girlfriend Valentina, forcing the family to go on the run.', 'Chris Renaud', 94, '2024-06-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wWba3TaojhK7NdycRhoQpsG0FaH.jpg', 'https://www.youtube.com/watch?v=LtNYaH61dXY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (713, 'The SpongeBob Movie: Sponge on the Run', 'When his best friend Gary is suddenly snatched away, SpongeBob takes Patrick on a madcap mission far beyond Bikini Bottom to save their pink-shelled pal.', 'Tim Hill', 95, '2020-08-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jlJ8nDhMhCYJuzOw3f52CP1W8MW.jpg', 'https://www.youtube.com/watch?v=HfiH_526qhY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (714, 'Bou Buttu Bhuta', 'Buttu and his mother live a modest life in an Odisha village, with Buttu dreaming of leaving for a better life elsewhere. However, a series of unforeseen events disrupt their lives. Will they overcome the challenges and realise their dreams?', 'Jagdish Mishra', 176, '2025-06-12', 'T18', 'or', 'https://image.tmdb.org/t/p/w500/g8wFbBlKcngQnSJFUK2d5JrAWaT.jpg', 'https://www.youtube.com/watch?v=M1JaMbSCaSs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (715, 'El Camino: A Breaking Bad Movie', 'In the wake of his dramatic escape from captivity, Jesse Pinkman must come to terms with his past in order to forge some kind of future.', 'Vince Gilligan', 123, '2019-10-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ePXuKdXZuJx8hHMNr2yM4jY2L7Z.jpg', 'https://www.youtube.com/watch?v=1JLUn2DFW4w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (716, 'Mirror Game', 'Ayna is an actor, and the prison is his stage. Unable to pursue his passion in a rigid society, he turns real life into his theater—taking money from the powerful to serve their prison sentences in their place. Everything changes when he falls for the girl next door, inspiring him to pull off one final swap and leave the dark trade forever. But his last performance plunges him deep into a treacherous rabbit hole. To survive a merciless system and break free from a criminal game he helped build, this underdog must execute the ultimate escape.', 'Amitabh Reza Chowdhury', 144, '2016-09-30', 'T18', 'bn', 'https://image.tmdb.org/t/p/w500/1Cz5Q7PH2JklNV7OzMkTenPGrEf.jpg', 'https://www.youtube.com/watch?v=zfTM48zbi_c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (717, 'Late Shift', 'Dedicated nurse Floria navigates the relentless pace of her hospital’s understaffed surgical ward with humanity and warmth. As her overnight shift intensifies, she is pushed to the brink in a race against time.', 'Petra Biondina Volpe', 92, '2025-02-27', 'P', 'de', 'https://image.tmdb.org/t/p/w500/2X2FZIYdXYNwDbStJhgeoVn0pWH.jpg', 'https://www.youtube.com/watch?v=UlxEVrEhVes', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (718, '10 Cloverfield Lane', 'After a catastrophic car crash, a young woman wakes up in a survivalist''s underground bunker, where he claims to have saved her from an apocalyptic attack that has left the outside world uninhabitable.', 'Dan Trachtenberg', 104, '2016-03-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/q8A39vcBDruhvoDTJd6L8a4lnTi.jpg', 'https://www.youtube.com/watch?v=yQy-ANhnUpE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (719, 'Teenage Mutant Ninja Turtles: Mutant Mayhem', 'After years of being sheltered from the human world, the Turtle brothers set out to win the hearts of New Yorkers and be accepted as normal teenagers through heroic acts. Their new friend April O''Neil helps them take on a mysterious crime syndicate, but they soon get in over their heads when an army of mutants is unleashed upon them.', 'Jeff Rowe', 100, '2023-07-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gyh0eECE2IqrW8GWl3KoHBfc45j.jpg', 'https://www.youtube.com/watch?v=E4Kz4tZ6RcA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (720, 'Bhairathi Ranagal', 'The story revolves around the life of Bhairathi Ranagal''s journey from being a law-abiding responsible lawyer to the benevolent crime boss of Karnataka.', 'Narthan', 132, '2024-11-14', 'T16', 'kn', 'https://image.tmdb.org/t/p/w500/ghA56IEkZ1FwJVDWWEihtVnRYvZ.jpg', 'https://www.youtube.com/watch?v=Toq88y-7x1o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (721, 'Jongli', 'Liza made a difficult decision at the moment of the birth of her illegitimate child in the hospital. So she had no choice but to abandon the child in the dustbin. As she was leaving the baby in a dumpster on the road behind the hospital in the dark of night, she came face to face with Dr. Tithi—the very doctor who had delivered Liza''s baby in the operating theater. Tithi brought her back to the hospital and began to tell her a story. A story intertwined with Tithi herself, a 6-year-old girl named Pakhi, and a wild-hearted man named Johnny.', 'M Raahim', 152, '2025-03-31', 'T16', 'bn', 'https://image.tmdb.org/t/p/w500/y6AGAsNYdNcGL9CxF41QOZ1d04g.jpg', 'https://www.youtube.com/watch?v=uajQZqbj7qE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (722, 'Barbarian', 'In town for a job interview, a young woman arrives at her Airbnb late at night only to find that it has been mistakenly double-booked and a strange man is already staying there. Against her better judgement, she decides to stay the night anyway.', 'Zach Cregger', 103, '2022-08-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/idT5mnqPcJgSkvpDX7pJffBzdVH.jpg', 'https://www.youtube.com/watch?v=Dr89pmKrqkI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (723, 'War Dogs', 'Based on the true story of two young men, David Packouz and Efraim Diveroli, who won a $300 million contract from the Pentagon to arm America''s allies in Afghanistan.', 'Todd Phillips', 114, '2016-08-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mDcPRjZC1bb6LavFU3gwsWdVfCM.jpg', 'https://www.youtube.com/watch?v=KWs5qnZnhfo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (724, 'Drive My Car', 'Yusuke Kafuku, a stage actor and director, still unable, after two years, to cope with the loss of his beloved wife, accepts to direct Uncle Vanya at a theater festival in Hiroshima. There he meets Misaki, an introverted young woman, appointed to drive his car. In between rides, secrets from the past and heartfelt confessions will be unveiled.', 'Ryusuke Hamaguchi', 179, '2021-08-18', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/znXps7wPyYq8UDCfeyO2vfEIeRS.jpg', 'https://www.youtube.com/watch?v=6BPKPb_RTwI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (725, 'The Specials', 'For twenty years, Bruno and Malik have lived in a different world—the world of autistic children and teens. In charge of two separate nonprofit organizations (The Hatch & The Shelter), they train young people from underprivileged areas to be caregivers for extreme cases that have been refused by all other institutions. It’s an exceptional partnership, outside of traditional settings, for some quite extraordinary characters.', 'Olivier Nakache, Éric Toledano', 114, '2019-10-23', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/zJziqrnSOzKiV0TrNVZ3AS0NMKI.jpg', 'https://www.youtube.com/watch?v=gRLC6syOqDE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (726, 'K.G.F: Chapter 1', 'A period drama set in the 1970s, KGF follows the story of a fierce rebel who rises against the brutal oppression in Kolar Gold Fields and becomes the symbol of hope to legions of downtrodden people.', 'Prashanth Neel', 156, '2018-12-20', 'T16', 'kn', 'https://image.tmdb.org/t/p/w500/ltHlJwvxKv7d0ooCiKSAvfwV9tX.jpg', 'https://www.youtube.com/watch?v=3oxo-wacE50', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (727, 'The Old Guard', 'Four undying warriors who''ve secretly protected humanity for centuries become targeted for their mysterious powers just as they discover a new immortal.', 'Gina Prince-Bythewood', 125, '2020-07-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/cjr4NWURcVN3gW5FlHeabgBHLrY.jpg', 'https://www.youtube.com/watch?v=aK-X2d0lJ_s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (728, 'FAR. The Story of a Journey around the World', 'Documentary about the journey of Patrick Allgair and Gwendolin Weisser, who travelled over 100,000 kilometres on foot and by hitchhiking. Starting in Freiburg, Germany, they travelled eastwards for three and a half years, passing through Ukraine, Russia, China, Japan and Mexico on their way around the world.', 'Gwendolin Weisser, Patrick Allgaier', 128, '2017-03-27', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/18LACzrgCsKN53zfqko5E0TShvR.jpg', 'https://www.youtube.com/watch?v=KwNASyvE5jE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (729, '100 METERS', 'A gifted runner trains a determined but unskilled classmate, unaware he''s creating a rival who will challenge him on the track for years to come.', 'Kenji Iwaisawa', 107, '2025-09-19', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/kQyS2UrSbkd5AF0seuTSvRqWIdh.jpg', 'https://www.youtube.com/watch?v=-EXAFb7Z4qI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (730, 'Maudie', 'Canadian folk artist Maud Lewis falls in love with a fishmonger while working for him as a live-in housekeeper.', 'Aisling Walsh', 115, '2016-06-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wu9RPdV0uEemFEewJQ6fWwJ9ZcU.jpg', 'https://www.youtube.com/watch?v=u6E8isRedHo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (731, 'Cars 3', 'Blindsided by a new generation of blazing-fast racers, the legendary Lightning McQueen finds himself pushed to the brink—and suddenly, the champion who once ruled the track is fighting just to stay in the race. With his career hanging in the balance, McQueen must turn to an ambitious young race technician with a plan of her own, draw strength from the legacy of the late Fabulous Hudson Hornet, and risk everything on one last shot at glory.', 'Brian Fee', 102, '2017-06-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zg5RDxvIIAKsucjuU2EZJIHEIvz.jpg', 'https://www.youtube.com/watch?v=2LeOH9AGJQM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (732, 'Christopher Robin', 'Christopher Robin, the boy who had countless adventures in the Hundred Acre Wood, has grown up and lost his way. Now it’s up to his spirited and loveable stuffed animals, Winnie The Pooh, Tigger, Piglet, and the rest of the gang, to rekindle their friendship and remind him of endless days of childlike wonder and make-believe, when doing nothing was the very best something.', 'Marc Forster', 104, '2018-08-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/i6Ytex4d3CdfIKJFxB5v5vh24vb.jpg', 'https://www.youtube.com/watch?v=-pYG1THEnUQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (733, 'Okja', 'A young girl named Mija risks everything to prevent a powerful, multi-national company from kidnapping her best friend - a massive animal named Okja.', 'Bong Joon Ho', 120, '2017-06-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pHlRr2MfjK77VIIAO7p0R4jhsJI.jpg', 'https://www.youtube.com/watch?v=8MWwXfzTcow', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (734, 'The Drama', 'A happily engaged couple is put to the test when an unexpected turn sends their wedding week off the rails.', 'Kristoffer Borgli', 105, '2026-04-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/rnIOUhzwJDfgQakx8EjoNyItKgs.jpg', 'https://www.youtube.com/watch?v=0ZDzsH3XGFA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (735, 'Artiste', 'A serial killer wreaks havoc across a town, leading a bereaved man to seek retribution.', 'Ratan Rishi', 141, '2025-03-21', 'T16', 'te', 'https://image.tmdb.org/t/p/w500/9DgtXsH5f4CgvyQFpIcstAo0SpS.jpg', 'https://www.youtube.com/watch?v=a_rbLSPWQhU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (736, 'Mickey 17', 'Unlikely hero Mickey Barnes finds himself in the extraordinary circumstance of working for an employer who demands the ultimate commitment to the job… to die, for a living.', 'Bong Joon Ho', 137, '2025-02-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/edKpE9B5qN3e559OuMCLZdW1iBZ.jpg', 'https://www.youtube.com/watch?v=osYpGSz_0i4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (737, 'Sisu: Road to Revenge', 'Returning to the house where his family was brutally murdered during the war, "the man who refuses to die" dismantles it, loads it on a truck, and is determined to rebuild it somewhere safe in their honor. When the commander who killed his family comes back hellbent on finishing the job, a relentless, eye-popping cross-country chase ensues.', 'Jalmari Helander', 89, '2025-10-21', 'T16', 'fi', 'https://image.tmdb.org/t/p/w500/roCMOuMQ55Z2TxVx1vZZTevlo0n.jpg', 'https://www.youtube.com/watch?v=VmStqCXIgio', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (738, 'Fast & Furious Presents: Hobbs & Shaw', 'Ever since US Diplomatic Security Service Agent Hobbs and lawless outcast Shaw first faced off, they just have traded smack talk and body blows. But when cyber-genetically enhanced anarchist Brixton''s ruthless actions threaten the future of humanity, they join forces to defeat him.', 'David Leitch', 137, '2019-07-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qRyy2UmjC5ur9bDi3kpNNRCc5nc.jpg', 'https://www.youtube.com/watch?v=9SA7FaKxZVI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (739, 'Passenger', 'After a young couple witnesses a gruesome highway accident, they soon realize they did not leave the crash scene alone, as a demonic presence called the Passenger that won''t stop until it claims them both turns their van life adventure into a nightmare.', 'André Øvredal', 94, '2026-05-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/svrAzMTif4OmIjGJzC0W92d5O1o.jpg', 'https://www.youtube.com/watch?v=eNIn8kW1kyE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (740, 'Belle', 'Suzu is a 17-year-old high-school student living in a rural town with her father. Wounded by the loss of her mother at a young age, Suzu one day discovers the massive online world "U" and dives into this alternate reality as her avatar, Belle. Before long, all of U''s eyes are fixed on Belle, when, suddenly, a mysterious, dragon-like figure appears before her.', 'Mamoru Hosoda', 121, '2021-07-16', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/fYHOD4pxZQk4rsP2tQrZI5uBlZV.jpg', 'https://www.youtube.com/watch?v=7iiDjDmywIM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (741, 'A Million Miles Away', 'The life of engineer and former NASA astronaut José M. Hernández, the first migrant farmworker to go to space.', 'Alejandra Márquez Abella', 122, '2023-09-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kMI3tgxLAZbzGOVlorUBva0kriS.jpg', 'https://www.youtube.com/watch?v=J-HcUuiLzR8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (742, 'Missing', 'When her mother disappears while on vacation in Colombia with her new boyfriend, June’s search for answers is hindered by international red tape. Stuck thousands of miles away in Los Angeles, June creatively uses all the latest technology at her fingertips to try and find her before it’s too late. But as she digs deeper, her digital sleuthing raises more questions than answers... and when June unravels secrets about her mom, she discovers that she never really knew her at all.', 'Nicholas D. Johnson, Will Merrick', 111, '2023-01-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wEOUYSU5Uf8J7152PT6jdb5233Y.jpg', 'https://www.youtube.com/watch?v=seBixtcx19E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (743, 'Lucky Baskhar', 'A middle-class bank clerk who longs to trade stability for adventure gets more than he bargained for when he unexpectedly becomes a wealthy man.', 'Venky Atluri', 151, '2024-10-30', 'T16', 'te', 'https://image.tmdb.org/t/p/w500/a47JQFl9L7VDa79tEvnTOJe0rPa.jpg', 'https://www.youtube.com/watch?v=Kv5RKsqVe-Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (744, 'Seaspiracy', 'Passionate about ocean life, a filmmaker sets out to document the harm that humans do to marine species — and uncovers an alarming global conspiracy.', 'Ali Tabrizi', 89, '2021-03-24', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/iFNri0fwn1WfCoxf3H3v1z8dCm4.jpg', 'https://www.youtube.com/watch?v=1Q5CXN7soQg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (745, 'Tumbbad', 'India, 1918. On the outskirts of Tumbbad, a cursed village where it always rains, Vinayak, along with his mother and his brother, care of a mysterious old woman who keeps the secret of an ancestral treasure that Vinayak gets obsessed with.', 'Rahi Anil Barve', 113, '2018-10-12', 'T16', 'hi', 'https://image.tmdb.org/t/p/w500/vzjZAKozbDplHWcQXbXo0APKxst.jpg', 'https://www.youtube.com/watch?v=ZjuhALyNgss', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (746, 'Before the Flood', 'A look at how climate change affects our environment and what society can do to prevent the demise of endangered species, ecosystems, and native communities across the planet.', 'Fisher Stevens', 93, '2016-10-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/2fFTLaLbm8Ak7JBSYQ8Mb3jcFx9.jpg', 'https://www.youtube.com/watch?v=yyjr_3YnL_8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (747, 'Kung Fu Panda 4', 'Po is gearing up to become the spiritual leader of his Valley of Peace, but also needs someone to take his place as Dragon Warrior. As such, he will train a new kung fu practitioner for the spot and will encounter a villain called the Chameleon who conjures villains from the past.', 'Mike Mitchell', 94, '2024-03-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kDp1vUBnMpe8ak4rjgl3cLELqjU.jpg', 'https://www.youtube.com/watch?v=_inKs4eeHiI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (748, 'Civil War', 'In the near future, a group of war journalists attempt to survive while reporting the truth as the United States stands on the brink of civil war.', 'Alex Garland', 109, '2024-04-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/sh7Rg8Er3tFcN9BpKIPOMvALgZd.jpg', 'https://www.youtube.com/watch?v=aDyQxtg0V2w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (749, 'Papillon', 'Henri “Papillon” Charrière, a safecracker from the Parisian underworld, is wrongfully convicted and sentenced to life imprisonment in the penal colony of French Guiana, where he forges a strong friendship with Louis Dega, a counterfeiter who needs his protection.', 'Michael Noer', 134, '2017-09-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ahF5c6vyP8HWMqIwlhecbRALkjq.jpg', 'https://www.youtube.com/watch?v=xqj7XOv9mC8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (750, 'Flee', 'Recounted mostly through animation to protect his identity, Amin looks back over his past as a child refugee from Afghanistan as he grapples with a secret he’s kept hidden for 20 years.', 'Jonas Poher Rasmussen', 89, '2021-06-17', 'K', 'da', 'https://image.tmdb.org/t/p/w500/vlMIbqOpYG553J1kOJXA7mwQvE6.jpg', 'https://www.youtube.com/watch?v=IcgMxg22tY0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (751, 'Jackass: Best and Last', 'The fifth and final installment to Jackass franchise where the crew go on one last insane crusade.', 'Jeff Tremaine', 92, '2026-06-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/tfgccePxnswMqhmtxafliLlcCVR.jpg', 'https://www.youtube.com/watch?v=sNwzFhGwA94', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (752, 'Aparajito', 'A young filmmaker prepares for the debut of his first feature film.', 'Anik Dutta', 138, '2022-05-13', 'T13', 'bn', 'https://image.tmdb.org/t/p/w500/1ut3XJUxQEus4B57TQ5wZHiXgN6.jpg', 'https://www.youtube.com/watch?v=zgO3bRmmlz4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (753, 'The Witcher: Nightmare of the Wolf', 'Escaping from poverty to become a witcher, Vesemir slays monsters for coin and glory, but when a new menace rises, he must face the demons of his past.', 'Han Kwang Il', 83, '2021-08-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3sLz2yv6vBDWqBbd8rdnNeoJ2kJ.jpg', 'https://www.youtube.com/watch?v=J365hQpaWRw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (754, 'I Still Believe', 'The true-life story of Christian music star Jeremy Camp and his journey of love and loss that looks to prove there is always hope.', 'Andrew Erwin, Jon Erwin', 115, '2020-03-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dqA2FCzz4OMmXLitKopzf476RVB.jpg', 'https://www.youtube.com/watch?v=7Za7-Q8YURM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (755, 'Jumanji: The Next Level', 'As the gang return to Jumanji to rescue one of their own, they discover that nothing is as they expect. The players will have to brave parts unknown and unexplored in order to escape the world’s most dangerous game.', 'Jake Kasdan', 123, '2019-12-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jyw8VKYEiM1UDzPB7NsisUgBeJ8.jpg', 'https://www.youtube.com/watch?v=F6QaLsw8EWY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (756, 'The Jungle Book', 'After a threat from the tiger Shere Khan, Mowgli, a man-cub fostered by wolves, is forced to flee the jungle, and he embarks on a journey of self-discovery with the help of the panther, Bagheera, and the free-spirited bear, Baloo.', 'Jon Favreau', 106, '2016-04-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/2Epx7F9X7DrFptn4seqn4mzBVks.jpg', 'https://www.youtube.com/watch?v=YW97nCUE3ZA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (757, 'Premalu', 'Sachin, a carefree graduate, crosses paths with Reenu, a spirited IT professional, in Hyderabad. As their friendship deepens, unspoken feelings, career ambitions and life choices challenge their bond.', 'Girish A. D.', 155, '2024-02-09', 'P', 'ml', 'https://image.tmdb.org/t/p/w500/uPpmBjY3znUqGY8kYwI5xvOrSc0.jpg', 'https://www.youtube.com/watch?v=OnxChVgg6N8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (758, 'Agak Laen: Menyala Pantiku!', 'After repeatedly failing their missions, Detectives Bene, Boris, Jegel, and Oki are given one last chance: to go undercover in a nursing home in search of a fugitive wanted for the murder of the mayor’s child.', 'Muhadkly Acho', 119, '2025-11-27', 'T16', 'id', 'https://image.tmdb.org/t/p/w500/fPJ9OjLgAQoLZrPeL6ZfQwNkfPK.jpg', 'https://www.youtube.com/watch?v=TauACNyt5mI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (759, 'Kokuho', 'Nagasaki, 1964: Following the death of his Yakuza father, 15-year-old Kikuo is taken under the wings of a famous Kabuki actor. Alongside Shunsuke, the actor’s only son, he decides to dedicate himself to this traditional form of theatre. For decades, the two young men grow and evolve together – and one will become the greatest Japanese master of the art of Kabuki.', 'Sang-il Lee', 174, '2025-06-06', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/a15F5KJ4mleusJR1YKP4zUyZaxG.jpg', 'https://www.youtube.com/watch?v=htY9T0KCyRY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (760, 'The Whisper Man', 'When his young son vanishes, a widower enlists help from his estranged father, a retired detective who put away the serial killer now linked to the case.', 'James Ashcroft', 111, '2026-08-27', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/ndRs5lADYm0PeVjuOxaMcInY0o2.jpg', 'https://www.youtube.com/watch?v=ZHRR-1CKYIQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (761, 'The Adam Project', 'After accidentally crash-landing in 2022, time-traveling fighter pilot Adam Reed teams up with his 12-year-old self on a mission to save the future.', 'Shawn Levy', 106, '2022-03-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wFjboE0aFZNbVOF05fzrka9Fqyx.jpg', 'https://www.youtube.com/watch?v=IE8HIsIrq4o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (762, 'Now You See Me 2', 'One year after outwitting the FBI and winning the public’s adulation with their mind-bending spectacles, the Four Horsemen resurface only to find themselves face to face with a new enemy who enlists them to pull off their most dangerous heist yet.', 'Jon M. Chu', 129, '2016-06-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/A81kDB6a1K86YLlcOtZB27jriJh.jpg', 'https://www.youtube.com/watch?v=AuEjHzOIgBE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (763, 'Birds of Prey (and the Fantabulous Emancipation of One Harley Quinn)', 'Harley Quinn joins forces with a singer, an assassin and a police detective to help a young girl who had a hit placed on her after she stole a rare diamond from a crime lord.', 'Cathy Yan', 109, '2020-02-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/h4VB6m0RwcicVEZvzftYZyKXs6K.jpg', 'https://www.youtube.com/watch?v=kGM4uYZzfu0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (764, 'The Greatest Beer Run Ever', 'Chickie wants to support his friends fighting in Vietnam, so he does something wild—personally bring them American beer. What starts as a well-meaning journey quickly changes Chickie''s life and perspective.', 'Peter Farrelly', 127, '2022-09-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ggf37TpcKaxwguhvtNn6MQpyqBn.jpg', 'https://www.youtube.com/watch?v=NqxziDlZOIo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (765, 'Mercy', 'In the near future, a detective stands on trial accused of murdering his wife. He has ninety minutes to prove his innocence to the advanced AI Judge he once championed, before it determines his fate.', 'Timur Bekmambetov', 100, '2026-01-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pyok1kZJCfyuFapYXzHcy7BLlQa.jpg', 'https://www.youtube.com/watch?v=7H7Djx17l8Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (766, 'The Devil All the Time', 'In Knockemstiff, Ohio and its neighboring backwoods, sinister characters converge around young Arvin Russell as he fights the evil forces that threaten him and his family.', 'Antonio Campos', 138, '2020-09-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/v3wGDRhnik4HSuaMzATkgaqDJLS.jpg', 'https://www.youtube.com/watch?v=EIzazUv2gtI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (767, 'The Stranger by the Shore', 'Abandoned after coming out, Shun befriends Mio just before he has to move. Years later, Mio returns with a confession. How will Shun feel?', 'Akiyo Ohashi', 59, '2020-09-11', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/4m74lboTcvrmnCM506t4y4c3klc.jpg', 'https://www.youtube.com/watch?v=l8ohnONoE24', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (768, 'Ocean''s Eight', 'Debbie Ocean, a criminal mastermind, gathers a crew of female thieves to pull off the heist of the century at New York''s annual Met Gala.', 'Gary Ross', 111, '2018-06-07', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/MvYpKlpFukTivnlBhizGbkAe3v.jpg', 'https://www.youtube.com/watch?v=MFWF9dU5Zc0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (769, 'I Am Not Your Negro', 'Working from the text of James Baldwin’s unfinished final novel, director Raoul Peck creates a meditation on what it means to be Black in the United States.', 'Raoul Peck', 93, '2017-02-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zwd0Zti7BvY1mO0mTPzM0fRrtc6.jpg', 'https://www.youtube.com/watch?v=rNUYdgIyaPM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (770, 'Ballabhpurer Roopkotha', 'The almost crumbling Rajbari of Ballabhpur only has two men living — the last descendant of Ray dynasty, Bhupati Ray, and his inherited menial, Manohar. Both the dwellers are overburdened with heavy debts and seek no hope of betterment until one day, Kolkata''s soap King, Mr. Haldar, plans buying the property. Can Bhupati Ray and Manohar succeed in selling it?', 'Anirban Bhattacharya', 136, '2022-10-25', 'T16', 'bn', 'https://image.tmdb.org/t/p/w500/84yy5xjv3sM8G2HbxUnKejKJgYz.jpg', 'https://www.youtube.com/watch?v=NER2p1UmdAY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (771, 'Nomadland', 'A woman in her sixties embarks on a journey through the western United States after losing everything in the Great Recession, living as a van-dwelling modern-day nomad.', 'Chloé Zhao', 108, '2021-01-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8Vc5EOUEIF1EUXuX9eLFf7BvN3P.jpg', 'https://www.youtube.com/watch?v=6sxCFZ8_d84', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (772, 'A Complete Unknown', 'New York, early 1960s. Against the backdrop of a vibrant music scene and tumultuous cultural upheaval, an enigmatic 19-year-old from Minnesota arrives in the West Village with his guitar and revolutionary talent, destined to change the course of American music.', 'James Mangold', 141, '2024-12-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/llWl3GtNoXosbvYboelmoT459NM.jpg', 'https://www.youtube.com/watch?v=FdV-Cs5o8mc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (773, 'Kung Fu Panda 3', 'While Po and his father are visiting a secret panda village, an evil spirit threatens all of China, forcing Po to form a ragtag army to fight back.', 'Alessandro Carloni, Jennifer Yuh Nelson', 95, '2016-01-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oajNi4Su39WAByHI6EONu8G8HYn.jpg', 'https://www.youtube.com/watch?v=10r9ozshGVE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (774, 'Decision to Leave', 'From a mountain peak in South Korea, a man plummets to his death. Did he jump, or was he pushed? When detective Hae-joon arrives on the scene, he begins to suspect the dead man’s wife Seo-rae. But as he digs deeper into the investigation, he finds himself trapped in a web of deception and desire.', 'Park Chan-wook', 139, '2022-06-29', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/zI8KZ4EdLUymWKX1YEkpZ0gtPUa.jpg', 'https://www.youtube.com/watch?v=97YCtcT470g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (775, 'Supergirl', 'When an unexpected and ruthless adversary strikes too close to home, Kara Zor-El, aka Supergirl, reluctantly joins forces with an unlikely companion on an epic, interstellar journey of vengeance and justice.', 'Craig Gillespie', 108, '2026-06-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uhzRnTW4DM13UQBvZP3eVNzQTuz.jpg', 'https://www.youtube.com/watch?v=YqdAEdkHrwo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (776, 'We Live in Time', 'An up-and-coming chef and a recent divorcée find their lives forever changed when a chance encounter brings them together, in a decade-spanning, deeply moving romance.', 'John Crowley', 108, '2024-10-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oeDNBgnlGF6rnyX1P1K8Vl2f3lW.jpg', 'https://www.youtube.com/watch?v=MH02yagHaNw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (777, 'Good Luck, Have Fun, Don''t Die', 'A ''Man from the Future'' arrives at an LA diner where he must recruit the precise combination of disgruntled patrons to join him on a one-night quest to save the world from the terminal threat of a rogue artificial intelligence.', 'Gore Verbinski', 134, '2026-02-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rWcfOdY7TU6lTdazWj0ebDZnAfO.jpg', 'https://www.youtube.com/watch?v=CaSxNAZUKsM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (778, 'Stand by Me Doraemon 2', 'Nobita travels to the future to show his beloved grandma his bride, but adult Nobita has fled his own wedding.', 'Ryuichi Yagi, Takashi Yamazaki', 96, '2020-11-20', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/vBv8iOFPLnXmtELUjcFc7OKHsR4.jpg', 'https://www.youtube.com/watch?v=rHieKpfmTOM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (779, 'It Chapter Two', '27 years after overcoming the malevolent supernatural entity Pennywise, the former members of the Losers'' Club, who have grown up and moved away from Derry, are brought back together by a devastating phone call.', 'Andy Muschietti', 169, '2019-09-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zfE0R94v1E8cuKAerbskfD3VfUt.jpg', 'https://www.youtube.com/watch?v=xhJ5P7Up3jA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (780, 'To All the Boys: Always and Forever', 'Senior year of high school takes center stage as Lara Jean returns from a family trip to Korea and considers her college plans — with and without Peter.', 'Michael Fimognari', 114, '2021-02-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iepqdM52f4w75fNcvgRF5QoIAjm.jpg', 'https://www.youtube.com/watch?v=2jPdejek5QA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (781, 'Love Ni Bhavai', 'A popular radio personality with an aversion to love meets two men with differing views on romance.', 'Saandeep Patel', 162, '2017-11-17', 'P', 'gu', 'https://image.tmdb.org/t/p/w500/qMkyyQgFZghXK8xLMq8gwQmqZS4.jpg', 'https://www.youtube.com/watch?v=OlsM8Nwb6nA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (782, 'Us', 'Husband and wife Gabe and Adelaide Wilson take their kids to their beach house expecting to unplug and unwind with friends. But as night descends, their serenity turns to tension and chaos when some shocking visitors arrive uninvited.', 'Jordan Peele', 116, '2019-03-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ux2dU1jQ2ACIMShzB3yP93Udpzc.jpg', 'https://www.youtube.com/watch?v=hNCmb-4oXJA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (783, 'Apex', 'A grieving woman pushing her limits on a solo adventure in the Australian wild is ensnared in a twisted game with a cunning killer who thinks she''s prey.', 'Baltasar Kormákur', 96, '2026-04-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/eTp7gSPkSF3Aw79mNx1NkBP1PZT.jpg', 'https://www.youtube.com/watch?v=kgv8jf_8dm0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (784, 'Forever My Girl', 'Years after leaving his fiancée at the altar to pursue fame and fortune, country music star Liam Page returns home hoping to win her back.', 'Bethany Ashton Wolf', 108, '2018-01-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/bKqdggnIPeOI15VqtBZTkvh4hA9.jpg', 'https://www.youtube.com/watch?v=5iEOQn8UUHI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (785, 'Minari', 'A Korean American family moves to an Arkansas farm in search of its own American dream. Amidst the challenges of this new life in the strange and rugged Ozarks, they discover the undeniable resilience of family and what really makes a home.', 'Lee Isaac Chung', 115, '2021-02-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6mPNdmjdbVKPITv3LLCmQoKs9Zw.jpg', 'https://www.youtube.com/watch?v=KQ0gFidlro8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (786, 'By Any Means', 'In 1960s Mississippi, a young Black FBI agent is forced to partner with a notorious mafia hitman to investigate a wave of brutal civil rights murders.', 'Elegance Bratton', 107, '2026-09-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/f4hdIed8vh10O8TkQ1CkHS8MQ3G.jpg', 'https://www.youtube.com/watch?v=ej8pjisr0Pc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (787, 'Les Misérables', 'Stéphane has recently joined the Anti-Crime Squad in Montfermeil, in the suburbs of Paris, France, where Victor Hugo set his famed novel “Les Miserables”. Alongside his new colleagues Chris and Gwada – both experienced members of the team – he quickly discovers tensions running high between local gangs. When the trio finds themselves overrun during the course of an arrest, a drone captures the encounter, threatening to expose the reality of everyday life.', 'Ladj Ly', 104, '2019-11-14', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/2ZQV9rPFXF0iFfKbsAvVIweQ1yM.jpg', 'https://www.youtube.com/watch?v=YFfdlLW9Rwg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (788, 'BTS: Yet to Come in Cinemas', 'Join RM, Jin, SUGA, j-hope, Jimin, V and Jung Kook in this special cinematic cut, re-edited and remixed for the big screen. Watch new close-up angles and a whole new view of the entire concert, BTS Yet To Come in Busan. Featuring hit songs from across the group''s career, including "Dynamite," "Butter" and “IDOL," plus the first concert performance of "Run BTS" from the group’s latest album Proof.', 'Yoon Dong Oh', 103, '2023-02-01', 'T13', 'ko', 'https://image.tmdb.org/t/p/w500/eWb45OsBHSO2t1j068bqDsPOGG9.jpg', 'https://www.youtube.com/watch?v=Rbiz1JONJwI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (789, 'BPM (Beats per Minute)', 'Paris, in the early 1990s: a group of young activists is desperately tied to finding the cure against an unknown lethal disease. They target the pharmaceutical labs that are retaining potential cures, and multiply direct actions, with the hope of saving their lives as well as the ones of future generations.', 'Robin Campillo', 143, '2017-08-23', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/azLtGx5ZhdTSP2b4oNLWtiE51OW.jpg', 'https://www.youtube.com/watch?v=4GzCfjF0vDU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (790, 'Judas and the Black Messiah', 'Bill O''Neal infiltrates the Black Panthers on the orders of FBI Agent Mitchell and J. Edgar Hoover. As Black Panther Chairman Fred Hampton ascends—falling for a fellow revolutionary en route—a battle wages for O’Neal’s soul.', 'Shaka King', 125, '2021-02-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iIgr75GoqFxe1X5Wz9siOODGe9u.jpg', 'https://www.youtube.com/watch?v=6ivHf4ODMi4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (791, 'Back to the Outback', 'Tired of being locked in a reptile house where humans gawk at them like they are monsters, a ragtag group of Australia’s deadliest creatures plot an escape from their zoo to the Outback, a place where they’ll fit in without being judged.', 'Clare Knight, Harry Cripps', 92, '2021-12-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jbAUTO7qFN8XFG2LM3bz30vzGFJ.jpg', 'https://www.youtube.com/watch?v=dDNhtB7L8Lk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (792, 'Trolls World Tour', 'Queen Poppy and Branch make a surprising discovery — there are other Troll worlds beyond their own, and their distinct differences create big clashes between these various tribes. When a mysterious threat puts all of the Trolls across the land in danger, Poppy, Branch, and their band of friends must embark on an epic quest to create harmony among the feuding Trolls to unite them against certain doom.', 'Walt Dohrn', 91, '2020-03-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7W0G3YECgDAfnuiHG91r8WqgIOe.jpg', 'https://www.youtube.com/watch?v=08AExF6dETA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (793, 'DAMaN', 'The film is set in 2015. Sid, is a young doctor who completed his MBBS has been posted to the cut-off of area of Malkangiri district Odisha having 151 villages & infamous for Naxals dominance & no basic facilities. It''s journey of a doctor.', 'Debi Prasad Lenka, Vishal Mourya', 121, '2022-11-04', 'P', 'or', 'https://image.tmdb.org/t/p/w500/mUHa29ySdqlCfDlrA3gqPxJNd9M.jpg', 'https://www.youtube.com/watch?v=QO7QKT111q8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (794, 'Kizumonogatari Part 3: Reiketsu', 'With help from Meme Oshino, the apparition specialist, Koyomi defeats the three powerful vampire hunters: Dramaturgy, Episode and Guillotinecutter. Koyomi takes back all the limbs of Kiss-shot Acerola-orion Heart-under-blade in order to become a human again.', 'Akiyuki Shinbo, Tatsuya Oishi', 83, '2017-01-06', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/rfKHhHvSwyCv59Ow6wuGX67RkXR.jpg', 'https://www.youtube.com/watch?v=4nTLr6Uf9Ug', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (795, 'The Ballad of Buster Scruggs', 'Vignettes weaving together the stories of six individuals in the old West at the end of the Civil War. Following the tales of a sharp-shooting songster, a wannabe bank robber, two weary traveling performers, a lone gold prospector, a woman traveling the West to an uncertain future, and a motley crew of strangers undertaking a carriage ride.', 'Ethan Coen, Joel Coen', 132, '2018-11-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/voxl654m7p36y8FLu8oQD7dfwwK.jpg', 'https://www.youtube.com/watch?v=_2PyxzSH1HM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (796, 'Jumanji: Welcome to the Jungle', 'Four teenagers in detention discover an old video game console with a game they’ve never heard of. When they decide to play, they are immediately sucked into the jungle world of Jumanji in the bodies of their avatars. They’ll have to complete the adventure of their lives filled with fun, thrills and danger or be stuck in the game forever!', 'Jake Kasdan', 119, '2017-12-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pSgXKPU5h6U89ipF7HBYajvYt7j.jpg', 'https://www.youtube.com/watch?v=10VphsyJhbU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (797, 'First Man', 'A look at the life of the astronaut, Neil Armstrong, and the legendary space mission that led him to become the first man to walk on the Moon on July 20, 1969.', 'Damien Chazelle', 141, '2018-10-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/i91mfvFcPPlaegcbOyjGgiWfZzh.jpg', 'https://www.youtube.com/watch?v=O9Y7DTCn7Cc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (798, 'The Farewell', 'A headstrong Chinese-American woman returns to China when her beloved grandmother is given a terminal diagnosis. Billi struggles with her family''s decision to keep grandma in the dark about her own illness as they all stage an impromptu wedding to see grandma one last time.', 'Lulu Wang', 100, '2019-07-12', 'K', 'en', 'https://image.tmdb.org/t/p/w500/7ht2IMGynDSVQGvAXhAb83DLET8.jpg', 'https://www.youtube.com/watch?v=RofpAjqwMa8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (799, 'Robin Williams: Come Inside My Mind', 'A funny, intimate and heartbreaking portrait of one of the world’s most beloved and inventive comedians, Robin Williams, told largely through his own words. Celebrates what he brought to comedy and to the culture at large, from the wild days of late-1970s L.A. to his death in 2014.', 'Marina Zenovich', 116, '2018-01-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ak9DZnzInl9oIUlXxsFsUd37ueh.jpg', 'https://www.youtube.com/watch?v=caIFNg_JRL4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (800, 'Our Fault', 'Jenna and Lion''s wedding brings about the long-awaited reunion between Noah and Nick after their breakup. Nick''s inability to forgive Noah stands as an insurmountable barrier. He, heir to his grandfather''s businesses, and she, starting her professional life, resist fueling a flame that''s still alive. But now that their paths have crossed again, will love be stronger than resentment?', 'Domingo González', 110, '2025-10-15', 'T13', 'es', 'https://image.tmdb.org/t/p/w500/yzqHt4m1SeY9FbPrfZ0C2Hi9x1s.jpg', 'https://www.youtube.com/watch?v=4ZDvKct1U4s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (801, 'The Heist of the Century', 'In 2006, a group of thieves performed what is considered one of the most famous and smart bank heists in the history of Argentina. How they robbed the Rio bank is as surprising as what happened afterwards. This is their story.', 'Ariel Winograd', 114, '2020-01-16', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/1zL4VCVin4S8kOXhszMDqfwWPCM.jpg', 'https://www.youtube.com/watch?v=u3rtVNSC-FU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (802, 'Ferdinand', 'Ferdinand, a little bull, prefers sitting quietly under a cork tree just smelling the flowers versus jumping around, snorting, and butting heads with other bulls. As Ferdinand grows big and strong, his temperament remains mellow. But one day five men come to choose the "biggest, fastest, roughest bull" for the bullfights in Madrid— and Ferdinand is mistakenly chosen.', 'Carlos Saldanha', 108, '2017-12-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rMm94JsRfcOPiPVsTRcBiiVBOhz.jpg', 'https://www.youtube.com/watch?v=0Iiq-9fhwa0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (803, 'Uttar Da Puttar', 'Vastu, destiny and daily life, where unexpected events challenge beliefs about luck, direction and the power to shape your own future.', 'Ravinder Siwatch', 103, '2026-07-24', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/gRx4Bc6GTwi8L3vq29bnciEuRgL.jpg', 'https://www.youtube.com/watch?v=9EISxkYkLEc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (804, 'Paramapadha Sopanam', 'Sarpanch, VRO, and medical officer-begin to meet brutal ends, each shrouded in secrecy.Police investigation reveals thirty fingerprints on bodies of deceased, but only one fingerprint is found on the last victim, creating a complex puzzle.', 'Naga Shiva', 106, '2025-07-11', 'T18', 'te', 'https://image.tmdb.org/t/p/w500/y1SlMiY354kg9YFYktWKeRyrXSF.jpg', 'https://www.youtube.com/watch?v=y3zccn77ksk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (805, 'Sapta Sagaradaache Ello – Side A', 'In the heart of ''Sapta Sagaradaache Ello’ resides an ardent love story between Manu and Priya. Set in 2010, the couple hails from a middle-class background. Circumstances land Manu in jail, putting his relationship with Priya in jeopardy.', 'Hemanth M. Rao', 140, '2023-09-01', 'P', 'kn', 'https://image.tmdb.org/t/p/w500/qjvSMN5dhSh7cymjj6if2aJ4ejW.jpg', 'https://www.youtube.com/watch?v=hcJ1ZHHahMA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (806, 'Beetlejuice Beetlejuice', 'After a family tragedy, three generations of the Deetz family return home to Winter River. Still haunted by Betelgeuse, Lydia''s life is turned upside down when her teenage daughter, Astrid, accidentally opens the portal to the Afterlife.', 'Tim Burton', 105, '2024-09-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kKgQzkUCnQmeTPkyIwHly2t6ZFI.jpg', 'https://www.youtube.com/watch?v=As-vKW4ZboU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (807, 'Saw X', 'Between the events of ''Saw'' and ''Saw II'', a sick and desperate John Kramer travels to Mexico for a risky and experimental medical procedure in hopes of a miracle cure for his cancer, only to discover the entire operation is a scam to defraud the most vulnerable. Armed with a newfound purpose, the infamous serial killer returns to his work, turning the tables on the con artists in his signature visceral way through devious, deranged, and ingenious traps.', 'Kevin Greutert', 118, '2023-09-27', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/u7Lp1Hi8aBS73jv4KRMIv5aK4ax.jpg', 'https://www.youtube.com/watch?v=t3PzUo4P21c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (808, 'Chhichhore', 'Following a group of friends from university as they progress into middle-age life and go their own separate ways.', 'Nitesh Tiwari', 146, '2019-09-05', 'T13', 'hi', 'https://image.tmdb.org/t/p/w500/cGDPQtQ5igtPMt3oJ6BCAor6dFp.jpg', 'https://www.youtube.com/watch?v=-KKlF-VxOfo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (809, 'Pain and Glory', 'Salvador Mallo, a filmmaker in the twilight of his career, remembers his life: his mother, his lovers, the actors he worked with. The sixties in a small village in Valencia, the eighties in Madrid, the present, when he feels an immeasurable emptiness, facing his mortality, the incapability of continuing filming, the impossibility of separating creation from his own life. The need of narrating his past can be his salvation.', 'Pedro Almodóvar', 114, '2019-03-22', 'P', 'es', 'https://image.tmdb.org/t/p/w500/cMlueArJXXwZbeLpb4NhC3pxmBk.jpg', 'https://www.youtube.com/watch?v=2jIh5JP9ajc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (810, 'Snowden', 'CIA employee Edward Snowden leaks thousands of classified documents to the press.', 'Oliver Stone', 135, '2016-09-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yfK7zxNL63VWfluFuoUaJj5PdNw.jpg', 'https://www.youtube.com/watch?v=QlSAiI3xMh4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (811, 'American Fiction', 'A novelist fed up with the establishment profiting from "Black" entertainment uses a pen name to write a book that propels him into the heart of hypocrisy and the madness he claims to disdain.', 'Cord Jefferson', 117, '2023-11-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/57MFWGHarg9jid7yfDTka4RmcMU.jpg', 'https://www.youtube.com/watch?v=5_4RlHpqVWM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (812, 'Big George Foreman', 'Fueled by an impoverished childhood, George Foreman channeled his anger into becoming an Olympic Gold medalist and World Heavyweight Champion, followed by a near-death experience that took him from the boxing ring to the pulpit. But when he sees his community struggling spiritually and financially, Foreman returns to the ring and makes history by reclaiming his title, becoming the oldest and most improbable World Heavyweight Boxing Champion ever.', 'George Tillman Jr.', 129, '2023-04-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fdVd6thTstt0MQ4dUC1IXiOXpxv.jpg', 'https://www.youtube.com/watch?v=urKDu40iaXk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (813, 'Made in Abyss: Wandering Twilight', 'Second compilation movie of the TV series which covers episodes 9-13. Riko and Reg descend to the third and fourth layer where Riko has her first experience of the Curse.', 'Masayuki Kojima', 105, '2019-01-18', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/ivEZMkRng0VvDuQUoU8nhtqcfwe.jpg', 'https://www.youtube.com/watch?v=BdRiv8EYbgM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (814, 'The Boss Baby: Family Business', 'The Templeton brothers — Tim and his Boss Baby little bro Ted — have become adults and drifted away from each other. But a new boss baby with a cutting-edge approach and a can-do attitude is about to bring them together again … and inspire a new family business.', 'Tom McGrath', 107, '2021-07-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aQ7huOn3F0iJCJrFezS8p9WEsri.jpg', 'https://www.youtube.com/watch?v=-rF2j6K5FoM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (815, 'The Call', 'Connected by phone in the same home but 20 years apart, a caller puts a woman’s past — and life — on the line to change her own fate.', 'Lee Chung-hyun', 112, '2020-11-23', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/oz8hvZHg7tIdGwh0ErPRhobJKPR.jpg', 'https://www.youtube.com/watch?v=hxkKeniT-0Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (816, 'Forgotten Love', 'A once-respected surgeon who''s lost his family and his memory gets a chance at redemption when he reconnects with someone from his forgotten past.', 'Michał Gazda', 140, '2023-09-26', 'T13', 'pl', 'https://image.tmdb.org/t/p/w500/1THDAakV8hmbRC9YIqJ9SngVinr.jpg', 'https://www.youtube.com/watch?v=SUbs1-j5JOg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (817, 'On My Skin', 'The incredible true story behind the most controversial Italian court cases in recent years. Stefano Cucchi was arrested for a minor crime and mysteriously found dead during his detention. In one week''s time, a family is changed forever.', 'Alessio Cremonini', 100, '2018-09-12', 'P', 'it', 'https://image.tmdb.org/t/p/w500/rwPgE6fLxuJmPWi8fFjgENJMAjr.jpg', 'https://www.youtube.com/watch?v=tI9wa-Y9O8s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (818, 'Good Time', 'After a botched bank robbery lands his younger brother in prison, Connie Nikas embarks on a twisted odyssey through New York City''s underworld to get his brother Nick out of jail.', 'Benny Safdie, Josh Safdie', 102, '2017-08-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yE1c9hj5Hf8a9KplAdRdhADqUro.jpg', 'https://www.youtube.com/watch?v=AVyGCxHZ_Ko', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (819, 'Challengers', 'Tennis player turned coach Tashi has taken her husband, Art, and transformed him into a world-famous Major champion. To jolt him out of his recent losing streak, she signs him up for a "Challenger" event — close to the lowest level of pro tournament — where he finds himself standing across the net from his former best friend and Tashi''s former boyfriend.', 'Luca Guadagnino', 132, '2024-04-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/H6vke7zGiuLsz4v4RPeReb9rsv.jpg', 'https://www.youtube.com/watch?v=-2N3hmRmwHQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (820, 'Sonchiriya', 'A legion of warring bandits terrorizes India''s Chambal Valley.', 'Abhishek Chaubey', 145, '2019-03-01', 'T18', 'hi', 'https://image.tmdb.org/t/p/w500/7ygikeDbneOlUFIQyvAmMrvi3vJ.jpg', 'https://www.youtube.com/watch?v=aejAkKGiimk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (821, 'The Conjuring: Last Rites', 'Paranormal investigators Ed and Lorraine Warren take on one last terrifying case involving mysterious entities they must confront.', 'Michael Chaves', 136, '2025-09-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/byWgphT74ClOVa8EOGzYDkl8DVL.jpg', 'https://www.youtube.com/watch?v=bMgfsdYoEEo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (822, 'Creed III', 'After dominating the boxing world, Adonis Creed has thrived in his career and family life. When a childhood friend and former boxing prodigy, Damian Anderson, resurfaces after serving a long sentence in prison, he is eager to prove that he deserves his shot in the ring. The face-off between former friends is more than just a fight. To settle the score, Adonis must put his future on the line to battle Damian — a fighter with nothing to lose.', 'Michael B. Jordan', 116, '2023-03-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cvsXj3I9Q2iyyIo95AecSd1tad7.jpg', 'https://www.youtube.com/watch?v=AHmCH7iB_IM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (823, 'Modha Rathri', 'Two strangers are brought together at an unusual wedding where, in one night, too many surprises unfold and several lies are told, spiraling into chaos that changes everything.', 'Raja Karuppasamy', 141, '2026-08-21', 'P', 'ta', 'https://image.tmdb.org/t/p/w500/3VuNFeniljhEe9MDW12MnDbETgH.jpg', 'https://www.youtube.com/watch?v=UrWrvwIRnqk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (824, 'The Platform', 'A slab of food descends down a vertical facility. The residents above eat heartily, leaving those below starving and desperate. A rebellion is imminent.', 'Galder Gaztelu-Urrutia', 95, '2019-11-08', 'T18', 'es', 'https://image.tmdb.org/t/p/w500/iXvQnzy6JCAx1PiQEKXuTY04ZHl.jpg', 'https://www.youtube.com/watch?v=RlfooqeZcdY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (825, 'Kizumonogatari Part 2: Nekketsu', 'Koyomi Araragi was turned into a vampire by the legendary vampire, Kiss-shot Acerola-orion Heart-under-blade, and he needs to revive the weakened vampire back to her complete form to return to being human again. The only way for Koyomi to achieve his goal is to fight the three vampire hunters – Dramaturgy, Episode and Guillotinecutter.', 'Akiyuki Shinbo, Tatsuya Oishi', 68, '2016-08-19', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/fv9AALP1dofQUvKAkxnkz105MOv.jpg', 'https://www.youtube.com/watch?v=nOiEjQy-J7U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (826, 'The Kissing Booth', 'When teenager Elle''s first kiss leads to a forbidden romance with the hottest boy in high school, she risks her relationship with her best friend.', 'Vince Marcello', 105, '2018-05-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vcQNnnXgKLacoYF4LNWgkNiDXPd.jpg', 'https://www.youtube.com/watch?v=7bfS6seiLhk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (827, 'Normal', 'An unassuming substitute sheriff with a troubled past responds to a bank robbery in a small, sleepy town and unknowingly uncovers something far more explosive.', 'Ben Wheatley', 91, '2026-04-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/t13MdGCKRZvkmrFW2A7Vih3QjwD.jpg', 'https://www.youtube.com/watch?v=5OndK0w1lYY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (828, 'Creed II', 'Between personal obligations and training for his next big fight against an opponent with ties to his family''s past, Adonis Creed is up against the challenge of his life.', 'Steven Caple Jr.', 130, '2018-11-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/v3QyboWRoA4O9RbcsqH8tJMe8EB.jpg', 'https://www.youtube.com/watch?v=cPNVNqn4T9I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (829, 'Solo Mio', 'After Matt''s dreams of a picturesque Italian wedding are shattered when his fiancée leaves him at the altar, he embarks on his planned honeymoon across Italy alone, immersing himself in the country''s vibrant culture, food, and beauty, meeting Gia along the way.', 'Charles Kinnane, Daniel Kinnane', 96, '2026-02-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/efSsZJaddeq0LOABZqpCXdMxv9P.jpg', 'https://www.youtube.com/watch?v=433MYSlERJo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (830, 'Sniper: The White Raven', 'Mykola is an eccentric pacifist who wants to be useful to humanity. When the war begins in Donbas, Mykola’s naive world is collapsing as the militants kill his pregnant wife and burn his home to the ground. Recovered, he makes a cardinal decision and gets enlisted in a sniper company. Having met his wife’s killers, he emotionally breaks down and arranges “sniper terror” for the enemy.', 'Marian Bushan', 120, '2022-05-03', 'T13', 'uk', 'https://image.tmdb.org/t/p/w500/lZOODJzwuQo0etJJyBBZJOSdZcW.jpg', 'https://www.youtube.com/watch?v=cZIhRHSXtyU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (831, 'Breakthrough', 'Tragedy strikes when a woman named Joyce''s son falls through the ice on a frozen lake and is trapped underwater for over 15 minutes. After being rushed to the hospital, the 14-year-old boy continues to fight for his life as Joyce, her husband and their pastor stay by his bedside and pray for a miracle.', 'Roxann Dawson', 116, '2019-04-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lUd2FNC8cMCcHyRMNZtVC48p3xH.jpg', 'https://www.youtube.com/watch?v=go1jaIRQc-o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (832, '35 - Chinna Katha Kaadu', 'A young mother faces challenges when her son fails to secure passing marks in mathematics, inciting events that test the family''s resilience and unity.', 'Nanda Kishore Emani', 145, '2024-09-06', 'K', 'te', 'https://image.tmdb.org/t/p/w500/8Wssy3WJYeF3QFu6E5c1iW74YjQ.jpg', 'https://www.youtube.com/watch?v=046kopv5sCQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (833, 'Eternals', 'The Eternals are a team of ancient aliens who have been living on Earth in secret for thousands of years. When an unexpected tragedy forces them out of the shadows, they are forced to reunite against mankind’s most ancient enemy, the Deviants.', 'Chloé Zhao', 156, '2021-11-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/lFByFSLV5WDJEv3KabbdAF959F2.jpg', 'https://www.youtube.com/watch?v=0WVDKZJkGlY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (834, 'The Tunnel to Summer, the Exit of Goodbyes', 'Urashima Tunnel – Once you enter that tunnel, you can get whatever you want, but at a price. Kaoru Tohno, who seems to have an elusive personality and traumatic past, and Anzu Hanashiro, who is struggling to reconcile her ideal image and true-to-heart attitude, team up to investigate the Urashima Tunnel and get what they want. This is an unforgettable summer story of nostalgia and sprinting in a remote countryside.', 'Tomohisa Taguchi', 83, '2022-09-09', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/5AGA6pbBKXZTI8k1c6odx30JuQR.jpg', 'https://www.youtube.com/watch?v=9biNIkmFhDw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (835, 'Miracles from Heaven', 'When Christy discovers her 10-year-old daughter Anna has a rare, incurable disease, she becomes a ferocious advocate for her daughter’s healing as she searches for a solution. After Anna has a freak accident and falls three stories, a miracle unfolds in the wake of her dramatic rescue that leaves medical specialists mystified, her family restored and their community inspired.', 'Patricia Riggen', 119, '2016-03-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hz9VF1TfaM0D04pYneSXUkNeOZv.jpg', 'https://www.youtube.com/watch?v=CldGTG6iVrU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (836, 'Collateral Beauty', 'Retreating from life after a tragedy, a man questions the universe by writing to Love, Time and Death. Receiving unexpected answers, he begins to see how these things interlock and how even loss can reveal moments of meaning and beauty.', 'David Frankel', 97, '2016-12-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4vfqosgik5pLb32RpskYifp8PWJ.jpg', 'https://www.youtube.com/watch?v=dpFyds_pS2E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (837, 'Silence', 'In the 17th century, two Portuguese Jesuit priests travel to Japan in an attempt to locate their mentor, who is rumored to have committed apostasy, and to propagate Catholicism.', 'Martin Scorsese', 161, '2016-12-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/x5T0cQDYws0xRBVG4Q3wpcrcmax.jpg', 'https://www.youtube.com/watch?v=IqrgxZLd_gE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (838, '777 Charlie', 'Dharma is stuck in a rut with his negative and lonely lifestyle and spends each day in the comfort of his loneliness. A pup named Charlie who is naughty and energetic which is a complete contrast with the Dharma’s character enters his life and gives him a new perspective towards it.', 'Kiranraj K.', 166, '2022-06-10', 'T13', 'kn', 'https://image.tmdb.org/t/p/w500/qArPmXH0aWsT3SEtYl8XrU2Oz48.jpg', 'https://www.youtube.com/watch?v=Z3r7f9zw-mo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (839, 'Kill Shot', 'Posing as hunters, a group of terrorists are in search of $100 million that was stolen and lost in a plane crash en route from Afghanistan.', 'Ari Novak', 93, '2023-08-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5kCEHZnUeAZFJvE3l8K5OYjIwjj.jpg', 'https://www.youtube.com/watch?v=KloxZEb6X9o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (840, 'Midway', 'The story of the Battle of Midway, and the leaders and soldiers who used their instincts, fortitude and bravery to overcome massive odds.', 'Roland Emmerich', 138, '2019-11-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hj8pyoNnynGeJTAbl7jcLZO8Uhx.jpg', 'https://www.youtube.com/watch?v=Z_7eN5iloyk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (841, 'The Runner', 'Maia Marten, a brilliant London lawyer, has her life shattered by a single call on her morning run: her son has been taken. To get him back, she must keep running, obey every ruthless command, and trust no one-each second a test of how far a mother will go to save her child.', 'Kevin Macdonald', 86, '2026-09-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/uxCaBoYXsDC4A0SqTm3SISj0OwK.jpg', 'https://www.youtube.com/watch?v=zz4rsZLcauY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (842, 'Crazy Rich Asians', 'An American-born Chinese economics professor accompanies her boyfriend to Singapore for his best friend''s wedding, only to get thrust into the lives of Asia''s rich and famous.', 'Jon M. Chu', 121, '2018-08-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/1XxL4LJ5WHdrcYcihEZUCgNCpAW.jpg', 'https://www.youtube.com/watch?v=ZQ-YX-5bAs0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (843, 'Dhurandhar: The Revenge', 'As rival gangs, corrupt officials and a ruthless Major Iqbal close in, Hamza''s mission for his country spirals into a bloody personal war where the line between patriot and monster disappears in the streets of Lyari.', 'Aditya Dhar', 235, '2026-03-18', 'T16', 'hi', 'https://image.tmdb.org/t/p/w500/ov8vrRLZGoXHpYjSY9Vpv1tHJX7.jpg', 'https://www.youtube.com/watch?v=NHk7scrb_9I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (844, 'Good Boy', 'Tommy, a volatile 19-year-old, revels in drugs, parties and violence. After getting separated from his friends on a drunken bender, he is abducted by a shadowy figure. He wakes to find himself imprisoned in the basement of a remote Yorkshire house, inhabited by a very strange family. But what unfolds is not what he could possibly expect.', 'Jan Komasa', 110, '2026-03-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/eWb841fMkSNly5gfL9J1N0xzVYI.jpg', 'https://www.youtube.com/watch?v=Qhe6GNgW8uI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (845, 'Fatherhood', 'A widowed new dad copes with doubts, fears, heartache and dirty diapers as he sets out to raise his daughter on his own. Inspired by a true story.', 'Paul Weitz', 109, '2021-06-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wvqO1gTAMZIFGi3Ioq1BN6KV95R.jpg', 'https://www.youtube.com/watch?v=T3mwUEoZdrI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (846, 'The Girl with the Needle', 'Struggling to survive in post-WWI Copenhagen, a newly unemployed and pregnant young woman is taken in by a charismatic elder to help run an underground adoption agency. The two form an unexpected bond, until a sudden discovery changes everything.', 'Magnus von Horn', 123, '2024-09-06', 'K', 'da', 'https://image.tmdb.org/t/p/w500/2xkyx8v9G3ePxe1IcFugFQkXHzQ.jpg', 'https://www.youtube.com/watch?v=NdjhUNH5v3Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (847, 'Roofman', 'A former Army Ranger and struggling father turns to robbing McDonald’s restaurants by cutting holes in their roofs, earning him the nickname "Roofman." After escaping prison, he secretly lives inside a Toys “R” Us for six months, surviving undetected while planning his next move. But when he falls for a divorced mom drawn to his undeniable charm, his double life begins to unravel, setting off a compelling and suspenseful game of cat and mouse as his past closes in.', 'Derek Cianfrance', 126, '2025-10-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wXDFtcnYtevleGzCmAD2ReQnJ4l.jpg', 'https://www.youtube.com/watch?v=GXecSGmQDEI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (848, 'Rocketry: The Nambi Effect', 'The story of the great Indian rocket scientist, Shri Nambi Narayanan''s life, a true patriot, who was turned into a villain in the blink of an eye after being falsely accused of treason.', 'R. Madhavan', 154, '2022-07-01', 'T13', 'ta', 'https://image.tmdb.org/t/p/w500/o7A1agEoXvwyyOmIbHnUhfnC34j.jpg', 'https://www.youtube.com/watch?v=E3s-w-G4R_w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (849, 'Where Hands Touch', 'Germany, 1944. Leyna, the 15-year old daughter of a white German mother and a black African father, meets Lutz, a compassionate member of the Hitler Youth whose father is a prominent Nazi soldier, and they form an unlikely connection in this quickly changing world.', 'Amma Asante', 122, '2018-09-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/omKzydOrom9kpdfQUE0G9Y9sPl0.jpg', 'https://www.youtube.com/watch?v=lJezTw0t4gk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (850, 'The Equalizer 2', 'Robert McCall, who serves an unflinching justice for the exploited and oppressed, embarks on a relentless, globe-trotting quest for vengeance when his former partner is murdered.', 'Antoine Fuqua', 121, '2018-07-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cQvc9N6JiMVKqol3wcYrGshsIdZ.jpg', 'https://www.youtube.com/watch?v=EiaVnU18pcs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
