  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (851, 'The Wolf''s Call', 'Shown from the perspective of a young submariner with unusually sensitive hearing and uncannily precise sound recognition. The fate of many often depends on his ability, and one time, whilst highly stressed, he makes a incorrect call which put his entire crew in mortal danger. Trying to regain the confidence of his comrades, he conducts an unauthorised investigation of an apparent plot which, it turns out, risks escalating into a nuclear apocalypse. Suddenly working under pressure with the fleet admiral, they must do whatever is necessary, even the unthinkable, to prevent a nuclear war, since a confirmed nuclear strike order cannot be countermanded.', 'Antonin Baudry', 116, '2019-02-20', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/8bxIzp9w9l9ZzGVwNaIKOaem05A.jpg', 'https://www.youtube.com/watch?v=a9Gz7Bg07u8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (852, 'American Made', 'The true story of pilot Barry Seal, who transported contraband for the CIA and the Medellin cartel in the 1980s.', 'Doug Liman', 115, '2017-08-18', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/23ILgoPSO5ShKcTZOuiTVfqFAUB.jpg', 'https://www.youtube.com/watch?v=AEBIJRAkujM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (853, 'Life and a Day', 'Somaieh, the youngest daughter of an indigent family, is getting married and fear is overwhelming each and every member of the family regarding how to overcome their difficulties after she''s gone.', 'Saeed Roustaee', 112, '2016-03-16', 'P', 'fa', 'https://image.tmdb.org/t/p/w500/oy0KMmuGr3pnobRZo5eZSvlmtg9.jpg', 'https://www.youtube.com/watch?v=VBIJhlPwrZI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (854, 'Late Night with the Devil', 'A live broadcast of a late-night talk show in 1977 goes horribly wrong, unleashing evil into the nation''s living rooms.', 'Cameron Cairnes, Colin Cairnes', 93, '2024-03-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mu8LRWT9GHkfiyHm7kgxT6YNvMW.jpg', 'https://www.youtube.com/watch?v=TiwvEtimLzQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (855, 'Seetha Kalyana Vaibhogame', 'Ram and Seetha marry secretly and flee to a new town. When Ram''s cancer-stricken father makes a final wish involving his daughter-in-law, Seetha must balance her love with family obligations.', 'Satish Paramvedha', 146, '2024-06-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sjKTpoElI6MWhEKykbpYfqC3tcM.jpg', 'https://www.youtube.com/watch?v=CzYhsNR91as', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (856, 'Kaguya-sama: Love Is War -The First Kiss That Never Ends-', 'After pining for one another and plotting for so long, Kaguya Shinomiya and Miyuki Shirogane finally have their climactic first kiss. However, they struggle to define their relationship. After all, how much of their true selves have they really shown to one another?', 'Mamoru Hatakeyama', 96, '2022-12-17', 'K', 'ja', 'https://image.tmdb.org/t/p/w500/jY092qLqa7qTMelwRiNPpLUolEz.jpg', 'https://www.youtube.com/watch?v=At-bu8dszQ8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (857, 'The King', 'England, 15th century. Hal, a capricious prince who lives among the populace far from court, is forced by circumstances to reluctantly accept the throne and become Henry V.', 'David Michôd', 140, '2019-10-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8u0QBGUbZcBW59VEAdmeFl9g98N.jpg', 'https://www.youtube.com/watch?v=svVykTznk9Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (858, 'Paul, Apostle of Christ', 'Luke risks his life to visit Paul in a Roman prison, where the apostle awaits execution under Nero. As Paul reflects on his past and the Christian community faces persecution, Luke resolves to record the story of the early church.', 'Andrew Hyatt', 108, '2018-03-22', 'K', 'en', 'https://image.tmdb.org/t/p/w500/2NUXG94dGMKYgJL1BkJGKynMb3l.jpg', 'https://www.youtube.com/watch?v=LyOqQZUDdO4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (859, 'Scream VI', 'Following the latest Ghostface killings, the four survivors leave Woodsboro behind and start a fresh chapter.', 'Matt Bettinelli-Olpin, Tyler Gillett', 123, '2023-03-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wDWwtvkRRlgTiUr6TyLSMX8FCuZ.jpg', 'https://www.youtube.com/watch?v=1Ie2qmAOc6Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (860, 'Quo Vadis, Aida?', 'Bosnia, July 1995. Aida is a translator for the UN in the small town of Srebrenica. When the Serbian army takes over the town, her family is among the thousands of citizens looking for shelter in the UN camp. As an insider to the negotiations Aida has access to crucial information that she needs to interpret. What is at the horizon for her family and people – rescue or death? Which move should she take?', 'Jasmila Žbanić', 104, '2021-02-26', 'T13', 'sr', 'https://image.tmdb.org/t/p/w500/eQy2Tgvmx0FkK8vMMqMW4aX5UXQ.jpg', 'https://www.youtube.com/watch?v=ErLD8P4VUjY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (861, 'Andragogy', 'A schoolteacher''s reputation is at risk when a video of her speaking up against injustice goes viral on the internet and is misinterpreted.', 'Wregas Bhanuteja', 110, '2023-11-02', 'P', 'id', 'https://image.tmdb.org/t/p/w500/9nRxHuA966OxNszQIskZPOSDZU8.jpg', 'https://www.youtube.com/watch?v=TLPEacYsEQs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (862, 'Out of My Mind', 'Melody Brooks, a sixth grader with cerebral palsy, has a quick wit and a sharp mind, but because she is non-verbal and uses a wheelchair, she is not given the same opportunities as her classmates. When a young educator notices her student''s untapped potential and Melody starts to participate in mainstream education, Melody shows that what she has to say is more important than how she says it.', 'Amber Sealey', 107, '2024-01-19', 'K', 'en', 'https://image.tmdb.org/t/p/w500/zo3DmHvUctMnIlwiJ4sz7JHH8I7.jpg', 'https://www.youtube.com/watch?v=AvVxyoQQzFs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (863, 'One Cut of the Dead', 'Real zombies arrive and terrorize the crew of a zombie film being shot in an abandoned warehouse, said to be the site of military experiments on humans.', 'Shinichiro Ueda', 96, '2017-11-04', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/rws34k2bqYVo2B5MkhKAbV8925j.jpg', 'https://www.youtube.com/watch?v=Du2XfUDfjN0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (864, 'The Zone of Interest', 'The commandant of Auschwitz, Rudolf Höss, and his wife Hedwig, strive to build a dream life for their family in a house and garden next to the camp.', 'Jonathan Glazer', 105, '2023-12-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hUu9zyZmDd8VZegKi1iK1Vk0RYS.jpg', 'https://www.youtube.com/watch?v=GFNtVaAuVYY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (865, 'Charm City Kings', 'Mouse desperately wants to join The Midnight Clique, the infamous Baltimore dirt bike riders who rule the summertime streets. When Midnight’s leader, Blax, takes 14-year-old Mouse under his wing, Mouse soon finds himself torn between the straight-and-narrow and a road filled with fast money and violence.', 'Ángel Manuel Soto', 125, '2020-01-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/j732HPX0HSPcYvKURAIIS5Ppvk1.jpg', 'https://www.youtube.com/watch?v=8Cvrs-BCs6o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (866, 'Mukhya Gamanika', 'A young constable stumbles into a deadly maze. The tragic murder of his father, coinciding with the disappearance of a husband, ignites a chase for the truth, forcing him to confront hidden dangers and protect what''s dear.', 'Venu Muralidhar Vadnala', 125, '2024-02-23', 'T16', 'te', 'https://image.tmdb.org/t/p/w500/gFozskWxgxksa70KTHZRyIeBnmU.jpg', 'https://www.youtube.com/watch?v=uOKjYtBBGYM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (867, 'The Edge of Seventeen', 'Two high school girls are best friends until one dates the other''s older brother, who is totally his sister''s nemesis.', 'Kelly Fremon Craig', 105, '2016-11-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/15FykQKiM0aYpC1MuybR43xl8eF.jpg', 'https://www.youtube.com/watch?v=aw9hlZ2uiII', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (868, 'Song Sung Blue', 'Based on a true story, two down-on-their-luck musicians form a joyous Neil Diamond tribute band, proving it''s never too late to find love and follow your dreams.', 'Craig Brewer', 133, '2025-12-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xStmzLprgzqjzfvpBI7uTbcRpwQ.jpg', 'https://www.youtube.com/watch?v=ZqU7iiHFCzw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (869, 'The Secret Life of Pets 2', 'Max the terrier must cope with some major life changes when his owner gets married and has a baby. When the family takes a trip to the countryside, nervous Max has numerous run-ins with canine-intolerant cows, hostile foxes and a scary turkey. Luckily for Max, he soon catches a break when he meets Rooster, a gruff farm dog who tries to cure the lovable pooch of his neuroses.', 'Chris Renaud', 86, '2019-05-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/s9xg4V5EDKiphgIksVJ9gewBM11.jpg', 'https://www.youtube.com/watch?v=U_8cQYEXEZE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (870, 'Warfare', 'A platoon of Navy SEALs embarks on a dangerous mission in Ramadi, Iraq, with the chaos and brotherhood of war retold through their memories of the event.', 'Alex Garland, Ray Mendoza', 95, '2025-04-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/l39TlELomwysfsr37vrvCV6rmaQ.jpg', 'https://www.youtube.com/watch?v=JER0Fkyy3tw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (871, 'M3GAN 2.0', 'After the underlying tech for M3GAN is stolen and misused by a powerful defense contractor to create a military-grade weapon known as Amelia, M3GAN''s creator Gemma realizes that the only option is to resurrect M3GAN and give her a few upgrades, making her faster, stronger, and more lethal.', 'Gerard Johnstone', 120, '2025-06-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oekamLQrwlJjRNmfaBE4llIvkir.jpg', 'https://www.youtube.com/watch?v=1FeiTZMtwLA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (872, 'BTS World Tour: Love Yourself in Seoul', 'Shot at the Olympic Stadium in Seoul during the BTS World Tour ‘Love Yourself’ to celebrate the seven members of the global boyband and their unprecedented international phenomenon.', 'Son Sung-deuk', 113, '2019-01-26', 'T13', 'ko', 'https://image.tmdb.org/t/p/w500/1u0rtWPgYfAWmqveXOsQDvMRODD.jpg', 'https://www.youtube.com/watch?v=GU83s-smn9g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (873, 'Patriots Day', 'In the aftermath of an unspeakable act of terror, Police Sergeant Tommy Saunders joins courageous survivors, first responders and investigators in a race against the clock to hunt down the Boston Marathon bombers before they strike again.', 'Peter Berg', 133, '2016-12-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mIDxsJTrOC7NhgOo3GziiHyKfsQ.jpg', 'https://www.youtube.com/watch?v=_c9IpI_pNGI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (874, 'After', 'Tessa Young is a dedicated student, dutiful daughter and loyal girlfriend to her high school sweetheart. Entering her first semester of college, Tessa''s guarded world opens up when she meets Hardin Scott, a mysterious and brooding rebel who makes her question all she thought she knew about herself -- and what she wants out of life.', 'Jenny Gage', 106, '2019-04-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/u3B2YKUjWABcxXZ6Nm9h10hLUbh.jpg', 'https://www.youtube.com/watch?v=2ZAdcWHuCmY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (875, 'The Gray Man', 'When a shadowy CIA agent uncovers damning agency secrets, he''s hunted across the globe by a sociopathic rogue operative who''s put a bounty on his head.', 'Anthony Russo, Joe Russo', 128, '2022-07-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8cXbitsS6dWQ5gfMTZdorpAAzEH.jpg', 'https://www.youtube.com/watch?v=BmllggGO4pM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (876, 'The Red Turtle', 'The dialogue-less film follows the major life stages of a castaway on a deserted tropical island populated by turtles, crabs and birds.', 'Michael Dudok de Wit', 81, '2016-03-27', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/wOBU3SLjQ9358Km9YWYasPZyebp.jpg', 'https://www.youtube.com/watch?v=4lwrzNqEUOM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (877, 'We Bare Bears: The Movie', 'When Grizz, Panda, and Ice Bear''s love of food trucks and viral videos get out of hand, the brothers are now chased away from their home and embark on a trip to Canada, where they can live in peace.', 'Daniel Chong', 69, '2020-06-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/khtIr0Gxtz52T10RRQZ42o1a5Ry.jpg', 'https://www.youtube.com/watch?v=0ZNsLy2IwcY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (878, 'Ghostland', 'A mother of two inherits a home from her aunt. On the first night in the new home she is confronted with murderous intruders and fights for her daughters’ lives. Sixteen years later the daughters reunite at the house, and that is when things get strange...', 'Pascal Laugier', 91, '2018-03-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ma9gY6OikBev8MsMaeA6h2EIdGo.jpg', 'https://www.youtube.com/watch?v=Q8KqeolPt2w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (879, 'Run', 'Chloe, a teenager who is confined to a wheelchair, is homeschooled by her mother, Diane. Chloe soon becomes suspicious of her mother and begins to suspect that she may be harboring a dark secret.', 'Aneesh Chaganty', 90, '2020-11-20', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/ilHG4EayOVoYeKqslspY3pR4wzC.jpg', 'https://www.youtube.com/watch?v=z_v0icKzgw0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (880, 'The Amateur', 'After his life is turned upside down when his wife is killed in a London terrorist attack, a brilliant but introverted CIA decoder takes matters into his own hands when his supervisors refuse to take action.', 'James Hawes', 123, '2025-04-09', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/SNEoUInCa5fAgwuEBMIMBGvkkh.jpg', 'https://www.youtube.com/watch?v=DCWcK4c-F8Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (881, 'Teen Wolf: The Movie', 'The wolves are howling once again, as a terrifying ancient evil emerges in Beacon Hills. Scott McCall, no longer a teenager yet still an Alpha, must gather new allies and reunite trusted friends to fight back against this powerful and deadly enemy.', 'Russell Mulcahy', 140, '2023-01-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wAkpPm3wcHRqZl8XjUI3Y2chYq2.jpg', 'https://www.youtube.com/watch?v=3NbHKvuvI5A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (882, 'Officer Black Belt', 'A talented martial artist who can''t walk past a person in need unites with a probation officer to fight and prevent crime as a martial arts officer.', 'Jason Kim', 108, '2024-09-12', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/pWOiCearczq7zmWo4ASbUIF6HYS.jpg', 'https://www.youtube.com/watch?v=WNkGz6aKFvk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (883, 'Dinner in America', 'An on-the-lam punk rocker and a young woman obsessed with a local band go on an unexpected and epic journey together through the decaying suburbs of the American Midwest.', 'Adam Rehmeier', 108, '2020-05-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/t63UhnHaWQGcuE3pViuW3LSjBJj.jpg', 'https://www.youtube.com/watch?v=QIf2SbZqtTE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (884, 'Bingo: The King of the Mornings', '1980s. Brazilian television exploding in color and auditorium programs not so politically correct. In the middle of this fervor, Augusto Mendes, a young rising actor, seeks his place in the sun. From porn studios to soap operas, he finally finds success and fame when he becomes "Bingo", a TV host clown from one of the audience leader TV shows for children. It turns out that behind the rice powder and red nose, nobody knows who he is.', 'Daniel Rezende', 113, '2017-08-24', 'T13', 'pt', 'https://image.tmdb.org/t/p/w500/izz36X4Hg7JCei5BOVeXTjVuQzF.jpg', 'https://www.youtube.com/watch?v=F2XG-bktBTM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (885, 'The Seed of the Sacred Fig', 'Investigating judge Iman grapples with paranoia amid political unrest in Tehran. When his gun vanishes, he suspects his wife and daughters, imposing draconian measures that strain family ties as societal rules crumble.', 'Mohammad Rasoulof', 167, '2024-09-18', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/ifOazNzv2cNJ5CQjMV7cPXG2Lmy.jpg', 'https://www.youtube.com/watch?v=A3P53zHCPJU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (886, 'Hope', 'In the remote South Korean village of Hope Harbor, police chief Bum-seok and officer Sung-ae are called to investigate a mysterious creature wreaking havoc on the community. But all is not as it seems, and perceptions can be misleading. What begins as ignorance plants the seed of disaster, escalating through human conflict into a tragedy of cosmic proportions.', 'Na Hong-jin', 157, '2026-07-15', 'T13', 'ko', 'https://image.tmdb.org/t/p/w500/1n37BJchWHLiSYQkuFxe5KjB951.jpg', 'https://www.youtube.com/watch?v=ODnHr2Emnf0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (887, 'The Long Walk', 'In a dystopian 1970s America, fifty teenage boys take part in a deadly annual walking contest, forced to maintain a minimum pace or be executed, until only one survivor remains.', 'Francis Lawrence', 108, '2025-09-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wobVTa99eW0ht6c1rNNzLkazPtR.jpg', 'https://www.youtube.com/watch?v=Toj3Zxun7aQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (888, 'The Legend of Maula Jatt', 'Maula Jatt, a fierce prizefighter with a tortured past seeks vengeance against his arch nemesis Noori Natt, the most feared warrior in the land of Punjab.', 'Bilal Lashari', 153, '2022-10-13', 'T16', 'pa', 'https://image.tmdb.org/t/p/w500/njmYtTRQ9hY35T9mmwrP7NnsNS6.jpg', 'https://www.youtube.com/watch?v=pEWqOAcYgpQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (889, 'M3GAN', 'A brilliant toy company roboticist uses artificial intelligence to develop M3GAN, a life-like doll programmed to emotionally bond with her newly orphaned niece. But when the doll''s programming works too well, she becomes overprotective of her new friend with terrifying results.', 'Gerard Johnstone', 102, '2022-12-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/d9nBoowhjiiYc4FBNtQkPY7c11H.jpg', 'https://www.youtube.com/watch?v=BRb4U99OU80', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (890, 'Uncle Tom II: An American Odyssey', 'Uncle Tom II is an odyssey depicting the gradual demoralization of America through Marxist infiltration of its institutions. The film explores how this deceptive ideology has torn apart the fabric of society while using black America as its number one tool for its destruction. From Executive Producer Larry Elder and Director Justin Malone, comes the continuation of their highly acclaimed film, Uncle Tom (2020). Uncle Tom II will take the audience deeper into black America’s often eradicated history of honorable men, entrepreneurship, prosperity, faith, and patriotism, to its current perceived state of anger, discontent and victimhood.', 'Justin Malone', 117, '2022-08-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/2kYdag5o8zhyFmnc68TNSEZv5Yf.jpg', 'https://www.youtube.com/watch?v=0qXdim5EeBw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (891, 'Simón', 'Simón, a Venezuelan freedom fighter exiled in Miami, copes not only with trauma, but also deep guilt over a choice he must make: stay in Miami and start a new life, or return home to the losing fight against a tyrannical regime.', 'Diego Vincentini', 99, '2023-04-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9ltmI5Mef0NHWm4Nxcpm6hT8VhY.jpg', 'https://www.youtube.com/watch?v=-6AFAeu33E4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (892, 'My Name Is Eftihia', 'A young girl, recently married, is traveling from Aidini to Greece with her mother and her two daughters. On board the ship she decides not to let life pass her by, but to live her own way. And she goes ahead! She writes endlessly wherever she can, on napkins and cigarette boxes, to bills. She smokes, she passionately falls in love, casually gambles in luxurious salons, but also in illegal basements. A teacher who becomes an actress and plays in streets and in theaters, a poet who becomes the greatest Greek folk songwriter. She collaborates with all the famous music personalities of the country, from Vassilis Tsitsanis and Apostolos Kaldaras to Manolis Ηiotis, Antonis Repanis and Manos Hadjidakis, bravely asserting herself to a cruel and typically male-dominated world.', 'Angelos Frantzis', 123, '2019-12-19', 'T13', 'el', 'https://image.tmdb.org/t/p/w500/oXK69ImFmvBUpop1UVn7KCuHW2a.jpg', 'https://www.youtube.com/watch?v=986_9-ki12w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (893, 'Damsel', 'A young woman''s marriage to a charming prince turns into a fierce fight for survival when she''s offered up as a sacrifice to a fire-breathing dragon.', 'Juan Carlos Fresnadillo', 107, '2024-03-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/AgHbB9DCE9aE57zkHjSmseszh6e.jpg', 'https://www.youtube.com/watch?v=iM150ZWovZM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (894, 'The Hand of God', 'In 1980s Naples, an awkward teen struggling to find his place experiences heartbreak and liberation after he''s inadvertently saved from a freak accident by football legend Diego Maradona.', 'Paolo Sorrentino', 130, '2021-11-24', 'K', 'it', 'https://image.tmdb.org/t/p/w500/kreVxr5moB7K52IGGV1BGAn6nq1.jpg', 'https://www.youtube.com/watch?v=i_1VW_0i6vo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (895, 'Last Christmas', 'Kate is a young woman who has a habit of making bad decisions, and her last date with disaster occurs after she accepts work as Santa''s elf for a department store. However, after she meets Tom there, her life takes a new turn.', 'Paul Feig', 103, '2019-11-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kDEjffiKgjuGo2DRzsqfjvW0CQh.jpg', 'https://www.youtube.com/watch?v=z9CEIcmWmtA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (896, 'Nope', 'Residents in a lonely gulch of inland California bear witness to an uncanny, chilling discovery.', 'Jordan Peele', 130, '2022-07-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/AcKVlWaNVVVFQwro3nLXqPljcYA.jpg', 'https://www.youtube.com/watch?v=HUgmq_8PlRY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (897, 'Sicario: Day of the Soldado', 'Agent Matt Graver teams up with operative Alejandro Gillick to prevent Mexican drug cartels from smuggling terrorists across the United States border.', 'Stefano Sollima', 122, '2018-06-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qcLYofEhNh51Sk1jUWjmKHLzkqw.jpg', 'https://www.youtube.com/watch?v=Pymm6cmE9uQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (898, 'Saga of Tanya the Evil: The Movie', 'The time is UC 1926. The Imperial Army''s 203rd Air Mage Battalion led by Major Tanya Degurechaff has won the battle to the south against the Republic''s stragglers. They expected to be given a vacation after returning victorious, but instead receive special orders from Staff HQ as soon as they get home. They are told that there were signs of a large-scale deployment near the Empire-Federation border. Faced with the prospect of a new major enemy, the desperate Empire fans the flame of war. Meanwhile, an international volunteer army spearheaded by the Commonwealth set foot in Federation territory. As they say, the enemy of an enemy is your friend. They suffer through misfortune purely out of national interest, and among them is a young girl. She is Warrant Officer Mary Sue, and she takes up arms hoping to bring the Empire, who killed her father, to justice.', 'Yutaka Uemura', 98, '2019-02-08', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/omEd5EwOo3LJlGtiiYwEZeCqM3E.jpg', 'https://www.youtube.com/watch?v=jTWkeiIMncI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (899, 'One Piece: Stampede', 'The world''s boldest buccaneers set sail for the great Pirate Festival, where the Straw Hats join a mad-dash race to find Gol D. Roger''s treasure. There''s just one little problem: An old member of Roger''s crew has a sinister score to settle.', 'Takashi Otsuka', 101, '2019-01-03', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/4E2lyUGLEr3yH4q6kJxPkQUhX7n.jpg', 'https://www.youtube.com/watch?v=4M6e4YsAKPA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (900, 'Elize: Shadows of a Woman', 'In this retelling of a real case, a former escort discovers her wealthy husband''s infidelity and struggles to cope as betrayal poisons their marriage.', 'Vellas', 93, '2026-07-22', 'T18', 'pt', 'https://image.tmdb.org/t/p/w500/l3wevYWTpiZSUEM5B0Q8c21ALAD.jpg', 'https://www.youtube.com/watch?v=KiKnd3cusPo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (901, 'No Game No Life: Zero', 'Six thousand years before Sora and Shiro were even a blink in the history of Disboard, war consumed the land, tearing apart the heavens, destroying stars, and even threatening to wipe out the human race. Amid the chaos and destruction, a young man named Riku leads humanity toward the tomorrow his heart believes in. One day, in the ruins of an Elf city, he meets Schwi, a female exiled "Ex Machina" android who asks him to teach her what it means to have a human heart.', 'Atsuko Ishizuka', 106, '2017-07-15', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/cCBB6BGRj5nCTaEgogDtkHfjOLK.jpg', 'https://www.youtube.com/watch?v=0-KGvuSmdr0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (902, 'Eddie the Eagle', 'The feel-good story of Michael ''Eddie'' Edwards, an unlikely but courageous British ski-jumper who never stopped believing in himself—even as an entire nation was counting him out. With the help of a rebellious and charismatic coach, Eddie takes on the establishment and wins the hearts of sports fans around the world by making an improbable and historic showing at the 1988 Calgary Winter Olympics.', 'Dexter Fletcher', 106, '2016-02-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/r562gvTRVHnDSvG7MrKHEECSn1V.jpg', 'https://www.youtube.com/watch?v=hyzQjVUmIxk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (903, 'Corpus Christi', 'A pious 20-year-old juvenile delinquent is sent to work at a sawmill in a small town; on arrival, he dresses up as a priest and accidentally takes over the local parish. The arrival of this young, charismatic preacher is an opportunity for the local community to begin the healing process after a tragedy that happened a year prior.', 'Jan Komasa', 116, '2019-09-10', 'P', 'pl', 'https://image.tmdb.org/t/p/w500/6VZlm8sEwxkE3L5nXxz17QLj1sF.jpg', 'https://www.youtube.com/watch?v=0dnOJnJVjyk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (904, 'Pirates of the Caribbean: Dead Men Tell No Tales', 'Thrust into an all-new adventure, a down-on-his-luck Capt. Jack Sparrow feels the winds of ill-fortune blowing even more strongly when deadly ghost sailors led by his old nemesis, the evil Capt. Salazar, escape from the Devil''s Triangle. Jack''s only hope of survival lies in seeking out the legendary Trident of Poseidon, but to find it, he must forge an uneasy alliance with a brilliant and beautiful astronomer and a headstrong young man in the British navy.', 'Espen Sandberg, Joachim Rønning', 129, '2017-05-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6lAPOAFYFWIO3SQRemEY2wInQMC.jpg', 'https://www.youtube.com/watch?v=jnVk2C2YrSA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (905, 'Bacurau', 'Bacurau, a small town in the Brazilian sertão, mourns the loss of its matriarch, Carmelita, who lived to be 94. Days later, its inhabitants notice that their community has vanished from most maps.', 'Juliano Dornelles, Kleber Mendonça Filho', 131, '2019-08-29', 'T16', 'pt', 'https://image.tmdb.org/t/p/w500/tBa4zMGzZUco26XT3WfZZCwQ76i.jpg', 'https://www.youtube.com/watch?v=LKTejyk9ZIA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (906, 'Through My Window', 'Raquel''s longtime crush on her next-door neighbor turns into something more when he starts developing feelings for her, despite his family''s objections.', 'Marçal Forés', 112, '2022-02-04', 'K', 'es', 'https://image.tmdb.org/t/p/w500/jmkpZvMVIRrMFevxzOubSBfG0s0.jpg', 'https://www.youtube.com/watch?v=_zxhK3Z-R0c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (907, 'Manas', 'Thirteen-year-old Marcielle lives on Marajó Island in the heart of the Amazon rainforest. To break a terrible cycle that imprisons the women around her in an isolated region, she must do the impossible to liberate herself and her younger sister from a dark abyss of silence held by her own family.', 'Marianna Brennand', 101, '2025-03-26', 'P', 'pt', 'https://image.tmdb.org/t/p/w500/u5k3lHTwKPbrJ5xJX6MbALL0Hta.jpg', 'https://www.youtube.com/watch?v=4ly9FXf1w4c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (908, 'About Dry Grasses', 'A young art teacher hopes to be transferred to Istanbul after completing his mandatory duty in a remote village school in Anatolia. After accusations of inappropriate contact with a student surface, his hopes of escape fade and he descends further into an existential crisis.', 'Nuri Bilge Ceylan', 197, '2023-07-12', 'T13', 'tr', 'https://image.tmdb.org/t/p/w500/mUFpdQSFAch1fMUb9MqHoESpmLS.jpg', 'https://www.youtube.com/watch?v=WI1QH2R6c6Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (909, 'Venom: The Last Dance', 'Eddie and Venom are on the run. Hunted by both of their worlds and with the net closing in, the duo are forced into a devastating decision that will bring the curtains down on Venom and Eddie''s last dance.', 'Kelly Marcel', 109, '2024-10-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vGXptEdgZIhPg3cGlc7e8sNPC2e.jpg', 'https://www.youtube.com/watch?v=FKBN1qAzW3s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (910, 'All Your Faces', 'Since 2014, France''s restorative justice programmes have offered a safe space for supervised dialogue between offenders and victims. Grégoire, Nawelle, and Sabine, victims of heists and violent robberies, agree to join one of these discussion groups alongside offenders Nassim, Issa, and Thomas, all convicted of violent robberies. Meanwhile Chloé, a victim of childhood sexual abuse, prepares for dialogue with her own agressor after learning he has moved back into town.', 'Jeanne Herry', 115, '2023-03-29', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/ptJWIUOm3aA15rjz5SJJwS6WJU4.jpg', 'https://www.youtube.com/watch?v=h3XKroA-sTw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (911, 'Triangle of Sadness', 'A celebrity model couple are invited on a luxury cruise for the uber-rich, helmed by an unhinged, alcoholic captain. What first appears Instagrammable ends catastrophically, leaving the survivors stranded on a desert island in a struggle of hierarchy.', 'Ruben Östlund', 147, '2022-09-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/k9eLozCgCed5FGTSdHu0bBElAV8.jpg', 'https://www.youtube.com/watch?v=VDvfFIZQIuQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (912, 'The Quiet Girl', 'A quiet, neglected girl is sent away from her dysfunctional family to live with relatives for the summer. She blossoms in their care, but in this house where there are meant to be no secrets, she discovers one.', 'Colm Bairéad', 95, '2022-05-12', 'T13', 'ga', 'https://image.tmdb.org/t/p/w500/6Njyz53N417cgxE0d7cBEWHUEjc.jpg', 'https://www.youtube.com/watch?v=6Xjy5dtlRik', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (913, 'Bird Box', 'Five years after an ominous unseen presence drives most of society to suicide, a survivor and her two children make a desperate bid to reach safety.', 'Susanne Bier', 124, '2018-12-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rGfGfgL2pEPCfhIvqHXieXFn7gp.jpg', 'https://www.youtube.com/watch?v=INJ2bPFy108', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (914, 'The Secret Agent', 'Brazil, 1977. Marcelo, a technology expert in his early 40s, is on the run. Hoping to reunite with his son, he travels to Recife during Carnival but soon realizes that the city is not the safe haven he was expecting.', 'Kleber Mendonça Filho', 161, '2025-07-23', 'T16', 'pt', 'https://image.tmdb.org/t/p/w500/rZqolYhxMEe6TZZTjSmFw9crDTD.jpg', 'https://www.youtube.com/watch?v=9UfrzDKrhEc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (915, 'It Ends with Us', 'When a woman''s first love suddenly reenters her life, her relationship with a charming, but abusive neurosurgeon is upended, and she realizes she must learn to rely on her own strength to make an impossible choice for her future.', 'Justin Baldoni', 131, '2024-08-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/AjV6jFJ2YFIluYo4GQf13AA1tqu.jpg', 'https://www.youtube.com/watch?v=DLET_u31M4M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (916, 'No manches, Frida', 'After being released from prison, Zequi, a bank robber, sets out to recover money buried by his accomplice; but is horrified to learn that a high school gymnasium is now over the site where the loot is hidden.', 'Nacho G. Velilla', 100, '2016-09-02', 'T13', 'es', 'https://image.tmdb.org/t/p/w500/6HfyXfIEywLa2HvcswKi44dDKxL.jpg', 'https://www.youtube.com/watch?v=eeDYKlRV9Qs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (917, 'DC League of Super-Pets', 'When Superman and the rest of the Justice League are kidnapped, Krypto the Super-Dog must convince a rag-tag shelter pack - Ace the hound, PB the potbellied pig, Merton the turtle and Chip the squirrel - to master their own newfound powers and help him rescue the superheroes.', 'Jared Stern', 105, '2022-07-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qpPMewlugFaejXjz4YNDnpTniFX.jpg', 'https://www.youtube.com/watch?v=1jkw2JPCl18', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (918, 'Fear Street: 1978', 'In 1978, two rival groups at Camp Nightwing must band together to solve a terrifying mystery when horrors from their towns'' history come alive.', 'Leigh Janiak', 111, '2021-07-08', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/5dNTxhoGDTHHGqUTdxcr4H1dqlU.jpg', 'https://www.youtube.com/watch?v=UyUuzCGblqc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (919, 'Hunting Season', 'When a reclusive survivalist and his daughter rescue a mysterious, wounded woman from a river, they become entangled in a deadly web of violence and revenge, forcing them to confront a brutal criminal to survive.', 'Raja Collins', 100, '2025-12-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cbryTyaWdqrKpQCw6K7zm2jrB5v.jpg', 'https://www.youtube.com/watch?v=O7vKuVadFmo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (920, 'A Dog Named Palma', 'The film is inspired by an incredible story of a shepherd dog named Palm who was inadvertently left in the airport by her owner. She befriends nine-year old Nicholas whose mother dies leaving him with a father he barely knows - a pilot who finds the dog at the airport. It''s a story of amazing adventures, true friendship and unconditional love.', 'Aleksandr Domogarov Jr.', 110, '2021-03-18', 'K', 'ru', 'https://image.tmdb.org/t/p/w500/rxc6ducVrgUWLat8WwUVLvr2GRR.jpg', 'https://www.youtube.com/watch?v=9yhhTYK2Rm4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (921, 'Nobody 2', 'Former assassin Hutch Mansell takes his family on a nostalgic vacation to a small-town theme park, only to be pulled back into violence when they clash with a corrupt operator, a crooked sheriff, and a ruthless crime boss.', 'Timo Tjahjanto', 89, '2025-08-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/svXVRoRSu6zzFtCzkRsjZS7Lqpd.jpg', 'https://www.youtube.com/watch?v=-5X2pt95cIo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (922, 'Hans Zimmer & Friends: Diamond in the Desert', 'An extraordinary live performance of Hans Zimmer''s most beloved and renowned movie soundtracks, including music from Dune, Gladiator, Interstellar, and The Lion King. Featuring conversations with creative collaborators Billie Eilish, Christopher Nolan, Denis Villeneuve, Finneas, Jerry Bruckheimer, Pharrell Williams, Timothée Chalamet, Zendaya, and more.', 'Paul Dugdale', 158, '2025-02-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/aAbU0BuIQa6CUPOqsvUoPK39apD.jpg', 'https://www.youtube.com/watch?v=ZMO2zV14NCI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (923, 'The Book of Henry', 'Susan, a single mother of two, works as a waitress in a small town. Her son, Henry, is an 11-year-old genius who not only manages the family finances but acts as emotional support for his mother and younger brother. When Henry discovers that the girl next door has a terrible secret, he implores Susan to take matters into her own hands.', 'Colin Trevorrow', 105, '2017-06-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/suLFg4UjvM5BoDipg2Wu3gZ802T.jpg', 'https://www.youtube.com/watch?v=Nd60i3ZnLOE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (924, 'Avicii: True Stories', 'Documentary about the arena-packing Swedish DJ, chronicling his explosive rise to fame and surprising decision to retire from live performances in 2016.', 'Levan Tsikurishvili', 97, '2017-10-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/obVlatSLP94kmml5UaCjLsdWPWG.jpg', 'https://www.youtube.com/watch?v=1ZFK3VKzQIs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (925, 'The Guernsey Literary & Potato Peel Pie Society', 'Free-spirited writer Juliet Ashton forms a life-changing bond with the delightful and eccentric Guernsey Literary and Potato Peel Pie Society, when she decides to write about the book club they formed during the occupation of Guernsey in WWII.', 'Mike Newell', 124, '2018-04-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/55oz5d6NdH7ohbM1I1Euh1Tt6PN.jpg', 'https://www.youtube.com/watch?v=HTDNGv61-Dk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (926, 'Cold War', 'A man and a woman meet in the ruins of post-war Poland. With vastly different backgrounds and temperaments, they are fatally mismatched and yet drawn to each other.', 'Paweł Pawlikowski', 88, '2018-06-08', 'P', 'pl', 'https://image.tmdb.org/t/p/w500/6rbS8oPIgUMhQgIX8oGVTtlNgLR.jpg', 'https://www.youtube.com/watch?v=8ImvkXgGVWw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (927, 'Jerry & Marge Go Large', 'The remarkable true story of how retiree Jerry Selbee discovers a mathematical loophole in the Massachusetts lottery and, with the help of his wife, Marge, wins $27 million dollars and uses the money to revive their small Michigan town.', 'David Frankel', 96, '2022-10-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/bbBGSm1kjgmZ0O3bPUQIbA0xlKQ.jpg', 'https://www.youtube.com/watch?v=ibI0mLL0zhc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (928, 'Guru Nanak Jahaz', 'The film is based on a true incident of 20th century popularly known as Komagata Maru incident. The film unveils a poignant chapter in history when a group of Indian Sikh immigrants aboard a Japanese steamship named Komagata Maru arrived in Vancouver carrying 376 passengers from India. Canada, enforcing discriminatory immigration laws, denied entry to most passengers who were of Indian descent. After two months of legal battles and protests, the ship was forced to return to India. The incident highlights racial prejudices and immigration policies of the time, symbolising a struggle for Equality and Justice.', 'Sharan Art', 140, '2025-05-01', 'T13', 'pa', 'https://image.tmdb.org/t/p/w500/aB3Rvx7S25HBog1TZuuGoqBYXoJ.jpg', 'https://www.youtube.com/watch?v=4xPks078zY8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (929, 'Remi, Nobody''s Boy', 'At the age of 10 years, young Rémi is snatched from his adoptive mother and entrusted to the signor Vitalis, a mysterious itinerant musician. Has its hard sides - he will learn the harsh life of acrobat and sing to win his bread. Accompanied by the faithful dog capi and of the small monkey Joli-Coeur, his long trip through France, made for meetings, friendships and mutual assistance, leads him to the secret of its origins.', 'Antoine Blossier', 109, '2018-12-12', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/mQYXlxlUTmOP4FWt52qkZZb8JNM.jpg', 'https://www.youtube.com/watch?v=rhe-8LSwXqI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (930, 'Love in the Big City', 'When a carefree woman learns that her closeted friend is gay, the two form an inseparable bond and find comfort in each other''s company.', 'E.oni', 118, '2024-10-01', 'K', 'ko', 'https://image.tmdb.org/t/p/w500/oBsnMMFoELfqQ445Uvr2oWxm6mT.jpg', 'https://www.youtube.com/watch?v=mqYjCJwmnfI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (931, 'Versatile', 'Tanveer, an aspiring actor, moves to the city after leaving a detention center. He meets Disha, his therapist, for mandatory counseling but hides dark secrets, posing a threat.', 'HarShiv Karthik', 90, '2024-04-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ilAhfkCnpYR5deJAlalOemWp7Gi.jpg', 'https://www.youtube.com/watch?v=BjoGMGD4ytI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (932, 'The Fate of the Furious', 'When a mysterious woman seduces Dom into the world of crime and a betrayal of those closest to him, the crew face trials that will test them as never before.', 'F. Gary Gray', 136, '2017-04-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/dImWM7GJqryWJO9LHa3XQ8DD5NH.jpg', 'https://www.youtube.com/watch?v=-9FU7Ia-BKg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (933, 'I Am Paul Walker', 'Exploring the life and legacy of actor Paul Walker, the Southern California native who cut his teeth as child actor before breaking out in the blockbuster Fast and Furious franchise.', 'Adrian Buitenhuis', 93, '2018-12-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nTBWHgO4GPpxxDv9vgz9C1Ib2ym.jpg', 'https://www.youtube.com/watch?v=0eL_cLqaMX0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (934, 'Boiling Point', 'A head chef balances multiple personal and professional crises at a popular restaurant in London.', 'Philip Barantini', 92, '2021-07-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kdkk7OBnIL1peW2zwcAAp6O54Jo.jpg', 'https://www.youtube.com/watch?v=ItAqal69VZE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (935, 'Red Shoes and the Seven Dwarfs', 'Princes who have been turned into Dwarfs seek the red shoes of a lady in order to break the spell, although it will not be easy.', 'Hong Sung-ho', 92, '2019-07-25', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/MBiKqTsouYqAACLYNDadsjhhC0.jpg', 'https://www.youtube.com/watch?v=NB3mZMyxcM0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (936, 'I Am: Celine Dion', 'A raw and honest behind-the-scenes look at the iconic superstar''s struggle with a life-altering illness. Serving as a love letter to her fans, this inspirational documentary highlights the music that has guided her life while also showcasing the resilience of the human spirit.', 'Irene Taylor', 103, '2024-06-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/v0zvMBdwzgSAj9xCufxDuq1WoJO.jpg', 'https://www.youtube.com/watch?v=KzV4mSZPke0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (937, 'The Hitman''s Bodyguard', 'The world’s top bodyguard gets a new client, a hitman who must testify at the International Court of Justice. They must put their differences aside and work together to make it to the trial on time.', 'Patrick Hughes', 118, '2017-08-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5CGjlz2vyBhW5xHW4eNOZIdgzYq.jpg', 'https://www.youtube.com/watch?v=IpKmt4MpctM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (938, 'Racionais MC''s: From the Streets of São Paulo', 'Armed with music and a message, influential hip-hop group Racionais MC''s turned their street poetry into a powerful movement in Brazil and beyond.', 'Juliana Vicente', 116, '2022-10-20', 'P', 'pt', 'https://image.tmdb.org/t/p/w500/wuAti3pkylfx0EyhfRUPpxK6Xkm.jpg', 'https://www.youtube.com/watch?v=DqSdAgyF41k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (939, 'The Great Grand Superhero: Aliens Ka Aagman', 'Follows a grandfather and grandson whose relationship transforms through the child''s imagination when they encounter aliens.', 'Manish Saini', 112, '2026-05-28', 'P', 'hi', 'https://image.tmdb.org/t/p/w500/6CYmHknTN2UGGhqQUZh4tqQ6fEr.jpg', 'https://www.youtube.com/watch?v=ZHz0pOzPEi0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (940, 'The Post', 'A cover-up that spanned four U.S. Presidents pushed the country''s first female newspaper publisher and a hard-driving editor to join an unprecedented battle between journalist and government. Inspired by true events.', 'Steven Spielberg', 116, '2017-12-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/h4XG3g6uMMPIBPjAoQhC2QIMdkl.jpg', 'https://www.youtube.com/watch?v=nrXlY6gzTTM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (941, 'The Foreigner', 'Quan is a humble London businessman whose long-buried past erupts in a revenge-fueled vendetta when the only person left for him to love – his teenage daughter – dies in an Irish Republican Army car bombing. His relentless search to find the terrorists leads to a cat-and-mouse conflict with a British government official whose own past may hold the clues to the identities of the elusive killers.', 'Martin Campbell', 114, '2017-09-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rwM4hzrmc5HiWfQD9ls9DL4QgGl.jpg', 'https://www.youtube.com/watch?v=r_rSAbYyIq0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (942, 'The Unbreakable Boy', 'When Scott and Teresa LeRette learn that their son Austin is both autistic and has brittle bone disease, they initially worry for their son’s future. But with Scott’s growing faith and Austin’s incredible spirit, they become ''unbreakable'', finding joy, gratitude, and courage even in the most trying times.', 'Jon Gunn', 108, '2025-02-20', 'K', 'en', 'https://image.tmdb.org/t/p/w500/ob1cuQzzggELGtWx5TchixKsBVn.jpg', 'https://www.youtube.com/watch?v=pGbLX3__m60', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (943, 'The Hating Game', 'Resolving to achieve professional success without compromising her ethics, Lucy embarks on a ruthless game of one-upmanship against cold and efficient nemesis Joshua, a rivalry that is complicated by her growing attraction to him.', 'Peter Hutchings', 102, '2021-12-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/prbZxJxGcy07y60eq8lCGMciTYz.jpg', 'https://www.youtube.com/watch?v=a9toRWhKaqk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (944, 'Eternity', 'In an afterlife where souls have one week to decide where to spend eternity, Joan is faced with the impossible choice between the man she spent her life with and her first love, who died young and has waited decades for her to arrive.', 'David Freyne', 114, '2025-11-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/yiwGcjfDKXD5PqQnyKUU9kspWQQ.jpg', 'https://www.youtube.com/watch?v=GzkoY6hUvQQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (945, 'Soulmate', 'When Mi-so and Ha-eun first meet in childhood, their lives become instantly intertwined, forming a bond surrounded by happiness and naivety. But as adulthood arrives, alone and together, they are forced to deal with sadness, anger, grief, growth, and most of all, love.', 'Min Yong-keun', 124, '2023-03-15', 'P', 'ko', 'https://image.tmdb.org/t/p/w500/iL0jvWpSVW1uFn9aAoUh3UwzdYA.jpg', 'https://www.youtube.com/watch?v=39lFxCkXDYI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (946, 'Revolution of Our Times', 'Throughout Hong Kong’s history, Hongkongers have fought for freedom and democracy but have yet to succeed. In 2019, a controversial extradition bill was introduced that would allow Hongkongers to be tried in mainland China. This decision spurred massive protests, riots, and resistance against heavy-handed Chinese rule over the City-State. Award-winning director Kiwi Chow documents the events to tell the story of the movement, with both a macro view of its historical context and footage and interviews from protestors on the front lines.', 'Kiwi Chow Kwun-Wai', 152, '2021-11-22', 'P', 'cn', 'https://image.tmdb.org/t/p/w500/aalqZbr1yAAoDU9996Qyaw4U63k.jpg', 'https://www.youtube.com/watch?v=WbBU1AZS8HA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (947, 'Godhi Banna Sadharana Mykattu', 'Venkob Rao, a widower suffering from Alzheimer''s disease, is moved to an old-age home by his son. When he goes missing one day, he crosses swords with criminals.', 'Hemanth M. Rao', 143, '2016-06-03', 'P', 'kn', 'https://image.tmdb.org/t/p/w500/4dImTMse7PPFGHPG6GQuwDng9fB.jpg', 'https://www.youtube.com/watch?v=aPk9fBdtugg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (948, 'Caramelo', 'After a life-changing diagnosis, a promising chef finds hope and humor with the help of a fur-midable dog friend.', 'Diego Freitas', 100, '2025-10-07', 'T13', 'pt', 'https://image.tmdb.org/t/p/w500/c4ZEAah5a01cu27w7vT2IAoFogk.jpg', 'https://www.youtube.com/watch?v=epiLkoJ4dAk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (949, 'Venom: Let There Be Carnage', 'After finding a host body in investigative reporter Eddie Brock, the alien symbiote must face a new enemy, Carnage, the alter ego of serial killer Cletus Kasady.', 'Andy Serkis', 97, '2021-09-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pzKsRuKLFmYrW5Q0q8E8G78Tcgo.jpg', 'https://www.youtube.com/watch?v=-FmWuCgJmxo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (950, 'Entergalactic', 'Ambitious artist Jabari attempts to balance success and love when he moves into his dream Manhattan apartment and falls for his next-door neighbor.', 'Fletcher Moules', 93, '2022-09-28', 'K', 'en', 'https://image.tmdb.org/t/p/w500/oMU3JpuKuasjAWIbUQgCaT6pco1.jpg', 'https://www.youtube.com/watch?v=2C2lyCIusKo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
