  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (951, 'Ejen Ali: The Movie', 'As MATA seeks to upgrade its gadget for all agents, Ali embarks on a mission to stop a plot against Cyberaya but begins to question his loyalty.', 'Muhammad Usamah Zaid', 97, '2019-11-28', 'T16', 'ms', 'https://image.tmdb.org/t/p/w500/cYdGwCMR1DD3Vg61zrR3NsyrJal.jpg', 'https://www.youtube.com/watch?v=1WVgHZyRY7Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (952, 'Deepwater Horizon', 'A story set on the offshore drilling rig Deepwater Horizon, which exploded during April 2010 and created the worst oil spill in U.S. history.', 'Peter Berg', 107, '2016-09-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jgBIYCZACe3iaS9TL2XzVGkO5p5.jpg', 'https://www.youtube.com/watch?v=8yASbM8M2vg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (953, 'Jim Henson Idea Man', 'Featuring unprecedented access to Jim Henson''s personal archives, filmmaker Ron Howard brings us a fascinating and insightful look at a complex man whose boundless imagination inspired the world.', 'Ron Howard', 108, '2024-05-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/w1IYhFVW2XyKfkIyZ65jZ2Uyn6Y.jpg', 'https://www.youtube.com/watch?v=iyGFV6VIxkI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (954, 'What Happened to Monday', 'In a world where families are limited to one child due to overpopulation, a set of identical septuplets must avoid being put to a long sleep by the government and dangerous infighting while investigating the disappearance of one of their own.', 'Tommy Wirkola', 123, '2017-08-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/atOgZMJpMrTdpqvPiHVPfBhR61l.jpg', 'https://www.youtube.com/watch?v=idZPTuwcMJA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (955, 'Nobody', 'The Little Pig Yao decides to leave Langlang Mountain to join the pilgrimage. On the journey west, what trials will the little monsters face? In the end, will they achieve their dreams and live as they truly desire?', 'Yu Shui', 118, '2025-08-02', 'P', 'zh', 'https://image.tmdb.org/t/p/w500/mCa8Pb4L0X56gxV1sIQkLJ2RKz0.jpg', 'https://www.youtube.com/watch?v=XmpXSsyqPjI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (956, 'Persian Lessons', 'Occupied France, 1942. Gilles is arrested by SS soldiers alongside other Jews and sent to a camp in Germany. He narrowly avoids sudden execution by swearing to the guards that he is not Jewish, but Persian. This lie temporarily saves him, but Gilles gets assigned a life-or-death mission: to teach Farsi to Head of Camp Koch, who dreams of opening a restaurant in Iran once the war is over. Through an ingenious trick, Gilles manages to survive by inventing words of "Farsi" every day and teaching them to Koch.', 'Vadim Perelman', 127, '2020-04-17', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/ppReRGszmdZC2194keN4cGoLIPQ.jpg', 'https://www.youtube.com/watch?v=Q6zQuPLd9HQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (957, 'Riders of Justice', 'Markus returns home to care for his daughter when his wife dies in a tragic train accident. However, when a survivor of the wreck surfaces and claims foul play, Markus suspects his wife was murdered and embarks on a mission to find those responsible.', 'Anders Thomas Jensen', 116, '2020-11-19', 'T16', 'da', 'https://image.tmdb.org/t/p/w500/sshNnwmQLk720iBQ0dZg3GVGKfK.jpg', 'https://www.youtube.com/watch?v=ZQSQ-D5Q4gM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (958, 'Caddo Lake', 'When an 8-year-old girl mysteriously vanishes on Caddo Lake, a series of past deaths and disappearances begin to link together, forever altering a broken family’s history.', 'Celine Held, Logan George', 103, '2024-11-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/r1h1YltM7bwzlWE330izIgQSwkj.jpg', 'https://www.youtube.com/watch?v=Rrx_lZxzjbQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (959, 'Dog Man', 'When a faithful police dog and his human police officer owner are injured together on the job, a harebrained but life-saving surgery fuses the two of them together and Dog Man is born. Dog Man is sworn to protect and serve—and fetch, sit and roll over. As Dog Man embraces his new identity and strives to impress his Chief, he must stop the pretty evil plots of feline supervillain Petey the Cat.', 'Peter Hastings', 89, '2025-01-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/89wNiexZdvLQ41OQWIsQy4O6jAQ.jpg', 'https://www.youtube.com/watch?v=QaJbAennB_Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (960, 'Sarvam Maya', 'An atheist priest''s life is upended after performing an exorcism, bonding with a charming spirit who helps him pursue music and heal his past.', 'Akhil Sathyan', 147, '2025-12-25', 'K', 'ml', 'https://image.tmdb.org/t/p/w500/mgLY1aQayVX6dQ2DiylLAhjEG8w.jpg', 'https://www.youtube.com/watch?v=xXvE6_8lOoM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (961, 'Dead to Rights', 'During the 1937 Nanjing Massacre, a postman poses as a photo developer, helping Japanese forces while secretly sheltering Chinese refugees. He later risks his life evacuating them and revealing evidence of the atrocities.', 'Shen Ao', 137, '2025-07-19', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/rx9xTly73NssFHPg9gKrX9tJdDI.jpg', 'https://www.youtube.com/watch?v=_PX1WNbKdAE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (962, 'The Guilty', 'Police officer Asger Holm, demoted to desk work as an alarm dispatcher, answers a call from a panicked woman who claims to have been kidnapped. Confined to the police station and with the phone as his only tool, Asger races against time to get help and find her.', 'Gustav Möller', 85, '2018-02-22', 'T16', 'da', 'https://image.tmdb.org/t/p/w500/42QPG6p7oLcLd4LQOPeSTLhqfMx.jpg', 'https://www.youtube.com/watch?v=abaoKA6rn5k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (963, 'Mrs. Harris Goes to Paris', 'A 1950s London cleaning lady falls in love with an haute couture dress by Christian Dior and decides to gamble everything for the sake of this folly.', 'Anthony Fabian', 116, '2022-07-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eUg0HDLhTEDcXGBU2iK6QRBILv4.jpg', 'https://www.youtube.com/watch?v=iO9JcPbbmAA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (964, 'Constantine: City of Demons - The Movie', 'A decade after a tragic mistake, family man Chas Chandler and occult detective John Constantine set out to cure his daughter Trish from a mysterious supernatural coma.', 'Doug Murphy', 90, '2018-10-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tZIMe2pYug1cS9e7AZnd1bTTidM.jpg', 'https://www.youtube.com/watch?v=Tgujmtdj_3c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (965, 'Descendants: Wicked Wonderland', 'Now that the Queen of Hearts is nice and Cinderella is safe, things seem perfect for Red and Chloe… But little do they know that changing the past created a new villain — Maddox Hatter. When Maddox captures the Queen of Hearts, Red and Chloe must work alongside Red’s new sister Pink, Luisa Madrigal’s son Luis, and Maddox’s son Max to save her and Wonderland.', 'Kimmy Gatewood', 98, '2026-07-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xdhLAADGSse8KCrsDLBuM5b68Cg.jpg', 'https://www.youtube.com/watch?v=0Gg7x3xBqBU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (966, 'OVERLORD: The Sacred Kingdom', 'Facing possible annihilation by the Demon Emperor''s demi-human army, the Sacred Kingdom reluctantly seeks aid from the feared, undead Sorcerer King Ainz.', 'Naoyuki Ito', 134, '2024-09-20', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/jEvytxNa5mfW7VAUmDWsZtIdATc.jpg', 'https://www.youtube.com/watch?v=K9hf4dmYJwc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (967, '96', 'Ram is a photographer and nature lover who travels all around India capturing moments. On a chance visit to his hometown Tanjavur, he goes into his school and begins to walk down memory lane to 1994 when he was a student harboring feelings for his classmate Janu.', 'C. Prem Kumar', 159, '2018-10-04', 'P', 'ta', 'https://image.tmdb.org/t/p/w500/nrVloCa2hCFOztRF1DZU2jnWIiQ.jpg', 'https://www.youtube.com/watch?v=r0synl-lI4I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (968, 'Game Night', 'Max and Annie''s weekly game night gets kicked up a notch when Max''s brother Brooks arranges a murder mystery party -- complete with fake thugs and federal agents. So when Brooks gets kidnapped, it''s all supposed to be part of the game. As the competitors set out to solve the case, they start to learn that neither the game nor Brooks are what they seem to be. The friends soon find themselves in over their heads as each twist leads to another unexpected turn over the course of one chaotic night.', 'John Francis Daley, Jonathan Goldstein', 100, '2018-02-15', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/85R8LMyn9f2Lev2YPBF8Nughrkv.jpg', 'https://www.youtube.com/watch?v=qmxMAdV6s4U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (969, 'Sword Art Online the Movie: Ordinal Scale', 'In 2026, a new machine called the Augma is developed to compete against the NerveGear and its successor, the Amusphere. A next-gen wearable device, the Augma doesn''t have a full-dive function like its predecessors. Instead, it uses Augmented Reality to get players into the game. It is safe, user-friendly and lets users play while they are conscious, making it an instant hit on the market. The most popular game on the system is “Ordinal Scale” an ARMMORPG developed exclusively for the Augma. Asuna and the gang have already been playing OS for a while, by the time Kirito decides to join them. They’re about to find out that Ordinal Scale isn’t all fun and games…', 'Tomohiko Ito', 119, '2017-02-18', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/2szdEK0Mr0RG0nWGFVTseNQHbnP.jpg', 'https://www.youtube.com/watch?v=0QjzZWTvkNs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (970, 'Nosferatu', 'A gothic tale of obsession between a haunted young woman and the terrifying vampire infatuated with her, causing untold horror in its wake.', 'Robert Eggers', 133, '2024-12-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5qGIxdEO841C0tdY8vOdLoRVrr0.jpg', 'https://www.youtube.com/watch?v=b59rxDB_JRg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (971, 'Sgt. Stubby: An American Hero', 'The true story of the most decorated dog in American military history - Sgt. Stubby - and the enduring bonds he forged with his brothers-in-arms in the trenches of World War I.', 'Richard Lanni', 85, '2018-04-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rmpykGuvJznJw4iY4hpVVn5ZDdh.jpg', 'https://www.youtube.com/watch?v=ab0pd9oNf7Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (972, 'Pokémon Detective Pikachu', 'In a world where people collect pocket-size monsters (Pokémon) to do battle, a boy comes across an intelligent monster who seeks to be a detective.', 'Rob Letterman', 105, '2019-05-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/uhWvnFgg3BNlcUz0Re1HfQqIcCD.jpg', 'https://www.youtube.com/watch?v=1roy4o4tqQM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (973, 'Beast', 'MMA legend Patton James, now a commercial fisherman, is pulled back into the cage when his brother is in danger. Reuniting with his old coach Sammy, he commits to one final fight in one championship against the brutal champion Xavier Grau.', 'Tyler Atkins', 115, '2026-04-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7NrvUI3vnW8H3rD7ExKcTL7KRcQ.jpg', 'https://www.youtube.com/watch?v=yJN2mJ4uOas', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (974, 'The Swimmers', 'From war-torn Syria to the 2016 Rio Olympics, two young sisters embark on a risky voyage, putting their hearts and their swimming skills to heroic use.', 'Sally El Hosaini', 134, '2022-09-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/u9MiJ6zLpDw4s3qZz93WDVwTUIo.jpg', 'https://www.youtube.com/watch?v=ObN4krVV20Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (975, 'Gangubai Kathiawadi', 'Duped and sold to a brothel, a young woman fearlessly reclaims her power, using underworld connections to preside over the world she was once a pawn in.', 'Sanjay Leela Bhansali', 157, '2022-02-24', 'T16', 'hi', 'https://image.tmdb.org/t/p/w500/x9ihTw6lJzPRiM2imWoER42FBZZ.jpg', 'https://www.youtube.com/watch?v=N1ZwRv3vJJY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (976, 'Nowhere', 'A young pregnant woman named Mia escapes from a country at war by hiding in a maritime container aboard a cargo ship. After a violent storm, Mia gives birth to the child while lost at sea, where she must fight to survive.', 'Albert Pintó', 108, '2023-09-29', 'T18', 'es', 'https://image.tmdb.org/t/p/w500/lncg31XDBdfYxrOnhrzVAUw8geT.jpg', 'https://www.youtube.com/watch?v=KDUtdcU10YA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (977, 'Phera', 'Two men share a house and a past that no longer fits them. As city life pulls Palash forward and age holds his father Pannalal in place, an unexpected return forces them to confront their differences and the quiet truths they have avoided.', 'Pritha Chakraborty', 135, '2026-05-29', 'P', 'bn', 'https://image.tmdb.org/t/p/w500/af291JbfBh7o00De8EtrNpOElvN.jpg', 'https://www.youtube.com/watch?v=oUK9nrGw4i8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (978, 'Blue Giant', 'High school student Dai Miyamoto has his life is turned upside down the day he discovers jazz. Picking up a saxophone and leaving his sleepy hometown for the bustling nightclubs of Tokyo, Dai will find that the life of a professional musician isn’t for the faint of heart, as he must confront what it truly means to be great.', 'Yuzuru Tachikawa', 120, '2023-02-17', 'K', 'ja', 'https://image.tmdb.org/t/p/w500/7LxbzvDvdeU7lBzB92JShURa0cM.jpg', 'https://www.youtube.com/watch?v=gUf5R-MzITU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (979, 'The Witch: Part 2. The Other One', 'A girl wakes up in a huge secret laboratory, then accidentally meets another girl who is trying to protect her house from a gang. The mystery girl overthrows the gang with her unexpected powers, and laboratory staff set out to find her.', 'Park Hoon-jung', 137, '2022-06-15', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/9YTuscJXmr9Iua62amCgGSU8PDW.jpg', 'https://www.youtube.com/watch?v=EgOiCWTR_JU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (980, 'Saltburn', 'Struggling to find his place at Oxford University, student Oliver Quick finds himself drawn into the world of the charming and aristocratic Felix Catton, who invites him to Saltburn, his eccentric family''s sprawling estate, for a summer never to be forgotten.', 'Emerald Fennell', 131, '2023-11-16', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/zGTfMwG112BC66mpaveVxoWPOaB.jpg', 'https://www.youtube.com/watch?v=fNYepvUtYGA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (981, 'A Dog''s Way Home', 'The adventure of Bella, a dog who embarks on an epic 400-mile journey home after she is separated from her beloved human.', 'Charles Martin Smith', 96, '2019-01-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/pZn87R7gtmMCGGO8KeaAfZDhXLg.jpg', 'https://www.youtube.com/watch?v=1pKdCHvH310', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (982, 'Travis Barker: Louder Than Fear', 'After surviving a devastating plane crash that nearly took his life, legendary and electrifying drummer Travis Barker embarks on a raw and redemptive journey in this intimate portrait of the man behind the tattoos who transformed pain into power.', 'Justin Krook, Michael Dwyer', 101, '2026-06-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nFjdTYHi7tRjijf3utArceQFtRi.jpg', 'https://www.youtube.com/watch?v=QOsVdlr0Q1I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (983, 'A Bag of Marbles', 'At the beginning of the 1940s, in a France occupied by Nazi forces, lived the Jewish Joffo family. Happy and tight-knit, she sees her future darken when all members of the family are forced to wear the yellow star. Fearing the worst, the parents organized their family to flee to the free zone in the south of the country. Maurice, twelve years old, and Joseph, ten years old, will therefore leave alone in order to maximize their chances of finding their older brothers already settled in Nice. The brothers left to their own devices demonstrate an incredible amount of cleverness, courage, and ingenuity to escape the enemy invasion and to try to reunite their family once again.', 'Christian Duguay', 113, '2017-01-18', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/kjVPBXfo7frULyUzQ8NRPAflP8G.jpg', 'https://www.youtube.com/watch?v=vIPluU4V03o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (984, 'Invisible Life', 'Rio de Janeiro, Brazil, 1950. In the conservative home of the Gusmão family, Eurídice and Guida are two inseparable sisters who support each other. While Guida can share with her younger sister the details of her romantic adventures, Eurídice finds in her older sister the encouragement she needs to pursue her dream of becoming a professional pianist.', 'Karim Aïnouz', 140, '2019-08-30', 'T13', 'pt', 'https://image.tmdb.org/t/p/w500/dHmy5vHcEfeBfy72sWxAdeSBLmn.jpg', 'https://www.youtube.com/watch?v=8fBBGRT9ga0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (985, 'Marrowbone', 'A young man and his three younger siblings are plagued by a sinister presence in the sprawling manor in which they live.', 'Sergio G. Sánchez', 111, '2017-10-27', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/iX77zMSqUv2Qt7ToEnN2mmEudEf.jpg', 'https://www.youtube.com/watch?v=HsiSsgXXFVs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (986, 'De Gaulle: Liberté', 'Part two of a two-part biopic following French army officer Charles De Gaulle''s life and political commitment between 1940 and 1945, and trace his development towards a political career.', 'Antonin Baudry', 159, '2026-06-26', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/tcypmwT43pt5jWiUyy2BomyPD1Y.jpg', 'https://www.youtube.com/watch?v=J6MRNchmZkY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (987, 'All My Life', 'It was a chance meeting started by one of Sol’s friends trying to chat up Jennifer. However, in the end, it was those two who hit it off. Sol enjoyed Jen’s smile, her effort, and how silly she could be. Jen enjoyed Sol’s cooking, his athleticism, and that he would join her in fun moments. As you can imagine, love bloomed, and things got serious. Jen’s investment in Sol led to her pushing him to follow his dreams and even move in to save money. Sol’s investment in Jen well, it led to him proposing. But what started as a liver tumor grew into full-on cancer, so with a diagnosis of 6 months to live, Sol and Jennifer try to make the best of it.', 'Marc Meyers', 93, '2020-10-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xoKZ4ZkVApcTaTYlGoZ3J8xcIzG.jpg', 'https://www.youtube.com/watch?v=mWyJvohEFj8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (988, 'Shawn Mendes: In Wonder', 'A portrait of singer-songwriter Shawn Mendes'' life, chronicling the past few years of his rise and journey.', 'Grant Singer', 83, '2020-11-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aSs7V3ryvxCSpcXcxf9NY8YBtGC.jpg', 'https://www.youtube.com/watch?v=n6b2il1O55U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (989, 'The Summit of the Gods', 'A photojournalist''s obsessive quest for the truth about the first expedition to Mt. Everest leads him to search for an esteemed climber who went missing.', 'Patrick Imbert', 95, '2021-09-22', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/uzvwwdsTXIUweKYhp8Eo7uidzr5.jpg', 'https://www.youtube.com/watch?v=AwDVv6pDBx8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (990, 'The Ringmaster', 'An aging chef from Minnesota has his life turned upside down when a relentless filmmaker from Las Vegas tries to make the chef''s onion rings world famous.', 'Dave Newberg, Molly Dworsky', 88, '2019-08-08', 'K', 'en', 'https://image.tmdb.org/t/p/w500/9rdlzyGGzDorcwVaTYFnSWPb3Rs.jpg', 'https://www.youtube.com/watch?v=WpS7wMYL87o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (991, 'TÁR', 'As celebrated conductor Lydia Tár starts rehearsals for a career-defining symphony, the consequences of her past choices begin to echo in the present.', 'Todd Field', 158, '2022-10-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dRVAlaU0vbG6hMf2K45NSiIyoUe.jpg', 'https://www.youtube.com/watch?v=Na6gA1RehsU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (992, 'Super Deluxe', 'An unfaithful newly-wed wife, an estranged parent, a priest and an angry son suddenly find themselves in the most unexpected predicaments, each poised to experience their destiny, all on one fateful day.', 'Thiagarajan Kumararaja', 176, '2019-03-29', 'T18', 'ta', 'https://image.tmdb.org/t/p/w500/rTsYDdFWyw87CTk4YgJO6nYmVcJ.jpg', 'https://www.youtube.com/watch?v=DWwvAmVbuEI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (993, 'My Hero Academia: World Heroes'' Mission', 'A mysterious group called Humarize strongly believes in the Quirk Singularity Doomsday theory which states that when quirks get mixed further in with future generations, that power will bring forth the end of humanity. In order to save everyone, the Pro-Heroes around the world ask UA Academy heroes-in-training to assist them and form a world-class selected hero team. It’s up to the heroes to save the world and the future of heroes in what is the most dangerous crisis to take place yet in My Hero Academia.', 'Kenji Nagasaki', 105, '2021-08-06', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/jzP5rPwwNqUGERlrUzKKljfyulf.jpg', 'https://www.youtube.com/watch?v=0r4OB67me6I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (994, 'The Running Man', 'Desperate to save his sick daughter, working-class Ben Richards is convinced by The Running Man''s charming but ruthless producer to enter the deadly competition game as a last resort. But Ben''s defiance, instincts, and grit turn him into an unexpected fan favorite — and a threat to the entire system. As ratings skyrocket, so does the danger, and Ben must outwit not just the Hunters, but a nation addicted to watching him fall.', 'Edgar Wright', 133, '2025-11-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dKL78O9zxczVgjtNcQ9UkbYLzqX.jpg', 'https://www.youtube.com/watch?v=KD18ddeFuyM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (995, 'Life of Crime: 1984-2020', 'An intimate documentary that looks at the vicious cycles of drug addiction and street crime in one of the roughest parts of New Jersey.', 'Jon Alpert', 121, '2021-09-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3HwH3RTBB7mS3RjCyfKuxxqiySO.jpg', 'https://www.youtube.com/watch?v=Qa73N9rakJk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (996, 'Leo', 'Jaded 74-year-old reptile Leo has been stuck in the same Florida classroom for decades with his terrarium-mate turtle. When he learns he only has one year left to live, he plans to escape to experience life on the outside but instead gets caught up in the problems of his anxious students — including an impossibly mean substitute teacher.', 'David Wachtenheim, Robert Marianetti, Robert Smigel', 102, '2023-11-17', 'K', 'en', 'https://image.tmdb.org/t/p/w500/gSOVog7ydsaF1YpgAqBqnKYFGY.jpg', 'https://www.youtube.com/watch?v=G_AEL-Xo5l8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (997, 'The Dirt', 'The story of Mötley Crüe and their rise from the Sunset Strip club scene of the early 1980s to superstardom.', 'Jeff Tremaine', 108, '2019-03-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xGY5rr8441ib0lT9mtHZn7e8Aay.jpg', 'https://www.youtube.com/watch?v=-NOp5ROn1HE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (998, 'The Killing of a Sacred Deer', 'Dr. Steven Murphy is a renowned cardiovascular surgeon who presides over a spotless household with his wife and two children. Lurking at the margins of his idyllic suburban existence is Martin, a fatherless teen who insinuates himself into the doctor''s life in gradually unsettling ways.', 'Yorgos Lanthimos', 121, '2017-10-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/e4DGlsc9g0h5AyoyvvAuIRnofN7.jpg', 'https://www.youtube.com/watch?v=CQFdGfwChtw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (999, 'My First Summer', 'Isolated on a remote property, 16-year-old Claudia finds her world transformed when a spirited girl named Grace wanders into her garden.', 'Katie Found', 78, '2020-10-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7GBMVO09clB7HUgfqbjZmOVAPOi.jpg', 'https://www.youtube.com/watch?v=LU64l9y71vk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (1000, 'Sugar Mill', 'A group of young men and women who work as seasonal workers in a sugar factory face terror from the kingdom of demons where the factory is located. They must find out the cause of the demons'' anger, before the terror ends their lives.', 'Awi Suryadi', 133, '2025-03-31', 'T16', 'id', 'https://image.tmdb.org/t/p/w500/z8Qy6WltFWdnMaQBowXrOr3Vfyg.jpg', 'https://www.youtube.com/watch?v=HiQir_4xyms', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;

